INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('asnar00/miso/android-stop-app', 'android-stop-app', 'asnar00', 'miso', 'community', 'android-stop-app asnar00 miso community The android-stop-app skill terminates Android apps using `adb shell am force-stop`, preserving app data while clearing memory. This skill benefits developers who need to stop apps before deploying new versions. Android 停止应用技能使用 adb shell am force-stop 命令停止 Android 应用，清除内存同时保留应用数据 Android アプリ停止スキルは、adb shell am force-stop コマンドを使用して Android アプリを停止し、メモリをクリーンにし、同時にアプリデータを保持します Android 앱 중지 스킬은 adb shell am force-stop 명령을 사용하여 Android 앱을 중지하고 메모리를 정리同时 앱 데이터를 보존합니다 android-stop-app detiene las aplicaciones Android mediante adb shell am force-stop, preservando los datos de la aplicación android-stop-app arrête les applications Android à l''aide de adb shell am force-stop, tout en préservant les données de l''application android-stop-app beendet Android-Apps mithilfe von adb shell am force-stop und bewahrt die App-Daten O android-stop-app é uma ferramenta que para aplicativos Android usando o comando adb shell am force-stop, terminando processos de aplicativos de forma limpa. ИИ Агент android-stop-app - это инструмент, который останавливает приложения Android с помощью команды adb shell am force-stop, чисто завершая процессы приложений. إيقاف تطبيق اندرويد هو أداة توقف تطبيقات الأندرويد باستخدام أمر adb shell am force-stop، الذي يوقف عمليات التطبيقات بطريقة نظيفة. how to use android-stop-app android-stop-app setup guide what is android-stop-app android-stop-app alternative android-stop-app vs force-stop android-stop-app install terminating android apps with adb clean app termination preserving app data Android 停止应用 adb shell am force-stop Android 应用停止指南 AI 应用停止工具 Android 应用开发 Android 应用测试 Terminates Android apps using `adb shell am force-stop` command Preserves app data while clearing memory Supports clean termination of app processes Invoked by user requests to stop or kill the Android app Useful for stopping apps before deploying new versions android-stop-app is a skill that stops Android apps running on connected devices using the `adb shell am force-stop` command, providing a clean termination of app processes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Awannaphasch2016/jousef-landing/infrastructure-verification', 'community', 'Awannaphasch2016', 'jousef-landing', 'Awannaphasch2016/jousef-landing', 'infrastructure-verification', 0, 0, 57, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:43.314Z', '1ffdac027f6627f06b18e34fdbbcbcf314c2185fbd2ebdf0a9343ad4e9547cf8', '{"id":"Awannaphasch2016/jousef-landing/infrastructure-verification","name":"infrastructure-verification","description":{"en":"The infrastructure-verification skill helps developers validate AWS VPC configurations and debug Lambda connection issues. It benefits developers working with AWS CLI, Terraform, and CloudWatch.","zh":"基础设施验证技能用于验证AWS基础设施，包括VPC、CloudWatch和Lambda函数，通过AWS CLI和Terraform进行设置和调试","ja":"インフラストラクチャ検証スキルは、VPC、CloudWatch、Lambda関数を含むAWSインフラストラクチャを検証するために使用され、AWS CLIとTerraformを使用して設定とデバッグを行います","ko":"인프라스트럭처 확인 기술은 VPC, CloudWatch, Lambda 함수를 포함한 AWS 인프라스트럭처를 확인하는 데 사용되며, AWS CLI와 Terraform을 사용하여 설정과 디버깅을 수행합니다","es":"La verificación de infraestructura es crucial para asegurar la conectividad y el rendimiento de tus aplicaciones. Aprende a utilizar AWS CLI y Terraform para verificar tu infraestructura","fr":"La vérification d''infrastructure est essentielle pour assurer la connectivité et les performances de vos applications. Découvrez comment utiliser AWS CLI et Terraform pour vérifier votre infrastructure","de":"Die Infrastruktur-Verifizierung ist entscheidend, um die Konnektivität und Leistung Ihrer Anwendungen zu gewährleisten. Erfahren Sie, wie Sie AWS CLI und Terraform verwenden, um Ihre Infrastruktur zu überprüfen","pt":"A habilidade de verificação de infraestrutura ajuda a depurar timeouts de conexão Lambda e a validar o caminho de rede para a AWS utilizando AWS CLI, Terraform e CloudWatch","ru":"ИИ Агенты для верификации инфраструктуры помогают отлаживать таймауты подключения Lambda и проверять сетевой путь к AWS с помощью AWS CLI, Terraform и CloudWatch","ar":"مهارة التحقق من البنية التحتية تساعد على تصحيح أخطاء التأخيرات في الاتصال Lambda و التحقق من مسار الشبكة إلى AWS باستخدام AWS CLI و Terraform و CloudWatch"},"seo":{"title":{"en":"infrastructure-verification: AWS VPC Validation Setup Gui...","zh":"基础设施验证设置指南 - AIエージェント工具","ja":"インフラストラクチャ検証ベストプラクティス - AIエージェント","ko":"인프라스트럭처 확인 설정 가이드 - AI 에이전트","es":"Guía de configuración de verificación de infraestructura ...","fr":"Guide de configuration de vérification d''infrastructure a...","de":"Einrichtungsleitfaden für Infrastruktur-Verifizierung mit...","pt":"Guia de Configuração de Verificação de Infraestrutura com...","ru":"Настройка инфраструктуры: ИИ Агенты для верификации с AWS...","ar":"دليل إعداد التحقق من البنية التحتية باستخدام AWS CLI و Te..."},"description":{"en":"Verify your AWS infrastructure with our AI agent skill. Learn how to debug Lambda connection timeouts and validate network paths to AWS. Get started now!","zh":"使用基础设施验证技能来排查Lambda连接超时、调试确定性故障模式和验证网络路径到AWS，了解AWS CLI、Terraform、VPC和CloudWatch的应用","ja":"Lambda接続タイムアウトの調査、決定的な故障パターンのデバッグ、AWSへのネットワークパスの検証を行うためのインフラストラクチャ検証スキルを使用してください。AWS CLI、Terraform、VPC、CloudWatchの適用について学びます","ko":"Lambda 연결 타임아웃을 조사하고, 결정적인 실패 패턴을 디버깅하고, AWS로의 네트워크 경로를 확인하기 위한 인프라스트럭처 확인 기술을 사용하세요. AWS CLI, Terraform, VPC, CloudWatch의 적용에 대해 알아보세요","es":"Aprende a verificar tu infraestructura con AWS CLI, Terraform y CloudWatch. Soluciona problemas de conexión y depuración de patrones de fallo","fr":"Découvrez comment vérifier votre infrastructure avec AWS CLI, Terraform et CloudWatch. Résolvez les problèmes de connexion et de débogage de modèles d''échec","de":"Erfahren Sie, wie Sie Ihre Infrastruktur mit AWS CLI, Terraform und CloudWatch überprüfen. Lösen Sie Verbindungs- und Fehlertyp-Debugging-Probleme","pt":"Aprenda a utilizar a habilidade de verificação de infraestrutura para depurar timeouts de conexão Lambda e validar o caminho de rede para a AWS","ru":"Изучите возможность использования ИИ Агентов для верификации инфраструктуры при отладке таймаутов подключения Lambda и проверке сетевого пути к AWS","ar":"تعرف على كيفية استخدام مهارة التحقق من البنية التحتية لتصحيح أخطاء التأخيرات في الاتصال Lambda و التحقق من مسار الشبكة إلى AWS"},"definition":{"en":"infrastructure-verification is a skill that validates AWS infrastructure configurations using AWS CLI, Terraform, and CloudWatch to ensure reliable Lambda deployments.","zh":"基础设施验证是指使用AWS CLI、Terraform等技术来检查和验证AWS基础设施的设置和配置","ja":"インフラストラクチャ検証は、AWS CLI、Terraformなどの技術を使用してAWSインフラストラクチャの設定と構成を検証することです","ko":"인프라스트럭처 확인은 AWS CLI, Terraform 등의 기술을 사용하여 AWS 인프라스트럭처의 설정과 구성의 유효성을 검사하는 것을 의미합니다","es":"La verificación de infraestructura es el proceso de comprobación de la configuración y el funcionamiento de la infraestructura de una aplicación","fr":"La vérification d''infrastructure est le processus de vérification de la configuration et du fonctionnement de l''infrastructure d''une application","de":"Die Infrastruktur-Verifizierung ist der Prozess der Überprüfung der Konfiguration und des Betriebs der Infrastruktur einer Anwendung","pt":"Verificação de infraestrutura é uma habilidade que utiliza tecnologias como AWS CLI e Terraform para depurar e validar a configuração da infraestrutura","ru":"Верификация инфраструктуры - это возможность, использующая технологии seperti AWS CLI и Terraform для отладки и проверки конфигурации инфраструктуры","ar":"التحقق من البنية التحتية هو مهارة تستخدم تقنيات مثل AWS CLI و Terraform لتصحيح أخطاء و التحقق من إعدادات البنية التحتية"},"features":{"en":["Validates network path to AWS using CloudWatch","Debugs Lambda connection timeouts with AWS CLI","Supports Terraform for infrastructure-as-code deployments","Investigates deterministic failure patterns in Lambda functions","Extracts insights from S3 upload timeout investigations","Deploys Lambda-in-VPC code with confidence"],"zh":["使用AWS CLI进行基础设施设置和调试","通过Terraform进行基础设施自动化","使用VPC和CloudWatch进行网络和性能监控","支持Lambda函数的部署和调试","提供基础设施验证报告和分析"],"ja":["AWS CLIを使用したインフラストラクチャ設定とデバッグ","Terraformを使用したインフラストラクチャ自動化","VPCとCloudWatchを使用したネットワークとパフォーマンスの監視","Lambda関数のデプロイとデバッグのサポート","インフラストラクチャ検証レポートと分析の提供"],"ko":["AWS CLI를 사용한 인프라스트럭처 설정과 디버깅","Terraform을 사용한 인프라스트럭처 자동화","VPC와 CloudWatch를 사용한 네트워크와 성능 모니터링","Lambda 함수의 배포와 디버깅 지원","인프라스트럭처 확인 보고서와 분석 제공"],"es":["Verificación de infraestructura con AWS CLI","Configuración de Terraform para la verificación de infraestructura","Monitoreo de CloudWatch para la detección de problemas","Depuración de patrones de fallo con bash","Verificación de la conectividad de la red a AWS"],"fr":["Vérification d''infrastructure avec AWS CLI","Configuration de Terraform pour la vérification d''infrastructure","Surveillance de CloudWatch pour la détection de problèmes","Débogage de modèles d''échec avec bash","Vérification de la connectivité du réseau à AWS"],"de":["Infrastruktur-Verifizierung mit AWS CLI","Konfiguration von Terraform für die Infrastruktur-Verifizierung","Überwachung von CloudWatch für die Erkennung von Problemen","Fehlertyp-Debugging mit bash","Verifizierung der Netzwerk-Konnektivität zu AWS"],"pt":["Utiliza AWS CLI para depurar timeouts de conexão Lambda","Valida o caminho de rede para a AWS com Terraform","Utiliza CloudWatch para monitorar a infraestrutura","Suporta bash para scripts de automação","Ajuda a identificar padrões de falha determinísticos"],"ru":["Использует AWS CLI для отладки таймаутов подключения Lambda","Проверяет сетевой путь к AWS с помощью Terraform","Использует CloudWatch для мониторинга инфраструктуры","Поддерживает bash для скриптов автоматизации","Помогает выявлять определенные закономерности неисправностей"],"ar":["تستخدم AWS CLI لتصحيح أخطاء التأخيرات في الاتصال Lambda","تتحقق من مسار الشبكة إلى AWS باستخدام Terraform","تستخدم CloudWatch لمراقبة البنية التحتية","تدعم bash لسكريبتات التأهيل","تساعد على تحديد أنماط الفشل المتعمدة"]},"keywords":{"en":["how to use infrastructure-verification","infrastructure-verification setup guide","AWS VPC validation tools","debugging Lambda connection timeouts","infrastructure-verification alternative","infrastructure-verification vs Terraform","installing infrastructure-verification","infrastructure-verification best practices","validating AWS infrastructure configurations"],"zh":["基础设施验证","AWS CLI","Terraform","VPC","CloudWatch","Lambda函数","AIエージェント工具","基础设施设置","基础设施调试"],"ja":["インフラストラクチャ検証","AWS CLI","Terraform","VPC","CloudWatch","Lambda関数","AIエージェント","インフラストラクチャ設定","インフラストラクチャデバッグ"],"ko":["인프라스트럭처 확인","AWS CLI","Terraform","VPC","CloudWatch","Lambda 함수","AI 에이전트","인프라스트럭처 설정","인프라스트럭처 디버깅"],"es":["verificación de infraestructura","AWS CLI","Terraform","CloudWatch","depuración de patrones de fallo","conectividad de red a AWS","herramientas de AI para la verificación de infraestructura","agentes de AI para la depuración de infraestructura"],"fr":["vérification d''infrastructure","AWS CLI","Terraform","CloudWatch","débogage de modèles d''échec","connectivité du réseau à AWS","outils d''IA pour la vérification d''infrastructure","agents d''IA pour la débogage d''infrastructure"],"de":["Infrastruktur-Verifizierung","AWS CLI","Terraform","CloudWatch","Fehlertyp-Debugging","Netzwerk-Konnektivität zu AWS","KI-Tools für die Infrastruktur-Verifizierung","KI-Agents für die Infrastruktur-Debugging"],"pt":["verificação de infraestrutura","AWS CLI","Terraform","CloudWatch","depuração de timeouts de conexão Lambda","validação de caminho de rede para a AWS","bash","scripts de automação","padrões de falha determinísticos"],"ru":["верификация инфраструктуры","ИИ Агенты","AWS CLI","Terraform","CloudWatch","отладка таймаутов подключения Lambda","проверка сетевого пути к AWS","bash","скрипты автоматизации","определенные закономерности неисправностей"],"ar":["التحقق من البنية التحتية","أدوات الذكاء الاصطناعي","AWS CLI","Terraform","CloudWatch","تصحيح أخطاء التأخيرات في الاتصال Lambda","التحقق من مسار الشبكة إلى AWS","bash","سكريبتات التأهيل","أنماط الفشل المتعمدة"]}},"owner":"Awannaphasch2016","repo":"jousef-landing","repoPath":"Awannaphasch2016/jousef-landing","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"infrastructure-verification","description":"Verify AWS infrastructure configuration before deployment. Use when validating VPC endpoints, NAT Gateway capacity, security groups, or debugging network path issues that cause Lambda connection timeouts.","bodyPreview":"# Infrastructure Verification Skill\n\n**Tech Stack**: AWS CLI, Terraform, VPC, CloudWatch, bash\n\n**Source**: Extracted from PDF S3 upload timeout investigation (2026-01-05) and Infrastructure-Application Contract principle.\n\n---\n\n## When to Use This Skill\n\nUse the infrastructure-verification skill when:\n- ✓ Before deploying Lambda-in-VPC code\n- ✓ Investigating Lambda connection timeouts\n- ✓ Debugging deterministic failure patterns (first N succeed, last M fail)\n- ✓ Validating network path to AWS","body":"# Infrastructure Verification Skill\n\n**Tech Stack**: AWS CLI, Terraform, VPC, CloudWatch, bash\n\n**Source**: Extracted from PDF S3 upload timeout investigation (2026-01-05) and Infrastructure-Application Contract principle.\n\n---\n\n## When to Use This Skill\n\nUse the infrastructure-verification skill when:\n- ✓ Before deploying Lambda-in-VPC code\n- ✓ Investigating Lambda connection timeouts\n- ✓ Debugging deterministic failure patterns (first N succeed, last M fail)\n- ✓ Validating network path to AWS services (S3, DynamoDB, RDS)\n- ✓ After adding VPC endpoints\n- ✓ Before concurrent Lambda executions\n\n**DO NOT use this skill for:**\n- ✗ Application code debugging (use error-investigation)\n- ✗ Performance optimization (different focus)\n- ✗ IAM permission issues (use AWS CLI directly)\n\n---\n\n## Core Verification Principles\n\n### Principle 1: Infrastructure Dependency Validation\n\n**From CLAUDE.md Principle #15:**\n> \"Before deploying code that depends on AWS infrastructure (S3, VPC endpoints, NAT Gateway), verify infrastructure exists and is correctly configured. Network path issues cause deterministic failure patterns.\"\n\n**When to validate:**\n- Before deploying Lambda functions that make AWS service calls\n- After Terraform infrastructure changes\n- When investigating Lambda timeout patterns\n- Before increasing concurrency limits\n\n### Principle 2: Pattern Recognition\n\n**Failure Pattern Types:**\n\n| Pattern | Root Cause | Investigation Priority |\n|---------|------------|----------------------|\n| **First N succeed, last M fail** | Infrastructure bottleneck (NAT, connection limits) | HIGH - VPC endpoint missing |\n| **Random scattered failures** | Performance issue (slow API, memory) | MEDIUM - Optimize code |\n| **All operations fail** | Configuration issue (permissions, endpoint) | HIGH - Fix config |\n| **Intermittent failures** | Rate limiting, transient network | LOW - Add retries |\n\n**Deterministic pattern** (first N succeed, last M fail) is strongest signal of infrastructure bottleneck.\n\n---\n\n## Verification Workflows\n\n### Workflow 1: VPC Endpoint Verification\n\n**Use when:** Lambda-in-VPC needs to access S3 or DynamoDB\n\n**Steps:**\n\n```bash\n# 1. Check if VPC endpoint exists\naws ec2 describe-vpc-endpoints \\\n  --filters \"Name=vpc-id,Values=vpc-xxx\" \\\n            \"Name=service-name,Values=com.amazonaws.ap-southeast-1.s3\" \\\n  --query ''VpcEndpoints[*].{ID:VpcEndpointId,State:State,Service:ServiceName}'' \\\n  --output table\n\n# Expected output (if endpoint exists):\n# -----------------------------------------\n# | DescribeVpcEndpoints                  |\n# +-------+-------+------------------------+\n# | ID    | State | Service                |\n# +-------+-------+------------------------+\n# | vpce-xxx | available | com.amazonaws.ap-southeast-1.s3 |\n# +-------+-------+------------------------+\n\n# If empty → No S3 VPC Endpoint (traffic goes through NAT Gateway)\n\n# 2. Verify endpoint state\naws ec2 describe-vpc-endpoints \\\n  --vpc-endpoint-ids vpce-xxx \\\n  --query ''VpcEndpoints[0].State'' \\\n  --output text\n\n# Expected: \"available\"\n# If \"pending\" → Wait for creation\n# If \"failed\" → Check Terraform logs\n\n# 3. Verify route table attachment\naws ec2 describe-vpc-endpoints \\\n  --vpc-endpoint-ids vpce-xxx \\\n  --query ''VpcEndpoints[0].RouteTableIds'' \\\n  --output table\n\n# Expected: List of route table IDs (must include Lambda subnet route tables)\n\n# 4. Check Lambda subnet route tables\naws lambda get-function-configuration \\\n  --function-name my-function \\\n  --query ''VpcConfig.SubnetIds'' \\\n  --output text | xargs -I {} aws ec2 describe-subnets --subnet-ids {}\n\n# Compare: Lambda subnets'' route tables should be in VPC endpoint''s RouteTableIds\n\n# 5. Verify S3 prefix list in route tables\nROUTE_TABLE_ID=$(aws ec2 describe-route-tables \\\n  --filters \"Name=vpc-id,Values=vpc-xxx\" \\\n  --query ''RouteTables[0].RouteTableId'' \\\n  --output text)\n\naws ec2 describe-route-tables \\\n  --route-table-ids $ROUTE_TABLE_ID \\\n  --query ''RouteTables[*].Routes[?GatewayId==`vpce-xxx`]''\n\n# Expected: Route with DestinationPrefixListId (S3 prefix list)\n```\n\n**Verification checklist:**\n- [ ] VPC endpoint exists (`describe-vpc-endpoints` returns result)\n- [ ] State is \"available\" (not \"pending\" or \"failed\")\n- [ ] Route tables attached (includes Lambda subnet route tables)\n- [ ] S3 prefix list routes created (check route tables)\n\n**Common issues:**\n- Missing VPC endpoint → Create with Terraform\n- State \"pending\" → Wait 2-3 minutes\n- Route tables not attached → Update Terraform `route_table_ids`\n- Lambda subnets not covered → Verify subnet route table IDs\n\n### Workflow 2: NAT Gateway Diagnosis\n\n**Use when:** Investigating Lambda connection timeouts with external services\n\n**Steps:**\n\n```bash\n# 1. Check NAT Gateway exists\naws ec2 describe-nat-gateways \\\n  --filter \"Name=vpc-id,Values=vpc-xxx\" \\\n  --query ''NatGateways[*].{ID:NatGatewayId,State:State,PublicIp:NatGatewayAddresses[0].PublicIp}'' \\\n  --output table\n\n# Expected: State \"available\"\n\n# 2. Check route tables using NAT Gateway\naws ec2 describe-route-tables \\\n  --filters \"Name=vpc-id,Values=vpc-xxx\" \\\n  --query ''RouteTables[*].Routes[?NatGatewayId!=`null`].[RouteTableId,DestinationCidrBlock,NatGatewayId]'' \\\n  --output table\n\n# Expected: Route 0.0.0.0/0 → nat-xxx (default route through NAT)\n\n# 3. Analyze connection saturation pattern\n# Run this during concurrent Lambda executions\naws logs filter-log-events \\\n  --log-group-name /aws/lambda/my-function \\\n  --start-time $(date -d ''5 minutes ago'' +%s)000 \\\n  --filter-pattern \"START RequestId\" \\\n  --query ''events[*].timestamp'' \\\n  --output text | xargs -n1 date -d @\n\n# Check execution pattern:\n# - All start within 1 second → Concurrent execution\n# - Some timeout after 600s → NAT Gateway saturation\n\n# 4. Check for connection timeout errors\naws logs filter-log-events \\\n  --log-group-name /aws/lambda/my-function \\\n  --filter-pattern \"ConnectTimeoutError\" \\\n  --query ''events[*].message'' \\\n  --output text\n\n# If errors found → NAT Gateway connection limit reached\n\n# 5. Calculate concurrent connection demand\nCONCURRENT_LAMBDAS=$(aws logs filter-log-events \\\n  --log-group-name /aws/lambda/my-function \\\n  --start-time $(date -d ''1 minute ago'' +%s)000 \\\n  --filter-pattern \"START RequestId\" \\\n  --query ''length(events)'' \\\n  --output text)\n\necho \"Concurrent Lambdas: $CONCURRENT_LAMBDAS\"\necho \"NAT Gateway connection limit: ~55,000 (but establishment rate limited)\"\n```\n\n**NAT Gateway saturation indicators:**\n- ✅ Deterministic pattern (first N succeed, last M fail)\n- ✅ ConnectTimeoutError in logs\n- ✅ Long execution times (600s = boto3 default timeout)\n- ✅ Timeline shows concurrent starts → split success/failure\n\n**Solution:** Add VPC Gateway Endpoint for S3/DynamoDB to bypass NAT\n\n### Workflow 3: Network Path Validation\n\n**Use when:** Verifying Lambda can reach AWS services\n\n**Steps:**\n\n```bash\n# 1. Identify Lambda VPC configuration\naws lambda get-function-configuration \\\n  --function-name my-function \\\n  --query ''VpcConfig.{VpcId:VpcId,SubnetIds:SubnetIds,SecurityGroupIds:SecurityGroupIds}'' \\\n  --output json\n\n# Save VPC ID, Subnet IDs, Security Group IDs\n\n# 2. Check security group egress rules\naws ec2 describe-security-groups \\\n  --group-ids sg-xxx \\\n  --query ''SecurityGroups[*].IpPermissionsEgress[*].{Proto:IpProtocol,Port:FromPort,Dest:IpRanges[0].CidrIp}'' \\\n  --output table\n\n# Expected: 0.0.0.0/0 allowed (all egress)\n# If restricted → Add rule for destination service\n\n# 3. Check route table for Lambda subnet\nSUBNET_ID=$(aws lambda get-function-configuration \\\n  --function-name my-function \\\n  --query ''VpcConfig.SubnetIds[0]'' \\\n  --output text)\n\nROUTE_TABLE_ID=$(aws ec2 describe-route-tables \\\n  --filters \"Name=association.subnet-id,Values=$SUBNET_ID\" \\\n  --query ''RouteTables[0].RouteTableId'' \\\n  --output text)\n\naws ec2 describe-route-tables \\\n  --route-table-ids $ROUTE_TABLE_ID \\\n  --query ''RouteTables[*].Routes[*].[DestinationCidrBlock,GatewayId,NatGatewayId]'' \\\n  --output table\n\n# Expected routes:\n# - local → vpc-xxx (VPC internal)\n# - 0.0.0.0/0 → nat-xxx (internet via NAT) OR vpce-xxx (S3 via endpoint)\n\n# 4. Test actual network path (requires test Lambda invocation)\n# Deploy temporary test Lambda:\n# - Attempts connection to S3\n# - Logs connection details\n# - Reports success/failure\n\n# 5. Analyze test results\naws logs tail /aws/lambda/network-test --since 1m\n\n# Look for:\n# - Connection established (success)\n# - Connection timeout (NAT saturated)\n# - Connection refused (security group blocked)\n# - DNS resolution failure (VPC DNS issue)\n```\n\n**Network path checklist:**\n- [ ] Lambda in VPC (`VpcConfig` not empty)\n- [ ] Security group allows egress to destination\n- [ ] Route table has path to destination (NAT or VPC endpoint)\n- [ ] VPC endpoint exists for AWS service (S3, DynamoDB)\n- [ ] Test invocation confirms connectivity\n\n### Workflow 4: Post-Deployment Infrastructure Validation\n\n**Use when:** After deploying infrastructure changes (VPC endpoints, security groups)\n\n**Steps:**\n\n```bash\n# 1. Verify Terraform outputs\ncd terraform\nterraform output s3_vpc_endpoint_id        # Should return vpce-xxx\nterraform output s3_vpc_endpoint_state     # Should return \"available\"\n\n# 2. Run smoke test Lambda invocation\naws lambda invoke \\\n  --function-name my-function \\\n  --payload ''{\"test\": true}'' \\\n  /tmp/response.json\n\n# Check response\ncat /tmp/response.json | jq .\n\n# 3. Verify CloudWatch logs show success\naws logs tail /aws/lambda/my-function --since 1m --follow\n\n# Expected:\n# - No ConnectTimeoutError\n# - Operation completes in expected time (2-3s not 600s)\n# - Success message logged\n\n# 4. Test concurrent execution (simulate production load)\nfor i in {1..10}; do\n  aws lambda invoke \\\n    --function-name my-function \\\n    --payload \"{\\\"id\\\": $i}\" \\\n    --invocation-type Event \\\n    /tmp/response_$i.json &\ndone\nwait\n\n# 5. Analyze concurrent execution results\naws logs filter-log-events \\\n  --log-group-name /aws/lambda/my-function \\\n  --start-time $(date -d ''5 minutes ago'' +%s)000 \\\n  --filter-pattern \"ConnectTimeoutError\" \\\n  --query ''length(events)'' \\\n  --output text\n\n# Expected: 0 (no timeout errors)\n# If > 0 → Infrastructure issue still exists\n\n# 6. Verify 100% success rate\naws logs filter-log-events \\\n  --log-group-name /aws/lambda/my-function \\\n  --start-time $(date -d ''5 minutes ago'' +%s)000 \\\n  --filter-pattern \"✅\" \\\n  --query ''length(events)'' \\\n  --output text\n\n# Expected: 10 (all concurrent executions succeeded)\n```\n\n**Post-deployment checklist:**\n- [ ] Terraform outputs confirm resource created\n- [ ] Smoke test invocation succeeds\n- [ ] CloudWatch logs show no errors\n- [ ] Concurrent execution test (10+ invocations)\n- [ ] 100% success rate (no timeouts)\n- [ ] Execution time within expected range (2-3s not 600s)\n\n---\n\n## Common Infrastructure Issues\n\n### Issue 1: Missing S3 VPC Endpoint\n\n**Symptom:**\n- Lambda timeout after 600s\n- Error: `ConnectTimeoutError: Connect timeout on endpoint URL: \"https://bucket.s3.region.amazonaws.com/...\"`\n- Pattern: First N concurrent operations succeed, last M timeout\n\n**Diagnosis:**\n\n```bash\n# Check for S3 VPC endpoint\naws ec2 describe-vpc-endpoints \\\n  --filters \"Name=vpc-id,Values=vpc-xxx\" \\\n            \"Name=service-name,Values=com.amazonaws.region.s3\"\n\n# If empty → No endpoint (S3 traffic goes through NAT)\n```\n\n**Fix:**\n\n```hcl\n# terraform/s3_vpc_endpoint.tf\ndata \"aws_route_tables\" \"vpc_route_tables\" {\n  vpc_id = data.aws_vpc.default.id\n}\n\nresource \"aws_vpc_endpoint\" \"s3\" {\n  vpc_id            = data.aws_vpc.default.id\n  service_name      = \"com.amazonaws.${var.aws_region}.s3\"\n  vpc_endpoint_type = \"Gateway\"\n\n  route_table_ids = data.aws_route_tables.vpc_route_tables.ids\n\n  policy = jsonencode({\n    Version = \"2012-10-17\"\n    Statement = [{\n      Effect    = \"Allow\"\n      Principal = \"*\"\n      Action    = \"s3:*\"\n      Resource  = \"*\"\n    }]\n  })\n\n  tags = {\n    Name = \"s3-endpoint\"\n  }\n}\n\noutput \"s3_vpc_endpoint_id\" {\n  value = aws_vpc_endpoint.s3.id\n}\n\noutput \"s3_vpc_endpoint_state\" {\n  value = aws_vpc_endpoint.s3.state\n}\n```\n\n**Verification:**\n\n```bash\ncd terraform\nterraform apply\nterraform output s3_vpc_endpoint_state  # Should be \"available\"\n\n# Test Lambda invocation\naws lambda invoke --function-name my-function --payload ''{}'' /tmp/response.json\naws logs tail /aws/lambda/my-function --since 1m\n# Expected: No timeout, completes in 2-3s\n```\n\n### Issue 2: NAT Gateway Connection Saturation\n\n**Symptom:**\n- Deterministic failure pattern (first 5 succeed, last 5 timeout)\n- All timeouts occur after ~10 minutes (boto3 default + retries)\n- Timeline analysis shows concurrent Lambda starts\n\n**Diagnosis:**\n\n```bash\n# Check timeline of Lambda executions\naws logs filter-log-events \\\n  --log-group-name /aws/lambda/my-function \\\n  --start-time $(date -d ''30 minutes ago'' +%s)000 \\\n  --filter-pattern \"START RequestId\" \\\n  | jq -r ''.events[] | .timestamp as $ts | ($ts/1000 | strftime(\"%H:%M:%S\")) + \" \" + (.message | split(\" \")[2])''\n\n# Look for:\n# - All start within 1 second (concurrent)\n# - Check which RequestIds have errors\naws logs filter-log-events \\\n  --log-group-name /aws/lambda/my-function \\\n  --filter-pattern \"ConnectTimeoutError\" \\\n  | jq -r ''.events[].message'' | grep -o \"RequestId: [a-z0-9-]*\"\n\n# Pattern: Last N RequestIds consistently fail\n```\n\n**Root Cause:**\n- NAT Gateway has limited connection establishment rate\n- Concurrent Lambdas try to establish S3 connections simultaneously\n- First N connections succeed → Upload completes in 2-3s\n- Last M connections queued → Eventually timeout after 600s\n\n**Fix:** Add S3 VPC Gateway Endpoint (see Issue 1)\n\n**Why this works:**\n- VPC Gateway Endpoint bypasses NAT Gateway\n- S3 traffic routed directly within AWS network\n- No connection establishment limits\n- Free (Gateway endpoints have no hourly charge)\n\n### Issue 3: Security Group Blocking Egress\n\n**Symptom:**\n- Lambda unable to connect to AWS service\n- Error: Connection refused or timeout\n- All invocations fail (not deterministic pattern)\n\n**Diagnosis:**\n\n```bash\n# Check security group egress rules\naws lambda get-function-configuration \\\n  --function-name my-function \\\n  --query ''VpcConfig.SecurityGroupIds[0]'' \\\n  --output text | xargs -I {} aws ec2 describe-security-groups --group-ids {}\n\n# Look for egress rules allowing HTTPS (port 443)\n# Expected: 0.0.0.0/0 or specific AWS service prefix list\n```\n\n**Fix:**\n\n```hcl\n# terraform/security_groups.tf\nresource \"aws_security_group_rule\" \"lambda_egress_https\" {\n  type              = \"egress\"\n  from_port         = 443\n  to_port           = 443\n  protocol          = \"tcp\"\n  cidr_blocks       = [\"0.0.0.0/0\"]\n  security_group_id = aws_security_group.lambda.id\n}\n```\n\n### Issue 4: Route Table Not Attached to VPC Endpoint\n\n**Symptom:**\n- VPC endpoint exists and is \"available\"\n- Lambda still times out connecting to S3\n- Deterministic or random failures\n\n**Diagnosis:**\n\n```bash\n# Check VPC endpoint route table attachment\naws ec2 describe-vpc-endpoints \\\n  --vpc-endpoint-ids vpce-xxx \\\n  --query ''VpcEndpoints[0].RouteTableIds'' \\\n  --output table\n\n# Get Lambda subnet route table\naws lambda get-function-configuration \\\n  --function-name my-function \\\n  --query ''VpcConfig.SubnetIds[0]'' \\\n  --output text | xargs -I {} aws ec2 describe-route-tables \\\n  --filters \"Name=association.subnet-id,Values={}\" \\\n  --query ''RouteTables[0].RouteTableId'' \\\n  --output text\n\n# Compare: Lambda''s route table should be in endpoint''s RouteTableIds\n```\n\n**Fix:**\n\n```hcl\n# terraform/s3_vpc_endpoint.tf\ndata \"aws_route_tables\" \"vpc_route_tables\" {\n  vpc_id = data.aws_vpc.default.id\n}\n\nresource \"aws_vpc_endpoint\" \"s3\" {\n  # ... other config ...\n\n  # Attach to ALL route tables (includes Lambda subnets)\n  route_table_ids = data.aws_route_tables.vpc_route_tables.ids\n}\n```\n\n---\n\n## Integration with Other Skills\n\n### With error-investigation\n- Use infrastructure-verification BEFORE error-investigation when:\n  - Investigating Lambda timeout patterns\n  - Debugging connection failures\n  - Analyzing deterministic failure patterns\n- Use error-investigation AFTER infrastructure-verification when:\n  - Infrastructure confirmed correct but errors persist\n  - Need to analyze application logs\n  - Debugging business logic failures\n\n### With deployment skill\n- Use infrastructure-verification:\n  - BEFORE deploying Lambda-in-VPC code\n  - AFTER deploying infrastructure changes (Terraform apply)\n  - During post-deployment validation\n- Complements deployment smoke tests with infrastructure-specific checks\n\n### With testing-workflow\n- Infrastructure verification is a form of pre-deployment testing\n- Validates infrastructure-application contract (CLAUDE.md Principle #15)\n- Catches configuration issues before code deployment\n\n---\n\n## Quick Reference\n\n### VPC Endpoint Types\n\n| Type | Services | Cost | Use Case |\n|------|----------|------|----------|\n| **Gateway** | S3, DynamoDB | FREE | High-throughput data access |\n| **Interface** | Most AWS services | ~$7.50/month | Other services (Secrets Manager, etc.) |\n\n### NAT Gateway Limits\n\n| Limit | Value | Impact |\n|-------|-------|--------|\n| **Concurrent connections** | 55,000 | Theoretical max |\n| **Connection establishment rate** | Limited | Causes saturation with concurrent Lambdas |\n| **Data transfer cost** | $0.045/GB | Expensive for large transfers |\n\n**Recommendation:** Use VPC Gateway Endpoints for S3/DynamoDB (free, unlimited, faster)\n\n### Common AWS CLI Commands\n\n```bash\n# VPC endpoint\naws ec2 describe-vpc-endpoints --vpc-endpoint-ids vpce-xxx\n\n# NAT Gateway\naws ec2 describe-nat-gateways --nat-gateway-ids nat-xxx\n\n# Security groups\naws ec2 describe-security-groups --group-ids sg-xxx\n\n# Route tables\naws ec2 describe-route-tables --route-table-ids rtb-xxx\n\n# Lambda VPC config\naws lambda get-function-configuration --function-name my-function --query ''VpcConfig''\n```\n\n---\n\n## File Organization\n\n```\n.claude/skills/infrastructure-verification/\n└── SKILL.md              # This file (complete skill)\n```\n\n---\n\n## References\n\n- [VPC Endpoints](https://docs.aws.amazon.com/vpc/latest/privatelink/vpc-endpoints.html)\n- [NAT Gateway](https://docs.aws.amazon.com/vpc/latest/userguide/vpc-nat-gateway.html)\n- [Lambda VPC Configuration](https://docs.aws.amazon.com/lambda/latest/dg/configuration-vpc.html)\n- [Bug Hunt Report](../../bug-hunts/2026-01-05-pdf-s3-upload-timeout.md) - Real-world investigation\n- CLAUDE.md Principle #15 (Infrastructure-Application Contract)\n- CLAUDE.md Principle #2 (Progressive Evidence Strengthening)\n"},"lastSynced":"2026-03-08T02:01:43.314Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Agents needing advanced AWS infrastructure validation and debugging capabilities.","zh":"适合需要高级 AWS 基础设施验证和调试功能的 Cloud Agent。","ja":"AWS インフラストラクチャの高度な検証およびデバッグ機能を必要とする Cloud Agent に適しています。","ko":"고급 AWS 인프라ストラク처 유효성 검사 및 디버깅 기능이 필요한 Cloud Agent에 적합합니다.","es":"Perfecto para agentes en la nube que necesitan capacidades avanzadas de validación y depuración de infraestructura de AWS.","fr":"Parfait pour les agents Cloud nécessitant des capacités de validation et de débogage d''infrastructure AWS avancées.","de":"Perfekt für Cloud-Agents, die erweiterte AWS-Infrastruktur-Validierungs- und Debugging-Funktionen benötigen.","pt":"Perfeito para Agentes de Nuvem que precisam de capacidades avançadas de validação e depuração de infraestrutura da AWS.","ru":"Идеально подходит для облачных агентов, которым необходимы расширенные возможности проверки и отладки инфраструктуры AWS.","ar":"مثالي لعميل السحابة الذي يحتاج إلى إمكانيات متقدمة للتحقق والتصحيح من البنية التحتية لأمازون ويب سيرفيس."},"recommendation":{"en":"Empowers agents to verify AWS VPC configurations, debug Lambda connection issues, and validate network paths using AWS CLI, Terraform, and CloudWatch, ensuring seamless infrastructure-application interactions.","zh":"赋予代理验证 AWS VPC 配置、调试 Lambda 连接问题、使用 AWS CLI、Terraform 和 CloudWatch 验证网络路径的能力，确保基础设施和应用程序之间的无缝交互。","ja":"AWS VPC 構成の検証、Lambda 接続の問題のデバッグ、AWS CLI、Terraform、CloudWatch を使用したネットワーク パスの検証を行うことができるため、インフラストラクチャとアプリケーションの無縫な相互作用が可能になります。","ko":"AWS VPC 구성 검증, Lambda 연결 문제 디버깅, AWS CLI, Terraform 및 CloudWatch를 사용한 네트워크 경로 유효성 검사를 가능하게 하여 인프라스트럭처와 애플리케이션 간의 무결점 상호 작용을 보장합니다.","es":"Habilita a los agentes a verificar configuraciones de AWS VPC, depurar problemas de conexión de Lambda y validar rutas de red utilizando AWS CLI, Terraform y CloudWatch, garantizando interacciones de infraestructura-aplicación sin problemas.","fr":"Permet aux agents de vérifier les configurations AWS VPC, de déboguer les problèmes de connexion Lambda et de valider les chemins de réseau à l''aide d''AWS CLI, Terraform et CloudWatch, garantissant des interactions infrastructure-application sans problèmes.","de":"Ermöglicht es Agenten, AWS VPC-Konfigurationen zu überprüfen, Lambda-Verbindungsprobleme zu debuggen und Netzwerkpfade mithilfe von AWS CLI, Terraform und CloudWatch zu validieren, um eine nahtlose Infrastruktur-Anwendungs-Interaktion zu gewährleisten.","pt":"Habilita os agentes a verificar configurações de VPC da AWS, depurar problemas de conexão do Lambda e validar caminhos de rede usando AWS CLI, Terraform e CloudWatch, garantindo interações perfeitas entre infraestrutura e aplicativos.","ru":"Позволяет агентам проверять конфигурации VPC от AWS, отлаживать проблемы подключения Lambda и проверять пути сети с помощью AWS CLI, Terraform и CloudWatch, обеспечивая бесперебойное взаимодействие между инфраструктурой и приложениями.","ar":"تمكّن الوكيل من التحقق من إعدادات VPC الخاصة بأمازون ويب سيرفيس، وتصحيح مشكلات الاتصال في Lambda، والتحقق من مسارات الشبكة باستخدام واجهة سطر أوامر أمازون ويب سيرفيس، وTerraform، وCloudWatch، مما يضمن تفاعلًا مثاليًا بين البنية التحتية والتطبيقات."},"useCases":{"en":["Validating AWS VPC configurations before deploying Lambda-in-VPC code","Debugging Lambda connection timeouts and deterministic failure patterns","Investigating network path issues to AWS using CloudWatch logs"],"zh":["在部署 Lambda-in-VPC 代码之前验证 AWS VPC 配置","调试 Lambda 连接超时和确定性故障模式","使用 CloudWatch 日志调查到 AWS 的网络路径问题"],"ja":["Lambda-in-VPC コードをデプロイする前に AWS VPC 構成を検証する","Lambda 接続のタイムアウトと決定的な故障パターンをデバッグする","CloudWatch ログを使用して AWS へのネットワーク パスの問題を調査する"],"ko":["Lambda-in-VPC 코드를 배포하기 전에 AWS VPC 구성 검증","Lambda 연결 시간 초과 및 결정적 실패 패턴 디버깅","CloudWatch 로그를 사용하여 AWS에 대한 네트워크 경로 문제 조사"],"es":["Validar configuraciones de AWS VPC antes de implementar código Lambda-in-VPC","Depurar tiempos de espera de conexión de Lambda y patrones de fallo determinísticos","Investigar problemas de ruta de red a AWS utilizando registros de CloudWatch"],"fr":["Valider les configurations AWS VPC avant de déployer du code Lambda-in-VPC","Déboguer les délais d''attente de connexion Lambda et les modèles de défaillance déterministes","Enquêter sur les problèmes de chemin de réseau vers AWS en utilisant les journaux CloudWatch"],"de":["Überprüfen von AWS VPC-Konfigurationen vor der Bereitstellung von Lambda-in-VPC-Code","Debuggen von Lambda-Verbindungszeitüberschreitungen und deterministischen Ausfallmustern","Untersuchen von Netzwerkpfadproblemen zu AWS unter Verwendung von CloudWatch-Protokollen"],"pt":["Validar configurações de VPC da AWS antes de implantar o código Lambda-in-VPC","Depurar timeouts de conexão do Lambda e padrões de falha determinísticos","Investigar problemas de caminho de rede para a AWS usando logs do CloudWatch"],"ru":["Проверка конфигураций VPC от AWS перед развертыванием кода Lambda-in-VPC","Отладка таймаутов подключения Lambda и детерминированных моделей отказов","Изучение проблем путей сети в AWS с помощью журналов CloudWatch"],"ar":["التحقق من إعدادات VPC الخاصة بأمازون ويب سيرفيس قبل نشر رمز Lambda-in-VPC","تصحيح مشكلات انتهاء وقت انتظار الاتصال في Lambda وأنماط الفشل القاصرة","تحقيق مشكلات مسار الشبكة إلى أمازون ويب سيرفيس باستخدام سجلات CloudWatch"]},"limitations":{"en":["Requires AWS CLI and Terraform setup","Limited to AWS infrastructure","Needs access to CloudWatch logs"],"zh":["需要 AWS CLI 和 Terraform 设置","仅限 AWS 基础设施","需要访问 CloudWatch 日志"],"ja":["AWS CLI と Terraform の設定が必要","AWS インフラストラクチャのみ","CloudWatch ログへのアクセスが必要"],"ko":["AWS CLI 및 Terraform 설정이 필요","AWS 인프라스트럭처만 해당","CloudWatch 로그에 대한 액세스가 필요"],"es":["Requiere configuración de AWS CLI y Terraform","Limitado a infraestructura de AWS","Necesita acceso a registros de CloudWatch"],"fr":["Nécessite une configuration AWS CLI et Terraform","Limité à l''infrastructure AWS","Nécessite un accès aux journaux CloudWatch"],"de":["Benötigt AWS CLI- und Terraform-Setup","Begrenzt auf AWS-Infrastruktur","Benötigt Zugriff auf CloudWatch-Protokolle"],"pt":["Requer configuração da AWS CLI e do Terraform","Limitado à infraestrutura da AWS","Necessita acesso a logs do CloudWatch"],"ru":["Требует настройки AWS CLI и Terraform","Ограничен инфраструктурой AWS","Требует доступа к журналам CloudWatch"],"ar":["يتطلب إعداد واجهة سطر أوامر أمازون ويب سيرفيس وTerraform","محدود بالبنية التحتية لأمازون ويب سيرفيس","يحتاج إلى الوصول إلى سجلات CloudWatch"]},"version":4},"contentHash":"1ffdac027f6627f06b18e34fdbbcbcf314c2185fbd2ebdf0a9343ad4e9547cf8","qualityScore":57}');
DELETE FROM skills_fts WHERE id = 'Awannaphasch2016/jousef-landing/infrastructure-verification';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Awannaphasch2016/jousef-landing/infrastructure-verification', 'infrastructure-verification', 'Awannaphasch2016', 'jousef-landing', 'community', 'infrastructure-verification Awannaphasch2016 jousef-landing community The infrastructure-verification skill helps developers validate AWS VPC configurations and debug Lambda connection issues. It benefits developers working with AWS CLI, Terraform, and CloudWatch. 基础设施验证技能用于验证AWS基础设施，包括VPC、CloudWatch和Lambda函数，通过AWS CLI和Terraform进行设置和调试 インフラストラクチャ検証スキルは、VPC、CloudWatch、Lambda関数を含むAWSインフラストラクチャを検証するために使用され、AWS CLIとTerraformを使用して設定とデバッグを行います 인프라스트럭처 확인 기술은 VPC, CloudWatch, Lambda 함수를 포함한 AWS 인프라스트럭처를 확인하는 데 사용되며, AWS CLI와 Terraform을 사용하여 설정과 디버깅을 수행합니다 La verificación de infraestructura es crucial para asegurar la conectividad y el rendimiento de tus aplicaciones. Aprende a utilizar AWS CLI y Terraform para verificar tu infraestructura La vérification d''infrastructure est essentielle pour assurer la connectivité et les performances de vos applications. Découvrez comment utiliser AWS CLI et Terraform pour vérifier votre infrastructure Die Infrastruktur-Verifizierung ist entscheidend, um die Konnektivität und Leistung Ihrer Anwendungen zu gewährleisten. Erfahren Sie, wie Sie AWS CLI und Terraform verwenden, um Ihre Infrastruktur zu überprüfen A habilidade de verificação de infraestrutura ajuda a depurar timeouts de conexão Lambda e a validar o caminho de rede para a AWS utilizando AWS CLI, Terraform e CloudWatch ИИ Агенты для верификации инфраструктуры помогают отлаживать таймауты подключения Lambda и проверять сетевой путь к AWS с помощью AWS CLI, Terraform и CloudWatch مهارة التحقق من البنية التحتية تساعد على تصحيح أخطاء التأخيرات في الاتصال Lambda و التحقق من مسار الشبكة إلى AWS باستخدام AWS CLI و Terraform و CloudWatch how to use infrastructure-verification infrastructure-verification setup guide AWS VPC validation tools debugging Lambda connection timeouts infrastructure-verification alternative infrastructure-verification vs Terraform installing infrastructure-verification infrastructure-verification best practices validating AWS infrastructure configurations 基础设施验证 AWS CLI Terraform VPC CloudWatch Lambda函数 AIエージェント工具 基础设施设置 基础设施调试 Validates network path to AWS using CloudWatch Debugs Lambda connection timeouts with AWS CLI Supports Terraform for infrastructure-as-code deployments Investigates deterministic failure patterns in Lambda functions Extracts insights from S3 upload timeout investigations Deploys Lambda-in-VPC code with confidence infrastructure-verification is a skill that validates AWS infrastructure configurations using AWS CLI, Terraform, and CloudWatch to ensure reliable Lambda deployments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('beggan78/f2016-6-dif/sport-wizard-translator', 'community', 'beggan78', 'f2016-6-dif', 'beggan78/f2016-6-dif', 'sport-wizard-translator', 0, 0, 57, '2026-03-08T01:57:15.304Z', '2026-03-08T02:01:58.600Z', 'e28e4b4085fc20da49a534e18d0022f6474280ec93f208d3b813142139adba62', '{"id":"beggan78/f2016-6-dif/sport-wizard-translator","name":"sport-wizard-translator","description":{"en":"The sport-wizard-translator skill provides accurate Swedish translations for soccer coaching applications, utilizing deep context analysis and domain-specific terminology. It benefits soccer coaches and developers creating 5v5 coaching tools.","zh":"Sport WizardTranslator是一个AI工具，使用深度上下文分析和领域特定术语将Sport Wizard应用程序文本翻译成自然的瑞典语","ja":"Sport WizardTranslatorは、深いコンテキスト分析とドメイン適切な用語を使用して、Sport Wizardアプリケーションのテキストを自然なスウェーデン語に翻訳するAIエージェントです","ko":"Sport WizardTranslator는 깊은 문맥 분석 및 도메인 적합 용어를 사용하여 Sport Wizard 애플리케이션 텍스트를 자연스러운 스웨덴어로 번역하는 AI 에이전트입니다","es":"sport-wizard-translator es una herramienta de traducción de texto que utiliza análisis de contexto profundo y terminología de fútbol para traducir aplicaciones de manera natural","fr":"sport-wizard-translator est un outil de traduction de texte qui utilise l''analyse de contexte approfondie et la terminologie de football pour traduire les applications de manière naturelle","de":"sport-wizard-translator ist ein Textübersetzungstool, das eine tiefe Kontextanalyse und Fußballterminologie nutzt, um Anwendungen natürlich zu übersetzen","pt":"O sport-wizard-translator é um ajudante de treinador de futebol para traduzir textos de futebol com precisão e contexto","ru":"ИИ Агент sport-wizard-translator предназначен для перевода футбольных терминов с учетом контекста","ar":"sport-wizard-translator هو مساعد مدرب كرة قدم لترجمة نصوص كرة القدم بدقة وسياق"},"seo":{"title":{"en":"sport-wizard-translator: Sw