INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('beggan78/f2016-6-dif/sport-wizard-translator', 'sport-wizard-translator', 'beggan78', 'f2016-6-dif', 'community', 'sport-wizard-translator beggan78 f2016-6-dif community The sport-wizard-translator skill provides accurate Swedish translations for soccer coaching applications, utilizing deep context analysis and domain-specific terminology. It benefits soccer coaches and developers creating 5v5 coaching tools. Sport WizardTranslator是一个AI工具，使用深度上下文分析和领域特定术语将Sport Wizard应用程序文本翻译成自然的瑞典语 Sport WizardTranslatorは、深いコンテキスト分析とドメイン適切な用語を使用して、Sport Wizardアプリケーションのテキストを自然なスウェーデン語に翻訳するAIエージェントです Sport WizardTranslator는 깊은 문맥 분석 및 도메인 적합 용어를 사용하여 Sport Wizard 애플리케이션 텍스트를 자연스러운 스웨덴어로 번역하는 AI 에이전트입니다 sport-wizard-translator es una herramienta de traducción de texto que utiliza análisis de contexto profundo y terminología de fútbol para traducir aplicaciones de manera natural sport-wizard-translator est un outil de traduction de texte qui utilise l''analyse de contexte approfondie et la terminologie de football pour traduire les applications de manière naturelle sport-wizard-translator ist ein Textübersetzungstool, das eine tiefe Kontextanalyse und Fußballterminologie nutzt, um Anwendungen natürlich zu übersetzen O sport-wizard-translator é um ajudante de treinador de futebol para traduzir textos de futebol com precisão e contexto ИИ Агент sport-wizard-translator предназначен для перевода футбольных терминов с учетом контекста sport-wizard-translator هو مساعد مدرب كرة قدم لترجمة نصوص كرة القدم بدقة وسياق how to use sport-wizard-translator sport-wizard-translator alternative sport-wizard-translator setup guide what is sport-wizard-translator sport-wizard-translator vs Google Translate sport-wizard-translator install for soccer coaching apps AI工具 Sport WizardTranslator 深度上下文分析 领域特定术语 自然语言处理 机器翻译 Performs deep context analysis to understand component context before translation Utilizes domain-appropriate Swedish soccer terminology for accurate translations Prioritizes natural Swedish phrasing over literal translations Maintains consistency with existing translation patterns in the codebase sport-wizard-translator is a specialized AI agent skill for translating Sport Wizard application text into natural, context-aware Swedish with proper soccer terminology.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pydantic/monty/python-playground', 'community', 'pydantic', 'monty', 'pydantic/monty', 'python-playground', 0, 0, 57, '2026-03-08T01:57:15.308Z', '2026-03-08T02:02:23.065Z', '2c73c1e1811973007d2774e3ef1d33dfb70cd8deb130b27c236c0f212348c044', '{"id":"pydantic/monty/python-playground","name":"python-playground","description":{"en":"The python-playground skill provides a secure Python interpreter for AI agents to run and test Python code in an isolated playground directory. This skill benefits AI developers and testers.","zh":"Python Playground 是一个使用 Rust 编写的安全 Python 解释器，允许您在隔离环境中运行 Python 代码。它支持测试和实验","ja":"Python Playground は、Rust で作成された安全な Python インタープリターで、隔離された環境で Python コードを実行できます。テストと実験に最適","ko":"Python Playground는 Rust로 작성된 보안 Python 인터프리터로, 격리된 환경에서 Python 코드를 실행할 수 있습니다. 테스트 및 실험에 적합","es":"Python-playground es un intérprete de Python minimal y seguro escrito en Rust para uso en agentes de IA, que permite ejecutar código Python en un directorio de playground aislado","fr":"Python-playground est un interpréteur Python minimal et sécurisé écrit en Rust pour les outils d''IA, qui permet d''exécuter du code Python dans un répertoire de playground isolé","de":"Python-playground ist ein minimalistischer und sicherer Python-Interpreter in Rust für KI-Tools, der die Ausführung von Python-Code in einem isolierten Playground-Verzeichnis ermöglicht","pt":"O python-playground é um interpretador Python mínimo e seguro escrito em Rust para testes e experimentação em AI. Ele permite executar código Python em um diretório de playground isolado.","ru":"Python-playground - это минимальный и безопасный интерпретатор Python на Rust для тестирования и экспериментов в ИИ Агентах. Он позволяет запускать код Python в изолированном каталоге playground.","ar":"python-playground هو محرك Python الأساسي والأمن مكتوب بلغة Rust للاختبارات والتجارب في أدوات الذكاء الاصطناعي. يسمح بتشغيل 코드 Python في دليل معزول للعب"},"seo":{"title":{"en":"python-playground: Secure Python Interpreter Setup Guide ...","zh":"Python Playground 安装指南 - 使用 Rust 编写的安全 Python 解释器","ja":"Python Playground セットアップガイド - AI エージェント用の Rust 製 Python イ...","ko":"Python Playground 설정 가이드 - Rust로 작성된 보안 Python 인터프리터","es":"Guía de configuración de python-playground para agentes d...","fr":"Guide de mise en place de python-playground pour les outi...","de":"Einrichtungsleitfaden für python-playground unter Verwend...","pt":"Guia de Configuração do python-playground: Interpretador ...","ru":"Настройка python-playground: Безопасный интерпретатор Pyt...","ar":"دليل إعداد python-playground: محرك Python الآمن مكتوب بلغ..."},"description":{"en":"Discover how to run Python code in a secure, isolated environment with python-playground. Learn how to setup and use this minimal Python interpreter written ...","zh":"使用 Python Playground 在隔离环境中运行 Python 代码，测试和实验。了解如何设置和使用这个安全的 Python 解释器","ja":"Python Playground で Python コードを隔離された環境で実行し、テストと実験を行う。設定方法と使い方を学ぶ","ko":"Python Playground에서 Python 코드를 격리된 환경에서 실행하고 테스트 및 실험을 수행합니다. 설정 방법과 사용 방법을 알아보세요","es":"Aprende a configurar python-playground, un intérprete de Python minimal y seguro escrito en Rust para uso en agentes de IA","fr":"Découvrez comment configurer python-playground, un interpréteur Python minimal et sécurisé écrit en Rust pour les outils d''IA","de":"Erfahren Sie, wie Sie python-playground konfigurieren, einen minimalistischen und sicheren Python-Interpreter in Rust für KI-Tools","pt":"Aprenda a configurar o python-playground, um interpretador Python mínimo e seguro escrito em Rust para testes e experimentação em AI","ru":"Узнайте, как настроить python-playground, минимальный и безопасный интерпретатор Python на Rust для тестирования и экспериментов в ИИ Агентах","ar":"تعرف على كيفية إعداد python-playground، محرك Python الأساسي والأمن مكتوب بلغة Rust للاختبارات والتجارب في أدوات الذكاء الاصطناعي"},"definition":{"en":"python-playground is a minimal, secure Python interpreter written in Rust, allowing AI agents to run Python code in a safe and isolated environment.","zh":"Python Playground 是一种使用 Rust 编写的安全 Python 解释器","ja":"Python Playground は、Rust で作成された安全な Python インタープリターです","ko":"Python Playground는 Rust로 작성된 보안 Python 인터프리터입니다","es":"Python-playground es un intérprete de Python minimal y seguro que permite ejecutar código Python en un entorno aislado para agentes de IA","fr":"Python-playground est un interpréteur Python minimal et sécurisé qui permet d''exécuter du code Python dans un environnement isolé pour les outils d''IA","de":"Python-playground ist ein minimalistischer und sicherer Python-Interpreter, der die Ausführung von Python-Code in einer isolierten Umgebung für KI-Tools ermöglicht","pt":"O python-playground é um interpretador Python escrito em Rust para uso em AI, projetado para testes e experimentação em um diretório de playground isolado.","ru":"Python-playground - это интерпретатор Python на Rust для использования в ИИ Агентах, предназначенный для тестирования и экспериментов в изолированном каталоге playground.","ar":"python-playground هو محرك Python مكتوب بلغة Rust للاستخدام في أدوات الذكاء الاصطناعي، مصمم للاختبارات والتجارب في دليل معزول للعب"},"features":{"en":["Runs Python code in an isolated playground directory for testing and experimentation","Supports testing of cpython behavior using `uv run` command","Allows testing of monty behavior using `cargo run` command","Creates a Python file at `playground/test.py` using the Write tool","Requires separate tool calls for each step, without chaining commands with `&&` or using heredocs"],"zh":["使用 Rust 编写，确保安全性","支持在隔离环境中运行 Python 代码","提供 uv 和 cargo 两种运行方式","支持测试和实验","使用 mkdir 和 Write 工具创建 playground 目录和文件","使用 uv run 和 cargo run 命令运行 Python 代码"],"ja":["Rust で作成されており、セキュリティが確保されている","隔離された環境で Python コードを実行できる","uv と cargo の 2 つの実行方法を提供","テストと実験をサポート","mkdir と Write ツールを使用して playground ディレクトリとファイルを作成","uv run と cargo run コマンドを使用して Python コードを実行"],"ko":["Rust로 작성되어 보안성이 확보됨","격리된 환경에서 Python 코드를 실행할 수 있음","uv와 cargo 두 가지 실행 방법을 제공함","테스트 및 실험을 지원함","mkdir 및 Write 도구를 사용하여 playground 디렉토리와 파일을 생성","uv run 및 cargo run 명령을 사용하여 Python 코드를 실행"],"es":["Intérprete de Python minimal y seguro","Escrito en Rust para uso en agentes de IA","Ejecución de código Python en un directorio de playground aislado","Compatibilidad con cpython y monty","Uso de herramientas como Write y uv para la ejecución de código","Soporte para la creación de archivos Python en el directorio de playground"],"fr":["Interpréteur Python minimal et sécurisé","Écrit en Rust pour les outils d''IA","Exécution de code Python dans un répertoire de playground isolé","Compatibilité avec cpython et monty","Utilisation d''outils comme Write et uv pour l''exécution de code","Prise en charge de la création de fichiers Python dans le répertoire de playground"],"de":["Minimalistischer und sicherer Python-Interpreter","In Rust für KI-Tools geschrieben","Ausführung von Python-Code in einem isolierten Playground-Verzeichnis","Kompatibilität mit cpython und monty","Verwendung von Tools wie Write und uv für die Code-Ausführung","Unterstützung für die Erstellung von Python-Dateien im Playground-Verzeichnis"],"pt":["Execução de código Python em um diretório de playground isolado","Suporte a testes de comportamento de cpython e monty","Uso de comandos separados para cada etapa do processo","Escrita em Rust para garantir segurança e desempenho","Permite testar e experimentar código Python de forma segura"],"ru":["Запуск кода Python в изолированном каталоге playground","Поддержка тестирования поведения cpython и monty","Использование отдельных команд для каждой стадии процесса","Написан на Rust для обеспечения безопасности и производительности","Позволяет тестировать и экспериментировать с кодом Python в безопасной форме"],"ar":["تشغيل код Python في دليل معزول للعب","دعم اختبار سلوك cpython و monty","استخدام أوامر منفصلة لكل مرحلة من مراحل العملية","كتابة بلغة Rust لضمان الأمان والأداء","يسمح باختبار وتجريب код Python بشكل آمن"]},"keywords":{"en":["how to use python-playground","python-playground setup guide","python-playground alternative","python-playground vs rust-python","python-playground install","secure python interpreter for AI","isolated python environment","rust-based python interpreter"],"zh":["Python Playground","Rust Python 解释器","安全 Python 解释器","隔离环境","Python 测试","Python 实验","AI 工具","AI 에ージェント","Python 编程"],"ja":["Python Playground","Rust Python インタープリター","安全な Python インタープリター","隔離された環境","Python テスト","Python 実験","AI エージェント","AI ツール","Python プログラミング"],"ko":["Python Playground","Rust Python 인터프리터","보안 Python 인터프리터","격리된 환경","Python 테스트","Python 실험","AI 에이전트","AI 도구","Python 프로그래밍"],"es":["python-playground","agentes de IA","intérprete de Python","Rust","seguridad","playground","cpython","monty"," Write","uv"],"fr":["python-playground","outils d''IA","interpréteur Python","Rust","sécurité","playground","cpython","monty","Write","uv"],"de":["python-playground","KI-Tools","Python-Interpreter","Rust","Sicherheit","Playground","cpython","monty","Write","uv"],"pt":["python-playground","interpretador python","rust","ai","testes de python","comportamento de cpython","comportamento de monty","desenvolvimento de ai","segurança em python"],"ru":["python-playground","интерпретатор python","rust","ИИ Агенты","тестирование python","поведение cpython","поведение monty","разработка ИИ","безопасность в python"],"ar":["python-playground","محرك python","rust","أدوات الذكاء الاصطناعي","اختبارات python","سلوك cpython","سلوك monty","تطوير الذكاء الاصطناعي","أمان في python"]}},"owner":"pydantic","repo":"monty","repoPath":"pydantic/monty","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.308Z","topics":[],"category":"community","skillMd":{"name":"python-playground","description":"Run and test Python code in a dedicated playground directory. Use when you need to execute Python scripts, test code snippets, investigate CPython behavior, or experiment with Python without affecting the main codebase.","bodyPreview":"# Python Playground\n\nRun Python code in an isolated playground directory for testing and experimentation.\n\n## Instructions\n\n1. First, ensure the playground directory exists: `mkdir -p playground`\n2. Use the Write tool to create the Python file at `playground/test.py`\n3. Run with: `uv run playground/test.py` to test cpython behavior or `cargo run -- playground/test.py` to test monty behavior\n\nIMPORTANT: Use separate tool calls for each step - do NOT chain commands with `&&` or use heredocs. This","body":"# Python Playground\n\nRun Python code in an isolated playground directory for testing and experimentation.\n\n## Instructions\n\n1. First, ensure the playground directory exists: `mkdir -p playground`\n2. Use the Write tool to create the Python file at `playground/test.py`\n3. Run with: `uv run playground/test.py` to test cpython behavior or `cargo run -- playground/test.py` to test monty behavior\n\nIMPORTANT: Use separate tool calls for each step - do NOT chain commands with `&&` or use heredocs. This allows the pre-approved commands to work without prompting.\n\n## Example workflow\n\nStep 1 - Create directory (Bash, already allowed):\n```bash\nmkdir -p playground\n```\n\nStep 2 - Write code (use Write tool, not cat):\nWrite to `playground/test.py`:\n```python\ndef foo():\n    raise ValueError(''test'')\n\nfoo()\n```\n\nStep 3 - Run script (Bash, already allowed):\n```bash\nuv run playground/test.py\n```\n\n## Guidelines\n\n- The `playground/` directory is gitignored\n- Use a different file name for each test you want to run, give the files recognizable names like `test_value_error.py`\n- Use `uv run ...` to run scripts (uses project Python)\n- Or, `cargo run -- ...` to run scripts using Monty\n- Use Write tool for creating files (avoids permission prompts)\n- Run mkdir and uv as separate commands (not chained)\n- do NOT delete files from playground after you''ve finished testing\n"},"lastSynced":"2026-03-08T02:02:23.065Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Analysis Agents needing a secure environment for testing and experimenting with Python code.","zh":"非常适合需要安全环境来测试和实验Python代码的Python分析代理。","ja":"Pythonコードを安全な環境でテストおよび実験する必要があるPython分析エージェントに最適です。","ko":"Python 코드를 안전한 환경에서 테스트하고 실험해야 하는 Python 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de análisis de Python que necesitan un entorno seguro para probar y experimentar con código Python.","fr":"Parfait pour les agents d''analyse Python ayant besoin d''un environnement sécurisé pour tester et expérimenter du code Python.","de":"Perfekt für Python-Analyse-Agents, die ein sicheres Umfeld für das Testen und Experimentieren mit Python-Code benötigen.","pt":"Perfeito para Agentes de Análise Python que necessitam de um ambiente seguro para testar e experimentar código Python.","ru":"Идеально для агентов анализа Python, которым требуется безопасная среда для тестирования и экспериментов с кодом Python.","ar":"مثالي لعميل تحليل بايثون الذي يحتاج إلى بيئة آمنة لاختبار وتجربة رمز بايثون."},"recommendation":{"en":"Empowers agents to run and test Python code in an isolated playground directory, utilizing tools like uv and cargo for cpython and monty behavior testing, while ensuring secure execution through separate tool calls and avoiding command chaining with && or heredocs.","zh":"使代理能够在隔离的游乐场目录中运行和测试Python代码，利用像uv和cargo这样的工具来测试cpython和monty行为，同时通过单独的工具调用来确保安全执行，并避免使用&&或heredocs进行命令链式调用。","ja":"エージェントが隔離されたプレイグラウンドディレクトリでPythonコードを実行およびテストできるようにし、uvやcargoなどのツールを使用してcpythonとmontyの動作をテストする，同时、別々のツールコールを使用して安全な実行を保証し、&&またはheredocsを使用したコマンドの連結を回避します。","ko":"에이전트가 분리된 플레이그라운드 디렉토리에서 Python 코드를 실행하고 테스트할 수 있도록 하며, uv와 cargo 같은 도구를 사용하여 cpython과 monty 동작을 테스트하는 동시에 별도의 도구 호출을 통해 안전한 실행을 보장하고 && 또는 heredocs를 사용한 명령어 연쇄 호출을 피합니다.","es":"Habilita a los agentes a ejecutar y probar código Python en un directorio de área de juego aislado, utilizando herramientas como uv y cargo para pruebas de comportamiento de cpython y monty, asegurando al mismo tiempo la ejecución segura a través de llamadas de herramientas separadas y evitando la cadena de comandos con && o heredocs.","fr":"Permet aux agents d''exécuter et de tester du code Python dans un répertoire de zone de jeu isolé, en utilisant des outils comme uv et cargo pour les tests de comportement de cpython et monty, tout en assurant l''exécution sécurisée grâce à des appels d''outils séparés et en évitant la chaîne de commandes avec && ou heredocs.","de":"Ermächtigt Agenten, Python-Code in einem isolierten Spielbereichsverzeichnis auszuführen und zu testen, indem Tools wie uv und cargo für cpython- und monty-VerhaltensTests verwendet werden, während gleichzeitig sichere Ausführung durch separate Toolaufrufe sichergestellt und Befehlsverkettung mit && oder heredocs vermieden wird.","pt":"Habilita os agentes a executar e testar código Python em um diretório de playground isolado, utilizando ferramentas como uv e cargo para testar o comportamento do cpython e monty, garantindo execução segura por meio de chamadas de ferramentas separadas e evitando encadeamento de comandos com && ou heredocs.","ru":"Наделяет агентов возможностью запускать и тестировать код Python в изолированном каталоге playground, используя инструменты seperti uv и cargo для тестирования поведения cpython и monty, обеспечивая безопасную выполнение за счет отдельных вызовов инструментов и избегая цепочки команд с && или heredocs.","ar":"يمنح الوكلاء khảية تشغيل واختبار رمز بايثون في دليل لعب معزول ، باستخدام أدوات مثل uv و cargo لاختبار سلوك cpython و monty ، وضمان التنفيذ الآمن من خلال مكالمات أداة منفصلة وتجنب تسلسل الأوامر مع && أو heredocs."},"useCases":{"en":["Testing Python scripts in a sandboxed environment","Debugging cpython behavior with uv","Experimenting with monty behavior using cargo"],"zh":["在沙盒环境中测试Python脚本","使用uv调试cpython行为","使用cargo实验monty行为"],"ja":["サンドボックス環境でPythonスクリプトをテストする","uvを使用してcpythonの動作をデバッグする","cargoを使用してmontyの動作を実験する"],"ko":["샌드박스 환경에서 Python 스크립트를 테스트하는 것","uv를 사용하여 cpython 동작을 디버깅하는 것","cargo를 사용하여 monty 동작을 실험하는 것"],"es":["Probar scripts de Python en un entorno aislado","Depurar el comportamiento de cpython con uv","Experimentar con el comportamiento de monty utilizando cargo"],"fr":["Tester des scripts Python dans un environnement isolé","Déboguer le comportement de cpython avec uv","Expérimenter le comportement de monty en utilisant cargo"],"de":["Python-Skripte in einer abgesicherten Umgebung testen","cpython-Verhalten mit uv debuggen","Mit cargo das Verhalten von monty experimentieren"],"pt":["Testar scripts Python em um ambiente isolado","Depurar comportamento do cpython com uv","Experimentar comportamento do monty usando cargo"],"ru":["Тестировать скрипты Python в изолированной среде","Отлаживать поведение cpython с uv","Экспериментировать с поведением monty с помощью cargo"],"ar":["اختبار سكريبتات بايثون في بيئة معزولة","تصحيح أخطاء سلوك cpython مع uv","التجربة مع سلوك monty باستخدام cargo"]},"limitations":{"en":["Requires separate tool calls for each step","No command chaining with && or heredocs allowed","Playground directory must exist and be accessible"],"zh":["需要为每个步骤调用单独的工具","不允许使用&&或heredocs进行命令链式调用","游乐场目录必须存在且可访问"],"ja":["各ステップごとに別々のツールコールが必要","&&またはheredocsを使用したコマンドの連結は許可されない","プレイグラウンドディレクトリは存在し、かつアクセス可能である必要がある"],"ko":["각 단계마다 별도의 도구 호출이 필요","&& 또는 heredocs를 사용한 명령어 연쇄 호출이 허용되지 않음","플레이그라운드 디렉토리가 존재하고 접근 가능해야 함"],"es":["Requiere llamadas de herramientas separadas para cada paso","No se permite la cadena de comandos con && o heredocs","El directorio de área de juego debe existir y ser accesible"],"fr":["Nécessite des appels d''outils séparés pour chaque étape","La chaîne de commandes avec && ou heredocs n''est pas autorisée","Le répertoire de zone de jeu doit exister et être accessible"],"de":["Benötigt separate Toolaufrufe für jeden Schritt","Befehlsverkettung mit && oder heredocs ist nicht erlaubt","Das Spielbereichsverzeichnis muss existieren und zugänglich sein"],"pt":["Requer chamadas de ferramentas separadas para cada etapa","Não é permitido encadeamento de comandos com && ou heredocs","O diretório de playground deve existir e ser acessível"],"ru":["Требует отдельных вызовов инструментов для каждого шага","Не допускается цепочка команд с && или heredocs","Каталог playground должен существовать и быть доступным"],"ar":["يتطلب مكالمات أداة منفصلة لكل خطوة","لا يسمح بتسلسل الأوامر مع && أو heredocs","يجب أن يكون دليل اللعب موجودًا وقابل الوصول"]},"version":4},"contentHash":"2c73c1e1811973007d2774e3ef1d33dfb70cd8deb130b27c236c0f212348c044","qualityScore":57}');
