INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pydantic/monty/python-playground', 'python-playground', 'pydantic', 'monty', 'community', 'python-playground pydantic monty community The python-playground skill provides a secure Python interpreter for AI agents to run and test Python code in an isolated playground directory. This skill benefits AI developers and testers. Python Playground 是一个使用 Rust 编写的安全 Python 解释器，允许您在隔离环境中运行 Python 代码。它支持测试和实验 Python Playground は、Rust で作成された安全な Python インタープリターで、隔離された環境で Python コードを実行できます。テストと実験に最適 Python Playground는 Rust로 작성된 보안 Python 인터프리터로, 격리된 환경에서 Python 코드를 실행할 수 있습니다. 테스트 및 실험에 적합 Python-playground es un intérprete de Python minimal y seguro escrito en Rust para uso en agentes de IA, que permite ejecutar código Python en un directorio de playground aislado Python-playground est un interpréteur Python minimal et sécurisé écrit en Rust pour les outils d''IA, qui permet d''exécuter du code Python dans un répertoire de playground isolé Python-playground ist ein minimalistischer und sicherer Python-Interpreter in Rust für KI-Tools, der die Ausführung von Python-Code in einem isolierten Playground-Verzeichnis ermöglicht O python-playground é um interpretador Python mínimo e seguro escrito em Rust para testes e experimentação em AI. Ele permite executar código Python em um diretório de playground isolado. Python-playground - это минимальный и безопасный интерпретатор Python на Rust для тестирования и экспериментов в ИИ Агентах. Он позволяет запускать код Python в изолированном каталоге playground. python-playground هو محرك Python الأساسي والأمن مكتوب بلغة Rust للاختبارات والتجارب في أدوات الذكاء الاصطناعي. يسمح بتشغيل 코드 Python في دليل معزول للعب how to use python-playground python-playground setup guide python-playground alternative python-playground vs rust-python python-playground install secure python interpreter for AI isolated python environment rust-based python interpreter Python Playground Rust Python 解释器 安全 Python 解释器 隔离环境 Python 测试 Python 实验 AI 工具 AI 에ージェント Python 编程 Runs Python code in an isolated playground directory for testing and experimentation Supports testing of cpython behavior using `uv run` command Allows testing of monty behavior using `cargo run` command Creates a Python file at `playground/test.py` using the Write tool Requires separate tool calls for each step, without chaining commands with `&&` or using heredocs python-playground is a minimal, secure Python interpreter written in Rust, allowing AI agents to run Python code in a safe and isolated environment.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('whddltjdwhd/bellog/bellog-structure', 'community', 'whddltjdwhd', 'bellog', 'whddltjdwhd/bellog', 'bellog-structure', 0, 0, 57, '2026-03-08T01:57:15.313Z', '2026-03-08T02:02:40.722Z', '6f81045fee9c6740c5d67e788399e84afe2a5cd282f60c799c5928c4bd22811c', '{"id":"whddltjdwhd/bellog/bellog-structure","name":"bellog-structure","description":{"en":"The bellog-structure skill defines the file structure and organization patterns for the Bellog blog project, benefiting developers working with Next.js. It provides a clear project setup for efficient development.","zh":"Bellog 结构定义了 Next.js 项目的文件结构、命名约定和组织模式，帮助开发者优化项目开发","ja":"Bellog 構造は Next.js プロジェクトのファイル構造、命名規約、組織パターンを定義し、開発者がプロジェクト開発を最適化できるようにします","ko":"Bellog 구조는 Next.js 프로젝트의 파일 구조, 이름 규칙, 조직 패턴을 정의하여 개발자가 프로젝트 개발을 최적화할 수 있도록 합니다","es":"Bellog-structure define la estructura de archivos y convenciones de nombramiento para el proyecto de blog Bellog","fr":"Bellog-structure définit la structure de fichiers et les conventions de nommage pour le projet de blog Bellog","de":"Bellog-structure definiert die Dateistruktur und Benennungskonventionen für das Bellog-Blog-Projekt","pt":"O Bellog-structure define a estrutura de arquivos e organização de projetos para o blog do Castle Bell, utilizando Next.js e React.","ru":"Bellog-structure определяет структуру файлов и организацию проекта для блога Castle Bell, используя Next.js и React.","ar":"بلوغ-ستракتشر يحدد هيكل الملفات وتنظيم المشروع لمدونة كاسل بيل، باستخدام Next.js و React."},"seo":{"title":{"en":"bellog-structure: Next.js Project Setup Guide | AI Agent ...","zh":"Bellog 结构设置指南 - Next.js 项目组织最佳实践","ja":"Bellog 構造設定ガイド - Next.js プロジェクト組織のベストプラクティス","ko":"Bellog 구조 설정 가이드 - Next.js 프로젝트 구성 최적화","es":"Guía de estructura de Bellog: Organización de archivos y ...","fr":"Guide de structure Bellog: Organisation de fichiers et co...","de":"Bellog-Struktur-Leitfaden: Dateiorganisation und Benennun...","pt":"Guia de Estrutura do Bellog-Structure para Desenvolvedores","ru":"ИИ Агент Bellog-Structure: Руководство по Настройке","ar":"دليل بنية بلوغ-ستракتشر للبرمجة"},"description":{"en":"Discover how to organize your Bellog blog project with a predefined file structure, naming conventions, and organization patterns. Get started with bellog-st...","zh":"了解 Bellog 项目结构、文件命名约定和组织模式，优化您的 Next.js 项目开发","ja":"Bellog プロジェクト構造、ファイル命名規約、組織パターンを学び、Next.js プロジェクト開発を最適化する","ko":"Bellog 프로젝트 구조, 파일 이름 규칙, 조직 패턴을 익히고 Next.js 프로젝트 개발을 최적화하세요","es":"Aprende a configurar la estructura de tu blog con Bellog, incluyendo la organización de archivos y convenciones de nombramiento","fr":"Découvrez comment configurer la structure de votre blog avec Bellog, y compris l''organisation de fichiers et les conventions de nommage","de":"Erfahren Sie, wie Sie die Struktur Ihres Blogs mit Bellog konfigurieren, einschließlich Dateiorganisation und Benennungskonventionen","pt":"Aprenda a configurar o Bellog-structure com o guia oficial de estrutura de arquivos e organização de projetos para desenvolvedores","ru":"Изучите структуру и организацию проекта Bellog-structure с помощью официального руководства по настройке для ИИ Агентов","ar":"تعلم كيفية تكوين بنية بلوغ-ستракتشر مع دليل الهيكل والتنظيم الرسمي للمشاريع للبرمجة"},"definition":{"en":"bellog-structure is a predefined file organization and naming convention system for the Bellog blog project, utilizing Next.js for efficient development and deployment.","zh":"Bellog 结构是一种 Next.js 项目的文件组织和命名约定","ja":"Bellog 構造は Next.js プロジェクトのファイル組織と命名規約の一種です","ko":"Bellog 구조는 Next.js 프로젝트의 파일 구성 및 이름 규칙의 일종입니다","es":"Bellog-structure es un conjunto de reglas para la organización de archivos y convenciones de nombramiento en el proyecto de blog Bellog","fr":"Bellog-structure est un ensemble de règles pour l''organisation de fichiers et les conventions de nommage dans le projet de blog Bellog","de":"Bellog-structure ist ein Satz von Regeln für die Dateiorganisation und Benennungskonventionen im Bellog-Blog-Projekt","pt":"O que é Bellog-structure? É uma estrutura de arquivos e organização de projetos para o blog do Castle Bell.","ru":"Что такое Bellog-structure? Это структура файлов и организация проекта для блога Castle Bell.","ar":"ما هو بلوغ-ستракتشر؟ هو هيكل الملفات وتنظيم المشروع لمدونة كاسل بيل."},"features":{"en":["Defines a project structure with a src/app directory for Next.js App Router","Includes layout.tsx for root layout with fonts and metadata","Utilizes page.tsx for the home page and template.tsx for page transitions","Supports client-side providers via providers.tsx","Organizes files and directories for efficient Next.js project development"],"zh":["Next.js 项目结构定义","文件命名约定和组织模式","App Router 和页面布局","客户端提供者和页面过渡包装器","支持 TypeScript 和 React"],"ja":["Next.js プロジェクト構造の定義","ファイル命名規約と組織パターン","App Router とページレイアウト","クライアント側プロバイダーとページ遷移ラッパー","TypeScript と React のサポート"],"ko":["Next.js 프로젝트 구조 정의","파일 이름 규칙 및 조직 패턴","App Router 및 페이지 레이아웃","클라이언트 측 제공자 및 페이지 전환 래퍼","TypeScript 및 React 지원"],"es":["Organización de archivos con Next.js App Router","Convenciones de nombramiento para layouts y páginas","Uso de providers para la gestión de estado en el cliente","Transiciones de página con template.tsx","Soporte para fuentes y metadatos en layout.tsx"],"fr":["Organisation de fichiers avec Next.js App Router","Conventions de nommage pour les layouts et les pages","Utilisation de providers pour la gestion de l''état sur le client","Transitions de page avec template.tsx","Prise en charge des polices et des métadonnées dans layout.tsx"],"de":["Dateiorganisation mit Next.js App Router","Benennungskonventionen für Layouts und Seiten","Verwendung von Providers für die Zustandsverwaltung auf dem Client","Seitentransitionen mit template.tsx","Unterstützung für Schriftarten und Metadaten in layout.tsx"],"pt":["Estrutura de arquivos personalizada para o blog do Castle Bell","Utilização de Next.js para roteamento de aplicativos","React para construção de interfaces de usuário","Organização de projetos com pastas e subpastas","Padrões de nomeação de arquivos consistentes"],"ru":["Пользовательская структура файлов для блога Castle Bell","Использование Next.js для маршрутизации приложений","React для построения интерфейсов пользователя","Организация проектов с папками и подпапками","Последовательные шаблоны именования файлов"],"ar":["هيكل ملفات مخصص لمدونة كاسل بيل","استخدام Next.js لتوجيه التطبيقات","React لبناء واجهات المستخدم","تنظيم المشاريع مع المجلدات والفرعي","أنماط تسمية الملفات المتسقة"]},"keywords":{"en":["how to use bellog-structure","bellog-structure setup guide","Next.js project organization","bellog-structure vs custom setup","bellog-structure install","what is bellog-structure","bellog-structure alternative","bellog-structure file structure","Next.js App Router setup"],"zh":["Bellog 结构","Next.js 项目组织","文件命名约定","组织模式","App Router","页面布局","客户端提供者","TypeScript","React"],"ja":["Bellog 構造","Next.js プロジェクト組織","ファイル命名規約","組織パターン","App Router","ページレイアウト","クライアント側プロバイダー","TypeScript","React"],"ko":["Bellog 구조","Next.js 프로젝트 구성","파일 이름 규칙","조직 패턴","App Router","페이지 레이아웃","클라이언트 측 제공자","TypeScript","React"],"es":["Bellog-structure","organización de archivos","convenciones de nombramiento","Next.js App Router","providers","transiciones de página","layout.tsx","template.tsx"],"fr":["Bellog-structure","organisation de fichiers","conventions de nommage","Next.js App Router","providers","transitions de page","layout.tsx","template.tsx"],"de":["Bellog-structure","Dateiorganisation","Benennungskonventionen","Next.js App Router","Providers","Seitentransitionen","layout.tsx","template.tsx"],"pt":["Bellog-structure","estrutura de arquivos","Next.js","React","organização de projetos","roteamento de aplicativos","construção de interfaces de usuário","padrões de nomeação de arquivos"],"ru":["Bellog-structure","структура файлов","Next.js","React","организация проектов","маршрутизация приложений","построение интерфейсов пользователя","шаблоны именования файлов"],"ar":["بلوغ-ستракتشر","هيكل الملفات","Next.js","React","تنظيم المشاريع","توجيه التطبيقات","بناء واجهات المستخدم","أنماط تسمية الملفات"]}},"owner":"whddltjdwhd","repo":"bellog","repoPath":"whddltjdwhd/bellog","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.313Z","topics":[],"category":"community","skillMd":{"name":"bellog-structure","description":"Provides file organization and naming conventions for the Bellog project. Triggers when creating new files or reorganizing code.","bodyPreview":"# Bellog File Organization\n\nThis skill defines the file structure, naming conventions, and organization patterns for the Bellog blog project.\n\n## Project Structure\n\n```\n/Users/castle_bell/Projects/bellog/\n├── src/\n│   ├── app/                    # Next.js App Router\n│   │   ├── layout.tsx          # Root layout with fonts & metadata\n│   │   ├── page.tsx            # Home page\n│   │   ├── template.tsx        # Page transition wrapper\n│   │   ├── providers.tsx       # Client-side providers\n│   │","body":"# Bellog File Organization\n\nThis skill defines the file structure, naming conventions, and organization patterns for the Bellog blog project.\n\n## Project Structure\n\n```\n/Users/castle_bell/Projects/bellog/\n├── src/\n│   ├── app/                    # Next.js App Router\n│   │   ├── layout.tsx          # Root layout with fonts & metadata\n│   │   ├── page.tsx            # Home page\n│   │   ├── template.tsx        # Page transition wrapper\n│   │   ├── providers.tsx       # Client-side providers\n│   │   ├── posts/\n│   │   │   ├── page.tsx        # All posts page\n│   │   │   └── [slug]/\n│   │   │       └── page.tsx    # Individual post\n│   │   ├── api/\n│   │   │   └── revalidate/\n│   │   │       └── route.ts    # Cache revalidation endpoint\n│   │   ├── robots.ts           # SEO robots.txt\n│   │   └── sitemap.ts          # Dynamic sitemap\n│   │\n│   ├── components/\n│   │   ├── common/             # App-wide shared components\n│   │   │   ├── Navbar.tsx\n│   │   │   ├── Footer.tsx\n│   │   │   ├── Intro.tsx\n│   │   │   ├── Header.tsx\n│   │   │   └── ...\n│   │   ├── posts/              # Post-specific components\n│   │   │   ├── PostCard.tsx\n│   │   │   ├── PostList.tsx\n│   │   │   ├── PostRenderer.tsx\n│   │   │   ├── NotionToc.tsx\n│   │   │   └── ...\n│   │   └── ui/                 # Low-level UI primitives\n│   │       ├── Tag.tsx\n│   │       ├── ThemeToggle.tsx\n│   │       ├── switch.tsx\n│   │       └── ...\n│   │\n│   ├── hooks/                  # Custom React hooks\n│   │   ├── useScrollSpy.ts\n│   │   ├── useTocObserver.ts\n│   │   └── useHeadings.ts\n│   │\n│   ├── lib/                    # Business logic & utilities\n│   │   ├── notion.ts           # Notion API client\n│   │   ├── posts.ts            # Post data fetching\n│   │   ├── tags.ts             # Tag utilities\n│   │   └── utils.ts            # General utilities\n│   │\n│   ├── constants/              # Shared constants\n│   │   └── ui.ts               # UI-related constants\n│   │\n│   ├── types/                  # TypeScript types\n│   │   └── index.d.ts          # Global type definitions\n│   │\n│   └── styles/                 # Global styles\n│       └── global.css          # Theme variables + Tailwind\n│\n├── public/                     # Static assets\n├── .claude/                    # Claude Code configuration\n│   ├── agents/                 # Custom sub-agents\n│   └── skills/                 # Custom skills\n├── .github/                    # GitHub configuration\n│   └── PULL_REQUEST_TEMPLATE.md\n├── .husky/                     # Git hooks\n├── tailwind.config.ts          # Tailwind configuration\n├── tsconfig.json               # TypeScript configuration\n├── next.config.ts              # Next.js configuration\n├── package.json                # Dependencies & scripts\n├── commitlint.config.ts        # Commit message linting\n├── CLAUDE.md                   # Project guide\n└── README.md                   # Project documentation\n```\n\n## Naming Conventions\n\n### Components\n\n**Rule:** PascalCase\n\n```\n✅ Correct:\nPostCard.tsx\nNotionToc.tsx\nScrollToTop.tsx\nThemeToggle.tsx\n\n❌ Wrong:\npostCard.tsx\nnotion-toc.tsx\nscroll_to_top.tsx\n```\n\n### Hooks\n\n**Rule:** camelCase with `use` prefix\n\n```\n✅ Correct:\nuseScrollSpy.ts\nuseTocObserver.ts\nuseHeadings.ts\nuseScrollPosition.ts\n\n❌ Wrong:\nUseScrollSpy.ts\nscroll-spy-hook.ts\nscrollSpy.ts (missing use prefix)\n```\n\n### Utilities & Libraries\n\n**Rule:** camelCase\n\n```\n✅ Correct:\nnotion.ts\nposts.ts\ntags.ts\nutils.ts\n\n❌ Wrong:\nNotion.ts\nPosts.ts\ntag-utils.ts\n```\n\n### Types\n\n**Rule:** camelCase file, PascalCase exports\n\n```\n✅ Correct:\nFile: index.d.ts\nExport: interface Post { }\nExport: type PostStatus = ''published'' | ''draft'';\n\n❌ Wrong:\nFile: Post.d.ts\nExport: interface post { }\n```\n\n### Constants\n\n**Rule:** SCREAMING_SNAKE_CASE for values, camelCase for file\n\n```\n✅ Correct:\nFile: ui.ts\nExports:\n  export const HEADER_OFFSET = 80;\n  export const SCROLL_SPY_OFFSET = 100;\n\n❌ Wrong:\nexport const headerOffset = 80;\nexport const header-offset = 80;\n```\n\n### API Routes\n\n**Rule:** camelCase folder, route.ts file\n\n```\n✅ Correct:\napp/api/revalidate/route.ts\n\n❌ Wrong:\napp/api/Revalidate/route.ts\napp/api/revalidate/revalidate.ts\n```\n\n## Where to Place Files\n\n### Decision Tree\n\n**Q: Is it a React component?**\n- Yes → `/src/components/`\n  - App-wide (Navbar, Footer) → `/src/components/common/`\n  - Post-specific (PostCard, NotionToc) → `/src/components/posts/`\n  - Reusable UI primitive (Tag, Button) → `/src/components/ui/`\n\n**Q: Is it a custom hook?**\n- Yes → `/src/hooks/use[Name].ts`\n\n**Q: Is it business logic or data fetching?**\n- Yes → `/src/lib/`\n  - Notion API → `/src/lib/notion.ts`\n  - Post data → `/src/lib/posts.ts`\n  - Utility functions → `/src/lib/utils.ts`\n\n**Q: Is it a constant value?**\n- Yes → `/src/constants/`\n  - UI-related → `/src/constants/ui.ts`\n  - API-related → `/src/constants/api.ts`\n\n**Q: Is it a TypeScript type?**\n- Yes → `/src/types/index.d.ts`\n\n**Q: Is it a page or route?**\n- Yes → `/src/app/[route]/page.tsx`\n\n**Q: Is it an API endpoint?**\n- Yes → `/src/app/api/[endpoint]/route.ts`\n\n## Component Organization\n\n### Common Components (`/src/components/common/`)\n\nComponents used across multiple pages:\n- Layout components (Navbar, Footer)\n- Page sections (Intro, Header)\n- Shared widgets (ProgressBar)\n\n**Examples:**\n- `Navbar.tsx` - Site navigation\n- `Footer.tsx` - Site footer\n- `Intro.tsx` - Hero section with animations\n- `ProgressBar.tsx` - Scroll progress indicator\n- `Header.tsx` - Page headers\n\n### Post Components (`/src/components/posts/`)\n\nComponents specific to blog posts:\n- Post rendering (PostRenderer)\n- Post navigation (NotionToc, PostNavigation)\n- Post lists (PostList, PostCard)\n\n**Examples:**\n- `PostCard.tsx` - Individual post preview\n- `PostList.tsx` - Grid of post cards\n- `PostRenderer.tsx` - Notion content renderer\n- `NotionToc.tsx` - Table of contents\n- `PostNavigation.tsx` - Previous/Next navigation\n- `GiscusComments.tsx` - Comment system\n\n### UI Components (`/src/components/ui/`)\n\nLow-level, reusable UI primitives:\n- Buttons, inputs, switches\n- Tags, badges\n- Shadcn/ui components\n\n**Examples:**\n- `Tag.tsx` - Tag display\n- `TagList.tsx` - Tag filtering\n- `ThemeToggle.tsx` - Dark/light mode toggle\n- `switch.tsx` - Radix UI switch (shadcn/ui)\n\n## File Templates\n\n### Component Template\n\n```typescript\n// For interactive components\n\"use client\";\n\nimport { useState } from ''react'';\nimport { motion } from ''framer-motion'';\n\ninterface ComponentNameProps {\n  // Props\n}\n\nexport function ComponentName({ }: ComponentNameProps) {\n  // Logic\n\n  return (\n    <div>\n      {/* JSX */}\n    </div>\n  );\n}\n```\n\n### Hook Template\n\n```typescript\nimport { useState, useEffect } from ''react'';\n\n/**\n * Brief description of what this hook does\n *\n * @example\n * const value = useHookName();\n */\nexport function useHookName() {\n  // Hook logic\n\n  return value;\n}\n```\n\n### Utility Template\n\n```typescript\n/**\n * Brief description of utility function\n *\n * @param paramName - Description\n * @returns Description\n */\nexport function utilityName(paramName: Type): ReturnType {\n  // Implementation\n}\n```\n\n### Type Definition Template\n\n```typescript\n// /src/types/index.d.ts\n\nexport interface Post {\n  id: string;\n  title: string;\n  slug: string;\n  date: string;\n  description: string;\n  tags: string[];\n  status: PostStatus;\n}\n\nexport type PostStatus = ''published'' | ''draft'' | ''archived'';\n```\n\n## Import Organization\n\n### Order\n\n```typescript\n// 1. React & Next.js\nimport { useState } from ''react'';\nimport Link from ''next/link'';\n\n// 2. Third-party libraries\nimport { motion } from ''framer-motion'';\nimport { Search } from ''lucide-react'';\n\n// 3. Internal imports (@/...)\nimport { Button } from ''@/components/ui/button'';\nimport { getAllPosts } from ''@/lib/posts'';\nimport { HEADER_OFFSET } from ''@/constants/ui'';\n\n// 4. Relative imports\nimport { helperFunction } from ''../utils'';\n\n// 5. Type imports (separate)\nimport type { Post } from ''@/types'';\n```\n\n### Path Aliases\n\nBellog uses `@/` for root imports:\n\n```typescript\n// ✅ Correct\nimport { PostCard } from ''@/components/posts/PostCard'';\nimport { getAllPosts } from ''@/lib/posts'';\nimport { HEADER_OFFSET } from ''@/constants/ui'';\n\n// ❌ Wrong (no relative paths from root)\nimport { PostCard } from ''../../components/posts/PostCard'';\n```\n\n## Code Organization Patterns\n\n### Single Responsibility\n\n```typescript\n// ✅ Good - Each file has one clear purpose\n// /src/lib/notion.ts - Notion API calls\n// /src/lib/posts.ts - Post data transformation\n// /src/lib/tags.ts - Tag utilities\n\n// ❌ Bad - Everything in one file\n// /src/lib/everything.ts\n```\n\n### Group Related Code\n\n```typescript\n// ✅ Good - Related components together\n/src/components/posts/\n  PostCard.tsx\n  PostList.tsx\n  PostNavigation.tsx\n\n// ❌ Bad - All components flat\n/src/components/\n  PostCard.tsx\n  Navbar.tsx\n  PostList.tsx\n  Footer.tsx\n```\n\n### Constants Extraction\n\n```typescript\n// ✅ Good - Constants in separate file\n// /src/constants/ui.ts\nexport const HEADER_OFFSET = 80;\nexport const SCROLL_SPY_OFFSET = 100;\n\n// Component uses constants\nimport { HEADER_OFFSET } from ''@/constants/ui'';\n\n// ❌ Bad - Magic numbers in component\nconst offset = 80; // What is this?\n```\n\n## File Size Guidelines\n\n**Components:** < 200 lines\n- If larger, consider splitting into smaller components\n\n**Hooks:** < 100 lines\n- If larger, consider extracting helper functions\n\n**Utils:** < 50 lines per function\n- If larger, break into smaller functions\n\n**Types:** No limit\n- Types can be long, that''s okay\n\n## Barrel Exports (Avoid)\n\n```typescript\n// ❌ Avoid barrel exports (index.ts files)\n// /src/components/index.ts\nexport { PostCard } from ''./PostCard'';\nexport { PostList } from ''./PostList'';\n\n// ✅ Prefer direct imports\nimport { PostCard } from ''@/components/posts/PostCard'';\nimport { PostList } from ''@/components/posts/PostList'';\n```\n\n**Why:** Barrel exports slow down builds and complicate tree-shaking.\n\n## Environment Files\n\n```\n.env.local          # Local development secrets (gitignored)\n.env.example        # Template (committed to git)\n```\n\n**Never commit:**\n- `.env.local`\n- `.env`\n- Any file with actual secrets\n\n## Git Ignore Patterns\n\nEnsure these are in `.gitignore`:\n\n```\n# Dependencies\nnode_modules/\n.pnp\n.pnp.js\n\n# Next.js\n.next/\nout/\n\n# Environment\n.env.local\n.env\n\n# IDE\n.vscode/\n.idea/\n\n# OS\n.DS_Store\n```\n\n## Documentation Structure\n\n```\n/                           # Root\n├── README.md              # Project overview & setup\n├── CLAUDE.md              # Development guide (for AI)\n└── docs/                  # Detailed documentation (if needed)\n    ├── architecture.md\n    └── deployment.md\n```\n\n## Quick Reference\n\n```\nComponents:     PascalCase.tsx      /src/components/{common,posts,ui}/\nHooks:          useName.ts          /src/hooks/\nUtilities:      name.ts             /src/lib/\nConstants:      NAME                /src/constants/\nTypes:          name.d.ts           /src/types/\nPages:          page.tsx            /src/app/[route]/\nAPI:            route.ts            /src/app/api/[endpoint]/\n```\n\n## Checklist for New Files\n\n- [ ] File in correct directory\n- [ ] Naming convention followed (PascalCase / camelCase)\n- [ ] Imports organized by category\n- [ ] Using @ alias for imports (not relative from root)\n- [ ] TypeScript types defined\n- [ ] No magic numbers (use constants)\n- [ ] Single responsibility (one clear purpose)\n- [ ] File size reasonable (< 200 lines for components)\n\nRemember: Organization is about findability. When someone looks for a file, it should be obvious where it is.\n"},"lastSynced":"2026-03-08T02:02:40.722Z","agentAnalysis":{"suitability":{"en":"Perfect for Next.js Agents needing structured project organization and efficient development workflows.","zh":"适用于需要结构化项目组织和高效开发工作流的 Next.js 代理。","ja":"Next.js エージェントが構造化されたプロジェクト組織と効率的な開発ワークフローを必要とする場合に最適です。","ko":"구조화된 프로젝트 조직과 효율적인 개발 워크플ロー가 필요한 Next.js 에이전트에게 적합합니다.","es":"Perfecto para agentes de Next.js que necesitan una organización de proyectos estructurada y flujos de desarrollo eficientes.","fr":"Parfait pour les agents Next.js ayant besoin d''une organisation de projet structurée et de flux de développement efficaces.","de":"Perfekt für Next.js-Agents, die eine strukturierte Projektorganisation und effiziente Entwicklungsworkflows benötigen.","pt":"Perfeito para Agentes Next.js que necessitam de organização de projeto estruturada e fluxos de desenvolvimento eficientes.","ru":"Идеально для агентов Next.js, которым необходима структурированная организация проекта и эффективные рабочие процессы разработки.","ar":"مثالي للوكلاء Next.js الذين يحتاجون إلى تنظيم مشروع منظم وعمليات تطوير فعالة."},"recommendation":{"en":"Empowers agents to establish a clear project setup with predefined file structures, naming conventions, and organization patterns, utilizing Next.js App Router and client-side providers.","zh":"赋予代理建立明确的项目设置的能力，包括预定义的文件结构、命名约定和组织模式，利用 Next.js App Router 和客户端提供程序。","ja":"Next.js App Router とクライアント側プロバイダーを利用して、エージェントが明確なプロジェクト設定を確立できるようにします。事前に定義されたファイル構造、命名規則、組織パターンなどが含まれます。","ko":"Next.js App Router와 클라이언트 측 제공자를 사용하여 에이전트가 명확한 프로젝트 설정을 구축할 수 있도록 합니다. 사전 정의된 파일 구조,命명 규칙 및 조직 패턴 등을 포함합니다.","es":"Habilita a los agentes a establecer una configuración de proyecto clara con estructuras de archivos predefinidas, convenciones de nomenclatura y patrones de organización, utilizando Next.js App Router y proveedores de lado del cliente.","fr":"Permet aux agents d''établir une configuration de projet claire avec des structures de fichiers prédéfinies, des conventions de nommage et des modèles d''organisation, en utilisant Next.js App Router et les fournisseurs côté client.","de":"Ermächtigt Agenten, eine klare Projektsetup mit vordefinierten Dateistrukturen, Benennungskonventionen und Organisationsmustern zu etablieren, unter Verwendung von Next.js App Router und Client-seitigen Anbietern.","pt":"Habilita os agentes a estabelecer uma configuração de projeto clara com estruturas de arquivo predefinidas, convenções de nomenclatura e padrões de organização, utilizando o Next.js App Router e provedores de lado do cliente.","ru":"Наделяет агентов возможностью устанавливать четкую настройку проекта с предварительно определенной структурой файлов, соглашениями об именах и шаблонами организации, используя Next.js App Router и клиентские провайдеры.","ar":"يمكن للوكلاء من إنشاء إعداد مشروع واضح مع هياكل الملفات المحددة مسبقًا وأساليب التسمية وأنماط التنظيم، باستخدام Next.js App Router وموفري الجانب العميل."},"useCases":{"en":["Configuring Next.js projects with App Router","Establishing consistent naming conventions","Organizing codebase with predefined directory structures"],"zh":["使用 App Router 配置 Next.js 项目","建立一致的命名约定","使用预定义的目录结构组织代码库"],"ja":["App Router を使用して Next.js プロジェクトを構成する","一貫した命名規則を確立する","事前に定義されたディレクトリ構造を使用してコードベースを整理する"],"ko":["App Router를 사용하여 Next.js 프로젝트를 구성하는 것","일관된 명명 규칙을 설정하는 것","사전 정의된 디렉토리 구조를 사용하여 코드베이스를 조직하는 것"],"es":["Configuración de proyectos Next.js con App Router","Establecimiento de convenciones de nomenclatura consistentes","Organización de la base de código con estructuras de directorios predefinidas"],"fr":["Configuration de projets Next.js avec App Router","Établissement de conventions de nommage cohérentes","Organisation de la base de code avec des structures de répertoires prédéfinies"],"de":["Konfiguration von Next.js-Projekten mit App Router","Festlegung konsistenter Benennungskonventionen","Organisation des Codebases mit vordefinierten Verzeichnisstrukturen"],"pt":["Configurando projetos Next.js com App Router","Estabelecendo convenções de nomenclatura consistentes","Organizando a base de código com estruturas de diretório predefinidas"],"ru":["Настройка проектов Next.js с App Router","Установление последовательных соглашений об именах","Организация кодовой базы с предварительно определенной структурой директорий"],"ar":["تكوين مشاريع Next.js مع App Router","إنشاء اتفاقيات تسمية متسقة","تنظيم قاعدة الشفرة مع هياكل الدليل المحددة مسبقًا"]},"limitations":{"en":["Specific to Next.js framework","Requires understanding of Next.js App Router and client-side providers"],"zh":["仅限于 Next.js 框架","需要了解 Next.js App Router 和客户端提供程序"],"ja":["Next.js フレームワークに特有のもの","Next.js App Router とクライアント側プロバイダーの理解が必要"],"ko":["Next.js 프레임워크에만 적용됨","Next.js App Router 및 클라이언트 측 제공자의 이해가 필요"],"es":["Específico del marco de trabajo Next.js","Requiere comprensión de Next.js App Router y proveedores de lado del cliente"],"fr":["Spécifique au framework Next.js","Nécessite une compréhension de Next.js App Router et des fournisseurs côté client"],"de":["Spezifisch für das Next.js-Framework","Benötigt Verständnis von Next.js App Router und Client-seitigen Anbietern"],"pt":["Específico do framework Next.js","Exige compreensão do Next.js App Router e provedores de lado do cliente"],"ru":["Спецефичен для фреймворка Next.js","Требует понимания Next.js App Router и клиентских провайдеров"],"ar":["محدد لإطار Next.js","يتطلب فهم Next.js App Router وموفري الجانب العميل"]},"version":4},"contentHash":"6f81045fee9c6740c5d67e788399e84afe2a5cd282f60c799c5928c4bd22811c","qualityScore":57}');
