INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('whddltjdwhd/bellog/bellog-structure', 'bellog-structure', 'whddltjdwhd', 'bellog', 'community', 'bellog-structure whddltjdwhd bellog community The bellog-structure skill defines the file structure and organization patterns for the Bellog blog project, benefiting developers working with Next.js. It provides a clear project setup for efficient development. Bellog 结构定义了 Next.js 项目的文件结构、命名约定和组织模式，帮助开发者优化项目开发 Bellog 構造は Next.js プロジェクトのファイル構造、命名規約、組織パターンを定義し、開発者がプロジェクト開発を最適化できるようにします Bellog 구조는 Next.js 프로젝트의 파일 구조, 이름 규칙, 조직 패턴을 정의하여 개발자가 프로젝트 개발을 최적화할 수 있도록 합니다 Bellog-structure define la estructura de archivos y convenciones de nombramiento para el proyecto de blog Bellog Bellog-structure définit la structure de fichiers et les conventions de nommage pour le projet de blog Bellog Bellog-structure definiert die Dateistruktur und Benennungskonventionen für das Bellog-Blog-Projekt O Bellog-structure define a estrutura de arquivos e organização de projetos para o blog do Castle Bell, utilizando Next.js e React. Bellog-structure определяет структуру файлов и организацию проекта для блога Castle Bell, используя Next.js и React. بلوغ-ستракتشر يحدد هيكل الملفات وتنظيم المشروع لمدونة كاسل بيل، باستخدام Next.js و React. how to use bellog-structure bellog-structure setup guide Next.js project organization bellog-structure vs custom setup bellog-structure install what is bellog-structure bellog-structure alternative bellog-structure file structure Next.js App Router setup Bellog 结构 Next.js 项目组织 文件命名约定 组织模式 App Router 页面布局 客户端提供者 TypeScript React Defines a project structure with a src/app directory for Next.js App Router Includes layout.tsx for root layout with fonts and metadata Utilizes page.tsx for the home page and template.tsx for page transitions Supports client-side providers via providers.tsx Organizes files and directories for efficient Next.js project development bellog-structure is a predefined file organization and naming convention system for the Bellog blog project, utilizing Next.js for efficient development and deployment.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Embassy-of-the-Free-Mind/sourcelibrary-v2/batch-translate', 'community', 'Embassy-of-the-Free-Mind', 'sourcelibrary-v2', 'Embassy-of-the-Free-Mind/sourcelibrary-v2', 'batch-translate', 0, 0, 57, '2026-03-08T01:57:15.315Z', '2026-03-08T02:02:47.056Z', '7d9d8d9a2171605aa599703e4cf90676880d00adea53dda13a3edfb8eff5f7ab', '{"id":"Embassy-of-the-Free-Mind/sourcelibrary-v2/batch-translate","name":"batch-translate","description":{"en":"The batch-translate skill automates the book translation process for developers, utilizing a pipeline of Crop, OCR, and Translate technologies. It benefits developers working with historical texts.","zh":"批量翻译工作流是一个自动化的流程，包括Crop、OCR和翻译。它可以帮助开发者简化书籍翻译工作。","ja":"バッチ翻訳ワークフローは、Crop、OCR、翻訳を含む自動化されたプロセスです。開発者が本の翻訳作業を簡素化するのに役立ちます。","ko":"배치 번역 워크플로우는 Crop, OCR, 번역을 포함한 자동화된 프로세스입니다. 개발자가 책 번역 작업을 간소화하는 데 도움이 됩니다.","es":"Batch-translate es un proceso de flujo de trabajo que permite procesar libros a través de la canalización completa: Recorte, OCR y Traducción.","fr":"Batch-translate est un workflow qui permet de traiter des livres via le pipeline complet : Recadrage, OCR et Traduction.","de":"Batch-translate ist ein Workflow-Prozess, der die Verarbeitung von Büchern durch die komplette Pipeline ermöglicht: Beschnitt, OCR und Übersetzung.","pt":"O batch-translate é um fluxo de trabalho que processa livros por meio de um pipeline completo: Crop, OCR e Tradução","ru":"Пакетная перевод - это рабочий процесс, который обрабатывает книги через полный пайплайн: Crop, OCR и перевод","ar":"ترجمة الدفعة هو عملية عمل تتم معالجتها من خلال خط أنابيب كامل: Crop و OCR و الترجمة"},"seo":{"title":{"en":"batch-translate: Streamlined Book Translation Workflow | ...","zh":"批量翻译工作流设置指南 - AI工具","ja":"バッチ翻訳ワークフロー設定ガイド - AIエージェント","ko":"배치 번역 워크플ロー 설정 가이드 - AI 에이전트","es":"Guía de configuración de batch-translate para agentes de IA","fr":"Guide de mise en place de batch-translate pour outils d''IA","de":"Einrichtungsleitfaden für batch-translate in KI-Tools","pt":"Batch-Translate: Guia de Configuração para Tradução em Lote","ru":"Пакетная Перевод: Настройка ИИ Агентов для Перевода Книг","ar":"ترجمة الدفعة: إرشادات الإعداد لترجمة الكتب بالجملة"},"description":{"en":"Discover how batch-translate automates book translation with Crop, OCR, and Translate. Get started with the roadmap reference and priority list now!","zh":"了解批量翻译工作流的技术细节，包括Crop、OCR和翻译过程。使用AI工具简化您的工作流程。","ja":"バッチ翻訳ワークフローの技術的詳細を学び、Crop、OCR、翻訳プロセスを最適化する。AIエージェントを使用してワークフローを簡素化する。","ko":"배치 번역 워크플로우의 기술적 세부 정보를 살펴보고 Crop, OCR, 번역 프로세스를 최적화 하십시오. AI 에이전트를 사용하여 워크플로우를 간소화하십시오.","es":"Aprende a configurar batch-translate para procesar libros a través de la canalización completa: Recorte → OCR → Traducción","fr":"Découvrez comment configurer batch-translate pour traiter des livres via le pipeline complet : Recadrage → OCR → Traduction","de":"Erfahren Sie, wie Sie batch-translate einrichten, um Bücher durch die komplette Pipeline zu verarbeiten: Beschnitt → OCR → Übersetzung","pt":"Aprenda a configurar o batch-translate para traduzir livros em lote com tecnologias de ponta como Crop, OCR e Tradução","ru":"Узнайте, как настроить пакетную перевод для перевода книг в批ном режиме с помощью передовых технологий như Crop, OCR и перевод","ar":"تعرف على كيفية ضبط ترجمة الدفعة لترجمة الكتب بالجملة باستخدام تقنيات متقدمة مثل Crop و OCR و الترجمة"},"definition":{"en":"batch-translate is a workflow process that automates book translation through a series of steps including cropping, optical character recognition, and translation.","zh":"批量翻译工作流是一个使用Crop、OCR和翻译技术的自动化流程。","ja":"バッチ翻訳ワークフローは、Crop、OCR、翻訳技術を使用する自動化されたプロセスです。","ko":"배치 번역 워크플로우는 Crop, OCR, 번역 기술을 사용하는 자동화된 프로세스입니다.","es":"Batch-translate es un agente de IA que procesa libros a través de la canalización completa","fr":"Batch-translate est un outil d''IA qui traite des livres via le pipeline complet","de":"Batch-translate ist ein KI-Tool, das Bücher durch die komplette Pipeline verarbeitet","pt":"O batch-translate é um processo de tradução em lote que utiliza tecnologias de Crop, OCR e Tradução","ru":"Пакетная перевод - это процесс перевода в批ном режиме, который использует технологии Crop, OCR и перевод","ar":"ترجمة الدفعة هي عملية ترجمة بالجملة تستخدم تقنيات Crop و OCR و الترجمة"},"features":{"en":["Processes books through a complete pipeline: Crop → OCR → Translate","References a translation priority list in `.claude/ROADMAP.md`","Supports processing of high-priority untranslated books, including Kircher encyclopedias","Utilizes command-line interface for workflow automation, as shown in `SKILL.md`","Includes roadmap reference for tracking translation progress","Automates tasks for historical texts such as Fludd: Utriusque Cosmi Historia"],"zh":["支持Crop、OCR和翻译技术","自动化书籍翻译工作流程","优先处理未翻译的书籍","支持多种书籍格式，包括Kircher encyclopedias和Fludd: Utriusque Cosmi Historia"],"ja":["Crop、OCR、翻訳技術をサポート","本の翻訳ワークフローを自動化","未翻訳の本を優先して処理","Kircher encyclopediasやFludd: Utriusque Cosmi Historiaなどの複数の本の形式をサポート"],"ko":["Crop, OCR, 번역 기술 지원","도서 번역 워크플로우 자동화","번역되지 않은 도서에 대한 우선 처리","Kircher encyclopedias 및 Fludd: Utriusque Cosmi Historia와 같은 여러 도서 형식 지원"],"es":["Procesamiento de libros a través de la canalización completa: Recorte → OCR → Traducción","Priorización de la traducción según la lista de prioridades","Compatibilidad con formatos de libros antiguos como Kircher y Fludd","Integración con herramientas de OCR para mejorar la precisión","Soporte para múltiples idiomas"],"fr":["Traitement de livres via le pipeline complet : Recadrage → OCR → Traduction","Priorisation de la traduction selon la liste de priorités","Compatibilité avec des formats de livres anciens tels que Kircher et Fludd","Intégration avec des outils d''OCR pour améliorer la précision","Prise en charge de plusieurs langues"],"de":["Verarbeitung von Büchern durch die komplette Pipeline: Beschnitt → OCR → Übersetzung","Priorisierung der Übersetzung nach der Prioritätenliste","Kompatibilität mit alten Buchformaten wie Kircher und Fludd","Integration mit OCR-Tools zur Verbesserung der Genauigkeit","Unterstützung für mehrere Sprachen"],"pt":["Processamento de livros em lote","Tecnologia de Crop para pré-processamento","Tecnologia de OCR para reconhecimento de texto","Tecnologia de Tradução para tradução automática","Suporte a prioridade de tradução para livros não traduzidos","Integração com o roadmap de tradução"],"ru":["Обработка книг в批ном режиме","Технология Crop для предварительной обработки","Технология OCR для распознавания текста","Технология перевода для автоматического перевода","Поддержка приоритета перевода для не переведенных книг","Интеграция с дорожной картой перевода"],"ar":["معالجة الكتب بالجملة","تكنولوجيا Crop للتحضير المسبق","تكنولوجيا OCR للتعرف على النص","تكنولوجيا الترجمة للترجمة الآلية","دعم الأولوية للترجمة للكتب غير المترجمة","التكامل مع خارطة الطريق للترجمة"]},"keywords":{"en":["how to use batch-translate","batch-translate alternative","batch-translate setup guide","what is batch-translate","batch-translate vs Google Translate","batch-translate install","automated book translation workflow","crop ocr translate pipeline","historical text translation"],"zh":["批量翻译","AI工具","Crop","OCR","翻译技术","书籍翻译","自动化工作流","开发者工具","AI解决方案"],"ja":["バッチ翻訳","AIエージェント","Crop","OCR","翻訳技術","本の翻訳","自動化ワークフロー","開発者ツール","AIソリューション"],"ko":["배치 번역","AI 에이전트","Crop","OCR","번역 기술","도서 번역","자동화 워크플로우","개발자 도구","AI 솔루션"],"es":["batch-translate","agentes de IA","procesamiento de libros","canalización completa","OCR","traducción","priorización de la traducción","formatos de libros antiguos"],"fr":["batch-translate","outils d''IA","traitement de livres","pipeline complet","OCR","traduction","priorisation de la traduction","formats de livres anciens"],"de":["batch-translate","KI-Tools","Buchverarbeitung","komplette Pipeline","OCR","Übersetzung","Priorisierung der Übersetzung","alte Buchformate"],"pt":["batch-translate","tradução em lote","Crop","OCR","Tradução","processamento de livros","roadmap de tradução","prioridade de tradução","IИ Агенты"],"ru":["пакетная перевод","перевод в批ном режиме","Crop","OCR","перевод","обработка книг","дорожная карта перевода","приоритет перевода","ИИ Агенты"],"ar":["ترجمة الدفعة","ترجمة بالجملة","Crop","OCR","الترجمة","معالجة الكتب","خارطة الطريق للترجمة","الأولوية للترجمة","أدوات الذكاء الاصطناعي"]}},"owner":"Embassy-of-the-Free-Mind","repo":"sourcelibrary-v2","repoPath":"Embassy-of-the-Free-Mind/sourcelibrary-v2","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.315Z","topics":[],"category":"community","skillMd":{"name":"batch-translate","description":"Batch process books through the complete pipeline - generate cropped images for split pages, OCR all pages, then translate with context. Use when asked to process, OCR, translate, or batch process one or more books.","bodyPreview":"# Batch Book Translation Workflow\n\nProcess books through the complete pipeline: Crop → OCR → Translate\n\n## Roadmap Reference\n\nSee `.claude/ROADMAP.md` for the translation priority list.\n\n**Priority 1 = UNTRANSLATED** - These are highest priority for processing:\n- Kircher encyclopedias (Oedipus, Musurgia, Ars Magna Lucis)\n- Fludd: Utriusque Cosmi Historia\n- Theatrum Chemicum, Musaeum Hermeticum\n- Cardano: De Subtilitate\n- Della Porta: Magia Naturalis\n- Lomazzo, Poliziano, Landino\n\n```bash\n# Get r","body":"# Batch Book Translation Workflow\n\nProcess books through the complete pipeline: Crop → OCR → Translate\n\n## Roadmap Reference\n\nSee `.claude/ROADMAP.md` for the translation priority list.\n\n**Priority 1 = UNTRANSLATED** - These are highest priority for processing:\n- Kircher encyclopedias (Oedipus, Musurgia, Ars Magna Lucis)\n- Fludd: Utriusque Cosmi Historia\n- Theatrum Chemicum, Musaeum Hermeticum\n- Cardano: De Subtilitate\n- Della Porta: Magia Naturalis\n- Lomazzo, Poliziano, Landino\n\n```bash\n# Get roadmap with priorities\ncurl -s \"https://sourcelibrary.org/api/books/roadmap\" | jq ''.books[] | select(.priority == 1) | {title, notes}''\n```\n\nRoadmap source: `src/app/api/books/roadmap/route.ts`\n\n## Overview\n\nThis workflow handles the full processing pipeline for historical book scans:\n1. **Generate Cropped Images** - For split two-page spreads, extract individual pages\n2. **OCR** - Extract text from page images using Gemini vision\n3. **Translate** - Translate OCR''d text with prior page context for continuity\n\n## API Endpoints\n\n| Endpoint | Purpose |\n|----------|---------|\n| `GET /api/books` | List all books |\n| `GET /api/books/BOOK_ID` | Get book with all pages |\n| `POST /api/jobs/queue-books` | Queue pages for Lambda worker processing (primary path) |\n| `GET /api/jobs` | List processing jobs |\n| `POST /api/jobs/JOB_ID/retry` | Retry failed pages in a job |\n| `POST /api/jobs/JOB_ID/cancel` | Cancel a running job |\n| `POST /api/books/BOOK_ID/batch-ocr-async` | Submit Gemini Batch API OCR job (50% cheaper, ~24h) |\n| `POST /api/books/BOOK_ID/batch-translate-async` | Submit Gemini Batch API translation job |\n\n## Processing Options\n\n### Option 1: Lambda Workers via Job System (Primary Path)\n\nThe primary processing path uses AWS Lambda workers via SQS queues. Each page is processed independently with automatic job tracking.\n\n```bash\n# Queue OCR for a book''s pages\ncurl -s -X POST \"https://sourcelibrary.org/api/jobs/queue-books\" \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"bookIds\": [\"BOOK_ID\"], \"action\": \"ocr\"}''\n\n# Queue translation\ncurl -s -X POST \"https://sourcelibrary.org/api/jobs/queue-books\" \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"bookIds\": [\"BOOK_ID\"], \"action\": \"translation\"}''\n\n# Queue image extraction\ncurl -s -X POST \"https://sourcelibrary.org/api/jobs/queue-books\" \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"bookIds\": [\"BOOK_ID\"], \"action\": \"image_extraction\"}''\n```\n\n**IMPORTANT: Always use `gemini-3-flash-preview` for all OCR and translation tasks. Do NOT use `gemini-2.5-flash`.**\n\n### Option 2: Gemini Batch API (50% Cheaper, Automated Pipeline)\n\nThe post-import-pipeline cron uses Gemini Batch API for automated processing of newly imported books. Results arrive in ~24 hours at 50% cost.\n\n| Job Type | API | Model | Cost |\n|----------|-----|-------|------|\n| Single page | Realtime (Lambda) | gemini-3-flash-preview | Full price |\n| batch_ocr | Batch API | gemini-3-flash-preview | **50% off** |\n| batch_translate | Batch API | gemini-3-flash-preview | **50% off** |\n\n## OCR Output Format\n\nOCR uses **Markdown output** with semantic tags:\n\n### Markdown Formatting\n- `# ## ###` for headings (bigger text = bigger heading)\n- `**bold**`, `*italic*` for emphasis\n- `->centered text<-` for centered lines (NOT for headings)\n- `> blockquotes` for quotes/prayers\n- `---` for dividers\n- Tables only for actual tabular data\n\n### Metadata Tags (hidden from readers)\n| Tag | Purpose |\n|-----|---------|\n| `<lang>X</lang>` | Detected language |\n| `<page-num>N</page-num>` | Page/folio number |\n| `<header>X</header>` | Running headers |\n| `<sig>X</sig>` | Printer''s marks (A2, B1) |\n| `<meta>X</meta>` | Hidden metadata |\n| `<warning>X</warning>` | Quality issues |\n| `<vocab>X</vocab>` | Key terms for indexing |\n\n### Inline Annotations (visible to readers)\n| Tag | Purpose |\n|-----|---------|\n| `<margin>X</margin>` | Marginal notes (before paragraph) |\n| `<gloss>X</gloss>` | Interlinear annotations |\n| `<insert>X</insert>` | Boxed text, additions |\n| `<unclear>X</unclear>` | Illegible readings |\n| `<note>X</note>` | Interpretive notes |\n| `<term>X</term>` | Technical vocabulary |\n| `<image-desc>X</image-desc>` | Describe illustrations |\n\n### Critical OCR Rules\n1. Preserve original spelling, capitalization, punctuation\n2. Page numbers/headers/signatures go in metadata tags only\n3. IGNORE partial text at edges (from facing page in spread)\n4. Describe images/diagrams with `<image-desc>`, never tables\n5. End with `<vocab>key terms, names, concepts</vocab>`\n\n## Step 1: Analyze Book Status\n\nFirst, check what work is needed for a book:\n\n```bash\n# Get book and analyze page status\ncurl -s \"https://sourcelibrary.org/api/books/BOOK_ID\" > /tmp/book.json\n\n# Count pages by status (IMPORTANT: check length > 0, not just existence - empty strings are truthy!)\njq ''{\n  title: .title,\n  total_pages: (.pages | length),\n  split_pages: [.pages[] | select(.crop)] | length,\n  needs_crop: [.pages[] | select(.crop) | select(.cropped_photo | not)] | length,\n  has_ocr: [.pages[] | select((.ocr.data // \"\") | length > 0)] | length,\n  needs_ocr: [.pages[] | select((.ocr.data // \"\") | length == 0)] | length,\n  has_translation: [.pages[] | select((.translation.data // \"\") | length > 0)] | length,\n  needs_translation: [.pages[] | select((.ocr.data // \"\") | length > 0) | select((.translation.data // \"\") | length == 0)] | length\n}'' /tmp/book.json\n```\n\n### Detecting Bad OCR\n\nPages that were OCR''d before cropped images were generated have incorrect OCR (contains both pages of the spread). Detect these:\n\n```bash\n# Find pages with crop data + OCR but missing cropped_photo at OCR time\n# These often contain \"two-page\" or \"spread\" in the OCR text\njq ''[.pages[] | select(.crop) | select(.ocr.data) |\n  select(.ocr.data | test(\"two-page|spread\"; \"i\"))] | length'' /tmp/book.json\n```\n\n## Step 2: Generate Cropped Images\n\nFor books with split two-page spreads, generate individual page images:\n\n```bash\n# Get page IDs needing crops\nCROP_IDS=$(jq ''[.pages[] | select(.crop) | select(.cropped_photo | not) | .id]'' /tmp/book.json)\n\n# Create crop job\ncurl -s -X POST \"https://sourcelibrary.org/api/jobs\" \\\n  -H \"Content-Type: application/json\" \\\n  -d \"{\n    \\\"type\\\": \\\"generate_cropped_images\\\",\n    \\\"book_id\\\": \\\"BOOK_ID\\\",\n    \\\"book_title\\\": \\\"BOOK_TITLE\\\",\n    \\\"page_ids\\\": $CROP_IDS\n  }\"\n```\n\nProcess the job:\n\n```bash\n# Trigger processing (40 pages per request, auto-continues)\ncurl -s -X POST \"https://sourcelibrary.org/api/jobs/JOB_ID/process\"\n```\n\n## Step 3: OCR Pages\n\n### Option A: Using Job System (for large batches)\n\n```bash\n# Get page IDs needing OCR (check for empty strings, not just null)\nOCR_IDS=$(jq ''[.pages[] | select((.ocr.data // \"\") | length == 0) | .id]'' /tmp/book.json)\n\n# Create OCR job\ncurl -s -X POST \"https://sourcelibrary.org/api/jobs\" \\\n  -H \"Content-Type: application/json\" \\\n  -d \"{\n    \\\"type\\\": \\\"batch_ocr\\\",\n    \\\"book_id\\\": \\\"BOOK_ID\\\",\n    \\\"book_title\\\": \\\"BOOK_TITLE\\\",\n    \\\"model\\\": \\\"gemini-3-flash-preview\\\",\n    \\\"language\\\": \\\"Latin\\\",\n    \\\"page_ids\\\": $OCR_IDS\n  }\"\n```\n\n### Option B: Using Lambda Workers with Page IDs\n\n```bash\n# OCR specific pages (including overwrite)\ncurl -s -X POST \"https://sourcelibrary.org/api/jobs/queue-books\" \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\n    \"bookIds\": [\"BOOK_ID\"],\n    \"action\": \"ocr\",\n    \"pageIds\": [\"PAGE_ID_1\", \"PAGE_ID_2\"],\n    \"overwrite\": true\n  }''\n```\n\nLambda workers automatically use `cropped_photo` when available.\n\n## Step 4: Translate Pages\n\n### Option A: Using Job System\n\n```bash\n# Get page IDs needing translation (must have OCR content, check for empty strings)\nTRANS_IDS=$(jq ''[.pages[] | select((.ocr.data // \"\") | length > 0) | select((.translation.data // \"\") | length == 0) | .id]'' /tmp/book.json)\n\n# Create translation job\ncurl -s -X POST \"https://sourcelibrary.org/api/jobs\" \\\n  -H \"Content-Type: application/json\" \\\n  -d \"{\n    \\\"type\\\": \\\"batch_translate\\\",\n    \\\"book_id\\\": \\\"BOOK_ID\\\",\n    \\\"book_title\\\": \\\"BOOK_TITLE\\\",\n    \\\"model\\\": \\\"gemini-3-flash-preview\\\",\n    \\\"language\\\": \\\"Latin\\\",\n    \\\"page_ids\\\": $TRANS_IDS\n  }\"\n```\n\n### Option B: Using Lambda Workers (Recommended)\n\nLambda FIFO queue automatically provides previous page context for translation continuity:\n\n```bash\n# Queue translation for pages that have OCR but no translation\ncurl -s -X POST \"https://sourcelibrary.org/api/jobs/queue-books\" \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"bookIds\": [\"BOOK_ID\"], \"action\": \"translation\"}''\n```\n\nThe translation Lambda worker processes pages sequentially via FIFO queue and fetches the previous page''s translation for context.\n\n## Complete Book Processing Script\n\nProcess a single book through the full pipeline using Lambda workers:\n\n```bash\n#!/bin/bash\nBOOK_ID=\"YOUR_BOOK_ID\"\nBASE_URL=\"https://sourcelibrary.org\"\n\n# 1. Fetch book data\necho \"Fetching book...\"\nBOOK=$(curl -s \"$BASE_URL/api/books/$BOOK_ID\")\nTITLE=$(echo \"$BOOK\" | jq -r ''.title[0:40]'')\necho \"Processing: $TITLE\"\n\n# 2. Queue OCR (Lambda workers handle all pages automatically)\nNEEDS_OCR=$(echo \"$BOOK\" | jq ''[.pages[] | select((.ocr.data // \"\") | length == 0)] | length'')\nif [ \"$NEEDS_OCR\" != \"0\" ]; then\n  echo \"Queueing OCR for $NEEDS_OCR pages...\"\n  curl -s -X POST \"$BASE_URL/api/jobs/queue-books\" \\\n    -H \"Content-Type: application/json\" \\\n    -d \"{\\\"bookIds\\\": [\\\"$BOOK_ID\\\"], \\\"action\\\": \\\"ocr\\\"}\"\n  echo \"OCR job queued!\"\nfi\n\n# 3. Queue translation (after OCR completes — check /jobs page)\nNEEDS_TRANS=$(echo \"$BOOK\" | jq ''[.pages[] | select((.ocr.data // \"\") | length > 0) | select((.translation.data // \"\") | length == 0)] | length'')\nif [ \"$NEEDS_TRANS\" != \"0\" ]; then\n  echo \"Queueing translation for $NEEDS_TRANS pages...\"\n  curl -s -X POST \"$BASE_URL/api/jobs/queue-books\" \\\n    -H \"Content-Type: application/json\" \\\n    -d \"{\\\"bookIds\\\": [\\\"$BOOK_ID\\\"], \\\"action\\\": \\\"translation\\\"}\"\n  echo \"Translation job queued!\"\nfi\n\necho \"Jobs queued! Monitor progress at $BASE_URL/jobs\"\n```\n\n## Fixing Bad OCR\n\nWhen pages were OCR''d before cropped images existed, they contain text from both pages. Fix with:\n\n```bash\n# 1. Generate cropped images first (Step 2 above)\n\n# 2. Find pages with bad OCR\nBAD_OCR_IDS=$(jq ''[.pages[] | select(.crop) | select(.ocr.data) |\n  select(.ocr.data | test(\"two-page|spread\"; \"i\")) | .id]'' /tmp/book.json)\n\n# 3. Re-OCR with overwrite via Lambda workers\ncurl -s -X POST \"https://sourcelibrary.org/api/jobs/queue-books\" \\\n  -H \"Content-Type: application/json\" \\\n  -d \"{\\\"bookIds\\\": [\\\"BOOK_ID\\\"], \\\"action\\\": \\\"ocr\\\", \\\"pageIds\\\": $BAD_OCR_IDS, \\\"overwrite\\\": true}\"\n```\n\n## Processing All Books\n\nUse the Lambda worker job system for bulk processing:\n\n```bash\n#!/bin/bash\nBASE_URL=\"https://sourcelibrary.org\"\n\n# Get all book IDs\nBOOK_IDS=$(curl -s \"$BASE_URL/api/books\" | jq -r ''[.[].id]'')\n\n# Queue OCR for all books (Lambda workers handle parallelism and rate limiting)\ncurl -s -X POST \"$BASE_URL/api/jobs/queue-books\" \\\n  -H \"Content-Type: application/json\" \\\n  -d \"{\\\"bookIds\\\": $BOOK_IDS, \\\"action\\\": \\\"ocr\\\"}\"\n\n# After OCR completes, queue translation\ncurl -s -X POST \"$BASE_URL/api/jobs/queue-books\" \\\n  -H \"Content-Type: application/json\" \\\n  -d \"{\\\"bookIds\\\": $BOOK_IDS, \\\"action\\\": \\\"translation\\\"}\"\n```\n\nMonitor progress at https://sourcelibrary.org/jobs\n\n## Monitoring Progress\n\nCheck overall library status:\n\n```bash\ncurl -s \"https://sourcelibrary.org/api/books\" | jq ''[.[] | {\n  title: .title[0:30],\n  pages: .pages_count,\n  ocr: .ocr_count,\n  translated: .translation_count\n}] | sort_by(-.pages)''\n```\n\n## Troubleshooting\n\n### Empty Strings vs Null (CRITICAL)\nIn jq, empty strings `\"\"` are truthy! This means:\n- `select(.ocr.data)` matches pages with `\"\"` (WRONG)\n- `select(.ocr.data | not)` does NOT match pages with `\"\"` (WRONG)\n- Use `select((.ocr.data // \"\") | length == 0)` to find missing/empty OCR\n- Use `select((.ocr.data // \"\") | length > 0)` to find pages WITH OCR content\n\n### Rate Limits (429 errors)\n\n#### Gemini API Tiers\n| Tier | RPM | How to Qualify |\n|------|-----|----------------|\n| Free | 15 | Default |\n| Tier 1 | 300 | Enable billing + $50 spend |\n| Tier 2 | 1000 | $250 spend |\n| Tier 3 | 2000 | $1000 spend |\n\n#### Optimal Sleep Times by Tier\n| Tier | Max RPM | Safe Sleep Time | Effective Rate |\n|------|---------|-----------------|----------------|\n| Free | 15 | 4.0s | ~15/min |\n| Tier 1 | 300 | 0.4s | ~150/min |\n| Tier 2 | 1000 | 0.12s | ~500/min |\n| Tier 3 | 2000 | 0.06s | ~1000/min |\n\n**Note:** Use ~50% of max rate to leave headroom for bursts.\n\n#### API Key Rotation\nThe system supports multiple API keys for higher throughput:\n- Set `GEMINI_API_KEY` (primary)\n- Set `GEMINI_API_KEY_2`, `GEMINI_API_KEY_3`, ... up to `GEMINI_API_KEY_10`\n- Keys rotate automatically with 60s cooldown after rate limit\n\nWith N keys at Tier 1, you get N × 300 RPM = N × 150 safe req/min\n\n### Function Timeouts\n- Jobs have `maxDuration=300s` for Vercel Pro\n- If hitting timeouts, reduce `CROP_CHUNK_SIZE` in job processing\n\n### Missing Cropped Photos\n- Check if crop job completed successfully\n- Verify page has `crop` data with `xStart` and `xEnd`\n- Re-run crop generation for specific pages\n\n### Bad OCR Detection\nLook for these patterns in OCR text indicating wrong image was used:\n- \"two-page spread\"\n- \"left page\" / \"right page\" descriptions\n- Duplicate text blocks\n- References to facing pages\n"},"lastSynced":"2026-03-08T02:02:47.056Z","agentAnalysis":{"suitability":{"en":"Ideal for Historical Text Analysis Agents requiring automated book translation pipelines","zh":"适合需要自动化图书翻译管道的历史文本分析代理","ja":"歴史的テキスト分析エージェントが自動化された本の翻訳パイプラインを必要とする場合に最適","ko":"자동화된 책 번역 파이프라인이 필요한 역사적 텍스트 분석 에이전트에 적합","es":"Ideal para Agentes de Análisis de Textos Históricos que requieren tuberías de traducción de libros automatizadas","fr":"Idéal pour les Agents d''Analyse de Textes Historiques nécessitant des pipelines de traduction de livres automatisés","de":"Ideal für historische Textanalyse-Agents, die automatisierte Buchübersetzungs-Pipelines erfordern","pt":"Ideal para Agentes de Análise de Textos Históricos que exigem pipelines de tradução de livros automatizados","ru":"Идеально для Агентов Анализа Исторических Текстов, требующих автоматизированных конвейеров перевода книг","ar":"مثالي لعميل تحليل النصوص التاريخية التي تتطلب خطوط أنابيب ترجمة الكتب الآلية"},"recommendation":{"en":"Empowers agents to process historical texts through a pipeline of Crop, OCR, and Translate technologies, supporting formats like Kircher encyclopedias and Fludd: Utriusque Cosmi Historia, utilizing roadmap priorities outlined in .claude/ROADMAP.md","zh":"使代理能够通过Crop、OCR和Translate技术的管道处理历史文本，支持Kircher百科全书和Fludd：Utriusque Cosmi Historia等格式，利用.claude/ROADMAP.md中概述的路线图优先级","ja":"エージェントがCrop、OCR、Translate技術のパイプラインを通じて歴史的テキストを処理できるようにし、Kircher百科事典やFludd：Utriusque Cosmi Historiaなどの形式をサポートし、.claude/ROADMAP.mdに概説されたロードマップの優先順位に従う","ko":"에이전트가 Crop, OCR, Translate 기술의 파이프라인을 통해 역사적 텍스트를 처리할 수 있도록 하며, Kircher 백과사전 및 Fludd: Utriusque Cosmi Historia와 같은 형식을 지원하며, .claude/ROADMAP.md에概述된 로드맵 우선순위를 사용","es":"Habilita a los agentes a procesar textos históricos a través de una tubería de tecnologías de Recorte, OCR y Traducción, que admiten formatos como enciclopedias de Kircher y Fludd: Utriusque Cosmi Historia, utilizando prioridades de hoja de ruta definidas en .claude/ROADMAP.md","fr":"Permet aux agents de traiter des textes historiques grâce à un pipeline de technologies de Recadrage, OCR et Traduction, prenant en charge des formats tels que les encyclopédies de Kircher et Fludd: Utriusque Cosmi Historia, en utilisant les priorités de feuille de route définies dans .claude/ROADMAP.md","de":"Ermächtigt Agents, historische Texte durch eine Pipeline von Crop-, OCR- und Übersetzungstechnologien zu verarbeiten, die Formate wie Kircher-Enzyklopädien und Fludd: Utriusque Cosmi Historia unterstützen, unter Verwendung von Straßenkartenprioritäten, die in .claude/ROADMAP.md aufgeführt sind","pt":"Habilita os agentes a processar textos históricos por meio de um pipeline de tecnologias de Recorte, OCR e Tradução, suportando formatos como enciclopédias Kircher e Fludd: Utriusque Cosmi Historia, utilizando prioridades de roadmap delineadas em .claude/ROADMAP.md","ru":"Наделяет агентов возможностью обрабатывать исторические тексты через конвейер технологий Crop, OCR и Translate, поддерживая форматы, такие как энциклопедии Kircher и Fludd: Utriusque Cosmi Historia, используя приоритеты дорожной карты, изложенные в .claude/ROADMAP.md","ar":"تمكين العميل من معالجة النصوص التاريخية من خلال خط أنابيب تكنولوجيا القص، و OCR، و الترجمة، و دعم تنسيقات مثل الموسوعات Kircher و Fludd: Utriusque Cosmi Historia، و باستخدام أولويات خارطة الطريق المحددة في .claude/ROADMAP.md"},"useCases":{"en":["Automating translation of unprocessed Kircher encyclopedias","Generating translated versions of Theatrum Chemicum and Musaeum Hermeticum","Processing Cardano: De Subtilitate and Della Porta: Magia Naturalis for analysis"],"zh":["自动化翻译未处理的Kircher百科全书","生成Theatrum Chemicum和Musaeum Hermeticum的翻译版本","处理Cardano：De Subtilitate和Della Porta：Magia Naturalis以进行分析"],"ja":["未処理のKircher百科事典の翻訳を自動化する","Theatrum ChemicumとMusaeum Hermeticumの翻訳バージョンを生成する","Cardano：De SubtilitateとDella Porta：Magia Naturalisを分析するために処理する"],"ko":["처리되지 않은 Kircher 백과사전의 번역을 자동화","Theatrum Chemicum 및 Musaeum Hermeticum의 번역 버전 생성","Cardano: De Subtilitate 및 Della Porta: Magia Naturalis를 분석하기 위해 처리"],"es":["Automatizar la traducción de enciclopedias de Kircher no procesadas","Generar versiones traducidas de Theatrum Chemicum y Musaeum Hermeticum","Procesar Cardano: De Subtilitate y Della Porta: Magia Naturalis para el análisis"],"fr":["Automatiser la traduction d''encyclopédies de Kircher non traitées","Générer des versions traduites de Theatrum Chemicum et Musaeum Hermeticum","Traiter Cardano: De Subtilitate et Della Porta: Magia Naturalis pour l''analyse"],"de":["Automatisierung der Übersetzung von unverarbeiteten Kircher-Enzyklopädien","Generierung von übersetzten Versionen von Theatrum Chemicum und Musaeum Hermeticum","Verarbeitung von Cardano: De Subtilitate und Della Porta: Magia Naturalis für die Analyse"],"pt":["Automatizar a tradução de enciclopédias Kircher não processadas","Gerar versões traduzidas de Theatrum Chemicum e Musaeum Hermeticum","Processar Cardano: De Subtilitate e Della Porta: Magia Naturalis para análise"],"ru":["Автоматизировать перевод необработанных энциклопедий Kircher","Генерировать переведенные версии Theatrum Chemicum и Musaeum Hermeticum","Обрабатывать Cardano: De Subtilitate и Della Porta: Magia Naturalis для анализа"],"ar":["أتمتة ترجمة الموسوعات Kircher غير المعالجة","إنتاج نسخ مترجمة من Theatrum Chemicum و Musaeum Hermeticum","معالجة Cardano: De Subtilitate و Della Porta: Magia Naturalis للتحليل"]},"limitations":{"en":["Requires access to historical text repositories","Priority processing based on .claude/ROADMAP.md","Limited to specific historical texts listed in the roadmap"],"zh":["需要访问历史文本仓库","基于.claude/ROADMAP.md的优先处理","仅限于路线图中列出的特定历史文本"],"ja":["歴史的テキストリポジトリへのアクセスが必要",".claude/ROADMAP.mdに基づく優先処理","ロードマップに記載された特定の歴史的テキストのみに制限される"],"ko":["歴史적 텍스트 저장소에 접근할 수 있어야 함",".claude/ROADMAP.md에 따라 우선순위에 따라 처리","로드맵에 나열된 특정 역사적 텍스트에만 제한됨"],"es":["Requiere acceso a repositorios de textos históricos","Priorización del procesamiento basada en .claude/ROADMAP.md","Limitado a textos históricos específicos enumerados en la hoja de ruta"],"fr":["Nécessite l''accès à des référentiels de textes historiques","Priorisation du traitement basée sur .claude/ROADMAP.md","Limité à des textes historiques spécifiques énumérés dans la feuille de route"],"de":["Erfordert Zugriff auf historische Text-Repositorys","Priorisierung der Verarbeitung basierend auf .claude/ROADMAP.md","Begrenzt auf bestimmte historische Texte, die in der Straßenkarte aufgeführt sind"],"pt":["Exige acesso a repositórios de textos históricos","Prioridade de processamento com base em .claude/ROADMAP.md","Limitado a textos históricos específicos listados na roadmap"],"ru":["Требует доступа к хранилищам исторических текстов","Приоритет обработки на основе .claude/ROADMAP.md","Ограничен конкретными историческими текстами, перечисленными в дорожной карте"],"ar":["يتطلب الوصول إلى مستودعات النصوص التاريخية","أولوية المعالجة بناءً على .claude/ROADMAP.md","محدود بالنصوص التاريخية المحددة المدرجة في خارطة الطريق"]},"version":4},"contentHash":"7d9d8d9a2171605aa599703e4cf90676880d00adea53dda13a3edfb8eff5f7ab","qualityScore":57}');
