INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Embassy-of-the-Free-Mind/sourcelibrary-v2/batch-translate', 'batch-translate', 'Embassy-of-the-Free-Mind', 'sourcelibrary-v2', 'community', 'batch-translate Embassy-of-the-Free-Mind sourcelibrary-v2 community The batch-translate skill automates the book translation process for developers, utilizing a pipeline of Crop, OCR, and Translate technologies. It benefits developers working with historical texts. 批量翻译工作流是一个自动化的流程，包括Crop、OCR和翻译。它可以帮助开发者简化书籍翻译工作。 バッチ翻訳ワークフローは、Crop、OCR、翻訳を含む自動化されたプロセスです。開発者が本の翻訳作業を簡素化するのに役立ちます。 배치 번역 워크플로우는 Crop, OCR, 번역을 포함한 자동화된 프로세스입니다. 개발자가 책 번역 작업을 간소화하는 데 도움이 됩니다. Batch-translate es un proceso de flujo de trabajo que permite procesar libros a través de la canalización completa: Recorte, OCR y Traducción. Batch-translate est un workflow qui permet de traiter des livres via le pipeline complet : Recadrage, OCR et Traduction. Batch-translate ist ein Workflow-Prozess, der die Verarbeitung von Büchern durch die komplette Pipeline ermöglicht: Beschnitt, OCR und Übersetzung. O batch-translate é um fluxo de trabalho que processa livros por meio de um pipeline completo: Crop, OCR e Tradução Пакетная перевод - это рабочий процесс, который обрабатывает книги через полный пайплайн: Crop, OCR и перевод ترجمة الدفعة هو عملية عمل تتم معالجتها من خلال خط أنابيب كامل: Crop و OCR و الترجمة how to use batch-translate batch-translate alternative batch-translate setup guide what is batch-translate batch-translate vs Google Translate batch-translate install automated book translation workflow crop ocr translate pipeline historical text translation 批量翻译 AI工具 Crop OCR 翻译技术 书籍翻译 自动化工作流 开发者工具 AI解决方案 Processes books through a complete pipeline: Crop → OCR → Translate References a translation priority list in `.claude/ROADMAP.md` Supports processing of high-priority untranslated books, including Kircher encyclopedias Utilizes command-line interface for workflow automation, as shown in `SKILL.md` Includes roadmap reference for tracking translation progress Automates tasks for historical texts such as Fludd: Utriusque Cosmi Historia batch-translate is a workflow process that automates book translation through a series of steps including cropping, optical character recognition, and translation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mashharuki/car/erc4337-privacy-wallet', 'community', 'mashharuki', 'car', 'mashharuki/car', 'erc4337-privacy-wallet', 0, 0, 57, '2026-03-08T01:57:15.316Z', '2026-03-08T02:02:47.314Z', '82ec00b11d97613ae9dbda179409ac1d2a8fa5c6c2822c9d0d324545abf62483', '{"id":"mashharuki/car/erc4337-privacy-wallet","name":"erc4337-privacy-wallet","description":{"en":"The erc4337-privacy-wallet skill provides comprehensive support for developing ERC-4337 compliant Account Abstraction wallets with privacy-preserving features. It benefits developers working on vehicle identity and sensitive data use cases.","zh":"ERC-4337隐私保护钱包提供智能合约模板、测试框架、隐私验证工具和安全最佳实践，保护用户隐私","ja":"ERC-4337プライバシーウォレットはスマートコントラクトテンプレート、テストフレームワーク、プライバシーバリデーションツール、セキュリティベストプラクティスを提供してユーザーのプライバシーを保護","ko":"ERC-4337 프라이버시 월렛은 스마트 컨트랙트 템플릿, 테스트 프레임워크, 프라이버시 검증 도구, 보안 최적화 방법을 제공하여 사용자의 프라이버시를 보호","es":"Esta habilidad proporciona soporte integral para desarrollar billeteras de abstracción de cuentas ERC-4337 con características de privacidad","fr":"Cette compétence fournit un support complet pour développer des portefeuilles d''abstraction de comptes ERC-4337 avec des caractéristiques de confidentialité","de":"Diese Fähigkeit bietet umfassende Unterstützung für die Entwicklung von ERC-4337-Kontenabstraktions-Wallets mit Datenschutzfunktionen","pt":"O erc4337-privacy-wallet fornece suporte abrangente para desenvolver carteiras de conta abstrata compatíveis com ERC-4337 com recursos de privacidade. Combina modelos de contrato inteligente, estruturas de teste e ferramentas de validação de privacidade.","ru":"ИИ Агент erc4337-privacy-wallet предоставляет комплексную поддержку для разработки кошельков абстракции учетных записей, соответствующих ERC-4337, с функциями защиты приватности. Он сочетает шаблоны умных контрактов, тестовые фреймворки и инструменты проверки приватности.","ar":"إرج 4337-خصوصية-محفظة يوفر دعمًا شاملاً لتحويل المحافظ المالية المجردة المتوافقة مع إرج 4337 مع ميزات الخصوصية. يجمع بين قوالب العقد الذكي وأطر الاختبار وأدوات التحقق من الخصوصية."},"seo":{"title":{"en":"erc4337-privacy-wallet: Secure Wallet Development for AI ...","zh":"ERC-4337隐私保护钱包设置指南","ja":"ERC-4337プライバシーウォレットのベストプラクティス","ko":"ERC-4337 프라이버시 월렛 구현 가이드","es":"Guía de configuración de billetera privada ERC-4337","fr":"Guide de mise en place du portefeuille privé ERC-4337","de":"Einrichtungsleitfaden für ERC-4337-Privatwallet","pt":"Guia de Configuração do erc4337-privacy-wallet para Desen...","ru":"Настройка ИИ Агента erc4337-privacy-wallet: Руководство д...","ar":"دليل إعداد إرج 4337-خصوصية-محفظة لل مطورين"},"description":{"en":"Unlock secure ERC-4337 wallet development with our expert AI agent skill, featuring smart contract templates and privacy validation tools. Get started now!","zh":"了解如何使用ERC-4337隐私保护钱包实现车辆身份和其他敏感数据的保护，提高AIエージェント的安全性","ja":"ERC-4337プライバシーウォレットを使用して車両のアイデンティティとその他の機密データを保護し、AIエージェントのセキュリティを高める","ko":"ERC-4337 프라이버시 월렛을 사용하여 차량 아이디와 다른 민감한 데이터를 보호하고 AI Tools의 보안을 강화하는 방법","es":"Desarrolle billeteras privadas ERC-4337 con funciones de privacidad para casos de uso de identidad de vehículos y datos sensibles","fr":"Développez des portefeuilles privés ERC-4337 avec des fonctionnalités de confidentialité pour les cas d''utilisation d''identité de véhicules et de données sen...","de":"Entwickeln Sie private ERC-4337-Wallets mit Datenschutzfunktionen für Fahrzeugidentitäts- und sensible Datenanwendungsfälle","pt":"Aprenda a configurar o erc4337-privacy-wallet com recursos de privacidade e segurança para desenvolvedores de soluções de carteira de conta abstrata","ru":"Узнайте, как настроить ИИ Агент erc4337-privacy-wallet с функциями защиты приватности и безопасности для разработчиков решений по абстракции учетных записей","ar":"تعرف على كيفية إعداد إرج 4337-خصوصية-محفظة مع ميزات الخصوصية والأمان للمطورين لحلول محفظة التمثيل الم_abstract"},"definition":{"en":"erc4337-privacy-wallet is a skill that enables the development of ERC-4337 compliant wallets with privacy-preserving features, using smart contract templates and testing frameworks.","zh":"ERC-4337隐私保护钱包是一种支持车辆身份和其他敏感数据保护的Account Abstraction钱包","ja":"ERC-4337プライバシーウォレットは車両のアイデンティティとその他の機密データを保護するためのアカウント抽象化ウォレット","ko":"ERC-4337 프라이버시 월렛은 차량 아이디와 다른 민감한 데이터를 보호하기 위한 어카운트 추상화 월렛","es":"Una billetera privada ERC-4337 es un tipo de billetera de abstracción de cuentas que protege la privacidad del usuario","fr":"Un portefeuille privé ERC-4337 est un type de portefeuille d''abstraction de comptes qui protège la confidentialité de l''utilisateur","de":"Ein privates ERC-4337-Wallet ist eine Art von Kontenabstraktions-Wallet, die den Datenschutz des Benutzers schützt","pt":"O erc4337-privacy-wallet é um recurso de desenvolvimento que fornece suporte para criar carteiras de conta abstrata com privacidade e segurança","ru":"ИИ Агент erc4337-privacy-wallet - это функция разработки, которая предоставляет поддержку для создания кошельков абстракции учетных записей с защитой приватности и безопасности","ar":"إرج 4337-خصوصية-محفظة هو ميزة تطوير توفر الدعم لإنشاء محافظ التمثيل الم_abstract مع الخصوصية والأمان"},"features":{"en":["Combines smart contract templates for ERC-4337 compliance","Includes testing frameworks for secure wallet implementation","Provides privacy validation tools for sensitive data protection","Supports security best practices for on-chain functionality","Enables secure implementation of wallets for vehicle identity use cases","Offers comprehensive support for Account Abstraction wallet development"],"zh":["智能合约模板","测试框架","隐私验证工具","安全最佳实践","Account Abstraction钱包支持"],"ja":["スマートコントラクトテンプレート","テストフレームワーク","プライバシーバリデーションツール","セキュリティベストプラクティス","アカウント抽象化ウォレット対応"],"ko":["스마트 컨트랙트 템플릿","테스트 프레임워크","프라이버시 검증 도구","보안 최적화 방법","어카운트 추상화 월렛 지원"],"es":["Plantillas de contrato inteligente para billeteras ERC-4337","Herramientas de validación de privacidad para casos de uso de identidad de vehículos","Marco de pruebas para garantizar la seguridad y la privacidad","Mejores prácticas para la implementación segura de billeteras","Soporte para la protección de datos sensibles","Funcionalidades de privacidad para mantener la funcionalidad en la cadena"],"fr":["Modèles de contrat intelligent pour les portefeuilles ERC-4337","Outils de validation de la confidentialité pour les cas d''utilisation d''identité de véhicules","Cadre de tests pour garantir la sécurité et la confidentialité","Bonnes pratiques pour la mise en œuvre sécurisée des portefeuilles","Support pour la protection des données sensibles","Fonctionnalités de confidentialité pour maintenir la fonctionnalité sur la chaîne"],"de":["Smart-Contract-Vorlagen für ERC-4337-Wallets","Werkzeuge zur Validierung des Datenschutzes für Fahrzeugidentitätsanwendungsfälle","Testrahmen zur Gewährleistung von Sicherheit und Datenschutz","Best Practices für die sichere Implementierung von Wallets","Unterstützung für den Schutz sensibler Daten","Datenschutzfunktionen zur Aufrechterhaltung der Funktionalität in der Kette"],"pt":["Modelos de contrato inteligente para carteiras de conta abstrata","Estruturas de teste para garantir a segurança e privacidade","Ferramentas de validação de privacidade para proteger dados sensíveis","Suporte à implementação de wallets compatíveis com ERC-4337","Recursos de segurança para proteger contra acessos não autorizados"],"ru":["Шаблоны умных контрактов для кошельков абстракции учетных записей","Тестовые фреймворки для обеспечения безопасности и защиты приватности","Инструменты проверки приватности для защиты конфиденциальных данных","Поддержка реализации кошельков, соответствующих ERC-4337","Механизмы безопасности для защиты от несанкционированного доступа"],"ar":["قوالب العقد الذكي للمحافظ المالية المجردة","أطر الاختبار لضمان الأمان والخصوصية","أدوات التحقق من الخصوصية لحماية البيانات الحساسة","دعم تنفيذ المحافظ المتوافقة مع إرج 4337","ميزات الأمان لحماية ضد الوصول غير المصرح به"]},"keywords":{"en":["how to use erc4337-privacy-wallet","what is erc4337-privacy-wallet","erc4337-privacy-wallet alternative","erc4337-privacy-wallet vs metamask","erc4337-privacy-wallet install","erc4337-privacy-wallet setup guide","erc4337-privacy-wallet for vehicle identity","erc4337-privacy-wallet for sensitive data","erc4337-privacy-wallet security best practices","erc4337-privacy-wallet account abstraction"],"zh":["ERC-4337","隐私保护钱包","AIエージェント","智能合约","Account Abstraction","车辆身份保护","敏感数据保护"],"ja":["ERC-4337","プライバシーウォレット","AIエージェント","スマートコントラクト","アカウント抽象化","車両のアイデンティティ保護","機密データ保護"],"ko":["ERC-4337","프라이버시 월렛","AI Tools","스마트 컨트랙트","어카운트 추상화","차량 아이디 보호","민감한 데이터 보호"],"es":["billetera privada ERC-4337","desarrollo de billeteras de abstracción de cuentas","privacidad en la cadena","seguridad de datos sensibles","contrato inteligente para billeteras","herramientas de validación de privacidad","mejores prácticas para la implementación segura","ERC-4337 para vehículos","privacidad en casos de uso de identidad de vehículos"],"fr":["portefeuille privé ERC-4337","développement de portefeuilles d''abstraction de comptes","confidentialité sur la chaîne","sécurité des données sensibles","contrat intelligent pour les portefeuilles","outils de validation de la confidentialité","bonnes pratiques pour la mise en œuvre sécurisée","ERC-4337 pour les véhicules","confidentialité dans les cas d''utilisation d''identité de véhicules"],"de":["privates ERC-4337-Wallet","Entwicklung von Kontenabstraktions-Wallets","Datenschutz in der Kette","Sicherheit sensibler Daten","Smart-Contract für Wallets","Werkzeuge zur Validierung des Datenschutzes","Best Practices für die sichere Implementierung","ERC-4337 für Fahrzeuge","Datenschutz in Fahrzeugidentitätsanwendungsfällen"],"pt":["erc4337-privacy-wallet","desenvolvimento de carteiras de conta abstrata","privacidade e segurança em blockchain","carteiras de conta abstrata compatíveis com ERC-4337","desenvolvimento de soluções de privacidade","segurança de dados em carteiras digitais"],"ru":["ИИ Агент erc4337-privacy-wallet","Разработка кошельков абстракции учетных записей","Защита приватности и безопасности в блокчейне","Кошельки абстракции учетных записей, соответствующие ERC-4337","Разработка решений по защите приватности","Безопасность данных в цифровых кошельках"],"ar":["إرج 4337-خصوصية-محفظة","تطوير المحافظ المالية المجردة","الخصوصية والأمان في سلاسل الكتل","المحافظ المالية المجردة المتوافقة مع إرج 4337","تطوير حلول الخصوصية","أمان البيانات في المحافظ الرقمية"]}},"owner":"mashharuki","repo":"car","repoPath":"mashharuki/car","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.316Z","topics":[],"category":"community","skillMd":{"name":"erc4337-privacy-wallet","description":"Privacy-preserving ERC-4337 wallet development for vehicle identity and sensitive data protection. Use when implementing ERC-4337 account abstraction wallets that handle sensitive information (vehicle license plates, biometric data, personal IDs) requiring on-chain privacy. Triggers on requests like implement ERC-4337 wallet for vehicle, create privacy-protected account abstraction, build wallet with vehicle number privacy, develop ERC-4337 with ZK proof integration, or any smart contract wallet development requiring commitment schemes, deterministic address generation, and sensitive data protection.","bodyPreview":"# ERC-4337 Privacy-Protected Wallet\n\n## Overview\n\nThis skill provides comprehensive support for developing ERC-4337 compliant Account Abstraction wallets with privacy-preserving features, specifically designed for vehicle identity and other sensitive data use cases. It combines smart contract templates, testing frameworks, privacy validation tools, and security best practices to enable the secure implementation of wallets that protect user privacy while maintaining on-chain functionality.\n\n**Key","body":"# ERC-4337 Privacy-Protected Wallet\n\n## Overview\n\nThis skill provides comprehensive support for developing ERC-4337 compliant Account Abstraction wallets with privacy-preserving features, specifically designed for vehicle identity and other sensitive data use cases. It combines smart contract templates, testing frameworks, privacy validation tools, and security best practices to enable the secure implementation of wallets that protect user privacy while maintaining on-chain functionality.\n\n**Key Capabilities:**\n- Privacy-protected smart contract templates (PrivacyProtectedAccount, AccountFactory, VehicleRegistry)\n- Commitment scheme implementation for sensitive data (vehicle plates, personal info)\n- Deterministic address generation using CREATE2\n- Comprehensive test suites with privacy verification\n- Automated privacy validation tooling\n- Security and compliance checklists\n\n## When to Use This Skill\n\nInvoke this skill when you encounter requests involving:\n\n- **Vehicle Identity Wallets**: \"Create a wallet from vehicle license plate information\"\n- **ERC-4337 Implementation**: \"Implement account abstraction for privacy-protected accounts\"\n- **Sensitive Data Protection**: \"Build wallet that hides user''s personal identification\"\n- **Deterministic Address Generation**: \"Generate predictable wallet addresses from private data\"\n- **ZK Proof Integration**: \"Add zero-knowledge proof verification to ERC-4337 wallet\"\n- **Privacy Auditing**: \"Validate that my smart contract doesn''t leak sensitive information\"\n\n## Quick Start Guide\n\n### 1. Understand the Requirements\n\nAsk the user these key questions:\n- What sensitive data needs protection? (vehicle plate, biometric, etc.)\n- Is deterministic address generation required?\n- Are ZK proofs needed, or is commitment hashing sufficient?\n- What is the target blockchain/testnet?\n\n### 2. Set Up the Project\n\n```bash\n# Copy contract templates\ncp -r assets/contracts/* ./contracts/\n\n# Install dependencies\ncd contracts\nnpm install\n\n# Compile contracts\nnpm run compile\n```\n\n### 3. Customize for Your Use Case\n\n**For vehicle-based wallets:**\n```solidity\n// Off-chain: Compute vehicle commitment\nconst plateNumber = \"ABC-1234\";\nconst userSalt = ethers.id(\"user-secret-entropy\");\nconst commitment = ethers.keccak256(\n    ethers.solidityPacked([\"string\", \"bytes32\"], [plateNumber, userSalt])\n);\n\n// Deploy account with commitment\nconst account = await factory.createAccount(\n    ownerAddress,\n    commitment,\n    12345  // deployment salt\n);\n```\n\n**For biometric/other sensitive data:**\n```solidity\n// Replace plateNumber with your sensitive data\nconst biometricHash = computeHash(biometricData);\nconst commitment = ethers.keccak256(\n    ethers.solidityPacked([\"bytes32\", \"bytes32\"], [biometricHash, userSalt])\n);\n```\n\n### 4. Run Privacy Validation\n\n```bash\n# Validate that contracts don''t leak sensitive data\npython scripts/validate_privacy.py contracts/PrivacyProtectedAccount.sol\n```\n\n### 5. Run Tests\n\n```bash\n# Run comprehensive test suite\nnpm test\n\n# Run specific test file\nnpx hardhat test tests/PrivacyProtectedAccount.test.ts\n```\n\n## Core Components\n\n### 1. PrivacyProtectedAccount\n\nThe main account contract that implements ERC-4337''s `IAccount` interface with privacy features.\n\n**Key Features:**\n- Stores only commitment (hash) of sensitive data, never raw values\n- Deterministic address generation via CREATE2\n- ERC-4337 compliant UserOperation validation\n- Owner-based access control\n- Batch transaction execution\n\n**Usage:**\n```solidity\n// Deploy via factory\nconst account = await factory.createAccount(owner, vehicleCommitment, salt);\n\n// Verify ownership without revealing data\nconst isValid = await account.verifyVehicleOwnership(plateNumber, userSalt);\n\n// Execute transaction\nawait account.execute(targetAddress, value, calldata);\n```\n\n**Privacy Guarantee:**\n- Vehicle commitment is stored as `bytes32` hash\n- Raw plate number never touches blockchain\n- Verification is view-only (off-chain safe)\n\n### 2. AccountFactory\n\nFactory contract for deploying PrivacyProtectedAccount instances with deterministic addresses.\n\n**Key Features:**\n- CREATE2-based deterministic deployment\n- Counterfactual address computation\n- Batch account creation\n- Cross-chain address consistency\n\n**Usage:**\n```solidity\n// Compute address before deployment\nconst predictedAddress = await factory.getAddress(owner, commitment, salt);\n\n// Deploy account\nconst account = await factory.createAccount(owner, commitment, salt);\n\n// Address matches prediction\nassert(accountAddress === predictedAddress);\n```\n\n**Use Cases:**\n- Receive funds before account creation\n- Consistent addresses across multiple chains\n- Privacy-preserving wallet generation\n\n### 3. VehicleRegistry\n\nOptional registry contract for managing vehicle-to-wallet mappings with privacy.\n\n**Key Features:**\n- Maps commitments to wallet addresses\n- Authorized verifier system\n- Selective disclosure support\n- Batch registration\n\n**Usage:**\n```solidity\n// Register vehicle with commitment only\nawait registry.registerVehicle(commitment, walletAddress, metadataHash);\n\n// Verify registration (authorized only)\nconst isRegistered = await registry.verifyVehicleRegistration(commitment);\n\n// Update commitment (ownership transfer)\nawait registry.updateVehicleCommitment(oldCommitment, newCommitment);\n```\n\n## Implementation Workflow\n\n### Step 1: Define Privacy Model\n\nDetermine what needs privacy protection:\n\n**Example - Vehicle Wallet:**\n```\nSensitive: License plate number\nPublic: Wallet address, transaction history\nCommitment: keccak256(plateNumber + salt)\n```\n\n**Example - Biometric Wallet:**\n```\nSensitive: Fingerprint hash\nPublic: Wallet address\nCommitment: keccak256(fingerprintHash + salt)\n```\n\n### Step 2: Generate Commitment Off-Chain\n\n**CRITICAL: Never pass raw sensitive data to blockchain functions.**\n\n```javascript\n// Frontend/Backend - OFF-CHAIN computation\nimport { ethers } from ''ethers'';\n\nfunction generateCommitment(sensitiveData, userSecret) {\n    // Generate cryptographically secure salt\n    const salt = ethers.keccak256(\n        ethers.solidityPacked(\n            [''string'', ''uint256'', ''address''],\n            [userSecret, Date.now(), userAddress]\n        )\n    );\n\n    // Compute commitment\n    const commitment = ethers.keccak256(\n        ethers.solidityPacked([''string'', ''bytes32''], [sensitiveData, salt])\n    );\n\n    return { commitment, salt };\n}\n\n// Usage\nconst { commitment, salt } = generateCommitment(licensePlate, userSecret);\n// Store salt securely off-chain!\n// Send only commitment to blockchain\n```\n\n### Step 3: Deploy Account\n\n```javascript\n// Connect to factory\nconst factory = await ethers.getContractAt(''AccountFactory'', factoryAddress);\n\n// Optional: Predict address first\nconst predictedAddress = await factory.getAddress(\n    ownerAddress,\n    commitment,\n    deploymentSalt\n);\nconsole.log(''Account will be deployed at:'', predictedAddress);\n\n// Deploy account\nconst tx = await factory.createAccount(ownerAddress, commitment, deploymentSalt);\nawait tx.wait();\n\nconsole.log(''Account deployed at:'', predictedAddress);\n```\n\n### Step 4: Create and Submit UserOperation\n\n```javascript\nimport { ethers } from ''ethers'';\n\n// Build UserOperation\nconst userOp = {\n    sender: accountAddress,\n    nonce: await account.getNonce(),\n    initCode: ''0x'',  // Empty if account exists\n    callData: account.interface.encodeFunctionData(''execute'', [\n        targetAddress,\n        value,\n        data\n    ]),\n    accountGasLimits: ethers.solidityPacked(\n        [''uint128'', ''uint128''],\n        [verificationGasLimit, callGasLimit]\n    ),\n    preVerificationGas,\n    gasFees: ethers.solidityPacked(\n        [''uint128'', ''uint128''],\n        [maxPriorityFeePerGas, maxFeePerGas]\n    ),\n    paymasterAndData: ''0x'',  // Or paymaster address + data\n    signature: ''0x''  // Will be filled after signing\n};\n\n// Sign UserOperation\nconst userOpHash = await account.getUserOpHash(userOp);\nconst signature = await owner.signMessage(ethers.getBytes(userOpHash));\nuserOp.signature = signature;\n\n// Submit to bundler\nawait bundler.sendUserOperation(userOp);\n```\n\n### Step 5: Verify Privacy Protection\n\n```bash\n# Run automated privacy validation\npython scripts/validate_privacy.py contracts/YourContract.sol\n\n# Expected output:\n# ✅ PRIVACY VALIDATION PASSED\n# No privacy violations detected.\n```\n\n## Privacy Patterns\n\n### Pattern 1: Basic Commitment\n\n```solidity\n// Off-chain\nconst commitment = keccak256(abi.encodePacked(sensitiveData, salt));\n\n// On-chain\nbytes32 public dataCommitment;\n\nfunction initialize(bytes32 _commitment) external {\n    dataCommitment = _commitment;\n}\n\nfunction verify(string memory data, bytes32 salt) external view returns (bool) {\n    return keccak256(abi.encodePacked(data, salt)) == dataCommitment;\n}\n```\n\n### Pattern 2: Multi-Attribute Commitment\n\n```solidity\n// For vehicles with multiple attributes\nstruct VehicleData {\n    string plateNumber;\n    string model;\n    uint256 year;\n}\n\n// Off-chain\nconst commitment = keccak256(abi.encode(\n    vehicleData.plateNumber,\n    vehicleData.model,\n    vehicleData.year,\n    salt\n));\n```\n\n### Pattern 3: ZK Proof Integration\n\nFor advanced privacy (see `references/privacy-patterns.md` for full examples):\n\n```solidity\n// Verify ZK proof instead of revealing data\nfunction _validateSignature(\n    PackedUserOperation calldata userOp,\n    bytes32 userOpHash\n) internal override returns (uint256) {\n    (bytes memory proof, bytes memory publicInputs) =\n        abi.decode(userOp.signature, (bytes, bytes));\n\n    require(zkVerifier.verify(proof, publicInputs), \"Invalid proof\");\n    return SIG_VALIDATION_SUCCESS;\n}\n```\n\n## Testing Strategy\n\n### Privacy Tests\n\n```typescript\ndescribe(\"Privacy Protection\", () => {\n    it(\"should not store raw sensitive data\", async () => {\n        // Verify storage doesn''t contain plate number\n        for (let i = 0; i < 20; i++) {\n            const storage = await ethers.provider.getStorage(account.address, i);\n            expect(storage).to.not.include(ethers.hexlify(ethers.toUtf8Bytes(plateNumber)));\n        }\n    });\n\n    it(\"should verify with correct preimage\", async () => {\n        const isValid = await account.verifyVehicleOwnership(plateNumber, salt);\n        expect(isValid).to.be.true;\n    });\n\n    it(\"should reject wrong preimage\", async () => {\n        const isValid = await account.verifyVehicleOwnership(\"WRONG-PLATE\", salt);\n        expect(isValid).to.be.false;\n    });\n});\n```\n\n### ERC-4337 Tests\n\n```typescript\ndescribe(\"UserOperation Validation\", () => {\n    it(\"should validate correct signature\", async () => {\n        const userOp = buildUserOp({ sender: account.address });\n        const userOpHash = await entryPoint.getUserOpHash(userOp);\n        userOp.signature = await owner.signMessage(ethers.getBytes(userOpHash));\n\n        await expect(entryPoint.handleOps([userOp], bundler.address))\n            .to.not.be.reverted;\n    });\n});\n```\n\n## Security Checklist\n\nBefore deploying to mainnet, verify:\n\n- [ ] Run privacy validation: `python scripts/validate_privacy.py`\n- [ ] All tests passing: `npm test`\n- [ ] No raw sensitive data in storage or events\n- [ ] Commitment generation uses strong salt (≥256 bits entropy)\n- [ ] Verification functions are `view` or `pure`\n- [ ] Access control properly implemented\n- [ ] EntryPoint address is correct\n- [ ] Contracts verified on Etherscan\n- [ ] Professional security audit completed\n\nSee `references/security-checklist.md` for complete checklist.\n\n## Common Pitfalls\n\n### ❌ Storing Raw Sensitive Data\n\n```solidity\n// NEVER DO THIS\ncontract BadExample {\n    string public licensePlate;  // Publicly visible!\n}\n```\n\n### ✅ Correct Approach\n\n```solidity\n// DO THIS\ncontract GoodExample {\n    bytes32 public vehicleCommitment;  // Only hash stored\n}\n```\n\n### ❌ Weak Salt Generation\n\n```solidity\n// WEAK - predictable\nbytes32 salt = bytes32(block.timestamp);\n```\n\n### ✅ Strong Salt\n\n```solidity\n// STRONG - unique per user with high entropy\nbytes32 salt = keccak256(abi.encodePacked(\n    userSecret,\n    block.timestamp,\n    block.prevrandao,\n    msg.sender\n));\n```\n\n### ❌ Exposing Data in Events\n\n```solidity\n// NEVER DO THIS\nevent VehicleRegistered(string plateNumber);\n```\n\n### ✅ Events with Commitments\n\n```solidity\n// DO THIS\nevent VehicleRegistered(bytes32 indexed commitment);\n```\n\n## Advanced Topics\n\n### ZK-SNARK Integration\n\nFor zero-knowledge proof integration, see `references/privacy-patterns.md` section on ZK proofs.\n\n**High-level flow:**\n1. Generate ZK circuit for vehicle ownership\n2. Prove knowledge of plate number without revealing it\n3. Verify proof on-chain in `_validateSignature()`\n\n### Cross-Chain Deployment\n\n```bash\n# Deploy to multiple networks with same addresses\nnpx hardhat run scripts/deploy.ts --network sepolia\nnpx hardhat run scripts/deploy.ts --network polygonAmoy\n\n# Addresses match due to CREATE2 determinism\n```\n\n### Gasless Transactions with Paymaster\n\n```javascript\n// Add paymaster to UserOperation\nuserOp.paymasterAndData = ethers.solidityPacked(\n    [''address'', ''bytes''],\n    [paymasterAddress, paymasterData]\n);\n\n// User doesn''t pay gas - paymaster sponsors it\n```\n\n## Resources\n\n### Bundled Resources\n\n- **`assets/contracts/`**: Production-ready contract templates\n  - `PrivacyProtectedAccount.sol` - Main account contract\n  - `AccountFactory.sol` - Deterministic factory\n  - `VehicleRegistry.sol` - Optional registry\n  - `package.json`, `hardhat.config.ts` - Project setup\n\n- **`assets/tests/`**: Comprehensive test suites\n  - Privacy protection tests\n  - ERC-4337 compliance tests\n  - Gas optimization tests\n\n- **`scripts/validate_privacy.py`**: Automated privacy validation tool\n  - Scans for sensitive data leaks\n  - Validates commitment patterns\n  - Checks event safety\n\n- **`references/`**: In-depth documentation\n  - `erc4337-architecture.md` - ERC-4337 deep dive\n  - `privacy-patterns.md` - Privacy implementation patterns\n  - `security-checklist.md` - Comprehensive security guide\n\n### External Resources\n\n- [ERC-4337 Specification](https://eips.ethereum.org/EIPS/eip-4337)\n- [Account Abstraction Docs](https://docs.erc4337.io/)\n- [MynaWallet Reference](https://github.com/MynaWallet/monorepo)\n- [Toyota MON](https://www.toyota-blockchain-lab.org/)\n- [OpenZeppelin Contracts](https://docs.openzeppelin.com/contracts/)\n\n## Support and Troubleshooting\n\n### Common Issues\n\n**Issue: Gas estimation fails**\n```\nSolution: Ensure account has sufficient deposit in EntryPoint\nawait account.addDeposit({ value: ethers.parseEther(\"0.1\") });\n```\n\n**Issue: Signature validation fails**\n```\nSolution: Check that userOpHash is computed correctly\nconst userOpHash = await entryPoint.getUserOpHash(userOp);\n```\n\n**Issue: Privacy validation fails**\n```\nSolution: Review reported violations and fix\n- Remove string storage for sensitive data\n- Make verification functions view/pure\n- Use commitments instead of raw data\n```\n\n### Getting Help\n\n1. Check `references/` for detailed documentation\n2. Review test files for usage examples\n3. Run privacy validation for security issues\n4. Consult ERC-4337 documentation for protocol questions\n\n## 参考文献\n- [ETHGlobalTokyo上位チーム勝手に解説 Myna](https://zenn.dev/kozayupapa/scraps/782815787c5c33)\n- [a42inc/ETHGlobalTokyo2023](https://github.com/a42inc/ETHGlobalTokyo2023)\n- [マイナンバーカードの公開鍵からSmartAccountのアドレスを一意に導出する方法 Study](https://zenn.dev/kozayupapa/articles/b0025b213ed39f)\n- [マイナンバーカードで署名をするところを動かしてみよう:ERC-4337 (AccountAbstraction)](https://zenn.dev/kozayupapa/articles/3347b360712b12)\n- [MynaWallet/monorepo](https://github.com/MynaWallet/monorepo)\n- [【Account Abstraction】UserOperation周りの具体的な実装について](https://zenn.dev/pokena/articles/84e243cf91a2cf)\n- [マイナウォレットメモ](https://zenn.dev/pokena/scraps/c8d8189a1c6cb9)\n"},"lastSynced":"2026-03-08T02:02:47.314Z","agentAnalysis":{"suitability":{"en":"Ideal for Blockchain Agents focused on Ethereum development needing advanced ERC-4337 compliant wallet integration with privacy-preserving features.","zh":"适合专注于以太坊开发的区块链代理，需要高级ERC-4337兼容钱包集成和隐私保护功能。","ja":"イーサリアム開発に焦点を当てたブロックチェーンエージェントに適しています。高度なERC-4337準拠のウォレット統合とプライバシー保護機能が必要です。","ko":"이더리움 개발에 중점을 둔 블록체인 에이전트에게 적합합니다. 고급 ERC-4337 호환 워レット 통합 및 개인 정보 보호 기능이 필요합니다.","es":"Ideal para agentes de Blockchain centrados en el desarrollo de Ethereum que necesitan una integración de billetera avanzada compatible con ERC-4337 con características de privacidad.","fr":"Idéal pour les agents Blockchain axés sur le développement Ethereum nécessitant une intégration de portefeuille avancée compatible ERC-4337 avec des fonctionnalités de préservation de la vie privée.","de":"Ideal für Blockchain-Agents, die auf Ethereum-Entwicklung fokussiert sind und eine erweiterte ERC-4337-kompatible Wallet-Integration mit Datenschutzfunktionen benötigen.","pt":"Ideal para Agentes de Blockchain focados no desenvolvimento do Ethereum que necessitam de integração avançada de carteira compatível com ERC-4337 com recursos de preservação da privacidade.","ru":"Идеально для агентов блокчейна, ориентированных на разработку Ethereum, требующих расширенной интеграции кошелька, соответствующего ERC-4337, с функциями сохранения конфиденциальности.","ar":"مثالي للوكلاء blockchain الذين يركزون على تطوير Ethereum وهم بحاجة إلى دمج محفظة متقدم متوافق مع ERC-4337 مع ميزات الحفاظ على الخصوصية."},"recommendation":{"en":"Empowers agents to develop secure and private Account Abstraction wallets using ERC-4337 compliant smart contract templates, testing frameworks, and privacy validation tools, ensuring on-chain functionality while protecting user privacy, particularly for vehicle identity and sensitive data use cases.","zh":"赋予代理开发安全且具有ERC-4337兼容的账户抽象钱包，使用智能合约模板、测试框架和隐私验证工具，确保链上功能同时保护用户隐私，特别是车辆身份和敏感数据使用案例。","ja":"エージェントに、ERC-4337準拠のスマートコントラクトテンプレート、テストフレームワーク、プライバシーバリデーションツールを使用して、セキュアでプライベートなアカウント抽象ウォレットを開発する力を与え、オンチェーン機能を保証しながらユーザーのプライバシーを保護する、特に車両IDと機密データの使用例。","ko":"에이전트가 보안且고 개인 정보를 보호하는 계정 추상화 월렛을 개발할 수 있도록_empowers_, ERC-4337 호환 스마트 계약 템플릿, 테스트 프레임워크 및 개인 정보 보호 유효성 검사 도구를 사용하여, 온체인 기능을 보장하면서 사용자의 개인 정보를 보호하는_power_, 특히 차량 ID 및 민감한 데이터 사용 사례.","es":"Habilita a los agentes a desarrollar billeteras de abstracción de cuentas seguras y privadas utilizando plantillas de contrato inteligente compatibles con ERC-4337, marcos de prueba y herramientas de validación de privacidad, garantizando la funcionalidad en la cadena mientras se protege la privacidad del usuario, particularmente para casos de uso de identidad de vehículo y datos sensibles.","fr":"Permet aux agents de développer des portefeuilles d''abstraction de comptes sécurisés et privés en utilisant des modèles de contrat intelligent compatibles ERC-4337, des cadres de test et des outils de validation de confidentialité, garantissant la fonctionnalité sur la chaîne tout en protégeant la vie privée de l''utilisateur, en particulier pour les cas d''utilisation de l''identité des véhicules et des données sensibles.","de":"Ermöglicht es Agenten, sichere und private Kontenabstraktions-Wallets mithilfe von ERC-4337-kompatiblen Smart-Contract-Vorlagen, Testframeworks und Datenschutz-Validierungstools zu entwickeln, wodurch die Funktionalität in der Kette gewährleistet wird, während die Privatsphäre des Benutzers geschützt wird, insbesondere für Fahrzeugidentitäts- und sensiblen Datenanwendungsfälle.","pt":"Habilita os agentes a desenvolver carteiras de Abstração de Conta seguras e privadas usando modelos de contrato inteligente compatíveis com ERC-4337, estruturas de teste e ferramentas de validação de privacidade, garantindo a funcionalidade na cadeia enquanto protege a privacidade do usuário, particularmente para casos de uso de identidade de veículo e dados sensíveis.","ru":"Наделяет агентов возможностью разработать безопасные и приватные кошельки Абстракции Аккаунта с использованием шаблонов умных контрактов, соответствующих ERC-4337, тестовых фреймворков и инструментов проверки приватности, обеспечивая функциональность в цепочке, при этом защищая конфиденциальность пользователей, особенно для случаев использования идентификации транспортных средств и чувствительных данных.","ar":"تمكّن الوكلاء من تطوير محافظ抽象 الحساب الآمنة والخاصة باستخدام قوالب عقود ذكية متوافقة مع ERC-4337 وأطر اختبار وأدوات التحقق من الخصوصية، مما يضمن الوظيفة في السلسلة مع حماية خصوصية المستخدم، özellikle في casos de uso de identidade de veículo وبيانات حساسة."},"useCases":{"en":["Developing ERC-4337 compliant Account Abstraction wallets with privacy-preserving features","Implementing secure and private vehicle identity management systems","Building sensitive data storage solutions with on-chain functionality and privacy protection"],"zh":["开发具有隐私保护功能的ERC-4337兼容的账户抽象钱包","实施安全且具有隐私保护的车辆身份管理系统","构建具有链上功能和隐私保护的敏感数据存储解决方案"],"ja":["プライバシー保護機能を備えたERC-4337準拠のアカウント抽象ウォレットを開発する","セキュアでプライベートな車両ID管理システムを実装する","オンチェーン機能とプライバシー保護を備えた機密データストレージソリューションを構築する"],"ko":["개인 정보 보호 기능을 갖춘 ERC-4337 호환 계정 추상화 월렛 개발","보안 및 개인 정보 보호 차량 ID 관리 시스템 구현","온체인 기능 및 개인 정보 보호를 갖춘 민감한 데이터 저장 솔루션 구축"],"es":["Desarrollar billeteras de abstracción de cuentas compatibles con ERC-4337 con características de privacidad.","Implementar sistemas de gestión de identidad de vehículo seguros y privados.","Construir soluciones de almacenamiento de datos sensibles con funcionalidad en la cadena y protección de la privacidad."],"fr":["Développer des portefeuilles d''abstraction de comptes compatibles ERC-4337 avec des fonctionnalités de préservation de la vie privée.","Mettre en œuvre des systèmes de gestion d''identité de véhicule sécurisés et privés.","Construire des solutions de stockage de données sensibles avec une fonctionnalité sur la chaîne et une protection de la vie privée."],"de":["ERC-4337-kompatible Kontenabstraktions-Wallets mit Datenschutzfunktionen entwickeln.","Sichere und private Fahrzeugidentitätsmanagementsysteme implementieren.","Lösungen für den Speicher von sensiblen Daten mit Kettenfunktionalität und Datenschutz aufbauen."],"pt":["Desenvolver carteiras de Abstração de Conta compatíveis com ERC-4337 com recursos de preservação da privacidade","Implementar sistemas de gerenciamento de identidade de veículo seguros e privados","Construir soluções de armazenamento de dados sensíveis com funcionalidade na cadeia e proteção de privacidade"],"ru":["Разработать кошельки Абстракции Аккаунта, соответствующие ERC-4337, с функциями сохранения конфиденциальности","Реализовать безопасные и приватные системы управления идентификацией транспортных средств","Построить решения для хранения чувствительных данных с функциональностью в цепочке и защитой приватности"],"ar":["تطوير محافظ抽象 الحساب المتوافقة مع ERC-4337 مع ميزات الحفاظ على الخصوصية","تنفيذ أنظمة إدارة الهوية الآمنة والخاصة للمركبات","بناء حلول لتخزين البيانات الحساسة مع الوظيفة في السلسلة وحماية الخصوصية"]},"limitations":{"en":["Requires knowledge of Ethereum smart contract development","Specifically designed for ERC-4337 compliance, may not be compatible with other blockchain protocols"],"zh":["需要以太坊智能合约开发知识","专门为ERC-4337兼容设计，可能与其他区块链协议不兼容"],"ja":["イーサリアムスマートコントラクト開発の知識が必要","ERC-4337準拠のために特別に設計されており、他のブロックチェーンプロトコルと互換性がない可能性がある"],"ko":["이더리움 스마트 계약 개발 지식이 필요합니다.","ERC-4337 호환을 위해 특별히 설계되었으므로 다른 블록체인 프로토콜과 호환되지 않을 수 있습니다."],"es":["Requiere conocimiento del desarrollo de contratos inteligentes de Ethereum.","Diseñado específicamente para la compatibilidad con ERC-4337, puede que no sea compatible con otros protocolos de blockchain."],"fr":["Nécessite des connaissances en développement de contrats intelligents Ethereum.","Conçu spécifiquement pour la compatibilité ERC-4337, il peut ne pas être compatible avec d''autres protocoles de blockchain."],"de":["Benötigt Kenntnisse in der Entwicklung von Ethereum-Smart-Contracts.","Speziell für ERC-4337-Kompatibilität konzipiert, kann es möglicherweise nicht mit anderen Blockchain-Protokollen kompatibel sein."],"pt":["Requer conhecimento de desenvolvimento de contrato inteligente do Ethereum","Especificamente projetado para conformidade com ERC-4337, pode não ser compatível com outros protocolos de blockchain"],"ru":["Требует знаний разработки умных контрактов Ethereum","Конкретно разработан для соответствия ERC-4337, может быть несовместим с другими протоколами блокчейна"],"ar":["يتطلب معرفة تطوير عقود ذكية Ethereum","صمّم خصيصًا للامتثال ل ERC-4337، قد لا يكون متوافقًا مع بروتوكولات blockchain الأخرى"]},"version":4},"contentHash":"82ec00b11d97613ae9dbda179409ac1d2a8fa5c6c2822c9d0d324545abf62483","qualityScore":57}');
