INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dudusoar/sdr-sentiment-analysis/manage-python-env', 'manage-python-env', 'dudusoar', 'sdr-sentiment-analysis', 'community', 'manage-python-env dudusoar sdr-sentiment-analysis community The manage-python-env skill provides tools for managing Python virtual environments using uv. It benefits developers by streamlining environment setup and dependency management. 管理 Python 虚拟环境的工具，使用 uv 快速安装和管理依赖项 Python の仮想環境を管理するツール、uv を使用して依存関係を迅速にインストールして管理 파이썬 가상 환경을 관리하는 도구, uv를 사용하여 의존성을 빠르게 설치하고 관리 Manage-python-env es una habilidad que proporciona herramientas y flujos de trabajo para administrar entornos de Python virtuales utilizando uv Manage-python-env est une compétence qui fournit des outils et des flux de travail pour gérer les environnements Python virtuels en utilisant uv Manage-python-env ist eine Fähigkeit, die Tools und Workflows zur Verwaltung von Python-Virtualumgebungen unter Verwendung von uv bereitstellt O manage-python-env é uma habilidade que fornece ferramentas para gerenciar ambientes virtuais Python usando uv. Isso inclui criar ambientes, instalar dependências e gerenciar pacotes. Manage-python-env - это навык, который предоставляет инструменты для управления виртуальными средами Python с помощью uv. Это включает в себя создание сред, установку зависимостей и управление пакетами. manage-python-env هو مهارة يوفر أدوات لإدارة البيئات الافتراضية لبايثون باستخدام uv. هذا يشمل إنشاء بيئات، وتثبيت الإعتماديات، وإدارة الحزم. how to use manage-python-env manage-python-env setup guide uv package installer python virtual environment management manage-python-env alternative manage-python-env vs pip install manage-python-env python environment troubleshooting manage-python-env best practices Python 环境管理 uv安装 虚拟环境管理 依赖项管理 Python 开发工具 AIエージェント Python 环境设置 Installs uv for fast Python package installation Creates new virtual environments using uv Installs dependencies from requirements.txt or pyproject.toml Manages environment updates, freezes, and cleanups Troubleshoots common issues with uv manage-python-env is a skill that offers tools and workflows for managing Python virtual environments using uv, a fast Python package installer and resolver.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NmBoyd/claude_setup/python-dev-guidelines', 'community', 'NmBoyd', 'claude_setup', 'NmBoyd/claude_setup', 'python-dev-guidelines', 0, 0, 57, '2026-03-08T01:57:15.317Z', '2026-03-08T02:02:53.297Z', 'bd65334a9638a93f345cbd11076daea9b4c9c607ca6e17d9f96381c61fb8e5ad', '{"id":"NmBoyd/claude_setup/python-dev-guidelines","name":"python-dev-guidelines","description":{"en":"The python-dev-guidelines skill provides a setup for Python development, covering modern Python 3.12+ patterns, type safety, testing, and project organization, benefiting developers who want to establish consistency and best practices in their Python projects.","zh":"本指南介绍了Python开发的最佳实践，涵盖现代Python 3.12+模式、类型安全、测试和项目组织","ja":"このガイドラインでは、Python開発のベストプラクティスを紹介します。 moderne Python 3.12+パターン、型安全性、テスト、プロジェクト組織","ko":"이 가이드는 Python 개발의 모범 사례를介绍합니다. 현대적인 Python 3.12+ 패턴, 형식 안전성, 테스트 및 프로젝트 조직","es":"Configuración para desarrollo Python con Claude, siguiendo las pautas de Python 3.12+ y mejores prácticas","fr":"Configuration pour le développement Python avec Claude, suivant les directives de Python 3.12+ et les meilleures pratiques","de":"Konfiguration für Python-Entwicklung mit Claude, unter Einhaltung der Richtlinien von Python 3.12+ und Best Practices","pt":"O python-dev-guidelines é um conjunto de diretrizes para desenvolvedores Python que visa estabelecer consistência e boas práticas para projetos de IA","ru":"Python-dev-guidelines - это набор руководств для разработчиков Python, целью которого является установление последовательности и лучших практик для проектов ИИ","ar":"python-dev-guidelines هو مجموعة من الإرشادات لمطوري بايثون التي تهدف إلى تحقيق الاتساق وأفضل الممارسات لمشاريع الإي أι"},"seo":{"title":{"en":"python-dev-guidelines: Python 3.12+ Development Setup Gui...","zh":"Python开发指南：快速开始指南","ja":"Python開発ガイドライン：セットアップガイド","ko":"Python 개발 가이드라인: 설정 가이드","es":"Guía de Configuración para Desarrollo Python con Claude","fr":"Guide de Configuration pour le Développement Python avec ...","de":"Konfigurationsleitfaden für Python-Entwicklung mit Claude","pt":"Guia de Configuração para Desenvolvedores Python com Ferr...","ru":"Настройка Руководства для Разработчиков Python с ИИ Агентами","ar":"دليل إعداد لمطوري بايثون مع أدوات الإي أι"},"description":{"en":"Learn how to set up your Python development environment with python-dev-guidelines, featuring modern Python 3.12+ patterns, type safety, and project organiza...","zh":"了解Python开发的最佳实践，包括现代Python 3.12+模式、类型安全、测试和项目组织","ja":"Python開発のベストプラクティスを学ぶ、 moderne Python 3.12+パターン、型安全性、テスト、プロジェクト組織","ko":"Python 개발의 모범 사례를 배우는 현대적인 Python 3.12+ 패턴, 형식 안전성, 테스트 및 프로젝트 조직","es":"Establezca las mejores prácticas para el desarrollo de Python con Claude, incluyendo patrones modernos de Python 3.12+, seguridad de tipos y pruebas","fr":"Établissez les meilleures pratiques pour le développement Python avec Claude, notamment les modèles modernes Python 3.12+, la sécurité des types et les tests","de":"Stellen Sie die besten Praktiken für die Python-Entwicklung mit Claude ein, einschließlich moderner Python-3.12+-Muster, Typsicherheit und Tests","pt":"Aprenda a configurar o seu ambiente de desenvolvimento Python com as melhores práticas e padrões modernos para projetos de IA","ru":"Узнайте, как настроить среду разработки Python с современными стандартами и лучшими практиками для проектов ИИ","ar":"تعلم كيفية تكوين بيئة تطوير بايثون مع أفضل الممارسات والمعايير الحديثة لمشاريع الإي أι"},"definition":{"en":"python-dev-guidelines is a set of standards and best practices for Python development, focusing on modern Python 3.12+ patterns, type safety, and project organization.","zh":"Python开发指南是一套确立Python开发一致性和最佳实践的标准","ja":"Python開発ガイドラインは、Python開発の一貫性とベストプラクティスを確立するための規格です","ko":"Python 개발 가이드라인은 Python 개발의 일관성과 모범 사례를 확립하는 규격입니다","es":"Guía de desarrollo Python para Claude, que establece normas para la seguridad de tipos, pruebas y organización de proyectos","fr":"Guide de développement Python pour Claude, qui établit des normes pour la sécurité des types, les tests et l''organisation des projets","de":"Leitfaden für Python-Entwicklung mit Claude, der Standards für Typsicherheit, Tests und Projektorganisation festlegt","pt":"O que é python-dev-guidelines? É um conjunto de padrões e diretrizes para desenvolvedores Python que trabalham com projetos de IA","ru":"Что такое python-dev-guidelines? Это набор стандартов и руководств для разработчиков Python, работающих с проектами ИИ","ar":"ما هو python-dev-guidelines؟ هو مجموعة من المعايير والإرشادات لمطوري بايثون الذين يعملون على مشاريع الإي أι"},"features":{"en":["Enforces strict typing with Pydantic v2 models","Uses ruff for formatting with 96-char lines and double quotes","Supports async/await syntax with FastAPI","Requires Python 3.12+ for modern development patterns","Includes project organization and testing guidelines","Utilizes `from __future__ import annotations` for type safety"],"zh":["使用现代Python 3.12+模式","支持FastAPI和async/await","使用ruff进行代码格式化","支持Pydantic v2模型","使用strict typing和类型安全"],"ja":["モダンなPython 3.12+パターンを使用","FastAPIとasync/awaitをサポート","ruffを使用してコードをフォーマット","Pydantic v2モデルをサポート","strict typingと型安全性を使用"],"ko":["현대적인 Python 3.12+ 패턴을 사용","FastAPI와 async/await를 지원","ruff를 사용하여 코드를 포맷팅","Pydantic v2 모델을 지원","strict typing과 형식 안전성을 사용"],"es":["Patrones modernos de Python 3.12+","Seguridad de tipos estricta con Pydantic v2","Formato de código con ruff","Soporte para FastAPI y async/await","Organización de proyectos y pruebas"],"fr":["Modèles modernes Python 3.12+","Sécurité des types stricte avec Pydantic v2","Formatage de code avec ruff","Prise en charge de FastAPI et async/await","Organisation des projets et des tests"],"de":["Moderne Python-3.12+-Muster","Strenge Typsicherheit mit Pydantic v2","Code-Formatierung mit ruff","Unterstützung für FastAPI und async/await","Projektorganisation und Tests"],"pt":["Suporte a Python 3.12+","Uso de FastAPI e async/await","Formatação de código com ruff","Tipagem estrita com Pydantic v2","Organização de projetos com padrões modernos"],"ru":["Поддержка Python 3.12+","Использование FastAPI и async/await","Форматирование кода с ruff","Строгая типизация с Pydantic v2","Организация проектов с современными стандартами"],"ar":["دعم بايثون 3.12+","استخدام FastAPI و async/await","تنسيق الكود مع ruff","التحقق من النوع الصارم مع Pydantic v2","تنظيم المشاريع مع المعايير الحديثة"]},"keywords":{"en":["python-dev-guidelines setup guide","python 3.12+ development best practices","how to use python-dev-guidelines","python-dev-guidelines vs pylint","python-dev-guidelines install","what is python-dev-guidelines","python development guidelines","python-dev-guidelines alternative","python 3.12+ type safety"],"zh":["Python开发指南","Python开发最佳实践","现代Python 3.12+模式","类型安全","测试","项目组织","FastAPI","async/await","ruff","Pydantic v2"],"ja":["Python開発ガイドライン","Python開発ベストプラクティス","モダンなPython 3.12+パターン","型安全性","テスト","プロジェクト組織","FastAPI","async/await","ruff","Pydantic v2"],"ko":["Python 개발 가이드라인","Python 개발 모범 사례","현대적인 Python 3.12+ 패턴","형식 안전성","테스트","프로젝트 조직","FastAPI","async/await","ruff","Pydantic v2"],"es":["desarrollo python","python 3.12","claude code","seguridad de tipos","pruebas python","organización de proyectos","fastapi","async/await","ruff","pydantic v2"],"fr":["développement python","python 3.12","code claude","sécurité des types","tests python","organisation des projets","fastapi","async/await","ruff","pydantic v2"],"de":["python-entwicklung","python 3.12","claude-code","typsicherheit","python-tests","projektorganisation","fastapi","async/await","ruff","pydantic v2"],"pt":["desenvolvimento python","projetos de ia","python 3.12+","fastapi","async/await","ruff","pydantic v2","organização de projetos"],"ru":["разработка python","проекты ии","python 3.12+","fastapi","async/await","ruff","pydantic v2","организация проектов"],"ar":["تطوير بايثون","مشاريع الإي أι","بايثون 3.12+","fastapi","async/await","ruff","pydantic v2","تنظيم المشاريع"]}},"owner":"NmBoyd","repo":"claude_setup","repoPath":"NmBoyd/claude_setup","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.317Z","topics":[],"category":"community","skillMd":{"name":"python-dev-guidelines","description":"Python development guidelines for modern Python projects. Use when creating Python modules, classes, functions, scripts, or working with type hints, pytest, packaging (pip/poetry), virtual environments, async/await, data classes, or Python best practices. Covers project structure, typing, testing patterns, error handling, logging, and Pythonic idioms.","bodyPreview":"# Python Development Guidelines\n\n## Purpose\n\nEstablish consistency and best practices for Python development, covering modern Python 3.12+ patterns, type safety, testing, and project organization.\n\n---\n\n## Standards Overview\n\n| Category | Standard |\n|----------|----------|\n| **Python** | 3.12+, FastAPI, async/await preferred |\n| **Formatting** | ruff (96-char lines, double quotes, sorted imports) |\n| **Typing** | Strict (Pydantic v2 models preferred); `from __future__ import annotations` |\n| **N","body":"# Python Development Guidelines\n\n## Purpose\n\nEstablish consistency and best practices for Python development, covering modern Python 3.12+ patterns, type safety, testing, and project organization.\n\n---\n\n## Standards Overview\n\n| Category | Standard |\n|----------|----------|\n| **Python** | 3.12+, FastAPI, async/await preferred |\n| **Formatting** | ruff (96-char lines, double quotes, sorted imports) |\n| **Typing** | Strict (Pydantic v2 models preferred); `from __future__ import annotations` |\n| **Naming** | `snake_case` (functions/variables), `PascalCase` (classes), `SCREAMING_SNAKE` (constants) |\n| **Error Handling** | Typed exceptions; context managers for resources |\n| **Documentation** | Google-style docstrings for public functions/classes |\n| **Testing** | Separate test files matching source file patterns |\n\n## When to Use This Skill\n\nAutomatically activates when working on:\n- Creating or modifying Python files (`.py`)\n- Writing classes, functions, or modules\n- Setting up Python projects (pyproject.toml, setup.py)\n- Writing tests with pytest\n- Working with type hints and mypy\n- Async/await patterns with FastAPI\n- Package management (pip, poetry, conda)\n\n---\n\n## Quick Start\n\n### New Python Project Checklist\n\n- [ ] **Python version**: 3.12+ specified in `.python-version`\n- [ ] **Project structure**: src layout or flat layout\n- [ ] **pyproject.toml**: Modern packaging config with ruff\n- [ ] **Type hints**: Strict typing with `from __future__ import annotations`\n- [ ] **Tests**: pytest with fixtures, matching source patterns\n- [ ] **Linting**: ruff (96-char lines, double quotes, sorted imports)\n- [ ] **Virtual env**: venv, poetry, or conda\n- [ ] **Documentation**: Google-style docstrings\n- [ ] **Exceptions**: Hierarchical exceptions in `exceptions.py`\n\n### New Module Checklist\n\n- [ ] `from __future__ import annotations` at top\n- [ ] Module docstring (Google-style)\n- [ ] Type hints on all public functions\n- [ ] `__all__` export list (if applicable)\n- [ ] Unit tests in `tests/` mirror structure\n- [ ] Error handling with typed exceptions from `exceptions.py`\n\n---\n\n## Project Structure\n\n### Recommended Layout (src-layout)\n\n```\nproject/\n├── src/\n│   └── mypackage/\n│       ├── __init__.py\n│       ├── exceptions.py     # Hierarchical typed exceptions\n│       ├── core/\n│       │   ├── __init__.py\n│       │   └── module.py\n│       ├── utils/\n│       │   ├── __init__.py\n│       │   └── helpers.py\n│       └── py.typed          # PEP 561 marker\n├── tests/\n│   ├── conftest.py           # Shared fixtures\n│   ├── test_core/\n│   │   └── test_module.py    # Mirrors src/mypackage/core/module.py\n│   └── test_utils/\n│       └── test_helpers.py   # Mirrors src/mypackage/utils/helpers.py\n├── pyproject.toml\n├── ruff.toml                 # ruff config (96-char, double quotes)\n├── README.md\n└── .python-version           # 3.12+\n```\n\n### Alternative: Flat Layout (smaller projects)\n\n```\nproject/\n├── mypackage/\n│   ├── __init__.py\n│   └── module.py\n├── tests/\n│   └── test_module.py\n├── pyproject.toml\n└── README.md\n```\n\n---\n\n## Core Principles (7 Key Rules)\n\n### 1. Type Everything Public (Strict Typing)\n\n```python\nfrom __future__ import annotations  # Always at top of file\n\n# ❌ NEVER: Untyped public functions\ndef process_data(data):\n    return data.upper()\n\n# ✅ ALWAYS: Full type annotations\ndef process_data(data: str) -> str:\n    \"\"\"Process input data.\n\n    Args:\n        data: The input string to process.\n\n    Returns:\n        The processed uppercase string.\n    \"\"\"\n    return data.upper()\n```\n\n### 2. Use Pydantic v2 for Data Models (Preferred)\n\n```python\nfrom __future__ import annotations\nfrom pydantic import BaseModel, EmailStr, Field\n\n# ✅ Pydantic v2 for validation (preferred)\nclass UserCreate(BaseModel):\n    \"\"\"User creation model with validation.\"\"\"\n\n    name: str = Field(..., min_length=1, max_length=100)\n    email: EmailStr\n\nclass UserResponse(BaseModel):\n    \"\"\"User response model.\"\"\"\n\n    id: int\n    name: str\n    email: str\n\n# For simple internal data without validation, dataclasses are acceptable\nfrom dataclasses import dataclass\n\n@dataclass\nclass InternalConfig:\n    timeout: int = 30\n    retries: int = 3\n```\n\n### 3. Handle Errors with Typed Hierarchical Exceptions\n\n```python\n# exceptions.py - Define hierarchical typed exceptions\nfrom __future__ import annotations\n\n\nclass AppError(Exception):\n    \"\"\"Base exception for application errors.\"\"\"\n\n    def __init__(self, message: str) -> None:\n        self.message = message\n        super().__init__(message)\n\n\nclass ValidationError(AppError):\n    \"\"\"Raised when validation fails.\"\"\"\n\n    pass\n\n\nclass NotFoundError(AppError):\n    \"\"\"Raised when resource not found.\"\"\"\n\n    pass\n\n\nclass DatabaseError(AppError):\n    \"\"\"Raised when database operation fails.\"\"\"\n\n    pass\n\n\n# Usage - catch specific exceptions, not general Exception\nfrom mypackage.exceptions import ValidationError, NotFoundError\n\nasync def get_user(user_id: int) -> User:\n    \"\"\"Get user by ID.\n\n    Args:\n        user_id: The user''s unique identifier.\n\n    Returns:\n        The user object.\n\n    Raises:\n        NotFoundError: If user does not exist.\n    \"\"\"\n    user = await db.find(user_id)\n    if not user:\n        raise NotFoundError(f\"User {user_id} not found\")\n    return user\n```\n\n### 4. Use Context Managers for Resources\n\n```python\nfrom __future__ import annotations\nfrom contextlib import asynccontextmanager, contextmanager\n\n# ❌ NEVER: Manual resource management\nf = open(\"file.txt\")\ndata = f.read()\nf.close()\n\n# ✅ ALWAYS: Context managers\nwith open(\"file.txt\") as f:\n    data = f.read()\n\n# ✅ Sync context manager\n@contextmanager\ndef database_transaction():\n    \"\"\"Manage database transaction with automatic cleanup.\"\"\"\n    conn = get_connection()\n    try:\n        yield conn\n        conn.commit()\n    except Exception:\n        conn.rollback()\n        raise\n    finally:\n        conn.close()\n\n# ✅ Async - use try/finally to ensure cleanup\n@asynccontextmanager\nasync def async_db_session():\n    \"\"\"Manage async database session with cleanup.\"\"\"\n    session = await create_session()\n    try:\n        yield session\n        await session.commit()\n    except Exception:\n        await session.rollback()\n        raise\n    finally:\n        await session.close()\n```\n\n### 5. Prefer Composition Over Inheritance\n\n```python\n# ❌ Avoid deep inheritance\nclass Animal: ...\nclass Mammal(Animal): ...\nclass Dog(Mammal): ...\n\n# ✅ Prefer composition and protocols\nfrom typing import Protocol\n\nclass Walker(Protocol):\n    def walk(self) -> None: ...\n\nclass Dog:\n    def __init__(self, legs: int = 4):\n        self.legs = legs\n\n    def walk(self) -> None:\n        print(f\"Walking on {self.legs} legs\")\n```\n\n### 6. Use Logging, Not Print\n\n```python\nimport logging\n\nlogger = logging.getLogger(__name__)\n\n# ❌ NEVER\nprint(f\"Processing {item}\")\n\n# ✅ ALWAYS\nlogger.info(\"Processing %s\", item)\nlogger.error(\"Failed to process\", exc_info=True)\n```\n\n### 7. Write Testable Code\n\n```python\n# ❌ Hard to test: hidden dependencies\ndef send_email(user_id: int) -> None:\n    user = database.get_user(user_id)  # Hidden dependency\n    smtp.send(user.email, \"Hello\")      # Hidden dependency\n\n# ✅ Easy to test: explicit dependencies\ndef send_email(\n    user: User,\n    email_sender: EmailSender\n) -> None:\n    email_sender.send(user.email, \"Hello\")\n```\n\n---\n\n## Type Hints Quick Reference\n\n```python\nfrom __future__ import annotations\nfrom typing import TypeVar, Generic\nfrom collections.abc import Callable\n\n# Basic types (Python 3.12+)\nvalues: list[int] = [1, 2, 3]\nmapping: dict[str, int] = {\"a\": 1}\nvalue: str | None = None  # Union syntax\n\n# Callable and Generics\nhandler: Callable[[int, str], bool]\nT = TypeVar(\"T\")\n\nclass Container(Generic[T]):\n    def __init__(self, value: T) -> None:\n        self.value = value\n```\n\n---\n\n## Testing Patterns\n\n```python\n# tests/test_user_service.py - mirrors src/mypackage/services/user_service.py\nfrom __future__ import annotations\nimport pytest\nfrom mypackage.services import UserService\nfrom mypackage.exceptions import ValidationError\n\nclass TestUserService:\n    \"\"\"Tests for UserService.\"\"\"\n\n    def test_create_user_success(self, mock_database):\n        \"\"\"Should create user with valid data.\"\"\"\n        service = UserService(mock_database)\n        user = service.create(name=\"Test\", email=\"test@example.com\")\n        assert user.name == \"Test\"\n\n    def test_create_user_invalid_email_raises(self, mock_database):\n        \"\"\"Should raise ValidationError for invalid email.\"\"\"\n        service = UserService(mock_database)\n        with pytest.raises(ValidationError, match=\"invalid email\"):\n            service.create(name=\"Test\", email=\"not-an-email\")\n```\n\n---\n\n## Anti-Patterns to Avoid\n\n❌ Mutable default arguments (`def foo(items=[])`)\n❌ Bare `except:` clauses - catch specific exceptions\n❌ Catching general `Exception` - use typed exceptions\n❌ `from module import *`\n❌ Global mutable state\n❌ Ignoring type checker errors\n❌ print() instead of logging\n❌ String concatenation in loops (use join)\n❌ Not using `if __name__ == \"__main__\":`\n❌ Missing `from __future__ import annotations`\n\n---\n\n## Async Patterns (FastAPI Preferred)\n\n```python\nfrom __future__ import annotations\nfrom fastapi import FastAPI, HTTPException, status\nfrom mypackage.exceptions import ValidationError\n\napp = FastAPI()\n\n# ✅ FastAPI endpoint with proper error handling\n@app.post(\"/users\", response_model=UserResponse, status_code=status.HTTP_201_CREATED)\nasync def create_user(user: UserCreate) -> UserResponse:\n    \"\"\"Create a new user.\"\"\"\n    try:\n        return await user_service.create(user)\n    except ValidationError as e:\n        raise HTTPException(status_code=400, detail=str(e)) from e\n\n# ✅ Async error handling with exception chaining (from e)\nasync def process_data(data: dict) -> Result:\n    \"\"\"Process data with proper exception handling.\"\"\"\n    try:\n        return await do_processing(data)\n    except KeyError as e:\n        raise ValidationError(f\"Missing required field: {e}\") from e\n\n# ✅ Concurrent operations\nasync def process_items(items: list[str]) -> list[dict]:\n    return await asyncio.gather(*[fetch_data(item) for item in items])\n```\n\n---\n\n## Resource Files\n\n### [style-guide.md](resources/style-guide.md)\nGoogle Python Style Guide + PEP 8 practices, naming, docstrings, imports\n\n<!-- ### [project-setup.md](resources/project-setup.md)\npyproject.toml, poetry, pip, virtual environments\n\n### [typing-guide.md](resources/typing-guide.md)\nAdvanced type hints, generics, protocols, mypy configuration\n\n### [testing-patterns.md](resources/testing-patterns.md)\npytest fixtures, mocking, parameterization, coverage\n\n### [async-patterns.md](resources/async-patterns.md)\nasyncio, aiohttp, async context managers\n\n### [packaging.md](resources/packaging.md)\nBuilding packages, publishing to PyPI, versioning -->\n\n---\n\n## Related Skills\n\n- **cpp-dev-guidelines** - C++ development patterns\n- **error-tracking** - Sentry integration for Python\n- **skill-developer** - Creating and managing skills\n\n---\n\n**Skill Status**: COMPLETE ✅\n**Line Count**: < 450 ✅\n**Progressive Disclosure**: Resource files for details ✅\n"},"lastSynced":"2026-03-08T02:02:53.297Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Analysis and Generation Agents specializing in modern Python 3.12+ development.","zh":"非常适合专注于现代 Python 3.12+ 开发的代码分析与生成智能体。","ja":"現代的な Python 3.12+ 開発に特化したコード分析および生成エージェントに最適です。","ko":"현대적인 Python 3.12+ 개발에 특화된 코드 분석 및 생성 에이전트에 이상적입니다.","es":"Ideal para Agentes de Análisis y Generación de Código que se especializan en el desarrollo de Python 3.12+ moderno.","fr":"Idéal pour les agents d''analyse et de génération de code spécialisés dans le développement Python 3.12+ moderne.","de":"Ideal für Code-Analyse- und Generierungsagenten, die sich auf die moderne Entwicklung von Python 3.12+ spezialisieren.","pt":"Ideal para Agentes de Análise e Geração de Código especializados em desenvolvimento moderno com Python 3.12+.","ru":"Идеально подходит для агентов анализа и генерации кода, специализирующихся на современной разработке с использованием Python 3.12+.","ar":"مثالي لوكلاء تحليل وتوليد التعليمات البرمجية المتخصصين في تطوير Python 3.12+ الحديث."},"recommendation":{"en":"Enforces strict type safety with Pydantic v2 models and modern async/await patterns, while ensuring consistent code formatting through ruff with 96-char line limits and sorted imports.","zh":"通过 Pydantic v2 模型和现代 async/await 模式强制执行严格的类型安全，同时通过 ruff 确保一致的代码格式，包括 96 字符行限制和排序的导入。","ja":"Pydantic v2 モデルと現代的な async/await パターンによる厳格な型安全性を強制し、ruff による 96 文字の行制限とインポートのソートを通じて一貫したコードフォーマットを保証します。","ko":"Pydantic v2 모델과 현대적인 async/await 패턴을 통해 엄격한 타입 안전성을 강제하며, ruff를 통한 96자 줄 제한과 정렬된 임포트로 일관된 코드 형식을 보장합니다.","es":"Aplica una estricta seguridad de tipos con modelos Pydantic v2 y patrones modernos de async/await, al mismo tiempo que garantiza un formato de código coherente a través de ruff con límites de línea de 96 caracteres y importaciones ordenadas.","fr":"Impose une sécurité stricte des types avec des modèles Pydantic v2 et des patrons modernes async/await, tout en assurant un formatage de code cohérent via ruff avec des limites de ligne de 96 caractères et des importations triées.","de":"Erzwingt eine strikte Typsicherheit mit Pydantic-v2-Modellen und modernen async/await-Mustern, während gleichzeitig ein konsistentes Code-Formatting durch ruff mit 96-zeichen-Längenbegrenzungen und sortierten Importen sichergestellt wird.","pt":"Impõe segurança de tipos rigorosa com modelos Pydantic v2 e padrões modernos async/await, garantindo ao mesmo tempo formatação de código consistente através do ruff com limites de linha de 96 caracteres e imports ordenados.","ru":"Обеспечивает строгую типобезопасность с моделями Pydantic v2 и современными шаблонами async/await, одновременно гарантируя единообразное форматирование кода с помощью ruff с ограничением длины строк в 96 символов и отсортированными импортами.","ar":"يفرض سلامة صارمة للنوع باستخدام نماذج Pydantic v2 وأنماط async/await الحديثة، مع ضمان تنسيق تعليمات برمجية متسق من خلال ruff بحدود أسطر 96 حرفًا واستيرادات مرتبة."},"useCases":{"en":["Generating type-annotated FastAPI endpoints","Refactoring legacy code to modern Python 3.12+ standards","Automating project setup with consistent structure and testing frameworks"],"zh":["生成带有类型注解的 FastAPI 端点","将遗留代码重构为现代 Python 3.12+ 标准","使用一致的结构和测试框架自动化项目设置"],"ja":["型注釈付きの FastAPI エンドポイントの生成","レガシーコードの現代的な Python 3.12+ 標準へのリファクタリング","一貫した構造とテストフレームワークを用いたプロジェクト設定の自動化"],"ko":["타입 어노테이션이 있는 FastAPI 엔드포인트 생성","레거시 코드를 현대적인 Python 3.12+ 표준으로 리팩토링","일관된 구조와 테스트 프레임워크를 사용한 프로젝트 설정 자동화"],"es":["Generación de puntos de conexión de FastAPI con anotaciones de tipo","Reestructuración de código heredado a los estándares de Python 3.12+ moderno","Automatización de la configuración del proyecto con una estructura coherente y marcos de prueba"],"fr":["Génération de points de terminaison FastAPI avec des annotations de type","Réorganisation de code hérité aux normes Python 3.12+ modernes","Automatisation de la configuration du projet avec une structure cohérente et des frameworks de test"],"de":["Generierung von FastAPI-Endpunkten mit Typannotierungen","Umstrukturierung von Legacy-Code zu modernen Python-3.12+-Standards","Automatisierung der Projektkonfiguration mit einer konsistenten Struktur und Testframeworks"],"pt":["Geração de endpoints FastAPI com anotações de tipo","Refatoração de código legado para os padrões modernos do Python 3.12+","Automação da configuração de projeto com estrutura consistente e frameworks de teste"],"ru":["Генерация типизированных конечных точек FastAPI","Рефакторинг устаревшего кода в соответствии с современными стандартами Python 3.12+","Автоматизация настройки проекта с единообразной структурой и фреймворками для тестирования"],"ar":["توليد نقاط نهاية FastAPI مع شرح الأنواع","إعادة هيكلة التعليمات البرمجية القديمة لتحويلها إلى معايير Python 3.12+ الحديثة","أتمتة إعداد المشروع بهيكل متسق وأطر عمل الاختبار"]},"limitations":{"en":["Python 3.12+ only","Requires ruff formatting tool","FastAPI framework focused"],"zh":["仅限 Python 3.12+","需要 ruff 格式化工具","专注于 FastAPI 框架"],"ja":["Python 3.12+ のみ","ruff フォーマットツールが必要","FastAPI フレームワークに特化"],"ko":["Python 3.12+ 전용","ruff 포맷팅 도구 필요","FastAPI 프레임워크에 초점"],"es":["Solo Python 3.12+","Requiere la herramienta de formato ruff","Enfocado en el marco de FastAPI"],"fr":["Uniquement Python 3.12+","Nécessite l''outil de formatage ruff","Axé sur le framework FastAPI"],"de":["Nur Python 3.12+","Benötigt das Formatierungstool ruff","Fokussiert auf das FastAPI-Framework"],"pt":["Apenas Python 3.12+","Requer a ferramenta de formatação ruff","Focado no framework FastAPI"],"ru":["Только Python 3.12+","Требует инструмент форматирования ruff","Ориентирован на фреймворк FastAPI"],"ar":["Python 3.12+ فقط","يتطلب أداة التنسيق ruff","يركز على إطار عمل FastAPI"]},"version":4},"contentHash":"bd65334a9638a93f345cbd11076daea9b4c9c607ca6e17d9f96381c61fb8e5ad","qualityScore":57}');
