INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NmBoyd/claude_setup/python-dev-guidelines', 'python-dev-guidelines', 'NmBoyd', 'claude_setup', 'community', 'python-dev-guidelines NmBoyd claude_setup community The python-dev-guidelines skill provides a setup for Python development, covering modern Python 3.12+ patterns, type safety, testing, and project organization, benefiting developers who want to establish consistency and best practices in their Python projects. 本指南介绍了Python开发的最佳实践，涵盖现代Python 3.12+模式、类型安全、测试和项目组织 このガイドラインでは、Python開発のベストプラクティスを紹介します。 moderne Python 3.12+パターン、型安全性、テスト、プロジェクト組織 이 가이드는 Python 개발의 모범 사례를介绍합니다. 현대적인 Python 3.12+ 패턴, 형식 안전성, 테스트 및 프로젝트 조직 Configuración para desarrollo Python con Claude, siguiendo las pautas de Python 3.12+ y mejores prácticas Configuration pour le développement Python avec Claude, suivant les directives de Python 3.12+ et les meilleures pratiques Konfiguration für Python-Entwicklung mit Claude, unter Einhaltung der Richtlinien von Python 3.12+ und Best Practices O python-dev-guidelines é um conjunto de diretrizes para desenvolvedores Python que visa estabelecer consistência e boas práticas para projetos de IA Python-dev-guidelines - это набор руководств для разработчиков Python, целью которого является установление последовательности и лучших практик для проектов ИИ python-dev-guidelines هو مجموعة من الإرشادات لمطوري بايثون التي تهدف إلى تحقيق الاتساق وأفضل الممارسات لمشاريع الإي أι python-dev-guidelines setup guide python 3.12+ development best practices how to use python-dev-guidelines python-dev-guidelines vs pylint python-dev-guidelines install what is python-dev-guidelines python development guidelines python-dev-guidelines alternative python 3.12+ type safety Python开发指南 Python开发最佳实践 现代Python 3.12+模式 类型安全 测试 项目组织 FastAPI async/await ruff Pydantic v2 Enforces strict typing with Pydantic v2 models Uses ruff for formatting with 96-char lines and double quotes Supports async/await syntax with FastAPI Requires Python 3.12+ for modern development patterns Includes project organization and testing guidelines Utilizes `from __future__ import annotations` for type safety python-dev-guidelines is a set of standards and best practices for Python development, focusing on modern Python 3.12+ patterns, type safety, and project organization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lawless-m/Earwig/Reverse Proxy Deployment', 'community', 'lawless-m', 'Earwig', 'lawless-m/Earwig', 'Reverse Proxy Deployment', 0, 0, 57, '2026-03-08T01:57:15.318Z', '2026-03-08T02:02:54.228Z', '4953cd51d5e885379697cc5c9ce3bd717b616462555b73bcc6ba8e1685c3ae95', '{"id":"lawless-m/Earwig/Reverse Proxy Deployment","name":"Reverse Proxy Deployment","description":{"en":"Reverse Proxy Deployment helps developers deploy web applications behind the Apache reverse proxy, ensuring correct frontend relative URL patterns and Apache ProxyPass configuration.","zh":"本指南介绍了如何在rivsprod01（dw.ramsden-international.com）上使用Apache反向代理部署Web应用程序，包括前端相对URL模式和Apache ProxyPass配置","ja":"rivsprod01（dw.ramsden-international.com）でのWebアプリケーションのApacheリバースプロキシを使用したデプロイ方法について、フロントエンドの相対URLパターンとApache ProxyPassの設定を説明","ko":"rivsprod01（dw.ramsden-international.com）에서 Apache 리버스 프록시를 사용하여 웹 애플리케이션을 배포하는 방법에 대해 설명합니다. 프론트엔드 상대 URL 패턴 및 Apache ProxyPass 설정을 포함합니다","es":"Esta guía cubre el despliegue de aplicaciones web detrás de un proxy inverso Apache en rivsprod01, incluyendo patrones de URL relativos y configuración de ProxyPass","fr":"Ce guide couvre le déploiement d''applications web derrière un proxy inverse Apache sur rivsprod01, y compris les modèles d''URL relatifs et la configuration de ProxyPass","de":"Dieser Leitfaden behandelt das Deployen von Webanwendungen hinter einem Reverse-Proxy von Apache auf rivsprod01, einschließlich relativer URL-Muster und ProxyPass-Konfiguration","pt":"O proxy reverso é uma técnica de deploy de aplicações web que permite o acesso através de um servidor proxy. Esta guia aborda a configuração do Apache para deploy de aplicações web com URLs relativos e configuração de ProxyPass.","ru":"Обратный прокси - это техника развертывания веб-приложений, позволяющая получить доступ через сервер-прокси. Это руководство охватывает настройку Apache для развертывания веб-приложений с относительными URL и конфигурацией ProxyPass для ИИ Агентов.","ar":"وكيل الوسائط العكسي هو تقنية لتنفيذ تطبيقات الويب التي تسمح بالوصول من خلال خادم وكيل. هذا الدليل يغطي إعداد Apache لتنفيذ تطبيقات الويب باستخدام عناوين URL النسبية وتكوين ProxyPass"},"seo":{"title":{"en":"Reverse Proxy Deployment: Setup Guide for AI Agents","zh":"反向代理部署设置指南","ja":"リバースプロキシ設定ガイド","ko":"리버스 프록시 배포 설정 가이드","es":"Despliegue de Proxy Inverso: Guía de Configuración","fr":"Déploiement de Proxy Inverse: Meilleures Pratiques","de":"Reverse-Proxy-Deployement: Einrichtungsanleitung","pt":"Guia de Configuração de Proxy Reverso para Desenvolvedores","ru":"Руководство по настройке обратного прокси для разработчик...","ar":"دليل إعداد وكيل الوسائط العكسي للطورين"},"description":{"en":"Learn how to deploy web applications behind Apache reverse proxy on rivsprod01, discover best practices and configuration tips, get started now!","zh":"了解如何使用Apache反向代理在rivsprod01（dw.ramsden-international.com）上部署Web应用程序","ja":"rivsprod01（dw.ramsden-international.com）でのWebアプリケーションのApacheリバースプロキシを使用したデプロイ方法について","ko":"rivsprod01（dw.ramsden-international.com）에서 Apache 리버스 프록시를 사용하여 웹 애플리케이션을 배포하는 방법에 대해 알아보세요","es":"Aprende a configurar Apache para desplegar aplicaciones web detrás de un proxy inverso con esta guía paso a paso para desarrolladores","fr":"Découvrez comment configurer Apache pour déployer des applications web derrière un proxy inverse avec ce guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie Apache konfigurieren, um Webanwendungen hinter einem Reverse-Proxy zu deployen, mit diesem Schritt-für-Schritt-Leitfaden für Entwickler","pt":"Aprenda a configurar o proxy reverso Apache para deploy de aplicações web com URLs relativos e configuração de ProxyPass","ru":"Узнайте, как настроить обратный прокси Apache для развертывания веб-приложений с относительными URL и конфигурацией ProxyPass для ИИ Агентов","ar":"تعرف على كيفية إعداد وكيل الوسائط العكسي Apache لتنفيذ تطبيقات الويب باستخدام عناوين URL النسبية وتكوين ProxyPass"},"definition":{"en":"Reverse Proxy Deployment is a technique for deploying web applications behind an Apache reverse proxy server, using relative URLs and ProxyPass configuration.","zh":"反向代理部署是指使用Apache反向代理服务器将Web应用程序部署到rivsprod01（dw.ramsden-international.com）","ja":"リバースプロキシ設定とは、Apacheリバースプロキシサーバーを使用してWebアプリケーションをrivsprod01（dw.ramsden-international.com）にデプロイすること","ko":"리버스 프록시 배포는 Apache 리버스 프록시 서버를 사용하여 웹 애플리케이션을 rivsprod01（dw.ramsden-international.com）에 배포하는 것을 의미합니다","es":"Un proxy inverso es un servidor que actúa como intermediario entre una aplicación web y los clientes, permitiendo el acceso a la aplicación a través de una URL pública","fr":"Un proxy inverse est un serveur qui agit comme intermédiaire entre une application web et les clients, permettant l''accès à l''application via une URL publique","de":"Ein Reverse-Proxy ist ein Server, der als Vermittler zwischen einer Webanwendung und den Clients agiert, sodass der Zugriff auf die Anwendung über eine öffentliche URL möglich ist","pt":"Proxy reverso é uma técnica de deploy de aplicações web que permite o acesso através de um servidor proxy","ru":"Обратный прокси - это техника развертывания веб-приложений, позволяющая получить доступ через сервер-прокси","ar":"وكيل الوسائط العكسي هو تقنية لتنفيذ تطبيقات الويب التي تسمح بالوصول من خلال خادم وكيل"},"features":{"en":["Uses relative URLs for frontend code","Configures Apache ProxyPass on rivsprod01","Supports deployment of web applications behind the Apache reverse proxy","Ensures correct frontend relative URL patterns","Provides Apache config creation for ProxyPass","Deploys web applications on dw.ramsden-international.com"],"zh":["使用相对URL进行前端开发","Apache ProxyPass配置","支持rivsprod01（dw.ramsden-international.com）部署","提高Web应用程序的安全性和性能","简化Web应用程序的部署和管理"],"ja":["フロントエンドの相対URLを使用","Apache ProxyPassの設定","rivsprod01（dw.ramsden-international.com）へのデプロイのサポート","Webアプリケーションのセキュリティとパフォーマンスの向上","Webアプリケーションのデプロイと管理の簡素化"],"ko":["프론트엔드 상대 URL 사용","Apache ProxyPass 설정","rivsprod01（dw.ramsden-international.com）에 대한 배포 지원","웹 애플리케이션의 보안 및 성능 향상","웹 애플리케이션의 배포 및 관리를 단순화"],"es":["Uso de URLs relativos en el código del frontend","Configuración de ProxyPass en Apache","Despliegue de aplicaciones web en rivsprod01","Compatibilidad con patrones de URL relativos","Configuración de Apache para proxy inverso"],"fr":["Utilisation d''URL relatifs dans le code frontend","Configuration de ProxyPass dans Apache","Déploiement d''applications web sur rivsprod01","Compatibilité avec les modèles d''URL relatifs","Configuration d''Apache pour proxy inverse"],"de":["Verwendung relativer URLs im Frontend-Code","Konfiguration von ProxyPass in Apache","Deployen von Webanwendungen auf rivsprod01","Kompatibilität mit relativen URL-Mustern","Konfiguration von Apache für Reverse-Proxy"],"pt":["Configuração de URLs relativos","Configuração de ProxyPass no Apache","Deploy de aplicações web com servidor proxy","Compatibilidade com rivsprod01 (dw.ramsden-international.com)","Uso de frontend com URLs relativos"],"ru":["Настройка относительных URL","Настройка ProxyPass в Apache","Развертывание веб-приложений с сервером-прокси","Совместимость с rivsprod01 (dw.ramsden-international.com)","Использование frontend с относительными URL для ИИ Агентов"],"ar":["تكوين عناوين URL النسبية","تكوين ProxyPass في Apache","تنفيذ تطبيقات الويب مع خادم وكيل","التوافق مع rivsprod01 (dw.ramsden-international.com)","استخدام الواجهة الأمامية مع عناوين URL النسبية"]},"keywords":{"en":["how to use Reverse Proxy Deployment","Reverse Proxy Deployment setup guide","Apache reverse proxy configuration","Reverse Proxy Deployment alternative","what is Reverse Proxy Deployment","Reverse Proxy Deployment install","ProxyPass configuration tutorial","Reverse Proxy Deployment best practices","dw.ramsden-international.com deployment"],"zh":["反向代理部署","Apache反向代理","Web应用程序部署","rivsprod01","dw.ramsden-international.com","相对URL","ProxyPass配置"],"ja":["リバースプロキシ設定","Apacheリバースプロキシ","Webアプリケーションデプロイ","rivsprod01","dw.ramsden-international.com","相対URL","ProxyPassの設定"],"ko":["리버스 프록시 배포","Apache 리버스 프록시","웹 애플리케이션 배포","rivsprod01","dw.ramsden-international.com","상대 URL","ProxyPass 설정"],"es":["despliegue de proxy inverso","configuración de Apache","patrones de URL relativos","ProxyPass","rivsprod01","desarrollo web","deploy de aplicaciones web","proxy inverso Apache"],"fr":["déploiement de proxy inverse","configuration d''Apache","modèles d''URL relatifs","ProxyPass","rivsprod01","développement web","déploiement d''applications web","proxy inverse Apache"],"de":["Reverse-Proxy-Deployement","Apache-Konfiguration","relative URL-Muster","ProxyPass","rivsprod01","Webentwicklung","Deployen von Webanwendungen","Reverse-Proxy Apache"],"pt":["proxy reverso","configuração de proxy","deploy de aplicações web","apache","rivsprod01","dw.ramsden-international.com","URLs relativos","ProxyPass"],"ru":["обратный прокси","настройка прокси","развертывание веб-приложений","apache","rivsprod01","dw.ramsden-international.com","относительные URL","ProxyPass","ИИ Агенты"],"ar":["وكيل الوسائط العكسي","تكوين الوكيل","تنفيذ تطبيقات الويب","apache","rivsprod01","dw.ramsden-international.com","عناوين URL النسبية","ProxyPass","أدوات الذكاء الاصطناعي"]}},"owner":"lawless-m","repo":"Earwig","repoPath":"lawless-m/Earwig","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.318Z","topics":[],"category":"community","skillMd":{"name":"Reverse Proxy Deployment","description":"Deploy web applications behind Apache reverse proxy on rivsprod01 with relative URLs and proper path configuration","bodyPreview":"# Reverse Proxy Deployment\n\nGuide for deploying web applications behind the Apache reverse proxy on rivsprod01 (dw.ramsden-international.com). Covers frontend relative URL patterns and Apache ProxyPass configuration.\n\n## Instructions\n\nWhen deploying a web application that will be accessed through the reverse proxy:\n\n1. **Use Relative URLs**: Frontend code must use relative URLs (not absolute localhost URLs) to work behind the proxy\n2. **Configure ProxyPass on rivsprod01**: Create Apache config i","body":"# Reverse Proxy Deployment\n\nGuide for deploying web applications behind the Apache reverse proxy on rivsprod01 (dw.ramsden-international.com). Covers frontend relative URL patterns and Apache ProxyPass configuration.\n\n## Instructions\n\nWhen deploying a web application that will be accessed through the reverse proxy:\n\n1. **Use Relative URLs**: Frontend code must use relative URLs (not absolute localhost URLs) to work behind the proxy\n2. **Configure ProxyPass on rivsprod01**: Create Apache config in `/etc/apache2/proxy-conf.d/` with proper path stripping\n3. **Order Matters**: More specific paths must come before general paths in Apache config\n4. **Test Locally First**: Verify services are accessible from rivsprod01 before configuring proxy\n5. **Use Trailing Slashes**: Both source and target URLs need trailing slashes for path stripping to work\n\n## Examples\n\n### Example 1: Deploy Web Application with API Backend\n\n```\nUser: I have a web app with frontend on port 9273 and API on port 8765. Deploy it behind the proxy at /myapp/\n\nClaude: I''ll set up your application for reverse proxy deployment:\n\n1. **Update Frontend URLs**: Change API calls to use relative URLs\n   - Before: `fetch(''http://localhost:8765/api/status'')`\n   - After: `fetch(''api/status'')`  // Relative to current path\n\n2. **Create Apache Config**: SSH to rivsprod01 and create `/etc/apache2/proxy-conf.d/myapp.conf`\n   - API path: `/myapp/api/` → backend on port 8765\n   - Frontend path: `/myapp/` → frontend on port 9273\n   - API location must come FIRST (more specific)\n\n3. **Reload Apache**: `sudo systemctl reload apache2`\n\n[Provides implementation using the ProxyPass Configuration pattern below]\n```\n\n### Example 2: Frontend Uses Absolute URLs\n\n```\nUser: My frontend has `fetch(''http://localhost:3000/api/data'')` hardcoded. How do I make it work behind a proxy?\n\nClaude: Absolute URLs won''t work behind a reverse proxy. You need to update the frontend to use relative URLs:\n\n**Options:**\n1. **Best: Use relative URLs** - `fetch(''api/data'')` - works anywhere\n2. **Alternative: Use base path** - Store base path in config, prepend to all API calls\n3. **Hidden input method** - Store proxy path in HTML, read in JavaScript\n\nFor option 1 (recommended):\n- Replace all `http://localhost:3000/api/` with `api/`\n- The browser resolves relative to current page path\n- If page is at `/myapp/`, API call goes to `/myapp/api/`\n\n[Shows the Relative URL Pattern implementation below]\n```\n\n### Example 3: Multiple Services on Same Machine\n\n```\nUser: I have 3 services running on ports 8001, 8002, 8003. Deploy all at /service1/, /service2/, /service3/\n\nClaude: I''ll configure all three services in a single Apache config file:\n\n1. **Create single config file**: `/etc/apache2/proxy-conf.d/services.conf`\n2. **Add ProxyPass for each**: More specific paths first (doesn''t matter here since no overlap)\n3. **Each service gets clean URLs**: Paths are stripped before forwarding\n4. **Reload once**: All services go live together\n\n[Provides implementation using the Multi-Service Configuration pattern below]\n```\n\n### Example 4: API Calls Return 404\n\n```\nUser: My frontend loads but API calls return 404. Frontend is at /rabbit/, API should be at /rabbit/api/\n\nClaude: The issue is likely ProxyPass configuration. Let me check:\n\n1. **Verify services are reachable**: From rivsprod01, can you curl the backend directly?\n   - `curl http://10.99.0.3:8765/status` should work\n\n2. **Check ProxyPass order**: API location must come BEFORE frontend location\n   - Wrong order: frontend `/rabbit/` catches `/rabbit/api/` requests\n   - Right order: API `/rabbit/api/` catches first, then frontend `/rabbit/`\n\n3. **Verify trailing slashes**: Both paths need trailing slashes for stripping\n   - `ProxyPass /rabbit/api/ http://10.99.0.3:8765/`\n   - Without trailing slash, path isn''t stripped properly\n\n[Shows debugging steps from Troubleshooting section below]\n```\n\n---\n\n# Reference Implementation Details\n\nThe sections below contain proven working configurations from production deployments.\n\n**Reference Files in This Folder**:\n- `rabbit.conf` - Example Apache config from Invoice OCR deployment\n\n## Relative URL Pattern\n\n**Purpose**: Make frontend work behind any reverse proxy path without hardcoding URLs\n\n### HTML Method (Recommended for Simple Cases)\n\n```html\n<!-- Hidden input stores the API base path -->\n<input type=\"hidden\" id=\"serverUrl\" value=\"api\">\n\n<script>\nfunction getServerUrl() {\n    return document.getElementById(''serverUrl'').value.trim();\n}\n\n// Use in fetch calls\nasync function checkStatus() {\n    const res = await fetch(`${getServerUrl()}/status`);\n    const data = await res.json();\n    // ...\n}\n</script>\n```\n\n**Key Points**:\n- Value is `\"api\"` (relative) not `\"http://localhost:8765\"` (absolute)\n- Browser resolves `api/status` relative to current page\n- If page is at `https://example.com/rabbit/`, request goes to `https://example.com/rabbit/api/status`\n- Proxy strips `/rabbit/` and forwards to backend\n\n### JavaScript Config Method (For Complex Applications)\n\n```javascript\n// config.js\nconst CONFIG = {\n    API_BASE: ''api'',  // Relative to current path\n    WS_BASE: ''ws''     // WebSocket endpoint if needed\n};\n\n// Use throughout app\nfetch(`${CONFIG.API_BASE}/endpoint`)\n```\n\n**When to use**:\n- Multiple API endpoints\n- Different base paths for dev/staging/prod\n- Need to change paths without editing HTML\n\n## ProxyPass Configuration Pattern\n\n**Purpose**: Configure Apache to forward requests from public path to internal service\n\n### Basic Single-Service Configuration\n\n**File**: `/etc/apache2/proxy-conf.d/myservice.conf`\n\n```apache\n# Single service on custom path\nProxyPass /myservice/ http://10.99.0.3:8080/\nProxyPassReverse /myservice/ http://10.99.0.3:8080/\n```\n\n**Key Points**:\n- Simple ProxyPass directives (no `<Location>` blocks needed)\n- Trailing slashes on both source and target strip the path prefix\n- Request to `/myservice/page` becomes `/page` at backend\n- `ProxyPassReverse` rewrites response headers (redirects, etc.)\n\n### API + Frontend Configuration\n\n**File**: `/etc/apache2/proxy-conf.d/service-with-api.conf`\n\n```apache\n# Backend API - Must come FIRST (more specific path)\nProxyPass /rabbit/api/ http://10.99.0.3:8765/\nProxyPassReverse /rabbit/api/ http://10.99.0.3:8765/\n\n# Frontend - Comes SECOND (less specific path)\nProxyPass /rabbit/ http://10.99.0.3:9273/\nProxyPassReverse /rabbit/ http://10.99.0.3:9273/\n```\n\n**Key Points**:\n- API location MUST be listed first (more specific)\n- If frontend is listed first, it catches API requests → 404\n- Both locations strip their prefix before forwarding\n- Request flow:\n  - `GET /rabbit/api/status` → matches first rule → `GET /status` to port 8765\n  - `GET /rabbit/index.html` → matches second rule → `GET /index.html` to port 9273\n\n### Large File Upload Configuration\n\n```apache\n# Service that handles file uploads (PDFs, images, etc.)\nProxyPass /uploads/ http://10.99.0.3:7000/\nProxyPassReverse /uploads/ http://10.99.0.3:7000/\n\n# Important for large PDF uploads\n<Location /uploads/>\n    ProxyPass http://10.99.0.3:7000/\n    ProxyPassReverse http://10.99.0.3:7000/\n\n    # Allow 50MB uploads\n    LimitRequestBody 52428800\n</Location>\n```\n\n**When to use**:\n- File upload services\n- PDF/image processing\n- Any endpoint that receives large request bodies\n\n## Multi-Service Configuration Pattern\n\n**Purpose**: Deploy multiple independent services in one config file\n\n**File**: `/etc/apache2/proxy-conf.d/all-services.conf`\n\n```apache\n# Service 1: API Gateway\nProxyPass /api/ http://10.99.0.3:8001/\nProxyPassReverse /api/ http://10.99.0.3:8001/\n\n# Service 2: Admin Dashboard\nProxyPass /admin/ http://10.99.0.3:8002/\nProxyPassReverse /admin/ http://10.99.0.3:8002/\n\n# Service 3: Public Website\nProxyPass /site/ http://10.99.0.3:8003/\nProxyPassReverse /site/ http://10.99.0.3:8003/\n```\n\n**Key Points**:\n- Each service is completely independent\n- Order doesn''t matter if paths don''t overlap\n- All go live together when Apache reloads\n- Can comment out individual services to disable temporarily\n\n## Deployment Workflow\n\n**Standard deployment process for new service:**\n\n### 1. Verify Local Service Accessibility\n\n```bash\n# From local machine where service runs\ncurl http://10.99.0.3:8765/status  # Test your port\n\n# From rivsprod01 (SSH in)\nssh rivsprod01 \"curl -s http://10.99.0.3:8765/status\"\n```\n\n**Expected**: JSON response or HTML, not connection refused\n\n### 2. Create Apache Configuration\n\n```bash\n# SSH to rivsprod01\nssh rivsprod01\n\n# Create config file (as root or with sudo)\nsudo nano /etc/apache2/proxy-conf.d/myservice.conf\n\n# Add ProxyPass configuration (see patterns above)\n\n# Verify syntax (optional, but recommended)\n# apache2ctl configtest   # May not be available\n# Just proceed to reload if command not found\n```\n\n### 3. Reload Apache\n\n```bash\nsudo systemctl reload apache2\n\n# Verify Apache is still running\nsudo systemctl status apache2\n```\n\n### 4. Test Public Access\n\n```bash\n# From any machine\ncurl https://dw.ramsden-international.com/myservice/\n\n# Or open in browser\n```\n\n## Troubleshooting\n\n### 404 Not Found - Service Works Locally\n\n**Cause**: ProxyPass configuration issue\n\n**Diagnostic Steps**:\n1. Verify service is accessible from rivsprod01:\n   ```bash\n   ssh rivsprod01 \"curl -s http://10.99.0.3:PORT/endpoint\"\n   ```\n\n2. Check Apache config order:\n   ```bash\n   ssh rivsprod01 \"cat /etc/apache2/proxy-conf.d/myservice.conf\"\n   ```\n   - API paths must come before frontend paths\n   - Verify trailing slashes on both source and target\n\n3. Check Apache error logs:\n   ```bash\n   ssh rivsprod01 \"sudo tail -50 /var/log/apache2/error.log | grep myservice\"\n   ```\n\n**Solution**:\n- Fix ProxyPass order (more specific first)\n- Add missing trailing slashes\n- Reload Apache: `sudo systemctl reload apache2`\n\n### 404 on API Calls, Frontend Works\n\n**Cause**: Frontend path is catching API requests\n\n**Example of Wrong Configuration**:\n```apache\n# WRONG - Frontend catches everything\nProxyPass /app/ http://10.99.0.3:9000/\nProxyPass /app/api/ http://10.99.0.3:8000/\n```\n\n**Solution - Put API First**:\n```apache\n# CORRECT - API catches specific path first\nProxyPass /app/api/ http://10.99.0.3:8000/\nProxyPass /app/ http://10.99.0.3:9000/\n```\n\n### Connection Refused from rivsprod01\n\n**Cause**: Service not listening on accessible IP\n\n**Diagnostic**:\n```bash\n# On machine running service\nnetstat -tlnp | grep PORT\n# or\nss -tlnp | grep PORT\n```\n\n**Look for**:\n- `127.0.0.1:PORT` - Only listening on localhost (wrong)\n- `10.99.0.3:PORT` - Listening on network IP (correct)\n- `0.0.0.0:PORT` - Listening on all interfaces (also correct)\n\n**Solution**: Configure service to bind to `0.0.0.0` or specific IP `10.99.0.3`\n\n### Service Stops Working After Apache Reload\n\n**Cause**: Configuration syntax error\n\n**Diagnostic**:\n```bash\nssh rivsprod01 \"sudo systemctl status apache2\"\n```\n\n**Solution**:\n1. Check for typos in ProxyPass URLs\n2. Verify no missing quotes or slashes\n3. Look at error log: `sudo tail /var/log/apache2/error.log`\n4. Fix config and reload again\n\n### CORS Errors in Browser Console\n\n**Cause**: Backend not configured for CORS, or wrong origin\n\n**Solution (Backend)**: Enable CORS in your service\n\n```python\n# FastAPI example\nfrom fastapi.middleware.cors import CORSMiddleware\n\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=[\"*\"],  # Or specific domain\n    allow_credentials=True,\n    allow_methods=[\"*\"],\n    allow_headers=[\"*\"],\n)\n```\n\n**Note**: Proxy handles forwarding; backend sees requests from proxy IP, not client\n\n## IP Addresses Reference\n\n| Hostname | IP Address | Purpose |\n|----------|-----------|---------|\n| rivsprod01 | 10.99.0.2 | Reverse proxy server (Apache) |\n| pogs (local) | 10.99.0.3 | Development machine running services |\n\n**Service Configuration**:\n- Services should bind to `10.99.0.3` or `0.0.0.0` to be accessible from rivsprod01\n- Use `http://10.99.0.3:PORT` in ProxyPass target URLs\n- Never use `localhost` or `127.0.0.1` in ProxyPass targets\n\n## File Locations on rivsprod01\n\n| Path | Purpose |\n|------|---------|\n| `/etc/apache2/proxy-conf.d/*.conf` | Proxy configurations (add yours here) |\n| `/etc/apache2/sites-available/default-ssl.conf` | Main SSL site config (includes proxy-conf.d) |\n| `/var/log/apache2/error.log` | Apache error log |\n| `/var/log/apache2/access.log` | Access log (if needed) |\n\n**Important**: Configs in `/etc/apache2/proxy-conf.d/` are automatically included by the SSL site configuration.\n\n## Best Practices Summary\n\n1. **Always use relative URLs** in frontend code for proxy compatibility\n2. **Test service accessibility** from rivsprod01 before configuring proxy\n3. **Put specific paths first** in Apache config (API before frontend)\n4. **Use trailing slashes** on both ProxyPass source and target for path stripping\n5. **Reload Apache** after config changes: `sudo systemctl reload apache2`\n6. **Keep configs organized** - one file per application or related service group\n7. **Document your paths** - add comments explaining what each ProxyPass does\n8. **Test both frontend and API** after deployment to verify routing\n"},"lastSynced":"2026-03-08T02:02:54.228Z","agentAnalysis":{"suitability":{"en":"Ideal for Web Development Agents requiring seamless Apache reverse proxy integration for secure web application deployment.","zh":"适合需要无缝Apache反向代理集成以实现安全Web应用程序部署的Web开发代理。","ja":"Apacheのリバースプロキシのシームレスな統合が必要なWeb開発エージェントに適しています。","ko":"보안 웹 응용 프로그램 배포를 위한 무결점 Apache 역방향 프록시 통합이 필요한 웹 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo web que requieren una integración sin problemas del proxy inverso de Apache para una implementación de aplicaciones web seguras.","fr":"Idéal pour les agents de développement Web nécessitant une intégration transparente du proxy inverse Apache pour un déploiement d''applications Web sécurisé.","de":"Ideal für Webentwicklungsagenten, die eine nahtlose Integration des Apache-Reverse-Proxys für eine sichere Bereitstellung von Webanwendungen erfordern.","pt":"Ideal para Agentes de Desenvolvimento Web que exigem integração perfeita do proxy reverso do Apache para implantação segura de aplicações web.","ru":"Идеально подходит для агентов веб-разработки, требующих бесшовной интеграции обратного прокси Apache для безопасного развертывания веб-приложений.","ar":"مثالي للوكلاء الذين يتطلبون تكاملًا بسلاسة مع وكيل Apache العكسي لتنفيذ تطبيقات الويب بشكل آمن."},"recommendation":{"en":"Empowers agents to deploy web applications behind the Apache reverse proxy, ensuring correct frontend relative URL patterns and Apache ProxyPass configuration using HTTP protocols and relative URLs.","zh":"赋予代理部署Web应用程序在Apache反向代理后面的能力，确保正确的前端相对URL模式和Apache ProxyPass配置使用HTTP协议和相对URL。","ja":"エージェントがApacheのリバースプロキシの後ろにウェブアプリケーションを配置できるようにし、HTTPプロトコルと相対URLを使用して、正しいフロントエンドの相対URLパターンとApache ProxyPassの設定を保証します。","ko":"에이전트가 Apache 역방향 프록시 뒤에 웹 응용 프로그램을 배포할 수 있도록 하여 HTTP 프로토콜 및 상대 URL을 사용하여 올바른 프론트엔드 상대 URL 패턴 및 Apache ProxyPass 구성이 보장되도록 합니다.","es":"Permite a los agentes implementar aplicaciones web detrás del proxy inverso de Apache, asegurando patrones de URL relativa correctos en el frontend y configuración de ProxyPass de Apache utilizando protocolos HTTP y URL relativas.","fr":"Permet aux agents de déployer des applications Web derrière le proxy inverse Apache, en garantissant des modèles d''URL relatifs corrects dans le frontend et une configuration ProxyPass Apache en utilisant des protocoles HTTP et des URL relatives.","de":"Ermöglicht es Agents, Webanwendungen hinter dem Apache-Reverse-Proxy zu bereitstellen, wodurch korrekte relative URL-Muster im Frontend und Apache-ProxyPass-Konfiguration unter Verwendung von HTTP-Protokollen und relativen URLs sichergestellt werden.","pt":"Habilita os agentes a implantar aplicações web atrás do proxy reverso do Apache, garantindo padrões de URL relativos corretos na frente e configuração do ProxyPass do Apache usando protocolos HTTP e URLs relativos.","ru":"Наделяет агентов возможностью развертывать веб-приложения за обратным прокси Apache, обеспечивая правильные относительные шаблоны URL в frontend и конфигурацию ProxyPass Apache с использованием протоколов HTTP и относительных URL.","ar":"يمنح الوكلاء القدرة على نشر تطبيقات الويب خلف وكيل Apache العكسي، وضمان أنماط URL النسبية الصحيحة في الواجهة الأمامية وتكوين Apache ProxyPass باستخدام بروتوكولات HTTP وURLs النسبية."},"useCases":{"en":["Configuring ProxyPass directives on rivsprod01","Deploying web applications with relative URL patterns","Securing web applications behind the Apache reverse proxy"],"zh":["在rivsprod01上配置ProxyPass指令","使用相对URL模式部署Web应用程序","在Apache反向代理后面保护Web应用程序"],"ja":["rivsprod01でProxyPassディレクティブを構成する","相対URLパターンを使用してWebアプリケーションをデプロイする","Apacheのリバースプロキシの後ろにWebアプリケーションを保護する"],"ko":["rivsprod01에서 ProxyPass 지시어를 구성하는 것","상대 URL 패턴을 사용하여 웹 응용 프로그램을 배포하는 것","Apache 역방향 프록시 뒤에 웹 응용 프로그램을 보호하는 것"],"es":["Configuración de directivas ProxyPass en rivsprod01","Implementación de aplicaciones web con patrones de URL relativa","Protección de aplicaciones web detrás del proxy inverso de Apache"],"fr":["Configuration des directives ProxyPass sur rivsprod01","Déploiement d''applications Web avec des modèles d''URL relatifs","Sécurisation d''applications Web derrière le proxy inverse Apache"],"de":["Konfiguration von ProxyPass-Richtlinien auf rivsprod01","Bereitstellung von Webanwendungen mit relativen URL-Mustern","Sicherung von Webanwendungen hinter dem Apache-Reverse-Proxy"],"pt":["Configurando diretivas ProxyPass no rivsprod01","Implantando aplicações web com padrões de URL relativos","Protegendo aplicações web atrás do proxy reverso do Apache"],"ru":["Настройка директив ProxyPass на rivsprod01","Развертывание веб-приложений с относительными шаблонами URL","Защита веб-приложений за обратным прокси Apache"],"ar":["تكوين توجيهات ProxyPass على rivsprod01","نشر تطبيقات الويب مع أنماط URL النسبية","حماية تطبيقات الويب خلف وكيل Apache العكسي"]},"limitations":{"en":["Requires Apache configuration access","Relative URLs must be used in frontend code"],"zh":["需要Apache配置访问权限","前端代码必须使用相对URL"],"ja":["Apacheの構成アクセスが必要","フロントエンドコードでは相対URLを使用する必要がある"],"ko":["Apache 구성 액세스 권한이 필요","프론트엔드 코드에서 상대 URL을 사용해야 함"],"es":["Requiere acceso a la configuración de Apache","Se deben utilizar URL relativas en el código del frontend"],"fr":["Nécessite un accès à la configuration Apache","Les URL relatives doivent être utilisées dans le code frontend"],"de":["Erfordert Zugriff auf die Apache-Konfiguration","Relative URLs müssen im Frontend-Code verwendet werden"],"pt":["Exige acesso à configuração do Apache","URLs relativos devem ser usados no código frontend"],"ru":["Требует доступа к конфигурации Apache","В коде frontend должны использоваться относительные URL"],"ar":["يتطلب الوصول إلى إعدادات Apache","يجب استخدام URLs النسبية في код الواجهة الأمامية"]},"version":4},"contentHash":"4953cd51d5e885379697cc5c9ce3bd717b616462555b73bcc6ba8e1685c3ae95","qualityScore":57}');
