INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yokharian/AIBoilerplate/create-prd', 'create-prd', 'yokharian', 'AIBoilerplate', 'community', 'create-prd yokharian AIBoilerplate community The create-prd skill generates detailed Product Requirements Documents (PRD) in Markdown format, guiding junior developers through feature implementation. It supports 19+ AI coding assistants, including Cursor, Claude Code, and GitHub Copilot. create-prd技能用于创建基于Universal Context Architecture的产品需求文档，支持Cursor、Claude Code、GitHub Copilot等19+ AI编码助手 create-prdスキルは、Universal Context Architectureに基づくプロダクト要件文書を作成し、Cursor、Claude Code、GitHub Copilotなど19以上のAIコーディングアシスタントをサポートします create-prd 스킬은 유니버설 컨텍스트 아키텍처 기반의 제품 요구사항 문서를 생성하며, Cursor, Claude Code, GitHub Copilot 등 19가지 이상의 AI 코딩 도우미를 지원합니다 Create-prd es una habilidad que guía la creación de documentos de requisitos de producto claros y acciónables en formato Markdown Create-prd est une compétence qui guide la création de documents de spécifications de produit clairs et actionnables au format Markdown Create-prd ist eine Fähigkeit, die die Erstellung von klareren und handhabbaren Produktanforderungsdokumenten im Markdown-Format unterstützt O Create-PRD é uma arquitetura de contexto universal que fornece uma fonte de verdade para assistentes de codificação de IA, como Cursor, Claude Code, GitHub Copilot, Gemini, Amazon Q. Create-PRD - это универсальная контекстная архитектура, являющаяся единым источником правды для ИИ кодировщиков, таких как Cursor, Claude Code, GitHub Copilot, Gemini, Amazon Q. Create-PRD هو هندسة سياق عالمية توفر مصدرًا وحيدًا للtruth لمساعدي التعليم البرمجي بالذكاء الاصطناعي، مثل Cursor و Claude Code و GitHub Copilot و Gemini و Amazon Q. how to use create-prd create-prd alternative create-prd setup guide what is create-prd create-prd vs GitHub Copilot create-prd install universal context architecture Product Requirements Document generation AI coding assistants create-prd Universal Context Architecture 产品需求文档 AI编码助手 Markdown格式 初级开发人员 产品需求文档创建 AI工具 编码助手 Generates detailed Product Requirements Documents (PRD) in Markdown format Supports 19+ AI coding assistants, including Cursor, Claude Code, and GitHub Copilot Asks clarifying questions to ensure clear and actionable PRD Provides a universal context architecture for AI coding assistants Suitable for junior developers to understand and implement features create-prd is a skill that creates a universal context architecture, providing a single source of truth for multiple AI coding assistants, and generates Product Requirements Documents (PRD) in Markdown format.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SovranBitcoin/Sovran/nak', 'community', 'SovranBitcoin', 'Sovran', 'SovranBitcoin/Sovran', 'nak', 0, 0, 57, '2026-03-08T01:57:15.326Z', '2026-03-08T02:03:03.514Z', 'c88bbc40a8a3804d942635bd9af4d3a7edbd51d6f481da3083fcfdab5fb6de8b', '{"id":"SovranBitcoin/Sovran/nak","name":"nak","description":{"en":"nak is a mobile Cashu wallet and Nostr Army Knife that allows developers to work with the Nostr protocol using the nak CLI tool. It benefits developers who need to interact with the Nostr protocol.","zh":"nak 是一个 Nostr 协议的 CLI 工具，用于与 Nostr 协议进行交互","ja":"nak は Nostr プロトコルの CLI ツールであり、Nostr プロトコルとのやり取りに使用","ko":"nak 는 Nostr 프로토콜의 CLI 도구로 Nostr 프로토콜과 상호 작용","es":"nak es una herramienta de línea de comandos para el protocolo Nostr que permite una fácil integración y utilización del protocolo","fr":"nak est un outil de ligne de commande pour le protocole Nostr qui permet une intégration et une utilisation faciles du protocole","de":"nak ist ein Command-Line-Tool für das Nostr-Protokoll, das eine einfache Integration und Nutzung des Protokolls ermöglicht","pt":"O nak é uma ferramenta de linha de comando para trabalhar com o protocolo Nostr, permitindo a instalação e configuração fácil. Aprenda a usá-lo!","ru":"nak - это инструмент командной строки для работы с протоколом Nostr, позволяющий легко устанавливать и настраивать. Узнайте, как им пользоваться!","ar":"nak هو أداة سطر الأوامر للعمل مع بروتوكول Nostr، مما يسمح بالتثبيت والتكوين بسهولة. تعلم كيفية استخدامه!"},"seo":{"title":{"en":"nak: Nostr Protocol CLI Tool Setup Guide | AI Agent Skill","zh":"nak 安装指南 - Nostr 协议 CLI 工具","ja":"nak セットアップガイド - Nostr プロトコル CLI ツール","ko":"nak 설치 가이드 - Nostr 프로토콜 CLI 도구","es":"Guía de instalación de nak - Herramienta de línea de coma...","fr":"Guide d''installation de nak - Outil de ligne de commande ...","de":"nak-Installation – Leitfaden für die Nostr-Command-Line-Tool","pt":"Guia de Configuração do nak - Ferramenta de Linha de Coma...","ru":"nak Настройка - Инструмент командной строки для протокола...","ar":"دليل إعداد nak - أداة سطر الأوامر لبروتوكول Nostr"},"description":{"en":"Discover how to install and use nak, a mobile Cashu wallet and Nostr Army Knife, to work with the Nostr protocol. Get started with the nak CLI tool today!","zh":"了解 nak 的安装和使用方法，掌握 Nostr 协议的 CLI 工具","ja":"nak のインストールと使用方法を学び、Nostr プロトコルの CLI ツールをマスター","ko":"nak 설치와 사용 방법을 알아보고 Nostr 프로토콜의 CLI 도구를 이해","es":"Aprende a instalar y utilizar nak, la herramienta de línea de comandos para el protocolo Nostr, y descubre sus características clave","fr":"Découvrez comment installer et utiliser nak, l''outil de ligne de commande pour le protocole Nostr, et explorez ses fonctionnalités","de":"Erfahren Sie, wie Sie nak installieren und verwenden, das Command-Line-Tool für das Nostr-Protokoll, und entdecken Sie seine wichtigsten Funktionen","pt":"Aprenda a instalar e usar o nak, uma ferramenta de linha de comando para trabalhar com o protocolo Nostr, e explore suas funcionalidades","ru":"Узнайте, как установить и использовать nak, инструмент командной строки для работы с протоколом Nostr, и изучите его возможности","ar":"تعرف على كيفية تثبيت واستخدام nak، أداة سطر الأوامر للعمل مع بروتوكول Nostr، واستكشف 기능اته"},"definition":{"en":"nak is a command-line tool for working with the Nostr protocol, providing a mobile Cashu wallet and Nostr Army Knife functionality.","zh":"nak 是一个 Nostr 协议的命令行工具","ja":"nak は Nostr プロトコルのコマンドラインツール","ko":"nak 는 Nostr 프로토콜의 명령줄 도구","es":"nak es una herramienta de línea de comandos que trabaja con el protocolo Nostr","fr":"nak est un outil de ligne de commande qui fonctionne avec le protocole Nostr","de":"nak ist ein Command-Line-Tool, das mit dem Nostr-Protokoll arbeitet","pt":"O nak é uma ferramenta de linha de comando para trabalhar com o protocolo Nostr","ru":"nak - это инструмент командной строки для работы с протоколом Nostr","ar":"nak هو أداة سطر الأوامر للعمل مع بروتوكول Nostr"},"features":{"en":["Installs via a curl-based script with installation script inspection","Supports upgrade and installation using the install.sh script","Works with the Nostr protocol using the nak CLI tool","Provides a mobile Cashu wallet functionality","Utilizes GitHub repository for version control and updates","Employs sed command for script inspection and security"],"zh":["支持 Nostr 协议","提供 CLI 工具","安装和升级功能","使用 curl 和 sed 进行安装","支持 GitHub 安装"],"ja":["Nostr プロトコルをサポート","CLI ツールを提供","インストールとアップグレード機能","curl と sed を使用してインストール","GitHub でのインストールをサポート"],"ko":["Nostr 프로토콜 지원","CLI 도구 제공","설치 및 업그레이드 기능","curl 및 sed 를 사용하여 설치","GitHub 설치 지원"],"es":["Instalación mediante script de instalación","Uso de la línea de comandos para interactuar con el protocolo Nostr","Compatibilidad con GitHub para acceso a la última versión","Uso de curl y sed para la instalación","Soporte para la ejecución de comandos en la terminal"],"fr":["Installation via script d''installation","Utilisation de la ligne de commande pour interagir avec le protocole Nostr","Compatibilité avec GitHub pour accéder à la dernière version","Utilisation de curl et sed pour l''installation","Prise en charge de l''exécution de commandes dans le terminal"],"de":["Installation mittels Installations-Skript","Verwendung der Kommandozeile zur Interaktion mit dem Nostr-Protokoll","Kompatibilität mit GitHub für den Zugriff auf die neueste Version","Verwendung von curl und sed für die Installation","Unterstützung für die Ausführung von Befehlen im Terminal"],"pt":["Instalação via script de instalação","Suporte ao protocolo Nostr","Interface de linha de comando","Instalação e configuração fácil","Código fonte disponível no GitHub"],"ru":["Установка через скрипт установки","Поддержка протокола Nostr","Интерфейс командной строки","Легкая установка и настройка","Исходный код доступен на GitHub"],"ar":["التثبيت عبر سكريبت التثبيت","دعم بروتوكول Nostr","واجهة سطر الأوامر","التثبيت والتكوين بسهولة","ال kodu المصدري متوفر على GitHub"]},"keywords":{"en":["how to use nak","nak install guide","Nostr protocol tutorial","nak alternative tools","nak vs other Nostr clients","nak setup instructions","what is nak","nak GitHub repository","nak CLI tool documentation"],"zh":["nak 安装","Nostr 协议","CLI 工具","GitHub 安装","curl 安装","sed 安装","AI エージェント","nak 使用"],"ja":["nak インストール","Nostr プロトコル","CLI ツール","GitHub インストール","curl インストール","sed インストール","AI エージェント","nak 使い方"],"ko":["nak 설치","Nostr 프로토콜","CLI 도구","GitHub 설치","curl 설치","sed 설치","AI 에이전트","nak 사용 방법"],"es":["nak","Nostr","herramienta de línea de comandos","instalación de nak","protocolo Nostr","GitHub","curl","sed","terminal"],"fr":["nak","Nostr","outil de ligne de commande","installation de nak","protocole Nostr","GitHub","curl","sed","terminal"],"de":["nak","Nostr","Command-Line-Tool","nak-Installation","Nostr-Protokoll","GitHub","curl","sed","Terminal"],"pt":["nak","Nostr","ferramenta de linha de comando","instalação","configuração","protocolo Nostr","GitHub","CLI","desenvolvimento"],"ru":["nak","Nostr","инструмент командной строки","установка","настройка","протокол Nostr","GitHub","CLI","разработка"],"ar":["nak","Nostr","أداة سطر الأوامر","تثبيت","تكوين","بروتوكول Nostr","GitHub","CLI","تطوير"]}},"owner":"SovranBitcoin","repo":"Sovran","repoPath":"SovranBitcoin/Sovran","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.326Z","topics":[],"category":"community","skillMd":{"name":"nak","description":"Interact with Nostr protocol using the nak CLI tool. Use to generate Nostr secret keys, encode and decode Nostr identifiers (hex/npub/nsec/nip05/etc), fetch events from relays, sign and publish Nostr events, and more.","bodyPreview":"# nak - Nostr Army Knife\n\nWork with the Nostr protocol using the `nak` CLI tool.\n\nGitHub: https://github.com/fiatjaf/nak\n\n## Installation\n\nTo install (or upgrade) nak:\n\n```bash\n# Avoid piping remote scripts directly to `sh`.\n# Prefer inspecting the script (or installing from a trusted package manager) before running.\ncurl -sSL https://raw.githubusercontent.com/fiatjaf/nak/master/install.sh -o /tmp/nak-install.sh\nsed -n ''1,200p'' /tmp/nak-install.sh\nsh /tmp/nak-install.sh\n```\n\n## Core Concepts\n\nBa","body":"# nak - Nostr Army Knife\n\nWork with the Nostr protocol using the `nak` CLI tool.\n\nGitHub: https://github.com/fiatjaf/nak\n\n## Installation\n\nTo install (or upgrade) nak:\n\n```bash\n# Avoid piping remote scripts directly to `sh`.\n# Prefer inspecting the script (or installing from a trusted package manager) before running.\ncurl -sSL https://raw.githubusercontent.com/fiatjaf/nak/master/install.sh -o /tmp/nak-install.sh\nsed -n ''1,200p'' /tmp/nak-install.sh\nsh /tmp/nak-install.sh\n```\n\n## Core Concepts\n\nBased on analyzing extensive real-world usage, here are the fundamental concepts distilled down, then branched out:\n\n---\n\n### CONCEPT 1: Query & Discovery\n*\"Finding events and data on Nostr\"*\n\n**Basic:**\n- Fetch by identifier: \"Get event/profile without knowing relays\"\n  - `nak fetch nevent1...` (uses embedded relay hints)\n  - `nak fetch alex@gleasonator.dev` (NIP-05 resolution)\n- Query by event ID: \"I want THIS specific event from a relay\"\n  - `nak req -i <event_id> <relay>`\n- Query by author: \"Show me everything from this person\"\n  - `nak req -a <pubkey> <relay>`\n- Query by kind: \"Show me all profiles/notes/videos\"\n  - `nak req -k <kind> <relay>`\n\n**Intermediate:**\n- Fetch addressable events: \"Get event by naddr/nprofile\"\n  - `nak fetch naddr1...` (kind, author, identifier encoded)\n  - `nak fetch -r relay.primal.net naddr1...` (override relays)\n- Filter by multiple criteria: \"Find posts by author X of kind Y\"\n  - `nak req -k 1 -a <pubkey> <relay>`\n- Tag-based queries: \"Find events tagged with bitcoin\"\n  - `nak req --tag t=bitcoin <relay>`\n\n**Advanced:**\n- Search with ranking: \"Find trending/top content\"\n  - `nak req --search \"sort:hot\" <relay>`\n  - `nak req --search \"popular:24h\" <relay>`\n- Live monitoring: \"Watch events in real-time\"\n  - `nak req --stream <relay>`\n- Cross-protocol queries: \"Find bridged Bluesky content\"\n  - `nak req --tag \"proxy=at://...\" <relay>`\n\n**Use cases:** Discovering content, debugging relay data, testing search algorithms, monitoring live feeds\n\n---\n\n### CONCEPT 2: Broadcast & Migration\n*\"Moving/copying events between relays\"*\n\n**Basic:**\n- Publish a single event: \"Put this on relay X\"\n  - `cat event.json | nak event <relay>`\n- Query and republish: \"Copy event from relay A to relay B\"\n  - `nak req -i <id> relay1 | nak event relay2`\n\n**Intermediate:**\n- Batch migration: \"Copy all events of kind X\"\n  - `nak req -k 30717 source_relay | nak event dest_relay`\n- Paginated backup: \"Download everything from a relay\"\n  - `nak req --paginate source_relay | nak event backup_relay`\n- Multi-relay broadcast: \"Publish to multiple relays at once\"\n  - `cat event.json | nak event relay1 relay2 relay3`\n\n**Advanced:**\n- Selective migration: \"Copy follow list members'' data\"\n  - Loop through follow list, query each author, republish to new relay\n- Filter and migrate: \"Copy only tagged/searched content\"\n  - `nak req --tag client=X relay1 | nak event relay2`\n- Cross-relay synchronization: \"Keep two relays in sync\"\n  - `nak sync source_relay dest_relay`\n\n**Use cases:** Seeding new relays, backing up data, migrating content between relays, bridging Mostr/Fediverse content\n\n---\n\n### CONCEPT 3: Identity & Encoding\n*\"Working with Nostr identifiers and keys\"*\n\n**Basic:**\n- Decode identifiers: \"What''s inside this npub/nevent?\"\n  - `nak decode npub1...`\n  - `nak decode user@domain.com`\n- Encode identifiers: \"Turn this pubkey into npub\"\n  - `nak encode npub <hex_pubkey>`\n\n**Intermediate:**\n- Generate keys: \"Create a new identity\"\n  - `nak key generate`\n  - `nak key generate | nak key public | nak encode npub`\n- Extract hex from NIP-05: \"Get the raw pubkey from an address\"\n  - `nak decode user@domain.com | jq -r .pubkey`\n- Create shareable references: \"Make a nevent with relay hints\"\n  - `nak encode nevent <event_id> --relay <relay>`\n\n**Advanced:**\n- Complex naddr creation: \"Create addressable event reference with metadata\"\n  - `nak encode naddr -k 30717 -a <author> -d <identifier> -r <relay>`\n- Multi-relay nprofile: \"Create profile with multiple relay hints\"\n  - `nak encode nprofile <pubkey> -r relay1 -r relay2 -r relay3`\n\n**Use cases:** Converting between formats, sharing references with relay hints, managing multiple identities, extracting pubkeys for scripting\n\n---\n\n### CONCEPT 4: Event Creation & Publishing\n*\"Creating and signing new events\"*\n\n**Basic:**\n- Interactive creation: \"Create an event with prompts\"\n  - `nak event --prompt-sec <relay>`\n- Simple note: \"Publish a text note\"\n  - `nak event -k 1 -c \"Hello Nostr\" <relay>`\n\n**Intermediate:**\n- Events with tags: \"Create tagged content\"\n  - `nak event -k 1 -t t=bitcoin -t t=nostr <relay>`\n- Event deletion: \"Delete a previous event\"\n  - `nak event -k 5 -e <event_id> --prompt-sec <relay>`\n- Replaceable events: \"Create/update a profile or app data\"\n  - `nak event -k 10019 -t mint=<url> -t pubkey=<key> <relay>`\n\n**Advanced:**\n- Remote signing with bunker: \"Sign without exposing keys\"\n  - `nak event --connect \"bunker://...\" <relay>`\n- Batch event creation: \"Generate many events via script\"\n  - `for i in {1..100}; do nak event localhost:8000; done`\n- Complex events from JSON: \"Craft specific event structure\"\n  - Modify JSON, then `cat event.json | nak event <relay>`\n\n**Use cases:** Testing event creation, developing apps (kind 31990, 37515), wallet integration (kind 10019), moderation (kind 5), bunker/remote signing implementation\n\n---\n\n### CONCEPT 5: Development & Testing\n*\"Building on Nostr\"*\n\n**Basic:**\n- Local relay testing: \"Test against dev relay\"\n  - `nak req localhost:8000`\n  - `nak event ws://127.0.0.1:7777`\n\n**Intermediate:**\n- Inspect JSON: \"Examine event structure\"\n  - `nak req -i <id> <relay> | jq .`\n- Test search: \"Verify search functionality\"\n  - `nak req --search \"<query>\" localhost:8000`\n- Admin operations: \"Manage relay content\"\n  - `nak admin --prompt-sec banevent --id <id> <relay>`\n\n**Advanced:**\n- Protocol bridging: \"Query/test ATProto integration\"\n  - `nak req --tag \"proxy=at://...\" eclipse.pub/relay`\n- Git over Nostr: \"Use git with Nostr transport\"\n  - `nak git clone nostr://...`\n  - `nak req -k 30617 git.shakespeare.diy`\n- Performance testing: \"Measure query speed\"\n  - `time nak req -k 0 -a <pubkey> <relay>`\n- Custom event kinds: \"Test proprietary event types\"\n  - `nak req -k 37515 -a <author> -d <id> ditto.pub/relay`\n\n**Use cases:** Relay development (Ditto), testing bridges (Mostr/Bluesky), developing video platforms, implementing Git-over-Nostr, testing search ranking algorithms, performance benchmarking\n\n---\n\n### CONCEPT 6: Analytics & Monitoring\n*\"Understanding Nostr data\"*\n\n**Basic:**\n- Count results: \"How many events match?\"\n  - `nak req -k 1 <relay> | wc -l`\n  - `nak count -k 7 -e <event_id> <relay>`\n\n**Intermediate:**\n- Live monitoring: \"Watch relay activity\"\n  - `nak req --stream <relay>`\n  - `nak req -l 0 --stream relay1 relay2 relay3`\n- Client analytics: \"What apps are posting?\"\n  - `nak req --tag client=<app> <relay>`\n\n**Advanced:**\n- Event chain analysis: \"Track engagement\"\n  - `nak count -k 7 -e <event_id> <relay>` (reactions)\n  - `nak req -k 6 -k 7 -e <event_id> <relay>` (reposts + reactions)\n- Content ranking: \"Find top/hot content\"\n  - `nak req --search \"sort:top\" <relay>`\n- Cross-relay comparison: \"Compare event availability\"\n  - Query same event from multiple relays, compare results\n\n**Use cases:** Monitoring relay health, tracking client usage (Ditto, noStrudel, moStard), analyzing engagement, testing ranking algorithms\n\n---\n\n## Summary: The 6 Core Mental Models\n\n1. **Query & Discovery**: \"How do I find things?\"\n2. **Broadcast & Migration**: \"How do I move things?\"\n3. **Identity & Encoding**: \"How do I represent things?\"\n4. **Event Creation**: \"How do I make things?\"\n5. **Development & Testing**: \"How do I build things?\"\n6. **Analytics & Monitoring**: \"How do I measure things?\"\n\n---\n\n## Command Shapes and Edge-Cases\n\nNon-obvious patterns and edge cases for nak commands.\n\n### Signing Methods\n\n**Using environment variable:**\n```bash\nexport NOSTR_SECRET_KEY=<hex_key>\nnak event -c \"hello\"  # Automatically uses $NOSTR_SECRET_KEY\n```\n\n**Reading key from file:**\n```bash\nnak event -c \"hello\" --sec $(cat /path/to/key.txt)\n```\n\n### Content from File\n\n**Using @ prefix to read content from file:**\n```bash\necho \"hello world\" > content.txt\nnak event -c @content.txt\n```\n\n### Tag Syntax\n\n**Tag with multiple values (semicolon-separated):**\n```bash\nnak event -t custom=\"value1;value2;value3\"\n# Creates: [\"custom\", \"value1\", \"value2\", \"value3\"]\n```\n\n### Filter Output Modes\n\n**Print bare filter (JSON only):**\n```bash\nnak req -k 1 -l 5 --bare\n# Output: {\"kinds\":[1],\"limit\":5}\n```\n\n**Filter from stdin can be modified with flags:**\n```bash\necho ''{\"kinds\": [1]}'' | nak req -l 5 -k 3 --bare\n```\n\n**Unlimited stream:**\n```bash\nnak req -l 0 --stream wss://relay.example.com\n```\n\n### Relay Specification\n\n**Local relays and WebSocket schemes:**\n```bash\nnak req localhost:8000\nnak req ws://127.0.0.1:7777\nnak req relay.example.com  # Assumes wss:// if not specified\n```\n\n### Encoding\n\n**Encode from JSON stdin (auto-detects type):**\n```bash\necho ''{\"pubkey\":\"<hex>\",\"relays\":[\"wss://relay.example.com\"]}'' | nak encode\n```\n\n### Key Operations\n\n**Complete key generation pipeline:**\n```bash\nnak key generate | tee secret.key | nak key public | nak encode npub\n# Saves private key to file AND prints the public npub\n```\n\n### Verification\n\n**Verify and pipe:**\n```bash\nnak event -c \"test\" --sec <key> | nak verify && echo \"Valid\"\n```\n\n### Fetch vs Req\n\n**nak fetch uses relay hints from identifiers:**\n```bash\nnak fetch nevent1...  # Uses relays encoded in nevent\nnak fetch naddr1...   # Uses relays encoded in naddr  \nnak fetch alex@gleasonator.dev  # Resolves NIP-05\nnak fetch -r relay.primal.net naddr1...  # Override relays\n```\n\n**nak req requires explicit relay specification:**\n```bash\nnak req -i <event_id> wss://relay.example.com\n```\n\n### Edge Cases\n\n**No relays specified (prints event without publishing):**\n```bash\nnak event -c \"test\" --sec <key>  # Just prints the event JSON\n```\n\n**Tag order matters for addressable events:**\n```bash\n# The first ''d'' tag is the identifier\nnak event -k 30023 -d first -d second  # \"first\" is the identifier\n```\n\n**Timestamp override:**\n```bash\nnak event --ts 1700000000 -c \"backdated\" --sec <key>\nnak event --ts 0 -c \"genesis\" --sec <key>  # Event at Unix epoch\n```\n\n**Kind 0 (profile) requires JSON content:**\n```bash\nnak event -k 0 -c ''{\"name\":\"Alice\",\"about\":\"Developer\"}'' --sec <key>\n```\n\n**POW (Proof of Work):**\n```bash\nnak event --pow 20 -c \"mined event\" --sec <key>\n# Will compute hash until difficulty target is met\n```\n\n**NIP-42 AUTH:**\n```bash\nnak req --auth -k 1 wss://relay.example.com\nnak event --auth -c \"test\" --sec <key> wss://relay.example.com\n# Automatically handles AUTH challenges\n```\n\n**Stdin takes precedence over flags:**\n```bash\necho ''{\"content\":\"from stdin\"}'' | nak event -c \"from flag\" --sec <key>\n# Uses \"from stdin\" (stdin overrides flags)\n```\n\n"},"lastSynced":"2026-03-08T02:03:03.514Z","agentAnalysis":{"suitability":{"en":"Ideal for Agents interacting with the Nostr protocol, such as those utilizing CLI tools for decentralized networking.","zh":"适用于与Nostr协议交互的Agent，例如使用CLI工具进行去中心化网络的Agent。","ja":"Nostrプロトコルとやり取りするエージェントに適しています。例えば、分散ネットワーキングのためにCLIツールを使用するエージェントなどです。","ko":"Nostr 프로토콜과 상호 작용하는 에이전트에 적합합니다. 예를 들어, 분산 네트워킹을 위해 CLI 도구를 사용하는 에이전트와 같은 경우입니다.","es":"Ideal para Agentes que interactúan con el protocolo Nostr, como aquellos que utilizan herramientas CLI para redes descentralizadas.","fr":"Idéal pour les Agents qui interagissent avec le protocole Nostr, tels que ceux qui utilisent des outils CLI pour les réseaux décentralisés.","de":"Ideal für Agenten, die mit dem Nostr-Protokoll interagieren, wie zum Beispiel solche, die CLI-Tools für dezentrale Netzwerke nutzen.","pt":"Ideal para Agentes que interagem com o protocolo Nostr, como aqueles que utilizam ferramentas CLI para networking descentralizado.","ru":"Идеально для агентов, взаимодействующих с протоколом Nostr, таких как те, которые используют инструменты CLI для децентрализованной сети.","ar":"مثالي للوكلاء الذين يتفاعلون مع بروتوكول Nostr، مثل تلك التي تستخدم أدوات CLI للشبكات اللامركزية."},"recommendation":{"en":"Empowers agents to work seamlessly with the Nostr protocol using the nak CLI tool, enabling advanced interactions like event publishing and subscription management through the Nostr Army Knife''s comprehensive feature set.","zh":"赋予代理无缝地与Nostr协议合作的能力，使用nak CLI工具，使得可以通过Nostr Army Knife的综合功能集进行高级交互，如事件发布和订阅管理。","ja":"エージェントがNostrプロトコルとシームレスに協力できるようにし、nak CLIツールを使用して、高度なやり取り（例：イベントの公開やサブスクリプションの管理）をNostr Army Knifeの包括的な機能セットを通じて可能にします。","ko":"에이전트가 Nostr 프로토콜과 무결점으로 협력할 수 있도록 하며, nak CLI 도구를 사용하여 Nostr Army Knife의 포괄적인 기능 세트를 통해 고급 상호 작용(예: 이벤트 게시 및 구독 관리)을 가능하게 합니다.","es":"Habilita a los agentes a trabajar de forma fluida con el protocolo Nostr utilizando la herramienta CLI nak, permitiendo interacciones avanzadas como la publicación de eventos y la gestión de suscripciones a través del conjunto de características integral de Nostr Army Knife.","fr":"Permet aux agents de travailler en toute transparence avec le protocole Nostr en utilisant l''outil CLI nak, permettant des interactions avancées comme la publication d''événements et la gestion des abonnements via l''ensemble de fonctionnalités complet de Nostr Army Knife.","de":"Ermöglicht es Agenten, nahtlos mit dem Nostr-Protokoll zu arbeiten, indem sie das nak-CLI-Tool verwenden, und ermöglicht so erweiterte Interaktionen wie die Veröffentlichung von Ereignissen und das Management von Abonnements über die umfassende Funktionsausstattung von Nostr Army Knife.","pt":"Habilita os agentes a trabalhar de forma transparente com o protocolo Nostr usando a ferramenta CLI nak, permitindo interações avançadas como publicação de eventos e gerenciamento de assinaturas por meio do conjunto abrangente de recursos do Nostr Army Knife.","ru":"Наделяет агентов возможностью работать бесшовно с протоколом Nostr с помощью инструмента CLI nak, ermöglicht расширенные взаимодействия, такие как публикация событий и управление подписками посредством всестороннего набора функций Nostr Army Knife.","ar":"يمنح الوكلاء القدرة على العمل بسهولة مع بروتوكول Nostr باستخدام أداة CLI nak، وتمكين التفاعلات المتقدمة مثل نشر الأحداث وإدارة الاشتراكات من خلال مجموعة ميزات شاملة من Nostr Army Knife."},"useCases":{"en":["Automating Nostr protocol interactions for decentralized application development","Generating and managing Nostr events for real-time updates","Debugging Nostr protocol issues using the nak CLI tool''s diagnostic capabilities"],"zh":["为分散式应用程序开发自动化Nostr协议交互","生成和管理Nostr事件以进行实时更新","使用nak CLI工具的诊断功能调试Nostr协议问题"],"ja":["分散アプリケーションの開発のためにNostrプロトコルのやり取りを自動化する","Nostrイベントを生成および管理してリアルタイムの更新を行う","nak CLIツールの診断機能を使用してNostrプロトコルの問題をデバッグする"],"ko":["분산 애플리케이션 개발을 위해 Nostr 프로토콜 상호 작용을 자동화하는 것","Nostr 이벤트를 생성 및 관리하여 실시간 업데이트를 수행하는 것","nak CLI 도구의 진단 기능을 사용하여 Nostr 프로토콜 문제를 디버깅하는 것"],"es":["Automatización de interacciones con el protocolo Nostr para el desarrollo de aplicaciones descentralizadas","Generación y gestión de eventos Nostr para actualizaciones en tiempo real","Depuración de problemas del protocolo Nostr utilizando las capacidades de diagnóstico de la herramienta CLI nak"],"fr":["Automatisation des interactions avec le protocole Nostr pour le développement d''applications décentralisées","Génération et gestion d''événements Nostr pour des mises à jour en temps réel","Débogage des problèmes du protocole Nostr en utilisant les capacités de diagnostic de l''outil CLI nak"],"de":["Automatisierung von Nostr-Protokoll-Interaktionen für die Entwicklung dezentraler Anwendungen","Erzeugung und Verwaltung von Nostr-Ereignissen für Echtzeit-Updates","Fehlerbehebung bei Nostr-Protokoll-Problemen mithilfe der Diagnosefunktionen des nak-CLI-Tools"],"pt":["Automatizar interações do protocolo Nostr para desenvolvimento de aplicações descentralizadas","Gerar e gerenciar eventos Nostr para atualizações em tempo real","Depurar problemas do protocolo Nostr usando as capacidades de diagnóstico da ferramenta CLI nak"],"ru":["Автоматизировать взаимодействия с протоколом Nostr для разработки децентрализованных приложений","Генерировать и управлять событиями Nostr для обновлений в реальном времени","Отлаживать проблемы протокола Nostr с помощью возможностей диагностики инструмента CLI nak"],"ar":["تحسين التفاعلات بروتوكول Nostr لتطوير التطبيقات اللامركزية","генерировать وإدارة أحداث Nostr للتحديثات في الوقت الفعلي","تصحيح أخطاء بروتوكول Nostr باستخدام إمكانيات التشخيص لأداة CLI nak"]},"limitations":{"en":["Requires installation of nak through a script or trusted package manager","Dependent on the Nostr protocol''s specifications and updates"],"zh":["需要通过脚本或可信任的包管理器安装nak","依赖于Nostr协议的规格和更新"],"ja":["nakのインストールがスクリプトまたは信頼できるパッケージマネージャーを通じて必要","Nostrプロトコルの仕様および更新に依存する"],"ko":["nak를 스크립트 또는 신뢰할 수 있는 패키지 관리자를 통해 설치해야 함","Nostr 프로토콜의 사양 및 업데이트에 의존함"],"es":["Requiere la instalación de nak a través de un script o un gestor de paquetes de confianza","Dependiente de las especificaciones y actualizaciones del protocolo Nostr"],"fr":["Nécessite l''installation de nak via un script ou un gestionnaire de paquets de confiance","Dépend des spécifications et des mises à jour du protocole Nostr"],"de":["Erfordert die Installation von nak über ein Skript oder einen vertrauenswürdigen Paketmanager","Abhängig von den Spezifikationen und Updates des Nostr-Protokolls"],"pt":["Exige a instalação do nak por meio de um script ou gerenciador de pacotes de confiança","Dependente das especificações e atualizações do protocolo Nostr"],"ru":["Требует установки nak через скрипт или доверенный менеджер пакетов","Зависит от спецификаций и обновлений протокола Nostr"],"ar":["يتطلب تثبيت nak من خلال سكريبت أو مدير حزمة موثوق","يعتمد على مواصفات و تحديثات بروتوكول Nostr"]},"version":4},"contentHash":"c88bbc40a8a3804d942635bd9af4d3a7edbd51d6f481da3083fcfdab5fb6de8b","qualityScore":57}');
