INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SovranBitcoin/Sovran/nak', 'nak', 'SovranBitcoin', 'Sovran', 'community', 'nak SovranBitcoin Sovran community nak is a mobile Cashu wallet and Nostr Army Knife that allows developers to work with the Nostr protocol using the nak CLI tool. It benefits developers who need to interact with the Nostr protocol. nak 是一个 Nostr 协议的 CLI 工具，用于与 Nostr 协议进行交互 nak は Nostr プロトコルの CLI ツールであり、Nostr プロトコルとのやり取りに使用 nak 는 Nostr 프로토콜의 CLI 도구로 Nostr 프로토콜과 상호 작용 nak es una herramienta de línea de comandos para el protocolo Nostr que permite una fácil integración y utilización del protocolo nak est un outil de ligne de commande pour le protocole Nostr qui permet une intégration et une utilisation faciles du protocole nak ist ein Command-Line-Tool für das Nostr-Protokoll, das eine einfache Integration und Nutzung des Protokolls ermöglicht O nak é uma ferramenta de linha de comando para trabalhar com o protocolo Nostr, permitindo a instalação e configuração fácil. Aprenda a usá-lo! nak - это инструмент командной строки для работы с протоколом Nostr, позволяющий легко устанавливать и настраивать. Узнайте, как им пользоваться! nak هو أداة سطر الأوامر للعمل مع بروتوكول Nostr، مما يسمح بالتثبيت والتكوين بسهولة. تعلم كيفية استخدامه! how to use nak nak install guide Nostr protocol tutorial nak alternative tools nak vs other Nostr clients nak setup instructions what is nak nak GitHub repository nak CLI tool documentation nak 安装 Nostr 协议 CLI 工具 GitHub 安装 curl 安装 sed 安装 AI エージェント nak 使用 Installs via a curl-based script with installation script inspection Supports upgrade and installation using the install.sh script Works with the Nostr protocol using the nak CLI tool Provides a mobile Cashu wallet functionality Utilizes GitHub repository for version control and updates Employs sed command for script inspection and security nak is a command-line tool for working with the Nostr protocol, providing a mobile Cashu wallet and Nostr Army Knife functionality.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('eliaskc/kajji/dex', 'community', 'eliaskc', 'kajji', 'eliaskc/kajji', 'dex', 0, 0, 57, '2026-03-08T01:57:15.326Z', '2026-03-08T02:03:03.515Z', 'a7153489d4ad2707c26a13defcb5732e264c4678e3acd9148479033afe24eab2', '{"id":"eliaskc/kajji/dex","name":"dex","description":{"en":"dex is a simple terminal interface for jj, providing a structured approach to task management through tickets. It benefits developers and AI agents by offering a comprehensive context for commands.","zh":"dex是一个简单的终端接口，用于优化任务管理。它采用票务而非待办事项的方式，提供结构化的工作流程","ja":"dexはターミナルインターフェースを使用したタスク管理の最適化ツールです。チケットを使用した構造化されたワークフローを提供","ko":"dex는 터미널 인터페이스를 사용한 작업 관리 최적화 도구입니다. 티켓을 사용한 구조화된 워크플로우를 제공","es":"dex es una interfaz de terminal para gestionar tareas y tickets con contexto comprehensivo, incluyendo nombre, descripción y resultado","fr":"dex est une interface terminal pour gérer des tâches et des tickets avec un contexte complet, incluant nom, description et résultat","de":"dex ist eine Terminal-Schnittstelle zur Verwaltung von Aufgaben und Tickets mit umfassendem Kontext, einschließlich Name, Beschreibung und Ergebnis","pt":"O dex é uma interface de terminal simples para jj, que permite aos desenvolvedores criar tarefas estruturadas com contexto abrangente","ru":"dex - простой интерфейс терминала для jj, который позволяет разработчикам создавать структурированные задачи с полным контекстом для ИИ Агентов","ar":"dex هو واجهة طرفية بسيطة لjj، يسمح للمطورين بإنشاء مهام منسقة مع سياق شامل"},"seo":{"title":{"en":"dex: Terminal Interface Setup Guide | AI Agent Skill","zh":"dex终端接口设置指南 - 优化任务管理","ja":"dexターミナルインターフェースのベストプラクティス - AIエージェント","ko":"dex 터미널 인터페이스 설정 가이드 - 효율적인 작업 관리","es":"Guía de configuración de dex: Terminal Interface para Des...","fr":"Guide de mise en route de dex: Interface Terminal pour Dé...","de":"Einrichtungsleitfaden für dex: Terminal-Schnittstelle für...","pt":"Guia de Configuração do dex: Interface de Terminal para D...","ru":"Установка и Настройка dex: Простой Интерфейс Терминала дл...","ar":"دليل تثبيت dex: واجهة طرفية بسيطة للتصميم"},"description":{"en":"Discover how to use dex for agent coordination and unlock efficient command invocation - get started now!","zh":"了解dex的核心原则：票务而非待办事项，并发现如何使用dex优化任务管理","ja":"dexのコアプリンシプル「チケット、ではなくToDo」を学び、AIエージェントを使用したタスク管理の最適化を発見","ko":"dex의 핵심 원칙: 티켓을 사용한 작업 관리를 알아보고, 효율적인 작업 관리를 위한 dex 사용법을 발견","es":"Aprende a utilizar dex, una interfaz de terminal simple para gestionar tareas y tickets con contexto comprehensivo","fr":"Découvrez comment utiliser dex, une interface terminal simple pour gérer des tâches et des tickets avec un contexte complet","de":"Erfahren Sie, wie Sie dex verwenden, eine einfache Terminal-Schnittstelle zur Verwaltung von Aufgaben und Tickets mit umfassendem Kontext","pt":"Aprenda a usar o dex, uma interface de terminal simples para jj, e descubra como ele pode ajudar no desenvolvimento de aplicativos","ru":"Узнайте, как использовать dex, простой интерфейс терминала для jj, и как он может помочь в разработке приложений для ИИ Агентов","ar":"تعرف على كيفية استخدام dex، واجهة طرفية بسيطة لjj، وكيف يمكنه مساعدتك في تصميم التطبيقات"},"definition":{"en":"dex is a terminal interface for agent coordination, utilizing tickets with comprehensive context for efficient command invocation.","zh":"dex是一种简单的终端接口，用于任务管理和协调","ja":"dexはターミナルインターフェースを使用したタスク管理と調整ツール","ko":"dex는 터미널 인터페이스를 사용한 작업 관리와 조정 도구","es":"dex es una herramienta de terminal para la coordinación de agentes, que utiliza tickets estructurados con contexto comprehensivo","fr":"dex est un outil de terminal pour la coordination d''agents, qui utilise des tickets structurés avec un contexte complet","de":"dex ist ein Terminal-Tool für die Koordination von Agenten, das strukturierte Tickets mit umfassendem Kontext verwendet","pt":"O dex é uma ferramenta de interface de terminal que permite criar tarefas estruturadas com nome, descrição e resultado","ru":"dex - это инструмент интерфейса терминала, который позволяет создавать структурированные задачи с именем, описанием и результатом для ИИ Агентов","ar":"dex هو أداة واجهة طرفية تسمح بإنشاء مهام منسقة مع اسم ووصف ونتيجة"},"features":{"en":["Invokes commands directly via `dex` or `npx @zeeg/dex`","Utilizes tickets with structured artifacts for comprehensive context","Includes name, description, and result for each ticket","Supports command invocation via bash with `command -v dex`","Provides a core principle of tickets, not todos, for task management"],"zh":["使用dex直接执行命令","支持npx @zeeg/dex命令","采用票务而非待办事项的方式","提供结构化的工作流程","包含名称、描述、结果等详细信息"],"ja":["dexを使用した直接コマンド実行","npx @zeeg/dexコマンドのサポート","チケットを使用した構造化されたワークフロー","名前、説明、結果などの詳細情報を含む","ターミナルインターフェースを使用したタスク管理"],"ko":["dex를 사용한 직접 명령어 실행","npx @zeeg/dex 명령어 지원","티켓을 사용한 구조화된 워크플로우","이름, 설명, 결과 등의詳細 정보 포함","터미널 인터페이스를 사용한 작업 관리"],"es":["Interfaz de terminal simple para gestionar tareas y tickets","Soporte para tickets estructurados con contexto comprehensivo","Uso de comandos CLI para invocar acciones","Compatibilidad con npx para ejecutar comandos sin instalar","Estructura de tickets con nombre, descripción y resultado"],"fr":["Interface terminal simple pour gérer des tâches et des tickets","Prise en charge de tickets structurés avec un contexte complet","Utilisation de commandes CLI pour invoquer des actions","Compatibilité avec npx pour exécuter des commandes sans installer","Structure de tickets avec nom, description et résultat"],"de":["Einfache Terminal-Schnittstelle zur Verwaltung von Aufgaben und Tickets","Unterstützung für strukturierte Tickets mit umfassendem Kontext","Verwendung von CLI-Befehlen zur Aufruf von Aktionen","Kompatibilität mit npx zur Ausführung von Befehlen ohne Installation","Ticket-Struktur mit Name, Beschreibung und Ergebnis"],"pt":["Interface de terminal simples para jj","Criação de tarefas estruturadas com contexto abrangente","Suporte a comandos via `dex` ou `npx @zeeg/dex`","Tarefas como tickets com nome, descrição e resultado","Suporte a tickets com implementação de detalhes e decisões"],"ru":["Простой интерфейс терминала для jj","Создание структурированных задач с полным контекстом для ИИ Агентов","Поддержка команд через `dex` или `npx @zeeg/dex`","Задачи как тикеты с именем, описанием и результатом","Поддержка тикетов с реализацией деталей и решений"],"ar":["واجهة طرفية بسيطة لjj","إنشاء مهام منسقة مع سياق شامل","دعم أوامر عبر `dex` أو `npx @zeeg/dex`","مهام كتذاكر مع اسم ووصف ونتيجة","دعم التذاكر مع تنفيذ تفاصيل وتصميمات"]},"keywords":{"en":["how to use dex","dex setup guide","dex terminal interface","agent coordination with dex","dex alternative","dex vs jj","dex install","what is dex","dex command invocation","dex tickets"],"zh":["dex终端接口","任务管理工具","AI工具","终端命令","npx @zeeg/dex","票务而非待办事项","结构化工作流程"],"ja":["dexターミナルインターフェース","タスク管理ツール","AIエージェント","ターミナルコマンド","npx @zeeg/dex","チケットを使用した構造化されたワークフロー","タスク管理の最適化"],"ko":["dex 터미널 인터페이스","작업 관리 도구","AI 에이전트","터미널 명령어","npx @zeeg/dex","티켓을 사용한 구조화된 워크플로우","작업 관리의 최적화"],"es":["dex terminal","herramientas de terminal para desarrolladores","gestión de tareas con contexto","tickets estructurados","CLI para desarrolladores","npx para ejecutar comandos","agentes de inteligencia artificial","herramientas de IA para desarrolladores"],"fr":["dex terminal","outils de terminal pour développeurs","gestion de tâches avec contexte","tickets structurés","CLI pour développeurs","npx pour exécuter des commandes","agents d''intelligence artificielle","outils d''IA pour développeurs"],"de":["dex terminal","terminal-tools für entwickler","aufgabenverwaltung mit kontext","strukturierte tickets","CLI für entwickler","npx zur ausführung von befehlen","künstliche intelligenz agenten","ia-tools für entwickler"],"pt":["dex","interface de terminal","jj","tarefas estruturadas","contexto abrangente","comandos dex","npx @zeeg/dex","tickets de desenvolvimento"],"ru":["dex","интерфейс терминала","jj","структурированные задачи","полный контекст","команды dex","npx @zeeg/dex","ИИ Агенты","тикеты разработки"],"ar":["dex","واجهة طرفية","jj","مهام منسقة","سياق شامل","أوامر dex","npx @zeeg/dex","تصميم التطبيقات","تذاكر التصميم"]}},"owner":"eliaskc","repo":"kajji","repoPath":"eliaskc/kajji","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.326Z","topics":[],"category":"community","skillMd":{"name":"dex","description":"Manage tasks via dex CLI. Use when breaking down complex work, tracking implementation items, or persisting context across sessions.","bodyPreview":"# Agent Coordination with dex\n\n## Command Invocation\n\nUse `dex` directly for all commands. If not on PATH, use `npx @zeeg/dex` instead.\n\n```bash\ncommand -v dex &>/dev/null && echo \"use: dex\" || echo \"use: npx @zeeg/dex\"\n```\n\n## Core Principle: Tickets, Not Todos\n\nDex tasks are **tickets** - structured artifacts with comprehensive context:\n\n- **Name**: One-line summary (issue title)\n- **Description**: Full background, requirements, approach (issue body)\n- **Result**: Implementation details, decis","body":"# Agent Coordination with dex\n\n## Command Invocation\n\nUse `dex` directly for all commands. If not on PATH, use `npx @zeeg/dex` instead.\n\n```bash\ncommand -v dex &>/dev/null && echo \"use: dex\" || echo \"use: npx @zeeg/dex\"\n```\n\n## Core Principle: Tickets, Not Todos\n\nDex tasks are **tickets** - structured artifacts with comprehensive context:\n\n- **Name**: One-line summary (issue title)\n- **Description**: Full background, requirements, approach (issue body)\n- **Result**: Implementation details, decisions, outcomes (PR description)\n\nThink: \"Would someone understand the what, why, and how from this task alone?\"\n\n## Dex Tasks are Ephemeral\n\n**Never reference dex task IDs in external artifacts** (commits, PRs, docs). Task IDs like `abc123` become meaningless once tasks are completed. Describe the work itself, not the task that tracked it.\n\n## When to Use dex\n\n**Use dex when:**\n\n- Breaking down complexity into subtasks\n- Work spans multiple sessions\n- Context needs to persist for handoffs\n- Recording decisions for future reference\n\n**Skip dex when:**\n\n- Work is a single atomic action\n- Everything fits in one session with no follow-up\n- Overhead exceeds value\n\n## dex vs Built-in Task Tools\n\nSome AI agents (like Claude Code) have built-in task tools. These are session-only and not the same as dex.\n\n|                 | dex                                   | Built-in Task Tools |\n| --------------- | ------------------------------------- | ------------------- |\n| **Persistence** | Files in `.dex/`                      | Session-only        |\n| **Context**     | Rich (description + context + result) | Basic               |\n| **Hierarchy**   | 3-level (epic → task → subtask)       | Flat                |\n\nUse **dex** for persistent work. Use built-in task tools for ephemeral in-session tracking only.\n\n## Basic Workflow\n\n### Create a Task\n\n```bash\ndex create \"Short name\" --description \"Full implementation context\"\n```\n\nDescription should include: what needs to be done, why, implementation approach, and acceptance criteria. See [examples.md](examples.md) for good/bad examples.\n\n### List and View Tasks\n\n```bash\ndex list                  # Pending tasks\ndex list --ready          # Unblocked tasks\ndex show <id>             # Full details\n```\n\n### Complete a Task\n\n```bash\ndex complete <id> --result \"What was accomplished\" --commit <sha>\n```\n\n**Always verify before completing.** Results must include evidence: test counts, build status, manual testing outcomes. See [verification.md](verification.md) for the full checklist.\n\n### Edit and Delete\n\n```bash\ndex edit <id> --description \"Updated description\"\ndex delete <id>\n```\n\nFor full CLI reference including blockers, see [cli-reference.md](cli-reference.md).\n\n## Understanding Task Fields\n\nTasks have two text fields:\n\n- **Name**: Brief one-line summary (shown in `dex list`)\n- **Description**: Full details - requirements, approach, acceptance criteria (shown with `--full`)\n\nWhen you run `dex show <id>`, the description may be truncated. The CLI will hint at `--full` if there''s more content.\n\n### Gathering Context\n\nWhen picking up a task, gather all relevant context:\n\n```bash\ndex show <id> --full              # Full task details\ndex show <parent-id> --full       # Parent context (if applicable)\ndex show <blocker-id> --full      # What blockers accomplished\n```\n\nBefore starting, verify you can answer:\n\n- **What** needs to be done specifically?\n- **Why** is this needed?\n- **How** should it be implemented?\n- **When** is it done (acceptance criteria)?\n\nIf any answer is unclear:\n\n1. Check parent task or completed blockers for more details\n2. Suggest entering plan mode to flesh out requirements before starting\n\n**Proceed without full context when:**\n\n- Task is trivial/atomic (e.g., \"Add .gitignore entry\")\n- Conversation already provides the missing context\n- Description itself is sufficiently detailed\n\n## Task Hierarchies\n\nThree levels: **Epic** (large initiative) → **Task** (significant work) → **Subtask** (atomic step).\n\n**Choosing the right level:**\n\n- Small feature (1-2 files) → Single task\n- Medium feature (3-7 steps) → Task with subtasks\n- Large initiative (5+ tasks) → Epic with tasks\n\n```bash\n# Create subtask under parent\ndex create --parent <id> \"Subtask name\" --description \"...\"\n```\n\nFor detailed hierarchy guidance, see [hierarchies.md](hierarchies.md).\n\n## Recording Results\n\nComplete tasks **immediately after implementing AND verifying**:\n\n- Capture decisions while fresh\n- Note deviations from plan\n- Document verification performed\n- Create follow-up tasks for tech debt\n\nYour result must include explicit verification evidence. Don''t just describe what you did—prove it works. See [verification.md](verification.md).\n\n## Commit Messages with GitHub Issues\n\nWhen a task is linked to a GitHub issue (shown in `dex show` output), include issue references in commit messages:\n\n- **Root tasks** (the task itself has GitHub metadata): Use `Fixes #N`\n  - This closes the issue when merged\n- **Subtasks** (parent/ancestor has GitHub metadata): Use `Refs #N`\n  - This links to the issue without closing it\n\nCheck `dex show <id>` for GitHub issue info before committing. The \"(via parent)\" indicator means use `Refs`, direct metadata means use `Fixes`.\n\n## Best Practices\n\n1. **Right-size tasks**: Completable in one focused session\n2. **Clear completion criteria**: Description should define \"done\"\n3. **Don''t over-decompose**: 3-7 children per parent\n4. **Action-oriented descriptions**: Start with verbs (\"Add\", \"Fix\", \"Update\")\n5. **Verify before completing**: Tests passing, manual testing done\n\n## Additional Resources\n\n- [cli-reference.md](cli-reference.md) - Full CLI documentation\n- [examples.md](examples.md) - Good/bad context and result examples\n- [verification.md](verification.md) - Verification checklist and process\n- [hierarchies.md](hierarchies.md) - Epic/task/subtask organization\n"},"lastSynced":"2026-03-08T02:03:03.515Z","agentAnalysis":{"suitability":{"en":"Perfect for Task Management Agents needing structured command invocation and ticket-based workflow management.","zh":"适用于需要结构化命令调用和基于票据的工作流管理的任务管理代理。","ja":"タスク管理エージェントが構造化されたコマンド呼び出しとチケットベースのワークフロ管理を必要とする場合に適しています。","ko":"구조화된 명령 호출 및 티켓 기반 워크플로 관리가 필요한 태스크 관리 에이전트에 적합합니다.","es":"Perfecto para Agentes de Gestión de Tareas que necesitan invocación de comandos estructurada y gestión de flujo de trabajo basada en tickets.","fr":"Parfait pour les Agents de Gestion de Tâches ayant besoin d''une invocation de commande structurée et d''une gestion de workflow basée sur des tickets.","de":"Perfekt für Task-Management-Agents, die eine strukturierte Befehlsaufruf und eine ticketbasierte Workflow-Verwaltung benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Tarefas que necessitam de invocação de comandos estruturada e gerenciamento de fluxo de trabalho baseado em tickets.","ru":"Идеально подходит для агентов управления задачами, которым требуется структурированное вызов команд и управление рабочим процессом на основе тикетов.","ar":"مثالي لوكلاء إدارة المهام الذين يحتاجون إلى استدعاء أوامر منظم و إدارة تدفق العمل المستندة إلى التذاكر."},"recommendation":{"en":"Empowers agents to manage tasks through tickets with comprehensive context, utilizing terminal interfaces and supporting libraries like npm and npx, while providing a structured approach to task management through commands like `dex` and `npx @zeeg/dex`.","zh":"赋予代理通过带有综合上下文的票据来管理任务的能力，利用终端接口和支持库，如npm和npx，同时通过命令如`dex`和`npx @zeeg/dex`提供结构化的任务管理方法。","ja":"エージェントに、包括的なコンテキストを備えたチケットを介してタスクを管理する機能を付与し、ターミナルインターフェイスとnpmやnpxなどのサポートライブラリを利用し、`dex`や`npx @zeeg/dex`などのコマンドを通じて構造化されたタスク管理手法を提供します。","ko":"에이전트가 종합적인 컨텍스트를 갖춘 티켓을 통해 태스크를 관리할 수 있도록 하는 동시에, 터미널 인터페이스와 npm 및 npx와 같은 지원 라이브러리를 활용하며, `dex` 및 `npx @zeeg/dex`와 같은 명령을 통해 구조화된 태스크 관리 방법을 제공합니다.","es":"Habilita a los agentes a gestionar tareas a través de tickets con contexto integral, utilizando interfaces de terminal y bibliotecas de soporte como npm y npx, mientras proporciona un enfoque estructurado para la gestión de tareas a través de comandos como `dex` y `npx @zeeg/dex`.","fr":"Permet aux agents de gérer des tâches via des tickets avec un contexte complet, en utilisant des interfaces de terminal et des bibliothèques de support comme npm et npx, tout en fournissant une approche structurée pour la gestion de tâches via des commandes comme `dex` et `npx @zeeg/dex`.","de":"Ermöglicht es Agenten, Aufgaben über Tickets mit umfassendem Kontext zu verwalten, indem sie Terminal-Schnittstellen und Support-Bibliotheken wie npm und npx verwenden, während sie einen strukturierten Ansatz für die Aufgabenverwaltung durch Befehle wie `dex` und `npx @zeeg/dex` bieten.","pt":"Habilita os agentes a gerenciar tarefas por meio de tickets com contexto abrangente, utilizando interfaces de terminal e bibliotecas de suporte como npm e npx, enquanto fornece uma abordagem estruturada para o gerenciamento de tarefas por meio de comandos como `dex` e `npx @zeeg/dex`.","ru":"Наделяет агентов возможностью управлять задачами через тикеты с полным контекстом, используя терминальные интерфейсы и поддерживающие библиотеки, такие как npm и npx, обеспечивая структурированный подход к управлению задачами посредством команд, таких как `dex` и `npx @zeeg/dex`.","ar":"تمكّن الوكلاء من إدارة المهام من خلال التذاكر مع السياق الشامل، باستخدام واجهات الطرفية ومكتبات الدعم مثل npm و npx، مع توفير نهج منظم لإدارة المهام من خلال أوامر مثل `dex` و `npx @zeeg/dex`."},"useCases":{"en":["Invoking commands directly through `dex`","Managing tasks as structured tickets with name, description, and result","Utilizing npm and npx for seamless integration"],"zh":["直接通过`dex`调用命令","以结构化的票据（包含名称、描述和结果）管理任务","利用npm和npx实现无缝集成"],"ja":["`dex`を介して直接コマンドを呼び出す","名前、説明、結果を含む構造化されたチケットとしてタスクを管理する","npmとnpxを利用してシームレスな統合を実現する"],"ko":["`dex`를 통해 직접 명령어를 호출하는 것","이름, 설명, 결과를 포함하는 구조화된 티켓으로 태스크를 관리하는 것","npm 및 npx를 활용하여 무縫의 통합을 구현하는 것"],"es":["Invocar comandos directamente a través de `dex`","Gestionar tareas como tickets estructurados con nombre, descripción y resultado","Utilizar npm y npx para una integración sin problemas"],"fr":["Appeler des commandes directement via `dex`","Gérer des tâches comme des tickets structurés avec nom, description et résultat","Utiliser npm et npx pour une intégration sans problème"],"de":["Befehle direkt über `dex` aufrufen","Aufgaben als strukturierte Tickets mit Name, Beschreibung und Ergebnis verwalten","npm und npx für eine nahtlose Integration verwenden"],"pt":["Invocar comandos diretamente por meio de `dex`","Gerenciar tarefas como tickets estruturados com nome, descrição e resultado","Utilizar npm e npx para integração sem interrupções"],"ru":["Вызов команд напрямую через `dex`","Управление задачами как структурированные тикеты с именем, описанием и результатом","Использование npm и npx для бесшовной интеграции"],"ar":["استدعاء أوامر مباشرة من خلال `dex`","إدارة المهام كتذاكر منظم مع اسم ووصف وناتج","استخدام npm و npx للحصول على التكامل السلس"]},"limitations":{"en":["Requires dex installation and PATH configuration","Limited to terminal interface interactions"],"zh":["需要dex安装和PATH配置","仅限于终端接口交互"],"ja":["dexのインストールとPATHの設定が必要","ターミナルインターフェイスとのやり取りのみに限定される"],"ko":["dex 설치 및 PATH 구성이 필요","터미널 인터페이스 상호작용에만 제한"],"es":["Requiere la instalación de dex y la configuración de PATH","Limitado a interacciones de interfaz de terminal"],"fr":["Nécessite l''installation de dex et la configuration de PATH","Limité aux interactions d''interface de terminal"],"de":["Benötigt die Installation von dex und die PATH-Konfiguration","Begrenzt auf Terminal-Schnittstellen-Interaktionen"],"pt":["Requer instalação do dex e configuração do PATH","Limitado a interações de interface de terminal"],"ru":["Требует установки dex и настройки PATH","Ограничен взаимодействием с терминальным интерфейсом"],"ar":["يتطلب تثبيت dex وتهيئة PATH","محدود بالتفاعلات مع واجهة الطرفية"]},"version":4},"contentHash":"a7153489d4ad2707c26a13defcb5732e264c4678e3acd9148479033afe24eab2","qualityScore":57}');
