INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eliaskc/kajji/dex', 'dex', 'eliaskc', 'kajji', 'community', 'dex eliaskc kajji community dex is a simple terminal interface for jj, providing a structured approach to task management through tickets. It benefits developers and AI agents by offering a comprehensive context for commands. dex是一个简单的终端接口，用于优化任务管理。它采用票务而非待办事项的方式，提供结构化的工作流程 dexはターミナルインターフェースを使用したタスク管理の最適化ツールです。チケットを使用した構造化されたワークフローを提供 dex는 터미널 인터페이스를 사용한 작업 관리 최적화 도구입니다. 티켓을 사용한 구조화된 워크플로우를 제공 dex es una interfaz de terminal para gestionar tareas y tickets con contexto comprehensivo, incluyendo nombre, descripción y resultado dex est une interface terminal pour gérer des tâches et des tickets avec un contexte complet, incluant nom, description et résultat dex ist eine Terminal-Schnittstelle zur Verwaltung von Aufgaben und Tickets mit umfassendem Kontext, einschließlich Name, Beschreibung und Ergebnis O dex é uma interface de terminal simples para jj, que permite aos desenvolvedores criar tarefas estruturadas com contexto abrangente dex - простой интерфейс терминала для jj, который позволяет разработчикам создавать структурированные задачи с полным контекстом для ИИ Агентов dex هو واجهة طرفية بسيطة لjj، يسمح للمطورين بإنشاء مهام منسقة مع سياق شامل how to use dex dex setup guide dex terminal interface agent coordination with dex dex alternative dex vs jj dex install what is dex dex command invocation dex tickets dex终端接口 任务管理工具 AI工具 终端命令 npx @zeeg/dex 票务而非待办事项 结构化工作流程 Invokes commands directly via `dex` or `npx @zeeg/dex` Utilizes tickets with structured artifacts for comprehensive context Includes name, description, and result for each ticket Supports command invocation via bash with `command -v dex` Provides a core principle of tickets, not todos, for task management dex is a terminal interface for agent coordination, utilizing tickets with comprehensive context for efficient command invocation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lisposter/creator/baoyu-cover-image', 'community', 'lisposter', 'creator', 'lisposter/creator', 'baoyu-cover-image', 0, 0, 57, '2026-03-08T01:57:15.330Z', '2026-03-08T02:03:11.123Z', 'bf9efcba2325aa8c673b788be213b072c28e9c150042608a923d59484b2ed397', '{"id":"lisposter/creator/baoyu-cover-image","name":"baoyu-cover-image","description":{"en":"baoyu-cover-image generates cover images for articles with customizable dimensions, palettes, and rendering styles. It benefits developers and content creators looking for automated image generation.","zh":"baoyu-cover-image是一种生成优雅文章封面图像的工具，支持5维度自定义","ja":"baoyu-cover-imageは、エレガントな記事のカバー画像を生成するツールです","ko":"baoyu-cover-image는 커스텀 커버 이미지를 생성하는 도구입니다","es":"baoyu-cover-image es una herramienta de línea de comandos (CLI) que genera imágenes de portada personalizadas para artículos. Ofrece 5 dimensiones de personalización","fr":"baoyu-cover-image est un outil en ligne de commande (CLI) qui génère des images de couverture personnalisées pour les articles. Il propose 5 dimensions de personnalisation","de":"baoyu-cover-image ist ein Kommandozeilen-Tool (CLI), das personalisierte Titelbilder für Artikel generiert. Es bietet 5 Dimensionen der Anpassung","pt":"O baoyu-cover-image é uma ferramenta de linha de comando que gera imagens de capa personalizadas para artigos com 5 dimensões de personalização.","ru":"ИИ Агент baoyu-cover-image - это инструмент командной строки, который генерирует индивидуальные обложки для статей с 5-мерной настройкой.","ar":"أداة baoyu-cover-image هي أداة سطر أوامر تُنشئ صور غلاف مخصصة للمقالات مع 5 أبعاد من التخصيص."},"seo":{"title":{"en":"baoyu-cover-image: Customizable Cover Image Generation | ...","zh":"baoyu-cover-image 自定义封面图像生成工具","ja":"baoyu-cover-image: AIエージェントによるカスタムカバー画像生成","ko":"baoyu-cover-image: 커스텀 커버 이미지 생성 도구","es":"Generador de Imágenes de Portada baoyu-cover-image: Guía ...","fr":"Générateur d''Images de Couverture baoyu-cover-image: Meil...","de":"baoyu-cover-image Cover Bild-Generator: Einrichtungsanlei...","pt":"Guia de Configuração do baoyu-cover-image: Gere Imagens d...","ru":"ИИ Агент baoyu-cover-image: Руководство по Настройке для ...","ar":"دليل إعداد أداة baoyu-cover-image: إنشاء صور غلاف مخصصة"},"description":{"en":"Discover how to generate elegant cover images with 5-dimensional customization using baoyu-cover-image. Learn how to use the --quick, --type, and --style com...","zh":"使用baoyu-cover-image生成优雅的文章封面图像，支持5维度自定义","ja":"baoyu-cover-imageを使用して、エレガントな記事のカバー画像を生成する","ko":"baoyu-cover-image를 사용하여 커스텀 커버 이미지를 생성하세요","es":"Aprende a generar imágenes de portada elegantes para artículos con personalización 5D usando baoyu-cover-image. Descubre cómo configurarlo y utilizarlo","fr":"Découvrez comment générer des images de couverture élégantes pour les articles avec une personnalisation 5D à l''aide de baoyu-cover-image. Configurez-le et u...","de":"Erfahren Sie, wie Sie mit baoyu-cover-image elegante Titelbilder für Artikel mit 5D-Anpassung erstellen. Konfigurieren und verwenden Sie es jetzt","pt":"Aprenda a usar o baoyu-cover-image para criar imagens de capa elegantes com personalização 5D para artigos","ru":"Откройте для себя, как использовать ИИ Агент baoyu-cover-image для генерации элегантных обложек для статей","ar":"اكتشف كيفية استخدام أداة baoyu-cover-image لإنشاء صور غلاف أنيقة مع تخصيص 5 أبعاد للمقالات"},"definition":{"en":"baoyu-cover-image is a command-line tool that generates elegant cover images for articles with 5-dimensional customization options.","zh":"baoyu-cover-image是一种命令行工具，用于生成自定义的文章封面图像","ja":"baoyu-cover-imageは、カスタムの記事のカバー画像を生成するためのCLIツールです","ko":"baoyu-cover-image는 커스텀 커버 이미지를 생성하는 CLI 도구입니다","es":"baoyu-cover-image es un generador de imágenes de portada que utiliza la línea de comandos para crear imágenes personalizadas","fr":"baoyu-cover-image est un générateur d''images de couverture qui utilise la ligne de commande pour créer des images personnalisées","de":"baoyu-cover-image ist ein Titelbild-Generator, der die Kommandozeile verwendet, um personalisierte Bilder zu erstellen","pt":"O baoyu-cover-image é uma ferramenta de CLI para gerar imagens de capa personalizadas para artigos","ru":"ИИ Агент baoyu-cover-image - это инструмент командной строки для генерации индивидуальных обложек для статей","ar":"أداة baoyu-cover-image هي أداة سطر أوامر لإنشاء صور غلاف مخصصة للمقالات"},"features":{"en":["Auto-selects dimensions based on content using the /baoyu-cover-image command","Supports quick mode with the --quick flag for faster image generation","Allows specification of dimensions using the --type, --palette, and --rendering options","Includes style presets with shorthand commands, such as --style blueprint","Supports reference images for customized output"],"zh":["支持5维度自定义","自动选择尺寸","快速模式","指定尺寸","样式预设"],"ja":["5次元のカスタマイズをサポート","自動でサイズを選択","クイックモード","サイズを指定","スタイルのプリセット"],"ko":["5차원 커스텀 지원","자동 크기 선택","快速 모드","크기 지정","스타일 프리셋"],"es":["Personalización 5D para imágenes de portada","Compatibilidad con la línea de comandos (CLI) para una configuración flexible","Opción de modo rápido para omitir la confirmación","Selección automática de dimensiones según el contenido","Estilos preestablecidos para una personalización rápida"],"fr":["Personnalisation 5D pour les images de couverture","Compatibilité avec la ligne de commande (CLI) pour une configuration flexible","Option de mode rapide pour ignorer la confirmation","Sélection automatique des dimensions en fonction du contenu","Styles prédéfinis pour une personnalisation rapide"],"de":["5D-Anpassung für Titelbilder","Kompatibilität mit der Kommandozeile (CLI) für eine flexible Konfiguration","Schnellmodus-Option, um die Bestätigung zu überspringen","Automatische Dimensionenauswahl basierend auf dem Inhalt","Vordefinierte Stile für eine schnelle Anpassung"],"pt":["Geração de imagens de capa com 5 dimensões de personalização","Modo rápido para saltar confirmação","Especificação de dimensões personalizadas","Pré-ajustes de estilo para paleta e renderização","Compatibilidade com referências"],"ru":["Генерация обложек с 5-мерной настройкой","Быстрый режим для пропуска подтверждения","Настройка индивидуальных размеров","Предустановки стиля для палитры и рендеринга","Возможность использования ссылок"],"ar":["إنشاء صور غلاف مع 5 أبعاد من التخصيص","وضع سريع لتخطي التأكيد","تحديد أبعاد مخصصة","إعدادات نمط مسبقة للوحة الألوان والتحويل","دعم المراجع"]},"keywords":{"en":["how to use baoyu-cover-image","baoyu-cover-image alternative","baoyu-cover-image setup guide","customizable cover image generation","command-line image generation","article cover image automation"],"zh":["baoyu-cover-image","自定义封面图像","文章封面图像生成","CLI工具","命令行工具","图像生成"],"ja":["baoyu-cover-image","AIエージェント","カスタムカバー画像","記事のカバー画像生成","CLIツール","コマンドラインツール"],"ko":["baoyu-cover-image","커스텀 커버 이미지","커버 이미지 생성","CLI 도구","커맨드 라인 도구","이미지 생성"],"es":["generador de imágenes de portada","herramienta de línea de comandos","personalización 5D","modo rápido","selección automática de dimensiones","estilos preestablecidos","CLI para desarrolladores","imagen de portada para artículos","baoyu-cover-image"],"fr":["générateur d''images de couverture","outil en ligne de commande","personnalisation 5D","mode rapide","sélection automatique des dimensions","styles prédéfinis","CLI pour développeurs","image de couverture pour les articles","baoyu-cover-image"],"de":["Titelbild-Generator","Kommandozeilen-Tool","5D-Anpassung","Schnellmodus","automatische Dimensionenauswahl","vordefinierte Stile","CLI für Entwickler","Titelbild für Artikel","baoyu-cover-image"],"pt":["baoyu-cover-image","gerador de imagens de capa","ferramenta de CLI","personalização 5D","modo rápido","especificação de dimensões","pré-ajustes de estilo"],"ru":["ИИ Агент baoyu-cover-image","генератор обложек","инструмент командной строки","5-мерная настройка","быстрый режим","настройка размеров","предустановки стиля"],"ar":["أداة baoyu-cover-image","مُنشئ صور غلاف","أداة سطر أوامر","تخصيص 5 أبعاد","وضع سريع","تحديد أبعاد","إعدادات نمط مسبقة"]}},"owner":"lisposter","repo":"creator","repoPath":"lisposter/creator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.330Z","topics":[],"category":"community","skillMd":{"name":"baoyu-cover-image","description":"Generates article cover images with 5 dimensions (type, palette, rendering, text, mood) combining 9 color palettes and 6 rendering styles. Supports cinematic (2.35:1), widescreen (16:9), and square (1:1) aspects. Use when user asks to generate cover image, create article cover, or make cover.","bodyPreview":"# Cover Image Generator\n\nGenerate elegant cover images for articles with 5-dimensional customization.\n\n## Usage\n\n```bash\n# Auto-select dimensions based on content\n/baoyu-cover-image path/to/article.md\n\n# Quick mode: skip confirmation\n/baoyu-cover-image article.md --quick\n\n# Specify dimensions\n/baoyu-cover-image article.md --type conceptual --palette warm --rendering flat-vector\n\n# Style presets (shorthand for palette + rendering)\n/baoyu-cover-image article.md --style blueprint\n\n# With reference","body":"# Cover Image Generator\n\nGenerate elegant cover images for articles with 5-dimensional customization.\n\n## Usage\n\n```bash\n# Auto-select dimensions based on content\n/baoyu-cover-image path/to/article.md\n\n# Quick mode: skip confirmation\n/baoyu-cover-image article.md --quick\n\n# Specify dimensions\n/baoyu-cover-image article.md --type conceptual --palette warm --rendering flat-vector\n\n# Style presets (shorthand for palette + rendering)\n/baoyu-cover-image article.md --style blueprint\n\n# With reference images\n/baoyu-cover-image article.md --ref style-ref.png\n\n# Direct content input\n/baoyu-cover-image --palette mono --aspect 1:1 --quick\n[paste content]\n```\n\n## Options\n\n| Option | Description |\n|--------|-------------|\n| `--type <name>` | hero, conceptual, typography, metaphor, scene, minimal |\n| `--palette <name>` | warm, elegant, cool, dark, earth, vivid, pastel, mono, retro |\n| `--rendering <name>` | flat-vector, hand-drawn, painterly, digital, pixel, chalk |\n| `--style <name>` | Preset shorthand (see [Style Presets](references/style-presets.md)) |\n| `--text <level>` | none, title-only, title-subtitle, text-rich |\n| `--mood <level>` | subtle, balanced, bold |\n| `--font <name>` | clean, handwritten, serif, display |\n| `--aspect <ratio>` | 16:9 (default), 2.35:1, 4:3, 3:2, 1:1, 3:4 |\n| `--lang <code>` | Title language (en, zh, ja, etc.) |\n| `--no-title` | Alias for `--text none` |\n| `--quick` | Skip confirmation, use auto-selection |\n| `--ref <files...>` | Reference images for style/composition guidance |\n\n## Five Dimensions\n\n| Dimension | Values | Default |\n|-----------|--------|---------|\n| **Type** | hero, conceptual, typography, metaphor, scene, minimal | auto |\n| **Palette** | warm, elegant, cool, dark, earth, vivid, pastel, mono, retro | auto |\n| **Rendering** | flat-vector, hand-drawn, painterly, digital, pixel, chalk | auto |\n| **Text** | none, title-only, title-subtitle, text-rich | title-only |\n| **Mood** | subtle, balanced, bold | balanced |\n| **Font** | clean, handwritten, serif, display | clean |\n\nAuto-selection rules: [references/auto-selection.md](references/auto-selection.md)\n\n## Galleries\n\n**Types**: hero, conceptual, typography, metaphor, scene, minimal\n→ Details: [references/types.md](references/types.md)\n\n**Palettes**: warm, elegant, cool, dark, earth, vivid, pastel, mono, retro\n→ Details: [references/palettes/](references/palettes/)\n\n**Renderings**: flat-vector, hand-drawn, painterly, digital, pixel, chalk\n→ Details: [references/renderings/](references/renderings/)\n\n**Text Levels**: none (pure visual) | title-only (default) | title-subtitle | text-rich (with tags)\n→ Details: [references/dimensions/text.md](references/dimensions/text.md)\n\n**Mood Levels**: subtle (low contrast) | balanced (default) | bold (high contrast)\n→ Details: [references/dimensions/mood.md](references/dimensions/mood.md)\n\n**Fonts**: clean (sans-serif) | handwritten | serif | display (bold decorative)\n→ Details: [references/dimensions/font.md](references/dimensions/font.md)\n\n## File Structure\n\nOutput directory per `default_output_dir` preference:\n- `same-dir`: `{article-dir}/`\n- `imgs-subdir`: `{article-dir}/imgs/`\n- `independent` (default): `cover-image/{topic-slug}/`\n\n```\n<output-dir>/\n├── source-{slug}.{ext}    # Source files\n├── refs/                  # Reference images (if provided)\n│   ├── ref-01-{slug}.{ext}\n│   └── ref-01-{slug}.md   # Description file\n├── prompts/cover.md       # Generation prompt\n└── cover.png              # Output image\n```\n\n**Slug**: 2-4 words, kebab-case. Conflict: append `-YYYYMMDD-HHMMSS`\n\n## Workflow\n\n### Progress Checklist\n\n```\nCover Image Progress:\n- [ ] Step 0: Check preferences (EXTEND.md) ⛔ BLOCKING\n- [ ] Step 1: Analyze content + save refs + determine output dir\n- [ ] Step 2: Confirm options (6 dimensions) ⚠️ unless --quick\n- [ ] Step 3: Create prompt\n- [ ] Step 4: Generate image\n- [ ] Step 5: Completion report\n```\n\n### Flow\n\n```\nInput → [Step 0: Preferences] ─┬─ Found → Continue\n                               └─ Not found → First-Time Setup ⛔ BLOCKING → Save EXTEND.md → Continue\n        ↓\nAnalyze + Save Refs → [Output Dir] → [Confirm: 6 Dimensions] → Prompt → Generate → Complete\n                                              ↓\n                                     (skip if --quick or all specified)\n```\n\n### Step 0: Load Preferences ⛔ BLOCKING\n\nCheck EXTEND.md existence (priority: project → user):\n```bash\ntest -f .baoyu-skills/baoyu-cover-image/EXTEND.md && echo \"project\"\ntest -f \"$HOME/.baoyu-skills/baoyu-cover-image/EXTEND.md\" && echo \"user\"\n```\n\n| Result | Action |\n|--------|--------|\n| Found | Load, display summary → Continue |\n| Not found | ⛔ Run first-time setup ([references/config/first-time-setup.md](references/config/first-time-setup.md)) → Save → Continue |\n\n**CRITICAL**: If not found, complete setup BEFORE any other steps or questions.\n\n### Step 1: Analyze Content\n\n1. **Save reference images** (if provided) → [references/workflow/reference-images.md](references/workflow/reference-images.md)\n2. **Save source content** (if pasted, save to `source.md`)\n3. **Analyze content**: topic, tone, keywords, visual metaphors\n4. **Deep analyze references** ⚠️: Extract specific, concrete elements (see reference-images.md)\n5. **Detect language**: Compare source, user input, EXTEND.md preference\n6. **Determine output directory**: Per File Structure rules\n\n### Step 2: Confirm Options ⚠️\n\nFull confirmation flow: [references/workflow/confirm-options.md](references/workflow/confirm-options.md)\n\n| Condition | Skipped | Still Asked |\n|-----------|---------|-------------|\n| `--quick` or `quick_mode: true` | 6 dimensions | Aspect ratio (unless `--aspect`) |\n| All 6 + `--aspect` specified | All | None |\n\n### Step 3: Create Prompt\n\nSave to `prompts/cover.md`. Template: [references/workflow/prompt-template.md](references/workflow/prompt-template.md)\n\n**CRITICAL - References in Frontmatter**:\n- Files saved to `refs/` → Add to frontmatter `references` list\n- Style extracted verbally (no file) → Omit `references`, describe in body\n- Before writing → Verify: `test -f refs/ref-NN-{slug}.{ext}`\n\n**Reference elements in body** MUST be detailed, prefixed with \"MUST\"/\"REQUIRED\", with integration approach.\n\n### Step 4: Generate Image\n\n1. **Backup existing** `cover.png` if regenerating\n2. **Check image generation skills**; if multiple, ask preference\n3. **Process references** from prompt frontmatter:\n   - `direct` usage → pass via `--ref` (use ref-capable backend)\n   - `style`/`palette` → extract traits, append to prompt\n4. **Generate**: Call skill with prompt file, output path, aspect ratio\n5. On failure: auto-retry once\n\n### Step 5: Completion Report\n\n```\nCover Generated!\n\nTopic: [topic]\nType: [type] | Palette: [palette] | Rendering: [rendering]\nText: [text] | Mood: [mood] | Font: [font] | Aspect: [ratio]\nTitle: [title or \"visual only\"]\nLanguage: [lang] | Watermark: [enabled/disabled]\nReferences: [N images or \"extracted style\" or \"none\"]\nLocation: [directory path]\n\nFiles:\n✓ source-{slug}.{ext}\n✓ prompts/cover.md\n✓ cover.png\n```\n\n## Image Modification\n\n| Action | Steps |\n|--------|-------|\n| **Regenerate** | Backup → Update prompt file FIRST → Regenerate |\n| **Change dimension** | Backup → Confirm new value → Update prompt → Regenerate |\n\n## Composition Principles\n\n- **Whitespace**: 40-60% breathing room\n- **Visual anchor**: Main element centered or offset left\n- **Characters**: Simplified silhouettes; NO realistic humans\n- **Title**: Use exact title from user/source; never invent\n\n## Extension Support\n\nCustom configurations via EXTEND.md. See **Step 0** for paths.\n\nSupports: Watermark | Preferred dimensions | Default aspect/output | Quick mode | Custom palettes | Language\n\nSchema: [references/config/preferences-schema.md](references/config/preferences-schema.md)\n\n## References\n\n**Dimensions**: [text.md](references/dimensions/text.md) | [mood.md](references/dimensions/mood.md) | [font.md](references/dimensions/font.md)\n**Palettes**: [references/palettes/](references/palettes/)\n**Renderings**: [references/renderings/](references/renderings/)\n**Types**: [references/types.md](references/types.md)\n**Auto-Selection**: [references/auto-selection.md](references/auto-selection.md)\n**Style Presets**: [references/style-presets.md](references/style-presets.md)\n**Compatibility**: [references/compatibility.md](references/compatibility.md)\n**Visual Elements**: [references/visual-elements.md](references/visual-elements.md)\n**Workflow**: [confirm-options.md](references/workflow/confirm-options.md) | [prompt-template.md](references/workflow/prompt-template.md) | [reference-images.md](references/workflow/reference-images.md)\n**Config**: [preferences-schema.md](references/config/preferences-schema.md) | [first-time-setup.md](references/config/first-time-setup.md) | [watermark-guide.md](references/config/watermark-guide.md)\n"},"lastSynced":"2026-03-08T02:03:11.123Z","agentAnalysis":{"suitability":{"en":"Perfect for Content Creation Agents needing automated cover image generation with customizable dimensions and styles.","zh":"适合需要自动化生成带有可定制尺寸和样式的封面图片的内容创作代理。","ja":"カスタマイズ可能な寸法とスタイルを持つ自動化されたカバー画像生成が必要なコンテンツ作成エージェントに最適です。","ko":"자동화된 커버 이미지 생성에 맞춤형 크기와 스타일이 필요한 콘텐츠 제작 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Creación de Contenido que necesitan generación automática de imágenes de portada con dimensiones y estilos personalizables.","fr":"Parfait pour les Agents de Création de Contenu ayant besoin de génération automatisée d''images de couverture avec des dimensions et des styles personnalisables.","de":"Perfekt für Inhalts-Erstellungsagenten, die eine automatisierte Erstellung von Coverbildern mit anpassbaren Dimensionen und Stilen benötigen.","pt":"Perfeito para Agentes de Criação de Conteúdo que precisam de geração automática de imagem de capa com dimensões e estilos personalizáveis.","ru":"Идеально подходит для агентов по созданию контента, которым необходима автоматизированная генерация изображений обложек с настраиваемыми размерами и стилями.","ar":"مثالي لوكلاء إنشاء المحتوى الذين يحتاجون إلى генера генерация آليّة لصورة الغلاف مع أبعاد وأساليب قابلة للتخصيص."},"recommendation":{"en":"Empowers agents to generate elegant cover images for articles using customizable dimensions, palettes, and rendering styles, including support for conceptual, warm, and flat-vector styles, as well as style presets like blueprint, all while handling file formats like .md.","zh":"赋予代理生成文章的优雅封面图片的能力，具有可定制的尺寸、调色板和渲染样式，包括概念、暖色和扁平矢量样式，以及像蓝图这样的样式预设，同时处理像 .md 这样的文件格式。","ja":"エージェントに、寸法、パレット、レンダリングスタイルをカスタマイズできる記事のエレガントなカバー画像を生成する能力を提供します。コンセプト、ウォーム、フラットベクタスタイルなど、またブループリントなどのスタイルプリセットにも対応し、.md などのファイル形式にも対応しています。","ko":"에이전트에게 맞춤형 크기, 팔레트, 렌더링 스타일을 갖춘 기사의 우아한 커버 이미지를 생성하는 능력을 부여합니다. 개념, 따뜻한 색상, 평면 벡터 스타일을 포함하여 블루프린트와 같은 스타일 프리셋도 지원하며, .md와 같은 파일 형식도 처리합니다.","es":"Habilita a los agentes a generar elegantes imágenes de portada para artículos utilizando dimensiones, paletas y estilos de representación personalizables, incluyendo soporte para estilos conceptuales, cálidos y de vector plano, así como preajustes de estilo como plano, y manejo de formatos de archivo como .md.","fr":"Permet aux agents de générer des images de couverture élégantes pour les articles en utilisant des dimensions, des palettes et des styles de rendu personnalisables, y compris la prise en charge des styles conceptuels, chauds et de vecteur plat, ainsi que des présélections de style comme blueprint, tout en gérant les formats de fichier tels que .md.","de":"Ermächtigt Agenten, elegante Coverbilder für Artikel zu erstellen, die anpassbare Dimensionen, Farbpaletten und Darstellungsstile verwenden, einschließlich Unterstützung für konzeptionelle, warme und flache Vektorstile sowie Stilvorgaben wie Blueprint, und zwar unter Berücksichtigung von Dateiformaten wie .md.","pt":"Habilita os agentes a gerar imagens de capa elegantes para artigos usando dimensões, paletas e estilos de renderização personalizáveis, incluindo suporte a estilos conceituais, quentes e vetoriais planos, bem como predefinições de estilo como blueprint, além de lidar com formatos de arquivo como .md.","ru":"Наделяет агентов возможностью генерировать элегантные изображения обложек для статей, используя настраиваемые размеры, палитры и стили рендеринга, включая поддержку концептуальных, тёплых и плоских векторных стилей, а также пресеты стилей, такие как чертёж, при этом обрабатывая форматы файлов, такие как .md.","ar":"يمنح الوكلاء القدرة على генера生成 صور غلاف أنيقة للمقالات باستخدام أبعاد وقوامز وأساليب ت渲ير قابلة للتخصيص، بما في ذلك الدعم لأساليب مفاهيمية ودافئة ومتجهة مسطحة، بالإضافة إلى مسودات نمط مثل الخطة، مع معالجة تنسيقات الملفات مثل .md."},"useCases":{"en":["Automating cover image generation for blog posts","Generating article thumbnails with specific dimensions and palettes","Customizing rendering styles for e-book covers"],"zh":["自动化博客文章的封面图片生成","生成具有特定尺寸和调色板的文章缩略图","自定义电子书封面的渲染样式"],"ja":["ブログ投稿のカバー画像生成の自動化","特定の寸法とパレットを持つ記事のサムネイル画像を生成","電子書籍のカバー画像のレンダリングスタイルをカスタマイズ"],"ko":["블로그 포스트의 커버 이미지 생성 자동화","특정 크기와 팔레트를 갖춘 기사 썸네일 생성","전자책 커버의 렌더링 스타일 맞춤화"],"es":["Automatización de la generación de imágenes de portada para publicaciones de blog","Generación de miniaturas de artículos con dimensiones y paletas específicas","Personalización de estilos de representación para portadas de libros electrónicos"],"fr":["Automatisation de la génération d''images de couverture pour les publications de blog","Génération de miniatures d''articles avec des dimensions et des palettes spécifiques","Personnalisation des styles de rendu pour les couvertures de livres électroniques"],"de":["Automatisierung der Erstellung von Coverbildern für Blog-Beiträge","Erstellung von Artikelvektorgrafiken mit spezifischen Dimensionen und Farbpaletten","Anpassung der Darstellungsstile für E-Book-Cover"],"pt":["Automatizar a geração de imagem de capa para posts de blog","Gerar miniaturas de artigos com dimensões e paletas específicas","Personalizar estilos de renderização para capas de e-book"],"ru":["Автоматизировать генерацию изображений обложек для постов в блоге","Генерировать миниатюры статей с конкретными размерами и палитрами","Настроить стили рендеринга для обложек электронных книг"],"ar":["توفير آلي لتصوير الغلاف للمشاركات في المدونة","توليد مصغرات للمقالات بأبعاد وقوامز محددة","تخصيص أساليب العرض للغلاف الكتاب الإلكتروني"]},"limitations":{"en":["Requires article content in .md format","Limited to generating cover images for articles"],"zh":["需要文章内容以 .md 格式提供","仅限生成文章的封面图片"],"ja":["記事の内容が .md 形式で提供される必要がある","記事のカバー画像の生成のみに限定される"],"ko":["기사 내용이 .md 형식으로 제공되어야 함","기사 커버 이미지 생성에만 제한됨"],"es":["Requiere contenido de artículo en formato .md","Limitado a la generación de imágenes de portada para artículos"],"fr":["Nécessite un contenu d''article au format .md","Limité à la génération d''images de couverture pour les articles"],"de":["Benötigt Artikelinhalt im .md-Format","Begrenzt auf die Erstellung von Coverbildern für Artikel"],"pt":["Exige conteúdo de artigo no formato .md","Limitado a gerar imagens de capa para artigos"],"ru":["Требует содержания статьи в формате .md","Ограничен генерацией изображений обложек для статей"],"ar":["يتطلب محتوى المقال بالتنسيق .md","محدود بالغلاف لتوليد صور الغلاف للمقالات"]},"version":4},"contentHash":"bf9efcba2325aa8c673b788be213b072c28e9c150042608a923d59484b2ed397","qualityScore":57}');
