INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lisposter/creator/baoyu-cover-image', 'baoyu-cover-image', 'lisposter', 'creator', 'community', 'baoyu-cover-image lisposter creator community baoyu-cover-image generates cover images for articles with customizable dimensions, palettes, and rendering styles. It benefits developers and content creators looking for automated image generation. baoyu-cover-image是一种生成优雅文章封面图像的工具，支持5维度自定义 baoyu-cover-imageは、エレガントな記事のカバー画像を生成するツールです baoyu-cover-image는 커스텀 커버 이미지를 생성하는 도구입니다 baoyu-cover-image es una herramienta de línea de comandos (CLI) que genera imágenes de portada personalizadas para artículos. Ofrece 5 dimensiones de personalización baoyu-cover-image est un outil en ligne de commande (CLI) qui génère des images de couverture personnalisées pour les articles. Il propose 5 dimensions de personnalisation baoyu-cover-image ist ein Kommandozeilen-Tool (CLI), das personalisierte Titelbilder für Artikel generiert. Es bietet 5 Dimensionen der Anpassung O baoyu-cover-image é uma ferramenta de linha de comando que gera imagens de capa personalizadas para artigos com 5 dimensões de personalização. ИИ Агент baoyu-cover-image - это инструмент командной строки, который генерирует индивидуальные обложки для статей с 5-мерной настройкой. أداة baoyu-cover-image هي أداة سطر أوامر تُنشئ صور غلاف مخصصة للمقالات مع 5 أبعاد من التخصيص. how to use baoyu-cover-image baoyu-cover-image alternative baoyu-cover-image setup guide customizable cover image generation command-line image generation article cover image automation baoyu-cover-image 自定义封面图像 文章封面图像生成 CLI工具 命令行工具 图像生成 Auto-selects dimensions based on content using the /baoyu-cover-image command Supports quick mode with the --quick flag for faster image generation Allows specification of dimensions using the --type, --palette, and --rendering options Includes style presets with shorthand commands, such as --style blueprint Supports reference images for customized output baoyu-cover-image is a command-line tool that generates elegant cover images for articles with 5-dimensional customization options.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('boomNDS/new_portfolio/content-research-writer', 'community', 'boomNDS', 'new_portfolio', 'boomNDS/new_portfolio', 'content-research-writer', 0, 0, 57, '2026-03-08T01:57:15.331Z', '2026-03-08T02:03:13.029Z', '1e2e8681cf7ba31550ac69151ec3fcb427559bcd3a92dc5e3b7070b7f4e076d3', '{"id":"boomNDS/new_portfolio/content-research-writer","name":"content-research-writer","description":{"en":"Content-Research-Writer assists developers in creating high-quality content, including blog posts, articles, and technical documentation, while maintaining a unique voice and style.","zh":"内容研究写作工具是开发人员的写作伙伴，帮助研究、提纲、草稿和改进内容","ja":"コンテンツ研究ライターは、開発者のためのライティングパートナーとして、研究、構成、草稿、改良をサポートする","ko":"콘텐츠 연구 작가는 개발자의ための 라이팅 파트너로서 연구، 아웃라인, 초안 및 리파인먼트를 지원","es":"El content-research-writer es una herramienta de escritura técnica que ayuda a los desarrolladores a crear contenido de alta calidad con investigación y citación","fr":"Le content-research-writer est un outil d''écriture technique qui aide les développeurs à créer du contenu de haute qualité avec recherche et citation","de":"Der content-research-writer ist ein Werkzeug für technisches Schreiben, das Entwicklern hilft, hochwertigen Inhalt mit Forschung und Zitierung zu erstellen","pt":"O Content Research Writer é uma ferramenta de criação de conteúdo que ajuda a pesquisar, esboçar e refinar textos, mantendo o estilo único do autor","ru":"ИИ Агент Content Research Writer - это инструмент создания контента, помогающий исследовать, очерчивать и совершенствовать тексты, сохраняя уникальный стиль автора","ar":"كتّاب البحث المحتوى هو أداة لإنشاء المحتوى تساعد في البحث والتحديث والتعديل النصوص، مع الحفاظ على الأسلوب الفريد للمؤلف"},"seo":{"title":{"en":"Content-Research-Writer: AI-Powered Writing Assistant for...","zh":"内容研究写作工具 Setup Guide","ja":"コンテンツ研究ライター AIエージェントのベストプラクティス","ko":"콘텐츠 연구