INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('boomNDS/new_portfolio/content-research-writer', 'content-research-writer', 'boomNDS', 'new_portfolio', 'community', 'content-research-writer boomNDS new_portfolio community Content-Research-Writer assists developers in creating high-quality content, including blog posts, articles, and technical documentation, while maintaining a unique voice and style. 内容研究写作工具是开发人员的写作伙伴，帮助研究、提纲、草稿和改进内容 コンテンツ研究ライターは、開発者のためのライティングパートナーとして、研究、構成、草稿、改良をサポートする 콘텐츠 연구 작가는 개발자의ための 라이팅 파트너로서 연구، 아웃라인, 초안 및 리파인먼트를 지원 El content-research-writer es una herramienta de escritura técnica que ayuda a los desarrolladores a crear contenido de alta calidad con investigación y citación Le content-research-writer est un outil d''écriture technique qui aide les développeurs à créer du contenu de haute qualité avec recherche et citation Der content-research-writer ist ein Werkzeug für technisches Schreiben, das Entwicklern hilft, hochwertigen Inhalt mit Forschung und Zitierung zu erstellen O Content Research Writer é uma ferramenta de criação de conteúdo que ajuda a pesquisar, esboçar e refinar textos, mantendo o estilo único do autor ИИ Агент Content Research Writer - это инструмент создания контента, помогающий исследовать, очерчивать и совершенствовать тексты, сохраняя уникальный стиль автора كتّاب البحث المحتوى هو أداة لإنشاء المحتوى تساعد في البحث والتحديث والتعديل النصوص، مع الحفاظ على الأسلوب الفريد للمؤلف how to use content-research-writer content-research-writer alternative content-research-writer setup guide what is content-research-writer content-research-writer vs writing assistants install content-research-writer content-research-writer for technical documentation content-research-writer for blog posts content-research-writer tutorial 内容研究写作工具 AI工具 写作伙伴 技术文档 案例研究 引用支持 自动提纲 开发者工具 Researches and writes case studies with accurate citations Drafts thought leadership pieces with a unique voice and style Produces technical documentation with sources and references Improves hooks and introductions for engaging content Writes blog posts, articles, and newsletters with AI assistance Content-Research-Writer is a skill that aids in content creation by researching, outlining, drafting, and refining content with proper citations and references.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ankitsharma495/Flowbase/rbac-authorization-patterns', 'community', 'ankitsharma495', 'Flowbase', 'ankitsharma495/Flowbase', 'rbac-authorization-patterns', 0, 0, 57, '2026-03-08T01:57:15.331Z', '2026-03-08T02:03:13.227Z', '602ccdd23f8b2f66d2eae3fd8fb2fbc1fd44f3956305146c656a9064af76bc99', '{"id":"ankitsharma495/Flowbase/rbac-authorization-patterns","name":"rbac-authorization-patterns","description":{"en":"The rbac-authorization-patterns skill provides expert guidance for implementing Role-Based Access Control (RBAC) and multi-tenant authorization in a Go/Echo backend with Supabase/PostgreSQL, benefiting developers of freight brokerage operations.","zh":"本指南介绍如何在 Go/Echo 后端和 Supabase/PostgreSQL 中实现 RBAC 授权模式和多租户授权","ja":"このガイドでは、Go/Echo バックエンドと Supabase/PostgreSQL で RBAC 認可パターンとマルチテナント認可を実装する方法について説明します","ko":"이 가이드는 Go/Echo 백엔드와 Supabase/PostgreSQL에서 RBAC 권한 패턴과 멀티 테넌트 인증을 구현하는 방법을 설명합니다","es":"Implemente patrones de autorización RBAC para laneweaverTMS con Go/Echo y Supabase/PostgreSQL","fr":"Mettez en œuvre des modèles d''autorisation RBAC pour laneweaverTMS avec Go/Echo et Supabase/PostgreSQL","de":"Implementieren Sie RBAC-Autorisierungsmuster für laneweaverTMS mit Go/Echo und Supabase/PostgreSQL","pt":"Implemente padrões de autorização RBAC com Go/Echo e Supabase para controlar o acesso de usuários em operações de freight brokerage","ru":"Реализуйте шаблоны авторизации RBAC с помощью Go/Echo и Supabase для управления доступом пользователей в операциях по грузоперевозкам","ar":"نفذ أنماط الترخيص RBAC باستخدام Go/Echo و Supabase للتحكم في الوصول للمستخدمين في عمليات السوق البرية"},"seo":{"title":{"en":"rbac-authorization-patterns: Setup Guide for Go/Echo Back...","zh":"RBAC 授权模式设置指南 - laneweaverTMS 后端安全","ja":"RBAC 認可パターン設定ガイド - laneweaverTMS バックエンドセキュリティ","ko":"RBAC 권한 패턴 설정 가이드 - laneweaverTMS 백엔드 보안","es":"Patrones de autorización RBAC: Guía de configuración para...","fr":"Modèles d''autorisation RBAC: Guide de mise en œuvre pour ...","de":"RBAC-Autorisierungsmuster: Einrichtungsanleitung für lane...","pt":"Padrões de Autorização RBAC: Guia de Configuração com Go/...","ru":"Установка шаблонов авторизации RBAC с помощью Go/Echo и S...","ar":"نماذج ترخيص RBAC: دليل الإعداد مع Go/Echo و Supabase للوك..."},"description":{"en":"Unlock secure authorization with rbac-authorization-patterns. Learn how to implement Role-Based Access Control and multi-tenant isolation with Supabase/Postg...","zh":"了解如何使用 RBAC 授权模式和多租户授权在 Go/Echo 后端和 Supabase/PostgreSQL 中实现安全访问控制","ja":"Go/Echo バックエンドと Supabase/PostgreSQL で RBAC 認可パターンとマルチテナント認可を使用してセキュアなアクセス制御を実現する方法について学びます","ko":"Go/Echo 백엔드와 Supabase/PostgreSQL에서 RBAC 권한 패턴과 멀티 테넌트 인증을 사용하여 보안 액세스 제어를 구현하는 방법에 대해 알아보세요","es":"Aprenda a implementar el control de acceso basado en roles (RBAC) y la autorización multi-tenant en Go/Echo con Supabase/PostgreSQL","fr":"Découvrez comment mettre en œuvre le contrôle d''accès basé sur les rôles (RBAC) et l''autorisation multi-locataire dans Go/Echo avec Supabase/PostgreSQL","de":"Erfahren Sie, wie Sie die rollenbasierte Zugriffskontrolle (RBAC) und die Multi-Tenant-Autorisierung in Go/Echo mit Supabase/PostgreSQL implementieren","pt":"Aprenda a implementar padrões de autorização RBAC com Go/Echo e Supabase para controlar o acesso de usuários em operações de freight brokerage","ru":"Изучите, как реализовать шаблоны авторизации RBAC с помощью Go/Echo и Supabase для управления доступом пользователей в операциях по грузоперевозкам для ИИ Аг...","ar":"تعرف على كيفية تنفيذ أنماط الترخيص RBAC باستخدام Go/Echo و Supabase للتحكم في الوصول للمستخدمين في عمليات السوق البرية للوكلاء الذكاء الاصطناعي"},"definition":{"en":"rbac-authorization-patterns is a technical skill for implementing Role-Based Access Control (RBAC) and multi-tenant authorization in Go/Echo backend applications.","zh":"RBAC 授权模式是一种基于角色的访问控制机制，用于实现安全的用户权限管理","ja":"RBAC 認可パターンは、セキュアなユーザー権限管理を実現するための役割ベースのアクセス制御メカニズムです","ko":"RBAC 권한 패턴은 보안 사용자 권한 관리를 구현하기 위한 역할 기반의 액세스 제어 메커니즘입니다","es":"Patrones de autorización RBAC para controlar el acceso a recursos y datos en aplicaciones","fr":"Modèles d''autorisation RBAC pour contrôler l''accès aux ressources et aux données dans les applications","de":"RBAC-Autorisierungsmuster zur Kontrolle des Zugriffs auf Ressourcen und Daten in Anwendungen","pt":"Padrões de autorização RBAC são um conjunto de regras para controlar o acesso de usuários em sistemas de informação","ru":"Шаблоны авторизации RBAC - это набор правил для управления доступом пользователей в информационных системах для ИИ Агентов","ar":"نماذج الترخيص RBAC هي مجموعة من القواعد للتحكم في الوصول للمستخدمين في أنظمة المعلومات للوكلاء الذكاء الاصطناعي"},"features":{"en":["Implements Echo middleware for role/permission checks","Sets up multi-tenant isolation with account-based access using Supabase/PostgreSQL","Designs JWT claims structure for authorization","Writes RLS policies for secure data access","Defines user roles and permissions for freight brokerage operations"],"zh":["实现用户角色和权限定义","使用 Echo 中间件进行角色和权限检查","设置多租户隔离和账户基于访问控制","设计 JWT 声明结构用于授权","编写 RLS 政策用于授权"],"ja":["ユーザー役割と権限の定義を実装","Echo ミドルウェアを使用した役割と権限のチェック","マルチテナントの分離とアカウントベースのアクセス制御の設定","認可のために JWT クレーム構造を設計","認可のために RLS ポリシーを記述"],"ko":["사용자 역할과 권한 정의 구현","Echo 미들웨어를 사용한 역할과 권한 확인","멀티 테넌트 분리 및 계정 기반 액세스 제어 설정","인증을 위한 JWT 클레임 구조 설계","인증을 위한 RLS 정책 작성"],"es":["Definición de roles y permisos de usuario para operaciones de corretaje de carga","Implementación de middleware Echo para comprobaciones de roles y permisos","Configuración de aislamiento multi-tenant con acceso basado en cuentas","Diseño de estructuras de reclamaciones JWT para autorización","Escritura de políticas RLS para autorización"],"fr":["Définition des rôles et des autorisations des utilisateurs pour les opérations de courtage de fret","Mise en œuvre de middleware Echo pour les vérifications de rôles et d''autorisations","Configuration de l''isolement multi-locataire avec un accès basé sur les comptes","Conception de structures de revendications JWT pour l''autorisation","Écriture de politiques RLS pour l''autorisation"],"de":["Definition von Benutzerrollen und -berechtigungen für Frachtvermittlungsoperationen","Implementierung von Echo-Middleware für Rollen- und Berechtigungsprüfungen","Einrichtung von Multi-Tenant-Isolation mit kontobasiertem Zugriff","Entwurf von JWT-Anspruchstrukturen für Autorisierung","Schreiben von RLS-Richtlinien für Autorisierung"],"pt":["Implementação de middleware Echo para verificação de papéis e permissões","Configuração de isolamento multi-tenant com acesso baseado em contas","Definição de estrutura de reivindicações JWT para autorização","Criação de políticas RLS para controle de acesso","Integração com Supabase/PostgreSQL para armazenamento de dados"],"ru":["Реализация middleware Echo для проверки ролей и разрешений","Настройка многоарендного изоляции с доступом на основе учетных записей","Определение структуры утверждений JWT для авторизации","Создание политик RLS для управления доступом","Интеграция с Supabase/PostgreSQL для хранения данных для ИИ Агентов"],"ar":["تنفيذ middleware Echo للتحقق من الأدوار والصلاحيات","تكوين العزل متعدد المستأجرين بالوصول المستند إلى الحساب","تحديد هيكل المطالبات JWT للترخيص","إنشاء سياسات RLS للتحكم في الوصول","التكامل مع Supabase/PostgreSQL لتخزين البيانات للوكلاء الذكاء الاصطناعي"]},"keywords":{"en":["how to use rbac-authorization-patterns","rbac-authorization-patterns setup guide","Role-Based Access Control with Go/Echo","multi-tenant authorization with Supabase/PostgreSQL","rbac-authorization-patterns vs traditional authorization","implementing rbac-authorization-patterns in freight brokerage operations"],"zh":["RBAC 授权模式","Go/Echo 后端","Supabase/PostgreSQL","多租户授权","用户角色管理","访问控制","JWT 声明结构","RLS 政策"],"ja":["RBAC 認可パターン","Go/Echo バックエンド","Supabase/PostgreSQL","マルチテナント認可","ユーザー役割管理","アクセス制御","JWT クレーム構造","RLS ポリシー"],"ko":["RBAC 권한 패턴","Go/Echo 백엔드","Supabase/PostgreSQL","멀티 테넌트 인증","사용자 역할 관리","액세스 제어","JWT 클레임 구조","RLS 정책"],"es":["patrones de autorización RBAC","control de acceso basado en roles","autorización multi-tenant","Go/Echo","Supabase/PostgreSQL","laneweaverTMS","implementación de RBAC","diseño de autorización"],"fr":["modèles d''autorisation RBAC","contrôle d''accès basé sur les rôles","autorisation multi-locataire","Go/Echo","Supabase/PostgreSQL","laneweaverTMS","mise en œuvre de RBAC","conception d''autorisation"],"de":["RBAC-Autorisierungsmuster","rollenbasierte Zugriffskontrolle","Multi-Tenant-Autorisierung","Go/Echo","Supabase/PostgreSQL","laneweaverTMS","Implementierung von RBAC","Autorisierungsdesign"],"pt":["rbac authorization patterns","go/echo","supabase/postgresql","freight brokerage","multi-tenant isolation","jwt claims structure","rls policies","role-based access control"],"ru":["шаблоны авторизации rbac","go/echo","supabase/postgresql","грузоперевозки","многоарендное изоляция","структура утверждений jwt","политики rls","контроль доступа на основе ролей для ИИ Агентов"],"ar":["نماذج ترخيص rbac","go/echo","supabase/postgresql","السوق البرية","عزل متعدد المستأجرين","هيكل المطالبات jwt","سياسات rls","التحكم في الوصول المستند إلى الأدوار للوكلاء الذكاء الاصطناعي"]}},"owner":"ankitsharma495","repo":"Flowbase","repoPath":"ankitsharma495/Flowbase","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.331Z","topics":[],"category":"community","skillMd":{"name":"rbac-authorization-patterns","description":"Provide patterns for implementing Role-Based Access Control and multi-tenant authorization in laneweaverTMS. Use when implementing user roles, permissions, tenant isolation, Echo authorization middleware, RLS policies for multi-tenant access, or JWT claims structure for freight brokerage applications.","bodyPreview":"# RBAC Authorization Patterns for laneweaverTMS\n\nExpert guidance for implementing Role-Based Access Control (RBAC) and multi-tenant authorization in a Go/Echo backend with Supabase/PostgreSQL.\n\n## When to Use This Skill\n\nUse when:\n- Defining user roles and permissions for freight brokerage operations\n- Implementing Echo middleware for role/permission checks\n- Setting up multi-tenant isolation with account-based access\n- Designing JWT claims structure for authorization\n- Writing RLS policies for","body":"# RBAC Authorization Patterns for laneweaverTMS\n\nExpert guidance for implementing Role-Based Access Control (RBAC) and multi-tenant authorization in a Go/Echo backend with Supabase/PostgreSQL.\n\n## When to Use This Skill\n\nUse when:\n- Defining user roles and permissions for freight brokerage operations\n- Implementing Echo middleware for role/permission checks\n- Setting up multi-tenant isolation with account-based access\n- Designing JWT claims structure for authorization\n- Writing RLS policies for tenant-isolated data access\n- Choosing appropriate HTTP status codes for authorization failures\n\n## Freight Brokerage Role Definitions\n\n### Standard Roles\n\n| Role | Description | Typical Access |\n|------|-------------|----------------|\n| `admin` | Full system access | All resources, user management, system config |\n| `dispatcher` | Load management, carrier selection | Loads, carriers, tracking, dispatch operations |\n| `sales` | Account management, quotes | Customers, quotes, lanes, tenders |\n| `finance` | Invoicing, payments, reports | Invoices, carrier bills, payments, financial reports |\n| `driver` | Limited mobile access | Assigned loads only, status updates, document upload |\n| `readonly` | View-only access | Read all operational data, no modifications |\n\n### Permission Model\n\nPermissions follow a `resource:action` pattern:\n\n```\nloads:read, loads:create, loads:update, loads:delete\ncarriers:read, carriers:create, carriers:update\ncustomers:read, customers:create, customers:update\ninvoices:read, invoices:create, invoices:approve\nreports:financial, reports:operational\nusers:manage\n```\n\n## Database Schema Patterns\n\n### Core RBAC Tables\n\n```sql\n-- Roles table\nCREATE TABLE public.roles (\n    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n    name TEXT NOT NULL UNIQUE,\n    description TEXT,\n    is_system_role BOOLEAN DEFAULT false,\n    created_at TIMESTAMPTZ DEFAULT now() NOT NULL,\n    updated_at TIMESTAMPTZ DEFAULT now() NOT NULL\n);\n\n-- Permissions table\nCREATE TABLE public.permissions (\n    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n    resource TEXT NOT NULL,\n    action TEXT NOT NULL,\n    description TEXT,\n    created_at TIMESTAMPTZ DEFAULT now() NOT NULL,\n    UNIQUE(resource, action)\n);\n\n-- Role-Permission junction\nCREATE TABLE public.role_permissions (\n    role_id UUID NOT NULL REFERENCES public.roles(id) ON DELETE CASCADE,\n    permission_id UUID NOT NULL REFERENCES public.permissions(id) ON DELETE CASCADE,\n    created_at TIMESTAMPTZ DEFAULT now() NOT NULL,\n    PRIMARY KEY (role_id, permission_id)\n);\n\n-- User-Role junction (within account/tenant context)\nCREATE TABLE public.user_roles (\n    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n    role_id UUID NOT NULL REFERENCES public.roles(id) ON DELETE CASCADE,\n    account_id UUID NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,\n    created_at TIMESTAMPTZ DEFAULT now() NOT NULL,\n    created_by UUID REFERENCES auth.users(id),\n    PRIMARY KEY (user_id, role_id, account_id)\n);\n\n-- Account-User junction for multi-tenant\nCREATE TABLE public.account_users (\n    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,\n    account_id UUID NOT NULL REFERENCES public.accounts(id) ON DELETE CASCADE,\n    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n    is_primary BOOLEAN DEFAULT false,\n    invited_at TIMESTAMPTZ DEFAULT now() NOT NULL,\n    accepted_at TIMESTAMPTZ,\n    created_at TIMESTAMPTZ DEFAULT now() NOT NULL,\n    UNIQUE(account_id, user_id)\n);\n\n-- Indexes for RLS policy performance\nCREATE INDEX idx_user_roles_user_id ON public.user_roles(user_id);\nCREATE INDEX idx_user_roles_account_id ON public.user_roles(account_id);\nCREATE INDEX idx_account_users_user_id ON public.account_users(user_id);\nCREATE INDEX idx_account_users_account_id ON public.account_users(account_id);\n```\n\n### Seed Default Roles\n\n```sql\nINSERT INTO public.roles (name, description, is_system_role) VALUES\n    (''admin'', ''Full system access'', true),\n    (''dispatcher'', ''Load management and carrier selection'', true),\n    (''sales'', ''Account management and quotes'', true),\n    (''finance'', ''Invoicing, payments, and reports'', true),\n    (''driver'', ''Limited mobile access for assigned loads'', true),\n    (''readonly'', ''View-only access to operational data'', true);\n```\n\n## Echo Authorization Middleware\n\n### Context Keys\n\n```go\npackage middleware\n\ntype contextKey string\n\nconst (\n    ContextKeyUserID    contextKey = \"user_id\"\n    ContextKeyAccountID contextKey = \"account_id\"\n    ContextKeyRoles     contextKey = \"roles\"\n    ContextKeyUser      contextKey = \"user\"\n)\n```\n\n### JWT Claims Structure\n\n```go\npackage auth\n\nimport \"github.com/golang-jwt/jwt/v5\"\n\ntype Claims struct {\n    jwt.RegisteredClaims\n    UserID      string   `json:\"user_id\"`\n    Email       string   `json:\"email\"`\n    AccountID   string   `json:\"account_id\"`\n    Roles       []string `json:\"roles\"`\n    Permissions []string `json:\"permissions,omitempty\"` // Optional: can derive from roles\n}\n```\n\n### Authentication Middleware\n\nValidates JWT and extracts claims into context:\n\n```go\npackage middleware\n\nimport (\n    \"net/http\"\n    \"strings\"\n\n    \"github.com/labstack/echo/v4\"\n)\n\nfunc JWTAuth(jwtSecret []byte) echo.MiddlewareFunc {\n    return func(next echo.HandlerFunc) echo.HandlerFunc {\n        return func(c echo.Context) error {\n            authHeader := c.Request().Header.Get(\"Authorization\")\n            if authHeader == \"\" {\n                return echo.NewHTTPError(http.StatusUnauthorized, \"missing authorization header\")\n            }\n\n            tokenString := strings.TrimPrefix(authHeader, \"Bearer \")\n            if tokenString == authHeader {\n                return echo.NewHTTPError(http.StatusUnauthorized, \"invalid authorization format\")\n            }\n\n            claims, err := ValidateToken(tokenString, jwtSecret)\n            if err != nil {\n                return echo.NewHTTPError(http.StatusUnauthorized, \"invalid or expired token\")\n            }\n\n            // Store in context for downstream handlers\n            c.Set(string(ContextKeyUserID), claims.UserID)\n            c.Set(string(ContextKeyAccountID), claims.AccountID)\n            c.Set(string(ContextKeyRoles), claims.Roles)\n            c.Set(string(ContextKeyUser), claims)\n\n            return next(c)\n        }\n    }\n}\n```\n\n### Tenant Context Middleware\n\nEnsures valid tenant context after authentication:\n\n```go\nfunc TenantContext() echo.MiddlewareFunc {\n    return func(next echo.HandlerFunc) echo.HandlerFunc {\n        return func(c echo.Context) error {\n            accountID := c.Get(string(ContextKeyAccountID))\n            if accountID == nil || accountID.(string) == \"\" {\n                return echo.NewHTTPError(http.StatusForbidden, \"no tenant context\")\n            }\n\n            // Optionally validate account exists and is active\n            // This can be cached for performance\n\n            return next(c)\n        }\n    }\n}\n```\n\n### Role-Based Authorization Middleware\n\n```go\n// RequireRole checks if user has any of the specified roles\nfunc RequireRole(roles ...string) echo.MiddlewareFunc {\n    return func(next echo.HandlerFunc) echo.HandlerFunc {\n        return func(c echo.Context) error {\n            userRoles, ok := c.Get(string(ContextKeyRoles)).([]string)\n            if !ok || len(userRoles) == 0 {\n                return echo.NewHTTPError(http.StatusForbidden, \"no roles assigned\")\n            }\n\n            for _, required := range roles {\n                for _, userRole := range userRoles {\n                    if userRole == required {\n                        return next(c)\n                    }\n                }\n            }\n\n            return echo.NewHTTPError(http.StatusForbidden, \"insufficient role permissions\")\n        }\n    }\n}\n\n// RequireAnyRole is an alias for RequireRole (OR logic)\nvar RequireAnyRole = RequireRole\n\n// RequireAllRoles checks if user has ALL specified roles\nfunc RequireAllRoles(roles ...string) echo.MiddlewareFunc {\n    return func(next echo.HandlerFunc) echo.HandlerFunc {\n        return func(c echo.Context) error {\n            userRoles, ok := c.Get(string(ContextKeyRoles)).([]string)\n            if !ok {\n                return echo.NewHTTPError(http.StatusForbidden, \"no roles assigned\")\n            }\n\n            userRoleSet := make(map[string]bool)\n            for _, r := range userRoles {\n                userRoleSet[r] = true\n            }\n\n            for _, required := range roles {\n                if !userRoleSet[required] {\n                    return echo.NewHTTPError(http.StatusForbidden, \"missing required role\")\n                }\n            }\n\n            return next(c)\n        }\n    }\n}\n```\n\n### Permission-Based Authorization Middleware\n\n```go\n// RequirePermission checks for specific resource:action permission\nfunc RequirePermission(resource, action string) echo.MiddlewareFunc {\n    return func(next echo.HandlerFunc) echo.HandlerFunc {\n        return func(c echo.Context) error {\n            claims, ok := c.Get(string(ContextKeyUser)).(*Claims)\n            if !ok {\n                return echo.NewHTTPError(http.StatusForbidden, \"invalid user context\")\n            }\n\n            // Check explicit permissions if available\n            requiredPerm := resource + \":\" + action\n            for _, perm := range claims.Permissions {\n                if perm == requiredPerm || perm == resource+\":*\" || perm == \"*:*\" {\n                    return next(c)\n                }\n            }\n\n            // Fallback: derive from roles (requires DB lookup or cached mapping)\n            if hasPermissionViaRole(claims.Roles, resource, action) {\n                return next(c)\n            }\n\n            return echo.NewHTTPError(http.StatusForbidden, \"permission denied\")\n        }\n    }\n}\n\n// hasPermissionViaRole checks role-permission mapping\n// In production, use cached lookup or include permissions in JWT\nfunc hasPermissionViaRole(roles []string, resource, action string) bool {\n    // Admin role has all permissions\n    for _, role := range roles {\n        if role == \"admin\" {\n            return true\n        }\n    }\n\n    // Role-permission mapping (simplified; use DB in production)\n    rolePerms := map[string][]string{\n        \"dispatcher\": {\"loads:*\", \"carriers:read\", \"tracking:*\"},\n        \"sales\":      {\"customers:*\", \"quotes:*\", \"lanes:*\", \"tenders:*\"},\n        \"finance\":    {\"invoices:*\", \"payments:*\", \"reports:financial\"},\n        \"driver\":     {\"loads:read\", \"loads:update_status\", \"documents:upload\"},\n        \"readonly\":   {\"loads:read\", \"carriers:read\", \"customers:read\"},\n    }\n\n    requiredPerm := resource + \":\" + action\n    for _, role := range roles {\n        for _, perm := range rolePerms[role] {\n            if matchPermission(perm, requiredPerm) {\n                return true\n            }\n        }\n    }\n    return false\n}\n\nfunc matchPermission(pattern, required string) bool {\n    if pattern == required {\n        return true\n    }\n    // Handle wildcard: \"loads:*\" matches \"loads:read\"\n    if strings.HasSuffix(pattern, \":*\") {\n        prefix := strings.TrimSuffix(pattern, \"*\")\n        return strings.HasPrefix(required, prefix)\n    }\n    return false\n}\n```\n\n### Middleware Chain Example\n\nApply middleware in order: Auth -> Tenant -> Role -> Permission:\n\n```go\nfunc SetupRoutes(e *echo.Echo, cfg *config.Config) {\n    // Public routes (no auth required)\n    e.GET(\"/health\", handlers.HealthCheck)\n\n    // API routes with auth\n    api := e.Group(\"/api/v1\")\n    api.Use(middleware.JWTAuth(cfg.JWTSecret))\n    api.Use(middleware.TenantContext())\n\n    // Load routes - dispatchers and admins\n    loads := api.Group(\"/loads\")\n    loads.Use(middleware.RequireRole(\"admin\", \"dispatcher\", \"sales\", \"readonly\"))\n    loads.GET(\"\", handlers.ListLoads)\n    loads.GET(\"/:id\", handlers.GetLoad)\n\n    // Modify operations require specific roles\n    loads.POST(\"\", handlers.CreateLoad, middleware.RequireRole(\"admin\", \"dispatcher\", \"sales\"))\n    loads.PUT(\"/:id\", handlers.UpdateLoad, middleware.RequireRole(\"admin\", \"dispatcher\"))\n\n    // Finance routes\n    finance := api.Group(\"/finance\")\n    finance.Use(middleware.RequireRole(\"admin\", \"finance\"))\n    finance.GET(\"/invoices\", handlers.ListInvoices)\n    finance.POST(\"/invoices\", handlers.CreateInvoice)\n\n    // Admin-only routes\n    admin := api.Group(\"/admin\")\n    admin.Use(middleware.RequireRole(\"admin\"))\n    admin.GET(\"/users\", handlers.ListUsers)\n    admin.POST(\"/users\", handlers.CreateUser)\n}\n```\n\n## Multi-Tenant RLS Policies\n\n### Enable RLS on Tables\n\n```sql\nALTER TABLE public.loads ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.carriers ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY;\n```\n\n### Account-Based Tenant Isolation\n\n```sql\n-- Users see only their account''s loads\nCREATE POLICY \"Users see only their account loads\"\n    ON public.loads\n    FOR SELECT\n    TO authenticated\n    USING (\n        account_id IN (\n            SELECT account_id\n            FROM public.account_users\n            WHERE user_id = (SELECT auth.uid())\n        )\n    );\n\n-- Users can create loads for their account\nCREATE POLICY \"Users create loads for their account\"\n    ON public.loads\n    FOR INSERT\n    TO authenticated\n    WITH CHECK (\n        account_id IN (\n            SELECT account_id\n            FROM public.account_users\n            WHERE user_id = (SELECT auth.uid())\n        )\n    );\n\n-- Users can update their account''s loads\nCREATE POLICY \"Users update their account loads\"\n    ON public.loads\n    FOR UPDATE\n    TO authenticated\n    USING (\n        account_id IN (\n            SELECT account_id\n            FROM public.account_users\n            WHERE user_id = (SELECT auth.uid())\n        )\n    )\n    WITH CHECK (\n        account_id IN (\n            SELECT account_id\n            FROM public.account_users\n            WHERE user_id = (SELECT auth.uid())\n        )\n    );\n```\n\n### Role-Based RLS Policies\n\nCombine tenant isolation with role restrictions:\n\n```sql\n-- Helper function to check user roles within account\nCREATE OR REPLACE FUNCTION public.user_has_role(required_roles TEXT[])\nRETURNS BOOLEAN\nLANGUAGE sql\nSECURITY DEFINER\nSTABLE\nAS $$\n    SELECT EXISTS (\n        SELECT 1\n        FROM public.user_roles ur\n        JOIN public.roles r ON ur.role_id = r.id\n        WHERE ur.user_id = (SELECT auth.uid())\n        AND r.name = ANY(required_roles)\n    );\n$$;\n\n-- Only finance and admin can view invoices\nCREATE POLICY \"Finance users view invoices\"\n    ON public.customer_invoices\n    FOR SELECT\n    TO authenticated\n    USING (\n        account_id IN (\n            SELECT account_id\n            FROM public.account_users\n            WHERE user_id = (SELECT auth.uid())\n        )\n        AND public.user_has_role(ARRAY[''admin'', ''finance'', ''readonly''])\n    );\n\n-- Only finance and admin can create invoices\nCREATE POLICY \"Finance users create invoices\"\n    ON public.customer_invoices\n    FOR INSERT\n    TO authenticated\n    WITH CHECK (\n        account_id IN (\n            SELECT account_id\n            FROM public.account_users\n            WHERE user_id = (SELECT auth.uid())\n        )\n        AND public.user_has_role(ARRAY[''admin'', ''finance''])\n    );\n```\n\n### Driver-Specific Policies\n\nDrivers see only their assigned loads:\n\n```sql\n-- Drivers see only loads assigned to them\nCREATE POLICY \"Drivers see assigned loads\"\n    ON public.loads\n    FOR SELECT\n    TO authenticated\n    USING (\n        -- Driver is assigned to this load\n        driver_user_id = (SELECT auth.uid())\n        OR\n        -- Or user has broader access via role\n        (\n            account_id IN (\n                SELECT account_id\n                FROM public.account_users\n                WHERE user_id = (SELECT auth.uid())\n            )\n            AND public.user_has_role(ARRAY[''admin'', ''dispatcher'', ''sales'', ''readonly''])\n        )\n    );\n```\n\n## Authorization Decision Patterns\n\n### HTTP Status Code Guidelines\n\n| Scenario | Status Code | When to Use |\n|----------|-------------|-------------|\n| Missing or invalid token | `401 Unauthorized` | Token absent, expired, or malformed |\n| Valid token, insufficient permissions | `403 Forbidden` | User authenticated but lacks required role/permission |\n| Resource not found (or hidden) | `404 Not Found` | Resource doesn''t exist OR hiding existence is security concern |\n\n### Security-Aware 404 Pattern\n\nUse 404 instead of 403 when revealing resource existence is a security concern:\n\n```go\nfunc GetLoad(c echo.Context) error {\n    loadID := c.Param(\"id\")\n    accountID := c.Get(string(middleware.ContextKeyAccountID)).(string)\n\n    load, err := repo.GetLoad(c.Request().Context(), loadID)\n    if err != nil {\n        if errors.Is(err, sql.ErrNoRows) {\n            // Resource doesn''t exist\n            return echo.NewHTTPError(http.StatusNotFound, \"load not found\")\n        }\n        return echo.NewHTTPError(http.StatusInternalServerError, \"failed to fetch load\")\n    }\n\n    // Check tenant ownership - return 404 to hide existence\n    if load.AccountID != accountID {\n        return echo.NewHTTPError(http.StatusNotFound, \"load not found\")\n    }\n\n    return c.JSON(http.StatusOK, load)\n}\n```\n\n### Error Response Structure\n\n```go\ntype ErrorResponse struct {\n    Error   string `json:\"error\"`\n    Code    string `json:\"code,omitempty\"`\n    Details string `json:\"details,omitempty\"`\n}\n\n// Authorization error examples\n// 401: {\"error\": \"missing authorization header\", \"code\": \"AUTH_REQUIRED\"}\n// 401: {\"error\": \"invalid or expired token\", \"code\": \"TOKEN_INVALID\"}\n// 403: {\"error\": \"insufficient role permissions\", \"code\": \"ROLE_REQUIRED\"}\n// 403: {\"error\": \"permission denied\", \"code\": \"PERMISSION_DENIED\"}\n```\n\n## JWT Claims Best Practices\n\n### Minimal Claims for Performance\n\nInclude only essential claims; derive others from database:\n\n```go\ntype MinimalClaims struct {\n    jwt.RegisteredClaims\n    UserID    string `json:\"sub\"`       // Use standard ''sub'' claim\n    AccountID string `json:\"account_id\"`\n    Roles     []string `json:\"roles\"`    // Include for middleware checks\n}\n```\n\n### Full Claims with Permissions\n\nFor reduced database lookups, include permissions:\n\n```go\ntype FullClaims struct {\n    jwt.RegisteredClaims\n    UserID      string   `json:\"sub\"`\n    Email       string   `json:\"email\"`\n    AccountID   string   `json:\"account_id\"`\n    AccountName string   `json:\"account_name\"`\n    Roles       []string `json:\"roles\"`\n    Permissions []string `json:\"permissions\"` // Flattened from roles\n}\n```\n\n### Token Generation\n\n```go\nfunc GenerateToken(user *User, account *Account, roles []string, permissions []string) (string, error) {\n    now := time.Now()\n    claims := &FullClaims{\n        RegisteredClaims: jwt.RegisteredClaims{\n            Subject:   user.ID,\n            IssuedAt:  jwt.NewNumericDate(now),\n            ExpiresAt: jwt.NewNumericDate(now.Add(24 * time.Hour)),\n            Issuer:    \"laneweavertms\",\n        },\n        UserID:      user.ID,\n        Email:       user.Email,\n        AccountID:   account.ID,\n        AccountName: account.Name,\n        Roles:       roles,\n        Permissions: permissions,\n    }\n\n    token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)\n    return token.SignedString(jwtSecret)\n}\n```\n\n## Authorization Checklist\n\n```\nRBAC Schema:\n[ ] roles, permissions, role_permissions tables created\n[ ] user_roles table includes account_id for multi-tenant\n[ ] account_users table for tenant membership\n[ ] Indexes on user_id, account_id columns for RLS performance\n\nMiddleware Chain:\n[ ] JWT validation middleware extracts claims to context\n[ ] Tenant context middleware validates account_id\n[ ] Role middleware checks user roles array\n[ ] Permission middleware checks specific resource:action\n\nRLS Policies:\n[ ] RLS enabled on all tenant-owned tables\n[ ] SELECT policies use account_id IN (SELECT from account_users)\n[ ] INSERT policies use WITH CHECK for account_id\n[ ] UPDATE policies use both USING and WITH CHECK\n[ ] auth.uid() wrapped in SELECT for query plan caching\n[ ] Indexes exist on columns used in RLS conditions\n\nJWT Claims:\n[ ] Token includes user_id, account_id, roles\n[ ] Token expiration set appropriately (e.g., 24 hours)\n[ ] Refresh token mechanism for long-lived sessions\n\nError Handling:\n[ ] 401 for missing/invalid authentication\n[ ] 403 for valid auth but insufficient permissions\n[ ] 404 when hiding resource existence is security concern\n[ ] Error responses don''t leak sensitive information\n```\n\n## Related Skills\n\n- **goth-oauth** - OAuth2 authentication foundation\n- **laneweaver-database-design** - Database schema conventions\n\n## Reference\n\n- Echo middleware documentation: https://echo.labstack.com/docs/middleware\n- Supabase RLS guide: https://supabase.com/docs/guides/auth/row-level-security\n- JWT best practices: https://datatracker.ietf.org/doc/html/rfc7519\n"},"lastSynced":"2026-03-08T02:03:13.227Z","agentAnalysis":{"suitability":{"en":"Perfect for Backend Agents needing advanced Role-Based Access Control (RBAC) implementation in Go/Echo with Supabase/PostgreSQL.","zh":"非常适合需要在 Go/Echo 中使用 Supabase/PostgreSQL 实现高级基于角色的访问控制 (RBAC) 的后端代理。","ja":"Go/Echo で Supabase/PostgreSQL を使用して高度なロールベースのアクセス制御 (RBAC) を実装する必要があるバックエンド エージェントに最適です。","ko":"Go/Echo에서 Supabase/PostgreSQL을 사용하여 고급 역할 기반 접근 제어(RBAC)를 구현해야 하는 백엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes de Backend que necesitan una implementación avanzada de Control de Acceso Basado en Roles (RBAC) en Go/Echo con Supabase/PostgreSQL.","fr":"Parfait pour les agents Backend nécessitant une mise en œuvre avancée du contrôle d''accès basé sur les rôles (RBAC) dans Go/Echo avec Supabase/PostgreSQL.","de":"Perfekt für Backend-Agents, die eine erweiterte Implementierung von rollenbasiertem Zugriffscontrolling (RBAC) in Go/Echo mit Supabase/PostgreSQL benötigen.","pt":"Perfeito para Agents Backend que precisam de implementação avançada de Controle de Acesso Baseado em Função (RBAC) em Go/Echo com Supabase/PostgreSQL.","ru":"Идеально подходит для агентов Backend, которым требуется продвинутая реализация Role-Based Access Control (RBAC) в Go/Echo с Supabase/PostgreSQL.","ar":"مثالي لعميل الخلفية الذي يحتاج إلى تنفيذ متقدم لمراقبة الوصول القائم على الدور (RBAC) في Go/Echo مع Supabase/PostgreSQL."},"recommendation":{"en":"Empowers agents to implement robust multi-tenant authorization, define user roles and permissions, and design JWT claims structures for secure authentication, leveraging Echo middleware and RLS policies for fine-grained access control.","zh":"赋予代理实现强大的多租户授权、定义用户角色和权限、设计 JWT 声明结构以实现安全的身份验证，利用 Echo 中间件和 RLS 策略进行细粒度的访问控制。","ja":"エージェントに、強力なマルチテナント認可を実装し、ユーザーロールと権限を定義し、セキュアな認証のための JWT クレーム構造を設計することを可能にし、Echo ミドルウェアと RLS ポリシーを使用して細粒度のアクセス制御を実現します。","ko":"에이전트가 강력한 멀티 테넌트 인증을 구현하고 사용자 역할 및 권한을 정의하며 보안 인증을 위한 JWT 클레임 구조를 설계할 수 있도록 하며 Echo 미들웨어 및 RLS 정책을 사용하여 세분화된 액세스 제어를 구현합니다.","es":"Permite a los agentes implementar una autorización de multi-inquilino robusta, definir roles y permisos de usuario y diseñar estructuras de reclamaciones JWT para una autenticación segura, aprovechando el middleware de Echo y las políticas de RLS para un control de acceso granular.","fr":"Permet aux agents de mettre en œuvre une autorisation multi-locataire robuste, de définir des rôles et des autorisations d''utilisateur et de concevoir des structures de revendications JWT pour une authentification sécurisée, en exploitant le middleware Echo et les politiques de RLS pour un contrôle d''accès granulaire.","de":"Ermöglicht es den Agents, eine robuste Multi-Mandanten-Autorisierung zu implementieren, Benutzerrollen und -berechtigungen zu definieren und JWT-Anspruchstrukturen für eine sichere Authentifizierung zu entwerfen, indem sie das Echo-Middleware und die RLS-Richtlinien für einen feingranularen Zugriffsschutz nutzen.","pt":"Habilita os agentes a implementar autorização de multi-locatário robusta, definir funções e permissões de usuário e projetar estruturas de reivindicações JWT para autenticação segura, aproveitando o middleware Echo e as políticas RLS para controle de acesso granular.","ru":"Позволяет агентам реализовывать прочную многоарендаторскую авторизацию, определять роли и разрешения пользователей, а также проектировать структуры претензий JWT для безопасной аутентификации, используя middleware Echo и политики RLS для тонкого контроля доступа.","ar":"يمنح الوكلاء تنفيذ صلاحيات متعددة المستأجرين متينة، وتحديد أدوار المستخدمين والصلاحيات، وتصميم هياكل مطالبات JWT للتحقق الآمن، واستخدام وسيط Echo وسياسات RLS للتحكم الدقيق في الوصول."},"useCases":{"en":["Implementing role-based access control for freight brokerage operations","Setting up multi-tenant isolation with account-based access in Supabase/PostgreSQL","Designing and implementing JWT claims structures for authorization","Writing RLS policies for secure data access"],"zh":["为货运代理操作实现基于角色的访问控制","在 Supabase/PostgreSQL 中设置基于帐户的访问的多租户隔离","设计和实现用于授权的 JWT 声明结构","编写 RLS 策略以实现安全的数据访问"],"ja":["貨物ブローカー操作のロールベースのアクセス制御を実装する","Supabase/PostgreSQL でアカウントベースのアクセスを使用したマルチテナントの分離を設定する","認可のための JWT クレーム構造を設計して実装する","セキュアなデータアクセスのための RLS ポリシーを記述する"],"ko":["화물 중개 운송業務를 위한 역할 기반 접근 제어 구현","Supabase/PostgreSQL에서 계정 기반 접근을 사용한 멀티 테넌트 분리를 설정","인증을 위한 JWT 클레임 구조 설계 및 구현","보안 데이터 접근을 위한 RLS 정책 작성"],"es":["Implementar el control de acceso basado en roles para operaciones de corretaje de carga","Configurar el aislamiento de multi-inquilino con acceso basado en cuenta en Supabase/PostgreSQL","Diseñar e implementar estructuras de reclamaciones JWT para la autorización","Escribir políticas de RLS para un acceso a datos seguro"],"fr":["Mettre en œuvre le contrôle d''accès basé sur les rôles pour les opérations de courtage de fret","Configurer l''isolement multi-locataire avec un accès basé sur le compte dans Supabase/PostgreSQL","Concevoir et mettre en œuvre des structures de revendications JWT pour l''autorisation","Écrire des politiques de RLS pour un accès aux données sécurisé"],"de":["Implementierung von rollenbasiertem Zugriffscontrolling für Frachtvermittlungsoperationen","Einrichtung der Multi-Mandanten-Isolation mit kontobasiertem Zugriff in Supabase/PostgreSQL","Entwerfen und Implementieren von JWT-Anspruchstrukturen für die Autorisierung","Schreiben von RLS-Richtlinien für einen sicheren Datenzugriff"],"pt":["Implementação de controle de acesso baseado em função para operações de corretagem de carga","Configuração de isolamento de multi-locatário com acesso baseado em conta no Supabase/PostgreSQL","Projeto e implementação de estruturas de reivindicações JWT para autorização","Escrita de políticas RLS para acesso de dados seguro"],"ru":["Реализация контроля доступа на основе ролей для операций по грузоперевозкам","Настройка изоляции многоарендаторов с доступом на основе учетной записи в Supabase/PostgreSQL","Проектирование и реализация структур претензий JWT для авторизации","Написание политик RLS для безопасного доступа к данным"],"ar":["تنفيذ مراقبة الوصول القائم على الدور لعمليات وسيطات الشحن","إعداد العزل المتعدد للمستأجرين مع الوصول المستند إلى الحساب في Supabase/PostgreSQL","تصميم وتنفيذ هياكل مطالبات JWT للصلاحيات","كتابة سياسات RLS للوصول الآمن إلى البيانات"]},"limitations":{"en":["Requires Go/Echo backend setup","Supabase/PostgreSQL database dependency","Limited to RBAC and multi-tenant authorization use cases"],"zh":["需要 Go/Echo 后端设置","依赖 Supabase/PostgreSQL 数据库","仅限于 RBAC 和多租户授权使用场景"],"ja":["Go/Echo バックエンドの設定が必要","Supabase/PostgreSQL データベースに依存している","RBAC とマルチテナント認可の使用シナリオに限定される"],"ko":["Go/Echo 백엔드 설정이 필요","Supabase/PostgreSQL 데이터베이스 의존","RBAC 및 멀티 테넌트 인증 사용 사례에만 제한"],"es":["Requiere configuración de backend Go/Echo","Dependencia de la base de datos Supabase/PostgreSQL","Limitado a casos de uso de RBAC y autorización de multi-inquilino"],"fr":["Nécessite une configuration de backend Go/Echo","Dépendance de la base de données Supabase/PostgreSQL","Limité aux cas d''utilisation de RBAC et d''autorisation multi-locataire"],"de":["Erfordert eine Go/Echo-Backend-Konfiguration","Datenbank-Abhängigkeit von Supabase/PostgreSQL","Begrenzt auf RBAC- und Multi-Mandanten-Autorisierungs-Anwendungsfälle"],"pt":["Exige configuração de backend Go/Echo","Dependência do banco de dados Supabase/PostgreSQL","Limitado a casos de uso de RBAC e autorização de multi-locatário"],"ru":["Требует настройки бэкенда Go/Echo","Зависимость от базы данных Supabase/PostgreSQL","Ограничен для случаев использования RBAC и многоарендаторской авторизации"],"ar":["يتطلب إعداد خلفية Go/Echo","اعتماد البيانات المخزنة في Supabase/PostgreSQL","محدود لاستخدام حالات RBAC والصلاحيات المتعددة للمستأجرين"]},"version":4},"contentHash":"602ccdd23f8b2f66d2eae3fd8fb2fbc1fd44f3956305146c656a9064af76bc99","qualityScore":57}');
