INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ankitsharma495/Flowbase/rbac-authorization-patterns', 'rbac-authorization-patterns', 'ankitsharma495', 'Flowbase', 'community', 'rbac-authorization-patterns ankitsharma495 Flowbase community The rbac-authorization-patterns skill provides expert guidance for implementing Role-Based Access Control (RBAC) and multi-tenant authorization in a Go/Echo backend with Supabase/PostgreSQL, benefiting developers of freight brokerage operations. 本指南介绍如何在 Go/Echo 后端和 Supabase/PostgreSQL 中实现 RBAC 授权模式和多租户授权 このガイドでは、Go/Echo バックエンドと Supabase/PostgreSQL で RBAC 認可パターンとマルチテナント認可を実装する方法について説明します 이 가이드는 Go/Echo 백엔드와 Supabase/PostgreSQL에서 RBAC 권한 패턴과 멀티 테넌트 인증을 구현하는 방법을 설명합니다 Implemente patrones de autorización RBAC para laneweaverTMS con Go/Echo y Supabase/PostgreSQL Mettez en œuvre des modèles d''autorisation RBAC pour laneweaverTMS avec Go/Echo et Supabase/PostgreSQL Implementieren Sie RBAC-Autorisierungsmuster für laneweaverTMS mit Go/Echo und Supabase/PostgreSQL Implemente padrões de autorização RBAC com Go/Echo e Supabase para controlar o acesso de usuários em operações de freight brokerage Реализуйте шаблоны авторизации RBAC с помощью Go/Echo и Supabase для управления доступом пользователей в операциях по грузоперевозкам نفذ أنماط الترخيص RBAC باستخدام Go/Echo و Supabase للتحكم في الوصول للمستخدمين في عمليات السوق البرية how to use rbac-authorization-patterns rbac-authorization-patterns setup guide Role-Based Access Control with Go/Echo multi-tenant authorization with Supabase/PostgreSQL rbac-authorization-patterns vs traditional authorization implementing rbac-authorization-patterns in freight brokerage operations RBAC 授权模式 Go/Echo 后端 Supabase/PostgreSQL 多租户授权 用户角色管理 访问控制 JWT 声明结构 RLS 政策 Implements Echo middleware for role/permission checks Sets up multi-tenant isolation with account-based access using Supabase/PostgreSQL Designs JWT claims structure for authorization Writes RLS policies for secure data access Defines user roles and permissions for freight brokerage operations rbac-authorization-patterns is a technical skill for implementing Role-Based Access Control (RBAC) and multi-tenant authorization in Go/Echo backend applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Aniket-a14/SRA/supabase-expert', 'community', 'Aniket-a14', 'SRA', 'Aniket-a14/SRA', 'supabase-expert', 0, 0, 57, '2026-03-08T01:57:15.338Z', '2026-03-08T02:03:21.860Z', 'fdc2de96f887a4049c73760241b0831ce3285b0b26cb12f1653c305cfbbb64bf', '{"id":"Aniket-a14/SRA/supabase-expert","name":"supabase-expert","description":{"en":"The supabase-expert skill helps developers build secure and scalable Supabase integrations, focusing on database design, Row Level Security, and authentication. It benefits developers working with Supabase.","zh":"Supabase集成专家技能帮助开发者构建安全可扩展的Supabase集成，实现Row Level Security、Type Safety和Edge Functions等功能","ja":"Supabaseエキスパートスキルは、開発者がセキュアでスケーラブルなSupabase統合を構築し、Row Level Security、Type Safety、Edge Functionsなどの機能を実現するのに役立ちます","ko":"Supabase 통합 전문가 스킬은 개발자가 보안이 강화되고 확장 가능한 Supabase 통합을 구축하고 Row Level Security, Type Safety, Edge Functions 등의 기능을 구현하는 데 도움이 됩니다","es":"El experto en Supabase ayuda a construir integraciones seguras y escalables. Utiliza esto para diseño de bases de datos, políticas de seguridad de nivel de fila y funciones de borde","fr":"L''expert Supabase aide à créer des intégrations sécurisées et évolutives. Utilisez-le pour la conception de bases de données, les politiques de sécurité de niveau de ligne et les fonctions de bord","de":"Der Supabase-Experte hilft bei der Erstellung sicherer und skalierbarer Integrationen. Verwenden Sie es für Datenbankdesign, Zeilenberechtigungspolicies und Edge-Funktionen","pt":"O Supabase Expert é um skill que ajuda a construir integrações seguras e escaláveis com o Supabase, utilizando Row Level Security e autenticação","ru":"Supabase Expert - это навык, который помогает создавать безопасные и масштабируемые интеграции с Supabase, используя RLS и аутентификацию","ar":"Supabase Expert هو مهارة تساعد على بناء تطبيقات متوافق مع Supabase باستخدام Row Level Security وأمان البيانات"},"seo":{"title":{"en":"supabase-expert: Secure Supabase Integration Setup Guide ...","zh":"Supabase集成专家：安全可扩展的数据库设计指南","ja":"Supabaseエキスパート：セキュアでスケーラブルなデータベース設計ガイド","ko":"Supabase 통합 전문가: 보안이 강화되고 확장 가능한 데이터베이스 설계 가이드","es":"Guía de configuración de Supabase Expert para integracion...","fr":"Guide de mise en place de Supabase Expert pour des intégr...","de":"Einrichtungsleitfaden für Supabase Expert zur Erstellung ...","pt":"Guia de Configuração do Supabase Expert: Melhores Prática...","ru":"ИИ Агент Supabase Expert: Руководство по Безопасной Интег...","ar":"دليل إعداد Supabase Expert: أفضل الممارسات لدمج البيانات ..."},"description":{"en":"Unlock secure and scalable Supabase integrations with supabase-expert. Learn how to implement Row Level Security and type safety for reliable database design.","zh":"使用Supabase集成专家技能，构建安全可靠的Supabase集成，实现Row Level Security、Type Safety和Edge Functions","ja":"Supabaseエキスパートスキルを使用して、セキュアで信頼性の高いSupabase統合を構築し、Row Level Security、Type Safety、Edge Functionsを実現します","ko":"Supabase 통합 전문가 스킬을 사용하여 보안이 강화되고 신뢰할 수 있는 Supabase 통합을 구축하고 Row Level Security, Type Safety, Edge Functions를 구현합니다","es":"Aprende a construir integraciones de Supabase seguras y escalables con nuestro experto en AI. Mejora la seguridad y la confiabilidad de tus proyectos","fr":"Découvrez comment créer des intégrations Supabase sécurisées et évolutives avec notre expert en IA. Améliorez la sécurité et la fiabilité de vos projets","de":"Erfahren Sie, wie Sie mit unserem Supabase-Experten sicherere und skalierbare Integrationen erstellen. Verbessern Sie die Sicherheit und Zuverlässigkeit Ihre...","pt":"Aprenda a configurar o Supabase Expert para criar integrações seguras e escaláveis com Row Level Security e autenticação","ru":"Узнайте, как настроить Supabase Expert для создания безопасных и масштабируемых интеграций с помощью RLS и аутентификации","ar":"تعلم كيفية إعداد Supabase Expert لإنشاء تطبيقات متوافق مع Row Level Security وأمان البيانات"},"definition":{"en":"supabase-expert is a skill that provides AI-powered guidance for building secure and scalable Supabase integrations, emphasizing security and type safety.","zh":"Supabase集成专家是一种AI驱动的软件，帮助开发者构建安全可扩展的Supabase集成","ja":"Supabaseエキスパートは、開発者がセキュアでスケーラブルなSupabase統合を構築するのに役立つAI駆動のソフトウェアです","ko":"Supabase 통합 전문가는 개발자가 보안이 강화되고 확장 가능한 Supabase 통합을 구축하는 데 도움이 되는 AI 기반 소프트웨어입니다","es":"Un experto en Supabase es un sistema de análisis de requisitos de software impulsado por IA que evalúa la calidad de los requisitos y sugiere mejoras estructuradas","fr":"Un expert Supabase est un système d''analyse de besoins logiciels alimenté par l''IA qui évalue la qualité des besoins et suggère des améliorations structurées","de":"Ein Supabase-Experte ist ein von KI angetriebenes System zur Analyse von Softwareanforderungen, das die Qualität der Anforderungen bewertet und strukturierte Verbesserungen vorschlägt","pt":"O que é Supabase Expert? É um skill que fornece orientação para integrações seguras e escaláveis com o Supabase","ru":"Что такое Supabase Expert? Это навык, который предоставляет руководство для безопасных и масштабируемых интеграций с Supabase","ar":"ما هو Supabase Expert? هو مهارة تقدم إرشادات لدمج البيانات الآمنة والمتناسقة مع Supabase"},"features":{"en":["Enables Row Level Security (RLS) on tables with user data","Generates TypeScript types for secure and scalable database design","Implements service role key for secure server contexts","Uses anon key for client-side operations","Tests RLS policies thoroughly for reliable security"],"zh":["Row Level Security（RLS）","Type Safety","Edge Functions","数据库设计","身份验证","实时功能"],"ja":["Row Level Security（RLS）","Type Safety","Edge Functions","データベース設計","認証","リアルタイム機能"],"ko":["Row Level Security（RLS）","Type Safety","Edge Functions","데이터베이스 설계","인증","실시간 기능"],"es":["Diseño de bases de datos seguras","Implementación de políticas de seguridad de nivel de fila (RLS)","Autenticación y autorización de usuarios","Funciones de borde (Edge Functions) para una mayor escalabilidad","Tipos de seguridad de TypeScript para una mejor integración"],"fr":["Conception de bases de données sécurisées","Mise en œuvre de politiques de sécurité de niveau de ligne (RLS)","Authentification et autorisation des utilisateurs","Fonctions de bord (Edge Functions) pour une meilleure évolutivité","Types de sécurité de TypeScript pour une meilleure intégration"],"de":["Sicheres Datenbankdesign","Implementierung von Zeilenberechtigungspolicies (RLS)","Authentifizierung und Autorisierung von Benutzern","Edge-Funktionen für eine bessere Skalierbarkeit","TypeScript-Sicherheitstypen für eine bessere Integration"],"pt":["Row Level Security (RLS) para proteger dados sensíveis","Autenticação e autorização para controle de acesso","Edge Functions para processamento em tempo real","Tipos de segurança para garantir a integridade dos dados","Integração com o Supabase para criar aplicações escaláveis"],"ru":["Row Level Security (RLS) для защиты конфиденциальных данных","Аутентификация и авторизация для контроля доступа","Edge Functions для обработки в режиме реального времени","Типы безопасности для обеспечения целостности данных","Интеграция с Supabase для создания масштабируемых приложений"],"ar":["Row Level Security (RLS) لحماية البيانات الحساسة","التحقق والتحقق من الهوية للسيطرة على الوصول","Edge Functions لمعالجة الوقت الفعلي","أنواع الأمان لضمان سلامة البيانات","التكامل مع Supabase لإنشاء تطبيقات قابلة للتحجيم"]},"keywords":{"en":["how to use supabase-expert","supabase-expert setup guide","supabase-expert alternative","supabase-expert vs prisma","supabase-expert install","what is supabase-expert","supabase-expert tutorial","supabase-expert security features","supabase-expert database design"],"zh":["Supabase集成","Row Level Security","Type Safety","Edge Functions","数据库设计","AI驱动的软件","Supabase专家","安全可扩展的集成"],"ja":["Supabase統合","Row Level Security","Type Safety","Edge Functions","データベース設計","AI駆動のソフトウェア","Supabaseエキスパート","セキュアでスケーラブルな統合"],"ko":["Supabase 통합","Row Level Security","Type Safety","Edge Functions","데이터베이스 설계","AI 기반 소프트웨어","Supabase 전문가","보안이 강화되고 확장 가능한 통합"],"es":["Supabase experto","integraciones seguras","diseño de bases de datos","políticas de seguridad de nivel de fila","autenticación de usuarios","funciones de borde","tipos de seguridad de TypeScript","herramientas de desarrollo de software","sistemas de análisis de requisitos de software"],"fr":["Expert Supabase","intégrations sécurisées","conception de bases de données","politiques de sécurité de niveau de ligne","authentification des utilisateurs","fonctions de bord","types de sécurité de TypeScript","outils de développement de logiciels","systèmes d''analyse de besoins logiciels"],"de":["Supabase-Experte","sichere Integrationen","Datenbankdesign","Zeilenberechtigungspolicies","Authentifizierung von Benutzern","Edge-Funktionen","TypeScript-Sicherheitstypen","Software-Entwicklungstools","Software-Anforderungsanalyse-Systeme"],"pt":["Supabase Expert","Integração segura","Row Level Security","Autenticação","Edge Functions","Tipos de segurança","Desenvolvimento de aplicações","Supabase"],"ru":["Supabase Expert","Безопасная интеграция","Row Level Security","Аутентификация","Edge Functions","Типы безопасности","Разработка приложений","Supabase"],"ar":["Supabase Expert","دمج آمن","Row Level Security","التحقق","Edge Functions","أنواع الأمان","تطوير التطبيقات","Supabase"]}},"owner":"Aniket-a14","repo":"SRA","repoPath":"Aniket-a14/SRA","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.338Z","topics":[],"category":"community","skillMd":{"name":"supabase-expert","description":"Expert guide for Supabase integration - database schemas, RLS policies, auth, Edge Functions, and real-time subscriptions. Use when working with Supabase backend features.","bodyPreview":"# Supabase Integration Expert Skill\n\n## Overview\n\nThis skill helps you build secure, scalable Supabase integrations. Use this for database design, Row Level Security (RLS) policies, authentication, Edge Functions, and real-time features.\n\n## Core Principles\n\n### 1. Security First\n- Always enable RLS on tables with user data\n- Use service role key only in secure server contexts\n- Use anon key for client-side operations\n- Test policies thoroughly\n\n### 2. Type Safety\n- Generate TypeScript types fro","body":"# Supabase Integration Expert Skill\n\n## Overview\n\nThis skill helps you build secure, scalable Supabase integrations. Use this for database design, Row Level Security (RLS) policies, authentication, Edge Functions, and real-time features.\n\n## Core Principles\n\n### 1. Security First\n- Always enable RLS on tables with user data\n- Use service role key only in secure server contexts\n- Use anon key for client-side operations\n- Test policies thoroughly\n\n### 2. Type Safety\n- Generate TypeScript types from schema\n- Use generated types in application\n- Keep types in sync with schema changes\n\n### 3. Performance\n- Use indexes for frequently queried columns\n- Implement pagination for large datasets\n- Use select() to limit returned fields\n- Cache when appropriate\n\n## Database Schema Design\n\n### Basic Table Creation\n\n```sql\n-- Create a table with standard fields\ncreate table public.items (\n  id uuid default gen_random_uuid() primary key,\n  created_at timestamp with time zone default timezone(''utc''::text, now()) not null,\n  updated_at timestamp with time zone default timezone(''utc''::text, now()) not null,\n  user_id uuid references auth.users(id) on delete cascade not null,\n  title text not null,\n  description text,\n  status text default ''draft'' check (status in (''draft'', ''published'', ''archived''))\n);\n\n-- Create updated_at trigger\ncreate or replace function public.handle_updated_at()\nreturns trigger as $$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$$ language plpgsql;\n\ncreate trigger set_updated_at\n  before update on public.items\n  for each row\n  execute function public.handle_updated_at();\n\n-- Create index\ncreate index items_user_id_idx on public.items(user_id);\ncreate index items_status_idx on public.items(status);\n```\n\n### Foreign Keys & Relations\n\n```sql\n-- One-to-many relationship\ncreate table public.comments (\n  id uuid default gen_random_uuid() primary key,\n  created_at timestamp with time zone default now() not null,\n  item_id uuid references public.items(id) on delete cascade not null,\n  user_id uuid references auth.users(id) on delete cascade not null,\n  content text not null\n);\n\n-- Many-to-many relationship\ncreate table public.item_tags (\n  item_id uuid references public.items(id) on delete cascade,\n  tag_id uuid references public.tags(id) on delete cascade,\n  primary key (item_id, tag_id)\n);\n```\n\n## Row Level Security (RLS)\n\n### Basic RLS Patterns\n\n```sql\n-- Enable RLS\nalter table public.items enable row level security;\n\n-- Users can read their own items\ncreate policy \"Users can read own items\"\n  on public.items for select\n  using (auth.uid() = user_id);\n\n-- Users can insert their own items\ncreate policy \"Users can insert own items\"\n  on public.items for insert\n  with check (auth.uid() = user_id);\n\n-- Users can update their own items\ncreate policy \"Users can update own items\"\n  on public.items for update\n  using (auth.uid() = user_id)\n  with check (auth.uid() = user_id);\n\n-- Users can delete their own items\ncreate policy \"Users can delete own items\"\n  on public.items for delete\n  using (auth.uid() = user_id);\n```\n\n### Advanced RLS Patterns\n\n```sql\n-- Public read, authenticated write\ncreate policy \"Anyone can read published items\"\n  on public.items for select\n  using (status = ''published'');\n\ncreate policy \"Authenticated users can insert\"\n  on public.items for insert\n  to authenticated\n  with check (true);\n\n-- Role-based access\ncreate policy \"Admins can do everything\"\n  on public.items for all\n  using (\n    exists (\n      select 1 from public.user_roles\n      where user_id = auth.uid()\n      and role = ''admin''\n    )\n  );\n\n-- Shared access\ncreate policy \"Users can read shared items\"\n  on public.items for select\n  using (\n    auth.uid() = user_id\n    or exists (\n      select 1 from public.item_shares\n      where item_id = items.id\n      and shared_with = auth.uid()\n    )\n  );\n```\n\n### Anonymous/Guest Access\n\n```sql\n-- Allow anonymous reads\ncreate policy \"Anonymous can read public content\"\n  on public.items for select\n  to anon\n  using (status = ''published'');\n\n-- Allow anonymous inserts (for guest mode)\ncreate policy \"Anonymous can create items\"\n  on public.items for insert\n  to anon\n  with check (true);\n```\n\n## Client Integration\n\n### Setup Client (Next.js)\n\n```typescript\n// lib/supabase/client.ts\nimport { createBrowserClient } from ''@supabase/ssr''\n\nexport function createClient() {\n  return createBrowserClient(\n    process.env.NEXT_PUBLIC_SUPABASE_URL!,\n    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!\n  )\n}\n\n// lib/supabase/server.ts\nimport { createServerClient } from ''@supabase/ssr''\nimport { cookies } from ''next/headers''\n\nexport function createServerClient() {\n  const cookieStore = cookies()\n\n  return createServerClient(\n    process.env.NEXT_PUBLIC_SUPABASE_URL!,\n    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,\n    {\n      cookies: {\n        get(name: string) {\n          return cookieStore.get(name)?.value\n        },\n      },\n    }\n  )\n}\n```\n\n### CRUD Operations\n\n```typescript\n// Query data\nconst { data, error } = await supabase\n  .from(''items'')\n  .select(''*'')\n  .eq(''status'', ''published'')\n  .order(''created_at'', { ascending: false })\n  .limit(10)\n\n// Insert data\nconst { data, error } = await supabase\n  .from(''items'')\n  .insert({ title: ''New Item'', user_id: userId })\n  .select()\n  .single()\n\n// Update data\nconst { data, error } = await supabase\n  .from(''items'')\n  .update({ title: ''Updated Title'' })\n  .eq(''id'', itemId)\n  .select()\n  .single()\n\n// Delete data\nconst { error } = await supabase\n  .from(''items'')\n  .delete()\n  .eq(''id'', itemId)\n\n// Complex joins\nconst { data, error } = await supabase\n  .from(''items'')\n  .select(`\n    *,\n    comments (\n      id,\n      content,\n      user:user_id (\n        email\n      )\n    )\n  `)\n  .eq(''user_id'', userId)\n```\n\n### Real-time Subscriptions\n\n```typescript\n// Subscribe to changes\nconst channel = supabase\n  .channel(''items-changes'')\n  .on(\n    ''postgres_changes'',\n    {\n      event: ''*'',\n      schema: ''public'',\n      table: ''items'',\n      filter: `user_id=eq.${userId}`,\n    },\n    (payload) => {\n      console.log(''Change received!'', payload)\n      // Update local state\n    }\n  )\n  .subscribe()\n\n// Cleanup\nchannel.unsubscribe()\n```\n\n## Authentication\n\n### Email/Password Auth\n\n```typescript\n// Sign up\nconst { data, error } = await supabase.auth.signUp({\n  email: ''user@example.com'',\n  password: ''password123'',\n  options: {\n    data: {\n      display_name: ''User Name'',\n    },\n  },\n})\n\n// Sign in\nconst { data, error } = await supabase.auth.signInWithPassword({\n  email: ''user@example.com'',\n  password: ''password123'',\n})\n\n// Sign out\nconst { error } = await supabase.auth.signOut()\n\n// Get current user\nconst { data: { user } } = await supabase.auth.getUser()\n```\n\n### OAuth Providers\n\n```typescript\n// Google OAuth\nconst { data, error } = await supabase.auth.signInWithOAuth({\n  provider: ''google'',\n  options: {\n    redirectTo: `${window.location.origin}/auth/callback`,\n  },\n})\n\n// Handle callback\n// app/auth/callback/route.ts\nexport async function GET(request: Request) {\n  const { searchParams } = new URL(request.url)\n  const code = searchParams.get(''code'')\n\n  if (code) {\n    const supabase = createServerClient()\n    await supabase.auth.exchangeCodeForSession(code)\n  }\n\n  return NextResponse.redirect(new URL(''/dashboard'', request.url))\n}\n```\n\n### Auth Middleware\n\n```typescript\n// middleware.ts\nimport { createServerClient } from ''@supabase/ssr''\nimport { NextResponse } from ''next/server''\nimport type { NextRequest } from ''next/server''\n\nexport async function middleware(request: NextRequest) {\n  const response = NextResponse.next()\n\n  const supabase = createServerClient(\n    process.env.NEXT_PUBLIC_SUPABASE_URL!,\n    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,\n    {\n      cookies: {\n        get(name: string) {\n          return request.cookies.get(name)?.value\n        },\n        set(name: string, value: string, options: any) {\n          response.cookies.set(name, value, options)\n        },\n        remove(name: string, options: any) {\n          response.cookies.set(name, '''', { ...options, maxAge: 0 })\n        },\n      },\n    }\n  )\n\n  const { data: { user } } = await supabase.auth.getUser()\n\n  // Redirect to login if not authenticated\n  if (!user && request.nextUrl.pathname.startsWith(''/dashboard'')) {\n    return NextResponse.redirect(new URL(''/login'', request.url))\n  }\n\n  return response\n}\n\nexport const config = {\n  matcher: [''/dashboard/:path*''],\n}\n```\n\n## Edge Functions\n\n### Basic Edge Function\n\n```typescript\n// supabase/functions/hello/index.ts\nimport { serve } from ''https://deno.land/std@0.168.0/http/server.ts''\nimport { createClient } from ''https://esm.sh/@supabase/supabase-js@2''\n\nserve(async (req) => {\n  try {\n    // Get Supabase client\n    const supabase = createClient(\n      Deno.env.get(''SUPABASE_URL'') ?? '''',\n      Deno.env.get(''SUPABASE_ANON_KEY'') ?? '''',\n      {\n        auth: {\n          autoRefreshToken: false,\n          persistSession: false,\n        },\n      }\n    )\n\n    // Get user from auth header\n    const authHeader = req.headers.get(''Authorization'')\n    const token = authHeader?.replace(''Bearer '', '''')\n    const { data: { user } } = await supabase.auth.getUser(token)\n\n    if (!user) {\n      return new Response(\n        JSON.stringify({ error: ''Unauthorized'' }),\n        { status: 401, headers: { ''Content-Type'': ''application/json'' } }\n      )\n    }\n\n    // Your logic here\n    const { data, error } = await supabase\n      .from(''items'')\n      .select(''*'')\n      .eq(''user_id'', user.id)\n\n    return new Response(\n      JSON.stringify({ data }),\n      { headers: { ''Content-Type'': ''application/json'' } }\n    )\n  } catch (error) {\n    return new Response(\n      JSON.stringify({ error: error.message }),\n      { status: 500, headers: { ''Content-Type'': ''application/json'' } }\n    )\n  }\n})\n```\n\n## Type Generation\n\n```bash\n# Generate TypeScript types\nnpx supabase gen types typescript --project-id your-project-id > types/supabase.ts\n\n# Use in code\nimport { Database } from ''@/types/supabase''\n\ntype Item = Database[''public''][''Tables''][''items''][''Row'']\ntype ItemInsert = Database[''public''][''Tables''][''items''][''Insert'']\ntype ItemUpdate = Database[''public''][''Tables''][''items''][''Update'']\n```\n\n## Common Patterns\n\n### Soft Deletes\n\n```sql\nalter table public.items add column deleted_at timestamp with time zone;\n\ncreate policy \"Users cannot see deleted items\"\n  on public.items for select\n  using (deleted_at is null);\n\n-- Soft delete function\ncreate or replace function soft_delete_item(item_id uuid)\nreturns void as $$\nbegin\n  update public.items\n  set deleted_at = now()\n  where id = item_id;\nend;\n$$ language plpgsql security definer;\n```\n\n### Audit Logs\n\n```sql\ncreate table public.audit_logs (\n  id uuid default gen_random_uuid() primary key,\n  created_at timestamp with time zone default now() not null,\n  user_id uuid references auth.users(id),\n  table_name text not null,\n  record_id uuid not null,\n  action text not null,\n  changes jsonb\n);\n\n-- Trigger function\ncreate or replace function public.audit_trigger()\nreturns trigger as $$\nbegin\n  insert into public.audit_logs (user_id, table_name, record_id, action, changes)\n  values (\n    auth.uid(),\n    TG_TABLE_NAME,\n    NEW.id,\n    TG_OP,\n    to_jsonb(NEW) - to_jsonb(OLD)\n  );\n  return NEW;\nend;\n$$ language plpgsql security definer;\n```\n\n## Troubleshooting\n\n### Common Issues\n\n1. **401 Errors**: Check RLS policies, ensure user is authenticated\n2. **403 Errors**: RLS policy blocking operation\n3. **Row not found**: Policy may be filtering it out\n4. **Connection issues**: Check URL and API keys\n5. **Type mismatches**: Regenerate types after schema changes\n\n### Debugging RLS\n\n```sql\n-- Test as specific user\nset request.jwt.claims = ''{\"sub\": \"user-uuid-here\"}'';\n\n-- Check what policies apply\nselect * from pg_policies where tablename = ''items'';\n\n-- Disable RLS temporarily (for testing only!)\nalter table public.items disable row level security;\n```\n\n## Best Practices Checklist\n\n- [ ] Enable RLS on all tables with user data\n- [ ] Create indexes for foreign keys and frequently queried columns\n- [ ] Use UUID for primary keys\n- [ ] Add created_at and updated_at timestamps\n- [ ] Implement soft deletes for important data\n- [ ] Use check constraints for enum-like fields\n- [ ] Generate and use TypeScript types\n- [ ] Test RLS policies thoroughly\n- [ ] Use service role key only server-side\n- [ ] Implement proper error handling\n- [ ] Add audit logs for sensitive operations\n- [ ] Use transactions for multi-step operations\n\n## When to Use This Skill\n\nInvoke this skill when:\n- Designing database schemas\n- Creating or debugging RLS policies\n- Setting up authentication\n- Building Edge Functions\n- Implementing real-time features\n- Troubleshooting Supabase issues\n- Optimizing database queries\n- Setting up type generation\n"},"lastSynced":"2026-03-08T02:03:21.860Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing secure and scalable Supabase integrations with expertise in Row Level Security and authentication.","zh":"非常适合需要安全且可扩展的Supabase集成的全栈代理，特别是具有行级安全和身份验证方面的专业知识。","ja":"セキュアでスケーラブルなSupabase統合を必要とするフルスタックエージェントに最適です。特に、行レベルセキュリティと認証の専門知識を持つエージェント。","ko":"보안 및 확장 가능한 Supabase 통합이 필요한 풀 스택 에이전트에게 적합합니다. 특히 행 수준 보안 및 인증 분야의 전문 지식을 보유한 에이전트에게 적합합니다.","es":"Perfecto para agentes Full Stack que necesitan integraciones de Supabase seguras y escalables con experiencia en Seguridad de Nivel de Fila y autenticación.","fr":"Parfait pour les agents Full Stack qui ont besoin d''intégrations Supabase sécurisées et évolutives avec une expertise en Sécurité au Niveau de la Ligne et en authentification.","de":"Perfekt für Full-Stack-Agents, die sichere und skalierbare Supabase-Integrationen mit Erfahrung in Zeilenberechtigung und Authentifizierung benötigen.","pt":"Perfeito para Agentes Full Stack que necessitam de integrações Supabase seguras e escaláveis com especialização em Segurança em Nível de Linha e autenticação.","ru":"Идеально для полнофункциональных агентов, нуждающихся в безопасных и масштабируемых интеграциях Supabase с опытом работы с Безопасностью на уровне строк и аутентификацией.","ar":"مثالي للوكلاء الكاملون الذين يحتاجون إلى تكاملات Supabase آمنة وقابلة للتوسيع مع خبرة في أمان مستوى الصف وتحقق"},"recommendation":{"en":"Empowers agents to design secure databases with Row Level Security policies, implement robust authentication mechanisms, and leverage Edge Functions for real-time features, all while ensuring type safety with generated TypeScript types.","zh":"赋予代理设计安全的数据库的能力，采用行级安全策略，实施强大的身份验证机制，并利用Edge Functions实现实时功能，同时通过生成的TypeScript类型确保类型安全。","ja":"エージェントが行レベルセキュリティポリシーで安全なデータベースを設計し、強力な認証メカニズムを実装し、Edge Functionsを使用してリアルタイム機能を実現し、生成されたTypeScriptタイプを使用してタイプセーフティを確保することができる。","ko":"에이전트가 행 수준 보안 정책을 사용하여 보안 데이터베이스를 설계하고 강력한 인증 메커니즘을 구현하며 Edge Functions를 사용하여 실시간 기능을 구현하고 생성된 TypeScript 형식을 사용하여 형식 안전을 보장할 수 있습니다.","es":"Habilita a los agentes a diseñar bases de datos seguras con políticas de Seguridad de Nivel de Fila, implementar mecanismos de autenticación robustos y aprovechar las Funciones de Edge para características en tiempo real, todo mientras se garantiza la seguridad de tipos con tipos de TypeScript generados.","fr":"Permet aux agents de concevoir des bases de données sécurisées avec des politiques de Sécurité au Niveau de la Ligne, de mettre en œuvre des mécanismes d''authentification robustes et de tirer parti des Fonctions de Edge pour des fonctionnalités en temps réel, le tout en garantissant la sécurité des types avec des types TypeScript générés.","de":"Ermächtigt Agents, sichere Datenbanken mit Zeilenberechtigungspolitiken zu entwerfen, robuste Authentifizierungsmechanismen zu implementieren und Edge-Funktionen für Echtzeitfunktionen zu nutzen, während die Typsicherheit mit generierten TypeScript-Typen gewährleistet wird.","pt":"Habilita os agentes a projetar bancos de dados seguros com políticas de Segurança em Nível de Linha, implementar mecanismos de autenticação robustos e aproveitar as Funções de Borda para recursos em tempo real, garantindo a segurança de tipo com tipos TypeScript gerados.","ru":"Наделяет агентов возможностью проектировать безопасные базы данных с политиками Безопасности на уровне строк, реализовывать прочные механизмы аутентификации и использовать Функции Края для функций в реальном времени, обеспечивая безопасность типов с помощью сгенерированных типов TypeScript.","ar":"يمنح الوكلاء القدرة على تصميم قواعد بيانات آمنة مع سياسات أمان مستوى الصف ، وتنفيذ آليات التحقق الصلبة ، واستخدام وظائف الحافة للميزات في الوقت الفعلي ، مع ضمان سلامة النوع مع أنواع TypeScript المولدة."},"useCases":{"en":["Designing secure Supabase databases with Row Level Security","Implementing authentication and authorization using service role keys and anon keys","Developing real-time features with Edge Functions and Supabase","Generating TypeScript types for secure and scalable Supabase integrations"],"zh":["使用行级安全设计安全的Supabas