INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Aniket-a14/SRA/supabase-expert', 'supabase-expert', 'Aniket-a14', 'SRA', 'community', 'supabase-expert Aniket-a14 SRA community The supabase-expert skill helps developers build secure and scalable Supabase integrations, focusing on database design, Row Level Security, and authentication. It benefits developers working with Supabase. Supabase集成专家技能帮助开发者构建安全可扩展的Supabase集成，实现Row Level Security、Type Safety和Edge Functions等功能 Supabaseエキスパートスキルは、開発者がセキュアでスケーラブルなSupabase統合を構築し、Row Level Security、Type Safety、Edge Functionsなどの機能を実現するのに役立ちます Supabase 통합 전문가 스킬은 개발자가 보안이 강화되고 확장 가능한 Supabase 통합을 구축하고 Row Level Security, Type Safety, Edge Functions 등의 기능을 구현하는 데 도움이 됩니다 El experto en Supabase ayuda a construir integraciones seguras y escalables. Utiliza esto para diseño de bases de datos, políticas de seguridad de nivel de fila y funciones de borde L''expert Supabase aide à créer des intégrations sécurisées et évolutives. Utilisez-le pour la conception de bases de données, les politiques de sécurité de niveau de ligne et les fonctions de bord Der Supabase-Experte hilft bei der Erstellung sicherer und skalierbarer Integrationen. Verwenden Sie es für Datenbankdesign, Zeilenberechtigungspolicies und Edge-Funktionen O Supabase Expert é um skill que ajuda a construir integrações seguras e escaláveis com o Supabase, utilizando Row Level Security e autenticação Supabase Expert - это навык, который помогает создавать безопасные и масштабируемые интеграции с Supabase, используя RLS и аутентификацию Supabase Expert هو مهارة تساعد على بناء تطبيقات متوافق مع Supabase باستخدام Row Level Security وأمان البيانات how to use supabase-expert supabase-expert setup guide supabase-expert alternative supabase-expert vs prisma supabase-expert install what is supabase-expert supabase-expert tutorial supabase-expert security features supabase-expert database design Supabase集成 Row Level Security Type Safety Edge Functions 数据库设计 AI驱动的软件 Supabase专家 安全可扩展的集成 Enables Row Level Security (RLS) on tables with user data Generates TypeScript types for secure and scalable database design Implements service role key for secure server contexts Uses anon key for client-side operations Tests RLS policies thoroughly for reliable security supabase-expert is a skill that provides AI-powered guidance for building secure and scalable Supabase integrations, emphasizing security and type safety.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AgentArtel/Open-RPG/git-routing', 'community', 'AgentArtel', 'Open-RPG', 'AgentArtel/Open-RPG', 'git-routing', 0, 0, 57, '2026-03-08T01:57:15.340Z', '2026-03-08T02:03:25.913Z', '0de67d36e924e274a7ec489c9550fb7bc8d6af134c7080ed46509f9ef3bb870a', '{"id":"AgentArtel/Open-RPG/git-routing","name":"git-routing","description":{"en":"git-routing standardizes commit messages for AI agent projects, ensuring consistent formatting and clarity. This skill benefits developers working on multi-agent projects.","zh":"Git-Routing 是一个用于多代理项目的提交消息格式，确保代码提交的清晰和一致性","ja":"Git-Routing は、マルチエージェントプロジェクトで使用されるコミットメッセージの形式で、コードの提交を明確かつ一貫性を持たせることを保証します","ko":"Git-Routing은 멀티 에이전트 프로젝트에서 사용되는 커밋 메시지 형식으로 코드 제출의 명확성과 일관성을 보장합니다","es":"git-routing es un estándar para commits en proyectos multiagentes, utilizando un formato de encabezado específico para AGENT, ACTION y TASK.","fr":"git-routing est un standard pour les commits dans les projets multi-agents, utilisant un format d''en-tête spécifique pour AGENT, ACTION et TASK.","de":"git-routing ist ein Standard für Commits in Multiagenten-Projekten, der ein spezifisches Header-Format für AGENT, ACTION und TASK verwendet.","pt":"O git-routing é uma habilidade que permite a configuração de projetos de multi-agentes com um formato de mensagem de commit específico","ru":"git-routing - это навык, который позволяет настраивать проекты с несколькими агентами, используя определенный формат сообщения о коммите","ar":"git-routing هو مهارة يُمكن من خلالها إعداد مشاريع متعددة الوكلاء باستخدام تنسيق رسالة الإلتزام محدد"},"seo":{"title":{"en":"git-routing: Commit Message Standardization for AI Agents...","zh":"Git-Routing 设置指南：多代理项目提交消息格式","ja":"Git-Routing のベストプラクティス：AIエージェントによるコミットメッセージ","ko":"Git-Routing 구현 가이드: 멀티 에이전트 프로젝트 커밋 메시지 형식","es":"Guía de Configuración de git-routing para Agentes de IA","fr":"Configurer git-routing pour les Outils d''IA : Meilleures ...","de":"Einrichtungsleitfaden für git-routing in KI-Agenten","pt":"Guia de Configuração do git-routing para Desenvolvedores","ru":"Настройка git-routing: Лучшие Практики для Разработчиков ...","ar":"دليل إعداد git-routing للطورين: أفضل الممارسات لمنصة العم..."},"description":{"en":"Learn how to standardize commit messages with git-routing. Discover the benefits of consistent formatting for your AI agent projects and get started today!","zh":"了解 Git-Routing 的提交消息格式和多代理项目的最佳实践，提高代码质量和团队协作效率","ja":"Git-Routing を使用して、AIエージェントによるコミットメッセージの書き方とマルチエージェントプロジェクトのベストプラクティスを学びましょう","ko":"Git-Routing을 사용하여 멀티 에이전트 프로젝트의 커밋 메시지 형식과 최고의 관행을 학습하여 코드 품질과 팀 협력을 향상시키세요","es":"Aprende a configurar git-routing para proyectos de multiagentes con este práctico guía. Descubre cómo mejorar tu flujo de trabajo con Agentes de IA.","fr":"Découvrez comment configurer git-routing pour vos projets multi-agents avec cet outil d''IA. Améliorez votre flux de travail avec les meilleures pratiques.","de":"Erfahren Sie, wie Sie git-routing für Ihre Multiagenten-Projekte einrichten. Verbessern Sie Ihren Arbeitsfluss mit KI-Agenten.","pt":"Aprenda a configurar o git-routing para projetos de multi-agentes com o formato de mensagem de commit adequado e valores de AGENTE válidos","ru":"Узнайте, как настроить git-routing для проектов с несколькими агентами, используя правильный формат сообщения о коммите и допустимые значения AGENTE, вместе ...","ar":"تعرف على كيفية إعداد git-routing لمشاريع متعددة الوكلاء باستخدام تنسيق رسالة الإلتزام المناسب وقيم وكيل صالحة"},"definition":{"en":"git-routing is a commit message formatting standard for AI agent projects, using a specific header format with required fields.","zh":"Git-Routing 是一种用于多代理项目的提交消息格式，包括AGENT、ACTION和TASK等字段","ja":"Git-Routing は、マルチエージェントプロジェクトで使用されるコミットメッセージの形式で、AGENT、ACTION、TASK などのフィールドを含みます","ko":"Git-Routing은 멀티 에이전트 프로젝트에서 사용되는 커밋 메시지 형식으로 AGENT, ACTION, TASK 등의 필드를 포함합니다","es":"git-routing es un formato de commit que utiliza un encabezado con AGENT, ACTION y TASK para proyectos de multiagentes.","fr":"git-routing est un format de commit qui utilise un en-tête avec AGENT, ACTION et TASK pour les projets multi-agents.","de":"git-routing ist ein Commit-Format, das ein Header mit AGENT, ACTION und TASK für Multiagenten-Projekte verwendet.","pt":"O git-routing é uma habilidade que define um formato de mensagem de commit para projetos de multi-agentes","ru":"git-routing - это навык, определяющий формат сообщения о коммите для проектов с несколькими агентами","ar":"git-routing هو مهارة تحدد تنسيق رسالة الإلتزام لمشاريع متعددة الوكلاء"},"features":{"en":["Enforces a specific commit message header format with required fields","Supports multiple agent values, including claude, cursor, lovable, and kimi","Requires a short description under 72 characters","Allows for an optional body with details","Uses a standardized format for task IDs and actions"],"zh":["提交消息格式包含AGENT、ACTION和TASK等字段","支持多代理项目的代码提交和管理","确保代码提交的清晰和一致性","AGENT字段支持claude、cursor、lovable和kimi等值","ACTION和TASK字段可以根据项目需要自定义"],"ja":["コミットメッセージの形式には、AGENT、ACTION、TASK などのフィールドが含まれる","マルチエージェントプロジェクトのコードの提交と管理をサポート","コードの提交を明確かつ一貫性を持たせることを保証","AGENTフィールドは、claude、cursor、lovable、kimi などの値をサポート","ACTIONとTASKフィールドは、プロジェクトのニーズに応じてカスタマイズ可能"],"ko":["커밋 메시지 형식에는 AGENT, ACTION, TASK 등의 필드가 포함됨","멀티 에이전트 프로젝트의 코드 제출과 관리를 지원","코드 제출의 명확성과 일관성을 보장","AGENT 필드는 claude, cursor, lovable, kimi 등의 값을 지원","ACTION과 TASK 필드는 프로젝트의 필요에 따라 커스터마이즈할 수 있음"],"es":["Formato de encabezado específico para commits","Soporte para múltiples valores de AGENT (claude, cursor, lovable, kimi)","Requerimiento de campos obligatorios (AGENT, ACTION, TASK)","Límite de 72 caracteres para la descripción corta","Soporte para cuerpos opcionales con detalles"],"fr":["Format d''en-tête spécifique pour les commits","Prise en charge de plusieurs valeurs d''AGENT (claude, cursor, lovable, kimi)","Exigence de champs obligatoires (AGENT, ACTION, TASK)","Limite de 72 caractères pour la description courte","Prise en charge de corps optionnels avec des détails"],"de":["Spezifisches Header-Format für Commits","Unterstützung für mehrere AGENT-Werte (claude, cursor, lovable, kimi)","Erfordernis von obligatorischen Feldern (AGENT, ACTION, TASK)","Begrenzung auf 72 Zeichen für die kurze Beschreibung","Unterstützung für optionale Körper mit Details"],"pt":["Formato de mensagem de commit personalizado","Valores de AGENTE pré-definidos (claude, cursor, lovable, kimi)","Suporte a projetos de multi-agentes","Integração com tecnologias de desenvolvimento de software","Melhoria da colaboração em equipe"],"ru":["Пользовательский формат сообщения о коммите","Предварительно определенные значения AGENTE (claude, cursor, lovable, kimi)","Поддержка проектов с несколькими агентами","Интеграция с технологиями разработки программного обеспечения","Улучшение командной работы"],"ar":["تنسيق رسالة الإلتزام المخصص","قيم وكيل مسبقة التعريف (claude, cursor, lovable, kimi)","دعم مشاريع متعددة الوكلاء","التكامل مع تكنولوجيا تطوير البرمجيات","تحسين التعاون الفريق"]},"keywords":{"en":["how to use git-routing","git-routing setup guide","git-routing alternative","git-routing vs conventional commits","git-routing install","what is git-routing","git-routing for AI agents","standardized commit messages","git-routing best practices"],"zh":["Git-Routing","提交消息格式","多代理项目","代码提交","AGENT","ACTION","TASK","claude","cursor","lovable","kimi"],"ja":["Git-Routing","コミットメッセージ","マルチエージェントプロジェクト","コードの提交","AGENT","ACTION","TASK","claude","cursor","lovable","kimi","AIエージェント"],"ko":["Git-Routing","커밋 메시지 형식","멀티 에이전트 프로젝트","코드 제출","AGENT","ACTION","TASK","claude","cursor","lovable","kimi","AI 에이전트"],"es":["git-routing","Agentes de IA","proyectos multiagentes","formato de commit","AGENT","ACTION","TASK","claude","cursor","lovable","kimi"],"fr":["git-routing","Outils d''IA","projets multi-agents","format de commit","AGENT","ACTION","TASK","claude","cursor","lovable","kimi"],"de":["git-routing","KI-Agenten","Multiagenten-Projekte","Commit-Format","AGENT","ACTION","TASK","claude","cursor","lovable","kimi"],"pt":["git-routing","formato de mensagem de commit","valores de AGENTE","projetos de multi-agentes","desenvolvimento de software","colaboração em equipe","guias de configuração"],"ru":["git-routing","формат сообщения о коммите","значения AGENTE","проекты с несколькими агентами","разработка программного обеспечения","командная работа","настройка ИИ Агентов"],"ar":["git-routing","تنسيق رسالة الإلتزام","قيم وكيل","مشاريع متعددة الوكلاء","تطوير البرمجيات","التعاون الفريق","إعداد وكلاء الذكاء الاصطناعي"]}},"owner":"AgentArtel","repo":"Open-RPG","repoPath":"AgentArtel/Open-RPG","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.340Z","topics":[],"category":"community","skillMd":{"name":"git-routing","description":"Commit message routing rules for multi-agent workflows. Defines the header format, valid values, routing table, and examples for automated agent handoffs.","bodyPreview":"## Commit Message Format\n\nEvery commit in a multi-agent project uses this header format:\n\n```\n[AGENT:agent] [ACTION:action] [TASK:task-id] Short description\n\nOptional body with details.\n```\n\nAll three header fields are required. The short description should be under 72 characters.\n\n## Valid AGENT Values\n\n| Value | Agent | Role |\n|-------|-------|------|\n| `claude` | Claude Code | Orchestrator |\n| `cursor` | Cursor | Implementation Specialist |\n| `lovable` | Lovable | UI/UX Specialist |\n| `kimi`","body":"## Commit Message Format\n\nEvery commit in a multi-agent project uses this header format:\n\n```\n[AGENT:agent] [ACTION:action] [TASK:task-id] Short description\n\nOptional body with details.\n```\n\nAll three header fields are required. The short description should be under 72 characters.\n\n## Valid AGENT Values\n\n| Value | Agent | Role |\n|-------|-------|------|\n| `claude` | Claude Code | Orchestrator |\n| `cursor` | Cursor | Implementation Specialist |\n| `lovable` | Lovable | UI/UX Specialist |\n| `kimi` | Kimi Code | Project Overseer |\n\n## Valid ACTION Values\n\n| Value | Meaning | Who Uses It |\n|-------|---------|-------------|\n| `submit` | Work completed, ready for review | Any agent submitting work |\n| `review` | Review in progress | Reviewer (Kimi or Claude Code) |\n| `approve` | Work approved | Reviewer |\n| `reject` | Work needs changes, feedback provided | Reviewer |\n| `update` | Progress update (not a submission) | Any agent |\n| `report` | Sprint or status report | Kimi or Claude Code |\n| `delegate` | Assigning work to another agent | Kimi or Claude Code |\n| `merge` | Merging approved work to target branch | Kimi or Claude Code |\n\n## Valid TASK Values\n\n| Pattern | When to Use | Example |\n|---------|-------------|---------|\n| Task ID | Standard task work | `TASK-001`, `TASK-P4-01` |\n| Sprint ID | Sprint-level work | `SPRINT-3`, `SPRINT-4` |\n| Category | Non-task work | `INFRA`, `DOCS`, `CLEANUP` |\n\n## Routing Table\n\nThis table defines what should happen after each commit pattern:\n\n| Commit Pattern | What Happens Next |\n|----------------|-------------------|\n| `[AGENT:cursor] [ACTION:submit] [TASK:X]` | Kimi or Claude Code reviews cursor''s work |\n| `[AGENT:lovable] [ACTION:submit] [TASK:X]` | Kimi or Claude Code reviews lovable''s work |\n| `[AGENT:claude] [ACTION:submit] [TASK:X]` | Kimi reviews claude''s work |\n| `[AGENT:kimi] [ACTION:approve] [TASK:X]` | Work merged to `pre-mortal`, next task assigned |\n| `[AGENT:kimi] [ACTION:reject] [TASK:X]` | Agent addresses feedback, re-submits |\n| `[AGENT:kimi] [ACTION:delegate] [TASK:X]` | Target agent picks up assignment |\n| `[AGENT:kimi] [ACTION:report] [SPRINT:X]` | Human PM reviews sprint summary |\n| `[AGENT:kimi] [ACTION:merge] [TASK:X]` | Branch merged to `pre-mortal` |\n| `[AGENT:claude] [ACTION:delegate] [TASK:X]` | Target agent picks up assignment |\n| `[AGENT:*] [ACTION:update] [TASK:X]` | Status tracking only, no action triggered |\n\n## Branch Rules\n\n- Agents commit to their own branch: `<agent>/<task-id>-<description>`\n- Submit commits are made on the agent''s branch\n- Approve and merge commits are made on `pre-mortal`\n- Report commits can be made on any branch\n\n## Examples\n\n### Agent submitting work\n\n```\n[AGENT:cursor] [ACTION:submit] [TASK:TASK-P4-01] Implement gateway API client hook\n\nAdded WebSocket JSON-RPC client with reconnection logic.\nFiles: src/hooks/use-gateway-api.ts, src/services/openclaw-client.ts\n```\n\n### Reviewer approving work\n\n```\n[AGENT:kimi] [ACTION:approve] [TASK:TASK-P4-01] Gateway API client approved\n\nAll acceptance criteria met. Merging to pre-mortal.\nUnblocks: TASK-P4-02, TASK-P4-03\n```\n\n### Reviewer requesting changes\n\n```\n[AGENT:kimi] [ACTION:reject] [TASK:TASK-P4-01] Error handling needs improvement\n\nMissing timeout handling on WebSocket reconnection.\nSee .ai/reviews/TASK-P4-01-review.md for details.\n```\n\n### Progress update\n\n```\n[AGENT:claude] [ACTION:update] [TASK:TASK-002] Enrich ideas with research findings\n\nUpdated 18 idea files with feasibility ratings and roadmap phases.\n```\n\n### Sprint report\n\n```\n[AGENT:kimi] [ACTION:report] [SPRINT:3] Sprint 3 complete — 8 tasks done\n\nSee .ai/reports/sprint-3-summary.md for full details.\n```\n\n### Delegating work\n\n```\n[AGENT:kimi] [ACTION:delegate] [TASK:TASK-P4-02] Assign agent CRUD sync to Cursor\n\nSee .ai/instructions/cursor-TASK-P4-02.md for assignment details.\n```\n\n### Merging approved work\n\n```\n[AGENT:kimi] [ACTION:merge] [TASK:TASK-P4-01] Merge gateway client to pre-mortal\n\nApproved in .ai/reviews/TASK-P4-01-review.md\n```\n\n## Reference\n\nFull routing specification with additional details: `.ai/templates/commit-message.md`\n\n"},"lastSynced":"2026-03-08T02:03:25.913Z","agentAnalysis":{"suitability":{"en":"Perfect for Multi-Agent Project Managers needing standardized commit message formatting.","zh":"非常适合需要标准化提交消息格式的多代理项目经理。","ja":"標準化されたコミットメッセージ形式を必要とするマルチエージェントプロジェクトマネージャーに最適です。","ko":"표준화된 커밋 메시지 형식을 필요로 하는 멀티 에이전트 프로젝트 매니저에게 적합합니다.","es":"Perfecto para Gerentes de Proyectos de Multi-Agente que necesitan un formato de mensaje de confirmación estandarizado.","fr":"Parfait pour les gestionnaires de projets multi-agents ayant besoin d''un format de message de validation standardisé.","de":"Perfekt für Multi-Agenten-Projektmanager, die ein standardisiertes Commit-Nachrichten-Format benötigen.","pt":"Perfeito para Gerentes de Projetos de Múltiplos Agentes que precisam de formatação de mensagens de commit padronizadas.","ru":"Идеально подходит для менеджеров проектов с множеством агентов, которым требуются стандартизированные форматы сообщений о коммитах.","ar":"مثالي لمدربي مشاريع وكلاء المتعددين الذين يحتاجون إلى تنسيق رسائل الالتزام المعيارية."},"recommendation":{"en":"Empowers agents to maintain consistent commit history using a standardized header format, including AGENT, ACTION, and TASK fields, ensuring clarity and readability in git repositories, with support for agents like Claude Code, Cursor, and Lovable.","zh":"赋予代理维护一致的提交历史记录，使用标准化的头部格式，包括AGENT、ACTION和TASK字段，确保git仓库中的清晰度和可读性，并支持诸如Claude Code、Cursor和Lovable等代理。","ja":"エージェントに、AGENT、ACTION、TASKフィールドを含む標準化されたヘッダーフォーマットを使用して一貫したコミット履歴を維持することを可能にし、Gitリポジトリの明確性と可読性を確保し、Claude Code、Cursor、Lovableなどのエージェントをサポートします。","ko":"에이전트가 AGENT, ACTION, TASK 필드를 포함한 표준화된 헤더 형식을 사용하여 일관된 커밋 기록을 유지할 수 있도록 하며, git 저장소의 명확성과 가독성을 보장하며 Claude Code, Cursor, Lovable 등의 에이전트를 지원합니다.","es":"Habilita a los agentes a mantener un historial de confirmación coherente utilizando un formato de encabezado estandarizado, que incluye los campos AGENT, ACTION y TASK, lo que garantiza la claridad y la legibilidad en los repositorios git, con soporte para agentes como Claude Code, Cursor y Lovable.","fr":"Permet aux agents de maintenir un historique de validation cohérent en utilisant un format d''en-tête standardisé, comprenant les champs AGENT, ACTION et TASK, garantissant ainsi la clarté et la lisibilité dans les référentiels git, avec une prise en charge pour les agents tels que Claude Code, Cursor et Lovable.","de":"Ermächtigt Agenten, ein konsistentes Commit-Verlauf aufrechtzuerhalten, indem ein standardisierter Header-Format verwendet wird, einschließlich der Felder AGENT, ACTION und TASK, was Klarheit und Lesbarkeit in git-Repositorys gewährleistet, mit Unterstützung für Agenten wie Claude Code, Cursor und Lovable.","pt":"Habilita os agentes a manter um histórico de commit consistente usando um formato de cabeçalho padronizado, incluindo campos AGENT, ACTION e TASK, garantindo clareza e legibilidade nos repositórios git, com suporte a agentes como Claude Code, Cursor e Lovable.","ru":"Наделяет агентов возможностью поддерживать последовательную историю коммитов с помощью стандартизированного формата заголовка, включая поля AGENT, ACTION и TASK, обеспечивая ясность и читаемость в репозиториях git, с поддержкой агентов như Claude Code, Cursor и Lovable.","ar":"تمكّن الوكلاء من الحفاظ على سجل التزامات متسق باستخدام تنسيق رأس معياري، بما في ذلك حقول AGENT و ACTION و TASK، مما يضمن الوضوح والقراءة في مستودعات جيت، مع دعم وكلاء مثل Claude Code و Cursor و Lovable."},"useCases":{"en":["Standardizing commit messages for multi-agent projects","Automating commit message formatting for consistent clarity","Debugging commit history using standardized TASK and ACTION fields"],"zh":["为多代理项目标准化提交消息","自动化提交消息格式以实现一致的清晰度","使用标准化的TASK和ACTION字段调试提交历史记录"],"ja":["マルチエージェントプロジェクトのコミットメッセージを標準化する","一貫した明確性を実現するためにコミットメッセージのフォーマットを自動化する","標準化されたTASKとACTIONフィールドを使用してコミット履歴をデバッグする"],"ko":["멀티 에이전트 프로젝트의 커밋 메시지를 표준화하는 것","일관된 명확성을实现하기 위해 커밋 메시지 형식을 자동화하는 것","표준화된 TASK 및 ACTION 필드를 사용하여 커밋 기록을 디버깅하는 것"],"es":["Estandarizar los mensajes de confirmación para proyectos multi-agente","Automatizar el formato de los mensajes de confirmación para una claridad coherente","Depurar el historial de confirmación utilizando los campos TASK y ACTION estandarizados"],"fr":["Standardiser les messages de validation pour les projets multi-agents","Automatiser le format des messages de validation pour une clarté cohérente","Déboguer l''historique de validation en utilisant les champs TASK et ACTION standardisés"],"de":["Standardisieren von Commit-Nachrichten für Multi-Agenten-Projekte","Automatisieren des Commit-Nachrichten-Formats für eine konsistente Klarheit","Debuggen des Commit-Verlaufs unter Verwendung der standardisierten TASK- und ACTION-Felder"],"pt":["Padronizar mensagens de commit para projetos de múltiplos agentes","Automatizar a formatação de mensagens de commit para clareza consistente","Depurar o histórico de commit usando campos TASK e ACTION padronizados"],"ru":["Стандартизировать сообщения о коммитах для проектов с множеством агентов","Автоматизировать форматирование сообщений о коммитах для последовательной ясности","Отладить историю коммитов с помощью полей TASK и ACTION"],"ar":["تقييس رسائل الالتزام لمشاريع وكلاء المتعددين","تأتمتة تنسيق رسائل الالتزام للوضوح المتسق","تصحيح أخطاء سجل الالتزام باستخدام حقول TASK و ACTION المعيارية"]},"limitations":{"en":["Requires adherence to the specified commit message header format","Limited to the defined set of valid AGENT values, including ''claude'', ''cursor'', and ''lovable''"],"zh":["需要遵守指定的提交消息头格式","仅限于定义的有效AGENT值，包括''claude''、''cursor''和''lovable''"],"ja":["指定されたコミットメッセージヘッダーフォーマットに従う必要がある","定義された有効なAGENT値に限定され、''claude''、''cursor''、''lovable''など"],"ko":["지정된 커밋 메시지 헤더 형식에 따라야 함","정의된 유효한 에이전트 값에 제한되며 ''claude'', ''cursor'', ''lovable'' 등"],"es":["Requiere la adhesión al formato de encabezado de mensaje de confirmación especificado","Limitado al conjunto definido de valores AGENT válidos, incluyendo ''claude'', ''cursor'' y ''lovable''"],"fr":["Nécessite l''adhésion au format d''en-tête de message de validation spécifié","Limité à l''ensemble défini de valeurs AGENT valides, comprenant ''claude'', ''cursor'' et ''lovable''"],"de":["Erfordert die Einhaltung des angegebenen Commit-Nachrichten-Header-Formats","Begrenzt auf die definierte Menge gültiger AGENT-Werte, einschließlich ''claude'', ''cursor'' und ''lovable''"],"pt":["Exige aderência ao formato de cabeçalho de mensagem de commit especificado","Limitado ao conjunto definido de valores AGENT válidos, incluindo ''claude'', ''cursor'' e ''lovable''"],"ru":["Требует соблюдения указанного формата заголовка сообщения о коммите","Ограничен определенным набором допустимых значений AGENT, включая ''claude'', ''cursor'' и ''lovable''"],"ar":["يتطلب الالتزام بتنسيق رأس رسالة الالتزام المحدد","محدود بمجموعة محددة من قيم AGENT الصالحة، بما في ذلك ''claude'' و ''cursor'' و ''lovable''"]},"version":4},"contentHash":"0de67d36e924e274a7ec489c9550fb7bc8d6af134c7080ed46509f9ef3bb870a","qualityScore":57}');
