INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AgentArtel/Open-RPG/git-routing', 'git-routing', 'AgentArtel', 'Open-RPG', 'community', 'git-routing AgentArtel Open-RPG community git-routing standardizes commit messages for AI agent projects, ensuring consistent formatting and clarity. This skill benefits developers working on multi-agent projects. Git-Routing 是一个用于多代理项目的提交消息格式，确保代码提交的清晰和一致性 Git-Routing は、マルチエージェントプロジェクトで使用されるコミットメッセージの形式で、コードの提交を明確かつ一貫性を持たせることを保証します Git-Routing은 멀티 에이전트 프로젝트에서 사용되는 커밋 메시지 형식으로 코드 제출의 명확성과 일관성을 보장합니다 git-routing es un estándar para commits en proyectos multiagentes, utilizando un formato de encabezado específico para AGENT, ACTION y TASK. git-routing est un standard pour les commits dans les projets multi-agents, utilisant un format d''en-tête spécifique pour AGENT, ACTION et TASK. git-routing ist ein Standard für Commits in Multiagenten-Projekten, der ein spezifisches Header-Format für AGENT, ACTION und TASK verwendet. O git-routing é uma habilidade que permite a configuração de projetos de multi-agentes com um formato de mensagem de commit específico git-routing - это навык, который позволяет настраивать проекты с несколькими агентами, используя определенный формат сообщения о коммите git-routing هو مهارة يُمكن من خلالها إعداد مشاريع متعددة الوكلاء باستخدام تنسيق رسالة الإلتزام محدد how to use git-routing git-routing setup guide git-routing alternative git-routing vs conventional commits git-routing install what is git-routing git-routing for AI agents standardized commit messages git-routing best practices Git-Routing 提交消息格式 多代理项目 代码提交 AGENT ACTION TASK claude cursor lovable kimi Enforces a specific commit message header format with required fields Supports multiple agent values, including claude, cursor, lovable, and kimi Requires a short description under 72 characters Allows for an optional body with details Uses a standardized format for task IDs and actions git-routing is a commit message formatting standard for AI agent projects, using a specific header format with required fields.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('0mar2090/hotelchavin/security-quality-guard', 'community', '0mar2090', 'hotelchavin', '0mar2090/hotelchavin', 'security-quality-guard', 0, 0, 57, '2026-03-08T01:57:15.341Z', '2026-03-08T02:03:28.479Z', '2aacfe73b10d1ecf2e946f72c7e795409d91a44641bb28a3c7f7062be8c27610', '{"id":"0mar2090/hotelchavin/security-quality-guard","name":"security-quality-guard","description":{"en":"The security-quality-guard skill acts as a code auditor and security enforcer for modern React/Next.js applications, utilizing Biome for linting and formatting. It benefits developers by ensuring code quality and security.","zh":"Security-Quality-Guard 是一个 React/Next.js 代码审计和安全工具，使用 Biome 进行 linting 和 formateo","ja":"Security-Quality-Guard は React/Next.js コード監査とセキュリティツールです。Biome を使用して linting と formateo を実行します","ko":"Security-Quality-Guard는 React/Next.js 코드 감사 및 보안 도구입니다. Biome를 사용하여 linting 및 formateo를 수행합니다","es":"Security-Quality-Guard es una herramienta de auditoría de código y seguridad para aplicaciones React/Next.js modernas que utiliza Biome para linting y formateo.","fr":"Security-Quality-Guard est un outil d''audit de code et de sécurité pour les applications React/Next.js modernes qui utilise Biome pour le linting et le formattage.","de":"Security-Quality-Guard ist ein Tool für die Code- und Sicherheitsprüfung von modernen React/Next.js-Anwendungen, das Biome für Linting und Formatierung verwendet.","pt":"O Security-Quality-Guard é uma ferramenta de auditoria de código e segurança para aplicativos React/Next.js modernos, utilizando Biome para linting e formatação.","ru":"Security-Quality-Guard — это инструмент аудита кода и безопасности для современных приложений React/Next.js, использующий Biome для линтинга и форматирования.","ar":"أداة الأمان والجودة Security-Quality-Guard هي أداة تدقيق شفرة وأمان لتطبيقات React/Next.js الحديثة، وتستخدم Biome لتحليل الشفرة وتشكيلها."},"seo":{"title":{"en":"security-quality-guard: Biome Linting Setup Guide | AI Ag...","zh":"Security-Quality-Guard 设置指南：React/Next.js 代码审计和安全","ja":"Security-Quality-Guard セットアップガイド：React/Next.js コード監査とセキュリティ","ko":"Security-Quality-Guard 설정 가이드: React/Next.js 코드 감사 및 보안","es":"Guía de Configuración de Security-Quality-Guard para Reac...","fr":"Guide de Configuration de Security-Quality-Guard pour Rea...","de":"Konfigurationsleitfaden für Security-Quality-Guard in Rea...","pt":"Guia de Configuração do Security-Quality-Guard para React...","ru":"Настройка Security-Quality-Guard для React/Next.js: Лучши...","ar":"إعداد أداة الأمان والجودة Security-Quality-Guard لReact/N..."},"description":{"en":"Discover how security-quality-guard enforces code security and quality for React/Next.js apps using Biome. Learn how to configure Biome for optimal linting a...","zh":"使用 Security-Quality-Guard 实现 React/Next.js 代码审计和安全，遵循 Biome 规则，pnpm biome check --apply","ja":"Security-Quality-Guard を使用して React/Next.js コード監査とセキュリティを実現します。Biome ルールに従い、pnpm biome check --apply","ko":"Security-Quality-Guard를 사용하여 React/Next.js 코드 감사 및 보안을 구현합니다. Biome 규칙을 따르고, pnpm biome check --apply","es":"Aprende a configurar Security-Quality-Guard para mejorar la seguridad y calidad de tus aplicaciones React/Next.js con Biome","fr":"Découvrez comment configurer Security-Quality-Guard pour améliorer la sécurité et la qualité de vos applications React/Next.js avec Biome","de":"Erfahren Sie, wie Sie Security-Quality-Guard konfigurieren, um die Sicherheit und Qualität Ihrer React/Next.js-Anwendungen mit Biome zu verbessern","pt":"Aprenda a configurar o Security-Quality-Guard para melhorar a segurança e qualidade do seu código React/Next.js com Biome","ru":"Узнайте, как настроить Security-Quality-Guard для повышения безопасности и качества вашего кода React/Next.js с помощью Biome","ar":"تعلم كيفية إعداد أداة الأمان والجودة Security-Quality-Guard لتحسين أمان وجودة رمزك React/Next.js مع Biome"},"definition":{"en":"security-quality-guard is a code auditing and security enforcement skill for React/Next.js applications, leveraging Biome for linting and formatting","zh":"Security-Quality-Guard 是一个 AI 에ージェント，用于 React/Next.js 代码审计和安全","ja":"Security-Quality-Guard は React/Next.js コード監査とセキュリティのための AI エージェントです","ko":"Security-Quality-Guard는 React/Next.js 코드 감사 및 보안을 위한 AI 에이전트입니다","es":"Security-Quality-Guard es una herramienta de seguridad y calidad que actúa como auditor de código para aplicaciones React/Next.js","fr":"Security-Quality-Guard est un outil de sécurité et de qualité qui agit comme un auditeur de code pour les applications React/Next.js","de":"Security-Quality-Guard ist ein Sicherheits- und Qualitäts-Tool, das als Code-Auditor für React/Next.js-Anwendungen fungiert","pt":"O Security-Quality-Guard é uma ferramenta de auditoria de código que utiliza Biome para garantir a qualidade e segurança de aplicativos React/Next.js","ru":"Security-Quality-Guard — это инструмент аудита кода, использующий Biome для обеспечения качества и безопасности приложений React/Next.js","ar":"أداة الأمان والجودة Security-Quality-Guard هي أداة تدقيق شفرة تستخدم Biome لضمان جودة وأمان تطبيقات React/Next.js"},"features":{"en":["Uses Biome as the sole linting and formatting tool","Configures Biome via biome.json","Runs commands like `pnpm biome check --apply` for automated fixes","Replaces ESLint and Prettier for streamlined code quality management","Enforces consistent code formatting through Biome''s rules"],"zh":["使用 Biome 进行 linting 和 formateo","支持 pnpm biome check --apply","配置 Biome 在 biome.json","不使用 ESLint、Prettier 等其他 linting 工具","仅使用 Biome 作为唯一的 linting 和 formateo 工具"],"ja":["Biome を使用して linting と formateo を実行","pnpm biome check --apply をサポート","Biome を biome.json で構成","ESLint、Prettier などの他の linting ツールを使用しない","Biome を唯一の linting と formateo ツールとして使用"],"ko":["Biome를 사용하여 linting 및 formateo를 수행","pnpm biome check --apply 지원","Biome를 biome.json에서 구성","ESLint, Prettier 등 다른 linting 도구를 사용하지 않음","Biome를唯一의 linting 및 formateo 도구로 사용"],"es":["Linting y formateo con Biome","Configuración de Biome en biome.json","Uso de comandos de fix con pnpm biome check --apply","Compatibilidad con aplicaciones React/Next.js modernas","Reemplazo de ESLint y Prettier con Biome"],"fr":["Linting et formattage avec Biome","Configuration de Biome dans biome.json","Utilisation de commandes de correction avec pnpm biome check --apply","Compatibilité avec les applications React/Next.js modernes","Remplacement d''ESLint et Prettier par Biome"],"de":["Linting und Formatierung mit Biome","Konfiguration von Biome in biome.json","Verwendung von Korrekturkommandos mit pnpm biome check --apply","Kompatibilität mit modernen React/Next.js-Anwendungen","Ersetzung von ESLint und Prettier durch Biome"],"pt":["Utiliza Biome para linting e formatação","Substitui ESLint e Prettier","Configuração personalizada em biome.json","Comandos de fix com `pnpm biome check --apply`","Integração com React e Next.js"],"ru":["Использует Biome для линтинга и форматирования","Заменяет ESLint и Prettier","Пользовательская конфигурация в biome.json","Команды фикса с `pnpm biome check --apply`","Интеграция с React и Next.js"],"ar":["تستخدم Biome لتحليل الشفرة وتشكيلها","تحل محل ESLint و Prettier","التكوين المخصص في biome.json","أوامر الإصلاح مع `pnpm biome check --apply`","التكامل مع React و Next.js"]},"keywords":{"en":["how to use security-quality-guard","security-quality-guard vs ESLint","Biome linting setup guide","security-quality-guard install","what is security-quality-guard","security-quality-guard alternative","security-quality-guard setup for React","Biome configuration for Next.js","security-quality-guard best practices"],"zh":["Security-Quality-Guard","React/Next.js 代码审计","Biome linting","pnpm biome check --apply","代码安全","AI 에ージェント","代码监査"],"ja":["Security-Quality-Guard","React/Next.js コード監査","Biome linting","pnpm biome check --apply","コードセキュリティ","AI エージェント","コード監査"],"ko":["Security-Quality-Guard","React/Next.js 코드 감사","Biome linting","pnpm biome check --apply","코드 보안","AI 에이전트","코드 감사"],"es":["Security-Quality-Guard","Biome","React","Next.js","linting","formateo","seguridad","calidad","desarrollo de aplicaciones"],"fr":["Security-Quality-Guard","Biome","React","Next.js","linting","formattage","sécurité","qualité","développement d''applications"],"de":["Security-Quality-Guard","Biome","React","Next.js","Linting","Formatierung","Sicherheit","Qualität","Anwendungs-Entwicklung"],"pt":["Security-Quality-Guard","Biome","React","Next.js","linting","formatação","segurança","qualidade","desenvolvimento web"],"ru":["Security-Quality-Guard","Biome","React","Next.js","линтинг","форматирование","безопасность","качество","веб-разработка"],"ar":["أداة الأمان والجودة","Biome","React","Next.js","تحليل الشفرة","تشكيل","أمان","جودة","تطوير الويب"]}},"owner":"0mar2090","repo":"hotelchavin","repoPath":"0mar2090/hotelchavin","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.341Z","topics":[],"category":"community","skillMd":{"name":"security-quality-guard","description":"Guardián de Calidad (Linting & Auth) - Auditor de código y seguridad","bodyPreview":"# Security & Quality Guard\n\nActúa como auditor de código y seguridad para aplicaciones React/Next.js modernas.\n\n## Linting con Biome\n\n**Olvida ESLint/Prettier.** Sigue las reglas de **Biome** para linting y formateo.\n\n### Reglas de Linting:\n- ✅ Usa **Biome** como única herramienta de linting y formateo\n- ✅ Si generas comandos de fix, usa: `pnpm biome check --apply`\n- ❌ NO uses ESLint, Prettier ni otras herramientas de linting\n- ✅ Configura Biome en `biome.json`\n\n### Comandos de Biome:\n```bash\n#","body":"# Security & Quality Guard\n\nActúa como auditor de código y seguridad para aplicaciones React/Next.js modernas.\n\n## Linting con Biome\n\n**Olvida ESLint/Prettier.** Sigue las reglas de **Biome** para linting y formateo.\n\n### Reglas de Linting:\n- ✅ Usa **Biome** como única herramienta de linting y formateo\n- ✅ Si generas comandos de fix, usa: `pnpm biome check --apply`\n- ❌ NO uses ESLint, Prettier ni otras herramientas de linting\n- ✅ Configura Biome en `biome.json`\n\n### Comandos de Biome:\n```bash\n# Verificar código\npnpm biome check .\n\n# Aplicar fixes automáticos\npnpm biome check --apply .\n\n# Solo formatear\npnpm biome format --write .\n\n# Solo lint\npnpm biome lint --apply .\n\n# CI mode (sin escribir cambios)\npnpm biome ci .\n```\n\n### Configuración Recomendada de Biome:\n```json\n{\n  \"$schema\": \"https://biomejs.dev/schemas/1.5.3/schema.json\",\n  \"organizeImports\": {\n    \"enabled\": true\n  },\n  \"linter\": {\n    \"enabled\": true,\n    \"rules\": {\n      \"recommended\": true,\n      \"correctness\": {\n        \"noUnusedVariables\": \"error\",\n        \"useExhaustiveDependencies\": \"warn\"\n      },\n      \"suspicious\": {\n        \"noExplicitAny\": \"error\",\n        \"noArrayIndexKey\": \"warn\"\n      },\n      \"style\": {\n        \"noNonNullAssertion\": \"warn\",\n        \"useImportType\": \"error\"\n      }\n    }\n  },\n  \"formatter\": {\n    \"enabled\": true,\n    \"formatWithErrors\": false,\n    \"indentStyle\": \"space\",\n    \"indentWidth\": 2,\n    \"lineWidth\": 100\n  },\n  \"javascript\": {\n    \"formatter\": {\n      \"quoteStyle\": \"single\",\n      \"trailingComma\": \"all\",\n      \"semicolons\": \"asNeeded\",\n      \"arrowParentheses\": \"asNeeded\"\n    }\n  },\n  \"files\": {\n    \"ignore\": [\n      \"node_modules\",\n      \".next\",\n      \"dist\",\n      \"build\",\n      \".turbo\"\n    ]\n  }\n}\n```\n\n## Autenticación y Seguridad\n\nProtege las rutas usando **Clerk** (o **Auth.js**). Verifica siempre `auth()` en Server Components antes de devolver datos sensibles.\n\n### Reglas de Autenticación:\n- ✅ **SIEMPRE** verifica autenticación en Server Components que manejan datos sensibles\n- ✅ Usa `auth()` de Clerk o `getServerSession()` de Auth.js\n- ✅ Retorna `null` o redirect si no hay usuario autenticado\n- ✅ Verifica permisos/roles antes de operaciones críticas\n- ❌ NUNCA expongas datos sensibles sin verificar autenticación\n\n### Ejemplo con Clerk:\n```typescript\n// app/dashboard/page.tsx\nimport { auth } from ''@clerk/nextjs''\nimport { redirect } from ''next/navigation''\n\nexport default async function DashboardPage() {\n  const { userId } = auth()\n  \n  if (!userId) {\n    redirect(''/sign-in'')\n  }\n  \n  // Ahora es seguro obtener datos del usuario\n  const userData = await getUserData(userId)\n  \n  return <Dashboard data={userData} />\n}\n```\n\n### Ejemplo con Server Actions:\n```typescript\n// actions/users.ts\n\"use server\"\n\nimport { auth } from ''@clerk/nextjs''\nimport { revalidatePath } from ''next/cache''\n\nexport async function updateUserProfile(data: UpdateProfileData) {\n  const { userId } = auth()\n  \n  if (!userId) {\n    throw new Error(''No autenticado'')\n  }\n  \n  // Verificar que el usuario solo puede actualizar su propio perfil\n  if (data.userId !== userId) {\n    throw new Error(''No autorizado'')\n  }\n  \n  const updatedUser = await db.user.update({\n    where: { id: userId },\n    data,\n  })\n  \n  revalidatePath(''/profile'')\n  return updatedUser\n}\n```\n\n### Middleware de Protección de Rutas:\n```typescript\n// middleware.ts\nimport { authMiddleware } from ''@clerk/nextjs''\n\nexport default authMiddleware({\n  // Rutas públicas\n  publicRoutes: [''/'', ''/about'', ''/pricing''],\n  \n  // Rutas que requieren autenticación\n  // Por defecto, todas las demás rutas están protegidas\n})\n\nexport const config = {\n  matcher: [''/((?!.+\\\\.[\\\\w]+$|_next).*)'', ''/'', ''/(api|trpc)(.*)''],\n}\n```\n\n### API Routes Seguras:\n```typescript\n// app/api/users/route.ts\nimport { auth } from ''@clerk/nextjs''\nimport { NextResponse } from ''next/server''\n\nexport async function GET() {\n  const { userId } = auth()\n  \n  if (!userId) {\n    return NextResponse.json(\n      { error: ''No autorizado'' },\n      { status: 401 }\n    )\n  }\n  \n  const users = await getUsers(userId)\n  return NextResponse.json(users)\n}\n\nexport async function POST(req: Request) {\n  const { userId } = auth()\n  \n  if (!userId) {\n    return NextResponse.json(\n      { error: ''No autorizado'' },\n      { status: 401 }\n    )\n  }\n  \n  const body = await req.json()\n  \n  // Validar con Zod\n  const result = userSchema.safeParse(body)\n  if (!result.success) {\n    return NextResponse.json(\n      { error: ''Datos inválidos'', details: result.error },\n      { status: 400 }\n    )\n  }\n  \n  const newUser = await createUser(userId, result.data)\n  return NextResponse.json(newUser, { status: 201 })\n}\n```\n\n## TypeScript Estricto\n\nUsa **TypeScript 5+**. **No uses `any`**. Usa `unknown` si es necesario y define interfaces estrictas para todas las props y respuestas de API.\n\n### Reglas de TypeScript:\n- ✅ Usa TypeScript 5+ con `strict: true`\n- ❌ **NUNCA** uses `any` - esto es inaceptable\n- ✅ Usa `unknown` cuando realmente no conoces el tipo\n- ✅ Define interfaces/types para todas las props de componentes\n- ✅ Define tipos para todas las respuestas de API\n- ✅ Usa `satisfies` para type narrowing sin perder inferencia\n- ✅ Habilita reglas estrictas: `noUncheckedIndexedAccess`, `noImplicitAny`, etc.\n\n### tsconfig.json Recomendado:\n```json\n{\n  \"compilerOptions\": {\n    \"target\": \"ES2022\",\n    \"lib\": [\"ES2023\", \"DOM\", \"DOM.Iterable\"],\n    \"jsx\": \"preserve\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"resolveJsonModule\": true,\n    \"allowJs\": true,\n    \"strict\": true,\n    \"noUncheckedIndexedAccess\": true,\n    \"noImplicitAny\": true,\n    \"strictNullChecks\": true,\n    \"strictFunctionTypes\": true,\n    \"noImplicitThis\": true,\n    \"alwaysStrict\": true,\n    \"noUnusedLocals\": true,\n    \"noUnusedParameters\": true,\n    \"noFallthroughCasesInSwitch\": true,\n    \"esModuleInterop\": true,\n    \"skipLibCheck\": true,\n    \"forceConsistentCasingInFileNames\": true,\n    \"isolatedModules\": true,\n    \"incremental\": true,\n    \"paths\": {\n      \"@/*\": [\"./src/*\"]\n    },\n    \"plugins\": [\n      {\n        \"name\": \"next\"\n      }\n    ]\n  },\n  \"include\": [\"next-env.d.ts\", \"**/*.ts\", \"**/*.tsx\", \".next/types/**/*.ts\"],\n  \"exclude\": [\"node_modules\"]\n}\n```\n\n### Ejemplos de Tipos Correctos:\n\n#### ❌ INCORRECTO:\n```typescript\n// ❌ NO: Uso de any\nfunction processData(data: any) {\n  return data.map((item: any) => item.value)\n}\n\n// ❌ NO: Props sin tipo\nfunction Button({ label, onClick }) {\n  return <button onClick={onClick}>{label}</button>\n}\n\n// ❌ NO: Respuesta de API sin tipo\nasync function fetchUser(id: string) {\n  const res = await fetch(`/api/users/${id}`)\n  return res.json() // tipo: any\n}\n```\n\n#### ✅ CORRECTO:\n```typescript\n// ✅ SÍ: Tipos explícitos\ninterface DataItem {\n  id: string\n  value: number\n}\n\nfunction processData(data: DataItem[]): number[] {\n  return data.map(item => item.value)\n}\n\n// ✅ SÍ: Props tipadas\ninterface ButtonProps {\n  label: string\n  onClick: () => void\n  variant?: ''primary'' | ''secondary''\n  disabled?: boolean\n}\n\nfunction Button({ label, onClick, variant = ''primary'', disabled }: ButtonProps) {\n  return <button onClick={onClick} disabled={disabled}>{label}</button>\n}\n\n// ✅ SÍ: Respuesta de API tipada\ninterface User {\n  id: string\n  name: string\n  email: string\n}\n\nasync function fetchUser(id: string): Promise<User> {\n  const res = await fetch(`/api/users/${id}`)\n  if (!res.ok) throw new Error(''Failed to fetch user'')\n  return res.json() as Promise<User>\n}\n\n// ✅ MEJOR: Con validación runtime\nimport { z } from ''zod''\n\nconst userSchema = z.object({\n  id: z.string(),\n  name: z.string(),\n  email: z.string().email(),\n})\n\ntype User = z.infer<typeof userSchema>\n\nasync function fetchUser(id: string): Promise<User> {\n  const res = await fetch(`/api/users/${id}`)\n  if (!res.ok) throw new Error(''Failed to fetch user'')\n  const data = await res.json()\n  return userSchema.parse(data) // Validación runtime + type safety\n}\n```\n\n### Uso Correcto de `unknown`:\n```typescript\n// ✅ SÍ: unknown cuando realmente no conoces el tipo\nfunction handleError(error: unknown) {\n  if (error instanceof Error) {\n    console.error(error.message)\n  } else if (typeof error === ''string'') {\n    console.error(error)\n  } else {\n    console.error(''Error desconocido'', error)\n  }\n}\n\n// ✅ SÍ: Type guards\nfunction isUser(value: unknown): value is User {\n  return (\n    typeof value === ''object'' &&\n    value !== null &&\n    ''id'' in value &&\n    ''name'' in value &&\n    ''email'' in value\n  )\n}\n\nfunction processUserData(data: unknown) {\n  if (isUser(data)) {\n    // Ahora TypeScript sabe que data es User\n    console.log(data.name)\n  }\n}\n```\n\n### React Server Components con TypeScript:\n```typescript\n// ✅ SÍ: Props tipadas en Server Components\ninterface PageProps {\n  params: { id: string }\n  searchParams: { filter?: string }\n}\n\nexport default async function UserPage({ params, searchParams }: PageProps) {\n  const user = await fetchUser(params.id)\n  return <UserProfile user={user} filter={searchParams.filter} />\n}\n\n// ✅ SÍ: generateMetadata tipado\nimport type { Metadata } from ''next''\n\nexport async function generateMetadata({ params }: PageProps): Promise<Metadata> {\n  const user = await fetchUser(params.id)\n  return {\n    title: user.name,\n    description: `Perfil de ${user.name}`,\n  }\n}\n```\n\n## Imports Absolutos\n\nPrefiere **imports absolutos** usando el alias `@/` en lugar de imports relativos.\n\n### Reglas de Imports:\n- ✅ Usa `@/components/...` en lugar de `../../../components/...`\n- ✅ Configura `paths` en `tsconfig.json`\n- ✅ Organiza imports: externos primero, luego internos, luego tipos\n- ✅ Usa `import type` para imports solo de tipos (Biome lo forzará)\n\n### ❌ INCORRECTO:\n```typescript\nimport Button from ''../../../components/ui/Button''\nimport { useUser } from ''../../hooks/useUser''\nimport { formatDate } from ''../../../lib/utils''\n```\n\n### ✅ CORRECTO:\n```typescript\n// Externos primero\nimport { useState } from ''react''\nimport { useQuery } from ''@tanstack/react-query''\n\n// Internos con @/ alias\nimport { Button } from ''@/components/ui/Button''\nimport { useUser } from ''@/hooks/useUser''\nimport { formatDate } from ''@/lib/utils''\n\n// Tipos al final con import type\nimport type { User } from ''@/types/user''\n```\n\n### Configuración de Path Aliases:\n```json\n// tsconfig.json\n{\n  \"compilerOptions\": {\n    \"baseUrl\": \".\",\n    \"paths\": {\n      \"@/*\": [\"./src/*\"],\n      \"@/components/*\": [\"./src/components/*\"],\n      \"@/lib/*\": [\"./src/lib/*\"],\n      \"@/hooks/*\": [\"./src/hooks/*\"],\n      \"@/types/*\": [\"./src/types/*\"]\n    }\n  }\n}\n```\n\n## Checklist de Auditoría de Código\n\nAntes de considerar código como \"listo\", verifica:\n\n### ✅ Linting & Formateo\n- [ ] `pnpm biome check --apply .` ejecutado sin errores\n- [ ] No hay warnings críticos de Biome\n- [ ] Imports organizados correctamente\n\n### ✅ Seguridad\n- [ ] Rutas protegidas verifican `auth()` o `getServerSession()`\n- [ ] Server Actions validan autenticación y autorización\n- [ ] API Routes retornan 401 para usuarios no autenticados\n- [ ] Datos sensibles nunca se exponen sin verificación\n- [ ] Middleware configurado para rutas protegidas\n\n### ✅ TypeScript\n- [ ] No hay uso de `any` en ninguna parte\n- [ ] Todas las props de componentes están tipadas\n- [ ] Todas las respuestas de API están tipadas\n- [ ] Todas las funciones tienen tipos de retorno explícitos\n- [ ] `pnpm tsc --noEmit` pasa sin errores\n\n### ✅ Imports\n- [ ] Todos los imports usan alias `@/` cuando es apropiado\n- [ ] Imports organizados: externos → internos → tipos\n- [ ] `import type` usado para tipos\n\n## Scripts Recomendados para package.json\n\n```json\n{\n  \"scripts\": {\n    \"dev\": \"next dev\",\n    \"build\": \"next build\",\n    \"start\": \"next start\",\n    \"lint\": \"biome check .\",\n    \"lint:fix\": \"biome check --apply .\",\n    \"format\": \"biome format --write .\",\n    \"type-check\": \"tsc --noEmit\",\n    \"ci\": \"pnpm type-check && pnpm biome ci .\",\n    \"pre-commit\": \"pnpm lint:fix && pnpm type-check\"\n  }\n}\n```\n\n## Ejemplo Completo de Componente Seguro y Limpio\n\n```typescript\n// components/UserProfile.tsx\n''use client''\n\nimport { useState } from ''react''\nimport { useMutation, useQueryClient } from ''@tanstack/react-query''\nimport { useForm } from ''react-hook-form''\nimport { zodResolver } from ''@hookform/resolvers/zod''\n\nimport { Button } from ''@/components/ui/Button''\nimport { Input } from ''@/components/ui/Input''\nimport { updateUserProfile } from ''@/actions/users''\nimport { userProfileSchema } from ''@/schemas/user''\n\nimport type { User } from ''@/types/user''\nimport type { z } from ''zod''\n\ntype UserProfileFormData = z.infer<typeof userProfileSchema>\n\ninterface UserProfileProps {\n  user: User\n}\n\nexport function UserProfile({ user }: UserProfileProps) {\n  const queryClient = useQueryClient()\n  const [isEditing, setIsEditing] = useState(false)\n\n  const {\n    register,\n    handleSubmit,\n    formState: { errors },\n    reset,\n  } = useForm<UserProfileFormData>({\n    resolver: zodResolver(userProfileSchema),\n    defaultValues: {\n      name: user.name,\n      email: user.email,\n    },\n  })\n\n  const mutation = useMutation({\n    mutationFn: updateUserProfile,\n    onSuccess: () => {\n      queryClient.invalidateQueries({ queryKey: [''user'', user.id] })\n      setIsEditing(false)\n    },\n  })\n\n  const onSubmit = (data: UserProfileFormData) => {\n    mutation.mutate({ ...data, userId: user.id })\n  }\n\n  return (\n    <div className=\"space-y-4\">\n      {isEditing ? (\n        <form onSubmit={handleSubmit(onSubmit)} className=\"space-y-4\">\n          <Input\n            {...register(''name'')}\n            label=\"Nombre\"\n            error={errors.name?.message}\n            disabled={mutation.isPending}\n          />\n          <Input\n            {...register(''email'')}\n            type=\"email\"\n            label=\"Email\"\n            error={errors.email?.message}\n            disabled={mutation.isPending}\n          />\n          <div className=\"flex gap-2\">\n            <Button type=\"submit\" disabled={mutation.isPending}>\n              {mutation.isPending ? ''Guardando...'' : ''Guardar''}\n            </Button>\n            <Button\n              type=\"button\"\n              variant=\"secondary\"\n              onClick={() => {\n                setIsEditing(false)\n                reset()\n              }}\n            >\n              Cancelar\n            </Button>\n          </div>\n        </form>\n      ) : (\n        <>\n          <div>\n            <h2>{user.name}</h2>\n            <p>{user.email}</p>\n          </div>\n          <Button onClick={() => setIsEditing(true)}>Editar</Button>\n        </>\n      )}\n    </div>\n  )\n}\n```\n\n---\n\n**Objetivo final:** Garantizar código limpio, seguro, type-safe y maintainable usando Biome, autenticación robusta, TypeScript estricto e imports organizados.\n"},"lastSynced":"2026-03-08T02:03:28.479Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced React/Next.js security auditing and code quality enforcement with Biome.","zh":"适用于需要高级 React/Next.js 安全审计和代码质量强制的代码审查代理，使用 Biome。","ja":"React/Next.js の高度なセキュリティ監査とコード品質の強制が必要なコードレビューエージェントに最適です。Biome を使用します。","ko":"고급 React/Next.js 보안 감사 및 코드 품질 적용이 필요한 코드 리뷰 에이전트에 적합합니다. Biome를 사용합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan auditorías de seguridad avanzadas de React/Next.js y aplicación de la calidad del código con Biome.","fr":"Parfait pour les agents de révision de code nécessitant une audit de sécurité avancée React/Next.js et une application de la qualité du code avec Biome.","de":"Perfekt für Code-Review-Agenten, die erweiterte React/Next.js-Sicherheitsaudits und Code-Qualitätsdurchsetzung mit Biome benötigen.","pt":"Perfeito para agentes de revisão de código que necessitam de auditoria de segurança avançada React/Next.js e aplicação de qualidade de código com Biome.","ru":"Идеально подходит для агентов проверки кода, которым требуется продвинутая безопасность React/Next.js и обеспечение качества кода с помощью Biome.","ar":"مثالي لعميل مراجعة الشفرة الذي يحتاج إلى تدقيق أمان متقدم React/Next.js وتنفيذ جودة الشفرة مع Biome."},"recommendation":{"en":"Empowers agents to enforce code quality and security standards in React/Next.js applications using Biome for linting and formatting, ensuring adherence to specific rules and configurations defined in biome.json, and leveraging commands like pnpm biome check --apply for automated fixes.","zh":"赋予代理人使用 Biome 进行 linting 和格式化来强制执行 React/Next.js 应用程序的代码质量和安全标准的能力，确保遵守在 biome.json 中定义的特定规则和配置，并利用诸如 pnpm biome check --apply 之类的命令进行自动修复。","ja":"Biome を使用して linting とフォーマッティングを実行し、biome.json で定義された特定のルールと構成に従って React/Next.js アプリケーションのコード品質とセキュリティ基準を強制する能力をエージェントに与え、pnpm biome check --apply などのコマンドを使用して自動修復を実行します。","ko":"Biome를 사용하여 linting 및 형식을 지정하여 biome.json에서 정의된 특정 규칙 및 구성에 따라 React/Next.js 애플리케이션의 코드 품질 및 보안 표준을 적용할 수 있는 능력을 에이전트에게 부여하고 pnpm biome check --apply와 같은 명령을 사용하여 자동 수정을 수행합니다.","es":"Habilita a los agentes a aplicar normas de calidad y seguridad del código en aplicaciones React/Next.js utilizando Biome para la revisión y el formato, garantizando el cumplimiento de reglas y configuraciones específicas definidas en biome.json, y aprovechando comandos como pnpm biome check --apply para soluciones automatizadas.","fr":"Permet aux agents d''appliquer des normes de qualité et de sécurité du code dans les applications React/Next.js en utilisant Biome pour la mise en forme et la configuration, en garantissant le respect de règles et de configurations spécifiques définies dans biome.json, et en exploitant des commandes comme pnpm biome check --apply pour des correctifs automatisés.","de":"Ermächtigt Agenten, Code-Qualitäts- und Sicherheitsstandards in React/Next.js-Anwendungen durchzusetzen, indem Biome für Linter und Formatierung verwendet wird, um die Einhaltung spezifischer Regeln und Konfigurationen in biome.json sicherzustellen und Befehle wie pnpm biome check --apply für automatisierte Korrekturen zu nutzen.","pt":"Habilita os agentes a impor padrões de qualidade e segurança de código em aplicações React/Next.js usando Biome para linting e formatação, garantindo a adesão a regras e configurações específicas definidas em biome.json, e aproveitando comandos como pnpm biome check --apply para correções automatizadas.","ru":"Наделяет агентов возможностью обеспечивать качество и безопасность кода в приложениях React/Next.js с помощью Biome для linting и форматирования, обеспечивая соблюдение определенных правил и конфигураций, определенных в biome.json, и использует команды типа pnpm biome check --apply для автоматических исправлений.","ar":"يُمكّن الوكيل من فرض معايير جودة وأمان الشفرة في تطبيقات React/Next.js باستخدام Biome للتنسيق والتنسيق، مما يضمن الامتثال للقواعد والتهيئة المحددة في ملف biome.json، ويوفر أوامر مثل pnpm biome check --apply لإصلاحات آلية."},"useCases":{"en":["Enforcing React/Next.js code quality standards with Biome","Automating security audits for modern web applications","Configuring and applying linting rules with Biome"],"zh":["使用 Biome 强制执行 React/Next.js 代码质量标准","自动化现代 Web 应用程序的安全审计","使用 Biome 配置和应用 linting 规则"],"ja":["Biome を使用して React/Next.js コード品質基準を強制する","モダンな Web アプリケーションのセキュリティ監査を自動化する","Biome を使用して linting ルールを構成して適用する"],"ko":["Biome를 사용하여 React/Next.js 코드 품질 표준을 적용하는 것","모던 웹 애플리케이션의 보안 감사 자동화","Biome를 사용하여 린팅 규칙을 구성하고 적용하는 것"],"es":["Aplicar normas de calidad de código React/Next.js con Biome","Automatizar auditorías de seguridad para aplicaciones web modernas","Configurar y aplicar reglas de revisión con Biome"],"fr":["Mettre en œuvre des normes de qualité de code React/Next.js avec Biome","Automatiser les audits de sécurité pour les applications web modernes","Configurer et appliquer des règles de mise en forme avec Biome"],"de":["Durchsetzung von React/Next.js-Code-Qualitätsstandards mit Biome","Automatisierung von Sicherheitsaudits für moderne Webanwendungen","Konfigurieren und Anwenden von Linter-Regeln mit Biome"],"pt":["Impor padrões de qualidade de código React/Next.js com Biome","Automatizar auditorias de segurança para aplicações web modernas","Configurar e aplicar regras de linting com Biome"],"ru":["Обеспечение качества кода React/Next.js с помощью Biome","Автоматизация аудита безопасности для современных веб-приложений","Настройка и применение правил linting с помощью Biome"],"ar":["فرض معايير جودة شفرة React/Next.js مع Biome","تحسين عمليات تدقيق الأمان لتطبيقات الويب الحديثة","تهيئة وتطبيق قواعد التنسيق مع Biome"]},"limitations":{"en":["Requires Biome configuration and setup","Limited to React/Next.js applications","Excludes use of ESLint, Prettier, and other linting tools"],"zh":["需要 Biome 配置和设置","仅限 React/Next.js 应用程序","不包括 ESLint、Prettier 和其他 linting 工具的使用"],"ja":["Biome の構成と設定が必要","React/Next.js アプリケーションに限定","ESLint、Prettier、その他の linting ツールの使用を除外"],"ko":["Biome 구성 및 설정이 필요","React/Next.js 애플리케이션에만 국한","ESLint, Prettier 및 기타 린팅 도구의 사용을 제외"],"es":["Requiere configuración y instalación de Biome","Limitado a aplicaciones React/Next.js","Excluye el uso de ESLint, Prettier y otras herramientas de revisión"],"fr":["Nécessite la configuration et la mise en place de Biome","Limité aux applications React/Next.js","Exclut l''utilisation d''ESLint, Prettier et d''autres outils de mise en forme"],"de":["Benötigt Biome-Konfiguration und -Einrichtung","Begrenzt auf React/Next.js-Anwendungen","Schließt die Verwendung von ESLint, Prettier und anderen Linter-Tools aus"],"pt":["Requer configuração e instalação do Biome","Limitado a aplicações React/Next.js","Exclui o uso de ESLint, Prettier e outras ferramentas de linting"],"ru":["Требует настройки и установки Biome","Ограничен приложениями React/Next.js","Исключает использование ESLint, Prettier и других инструментов linting"],"ar":["يتطلب تهيئة وضبط Biome","محدود بتطبيقات React/Next.js","استبعاد استخدام ESLint و Prettier وأدوات تنسيق أخرى"]},"version":4},"contentHash":"2aacfe73b10d1ecf2e946f72c7e795409d91a44641bb28a3c7f7062be8c27610","qualityScore":57}');
