INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('0mar2090/hotelchavin/security-quality-guard', 'security-quality-guard', '0mar2090', 'hotelchavin', 'community', 'security-quality-guard 0mar2090 hotelchavin community The security-quality-guard skill acts as a code auditor and security enforcer for modern React/Next.js applications, utilizing Biome for linting and formatting. It benefits developers by ensuring code quality and security. Security-Quality-Guard 是一个 React/Next.js 代码审计和安全工具，使用 Biome 进行 linting 和 formateo Security-Quality-Guard は React/Next.js コード監査とセキュリティツールです。Biome を使用して linting と formateo を実行します Security-Quality-Guard는 React/Next.js 코드 감사 및 보안 도구입니다. Biome를 사용하여 linting 및 formateo를 수행합니다 Security-Quality-Guard es una herramienta de auditoría de código y seguridad para aplicaciones React/Next.js modernas que utiliza Biome para linting y formateo. Security-Quality-Guard est un outil d''audit de code et de sécurité pour les applications React/Next.js modernes qui utilise Biome pour le linting et le formattage. Security-Quality-Guard ist ein Tool für die Code- und Sicherheitsprüfung von modernen React/Next.js-Anwendungen, das Biome für Linting und Formatierung verwendet. O Security-Quality-Guard é uma ferramenta de auditoria de código e segurança para aplicativos React/Next.js modernos, utilizando Biome para linting e formatação. Security-Quality-Guard — это инструмент аудита кода и безопасности для современных приложений React/Next.js, использующий Biome для линтинга и форматирования. أداة الأمان والجودة Security-Quality-Guard هي أداة تدقيق شفرة وأمان لتطبيقات React/Next.js الحديثة، وتستخدم Biome لتحليل الشفرة وتشكيلها. how to use security-quality-guard security-quality-guard vs ESLint Biome linting setup guide security-quality-guard install what is security-quality-guard security-quality-guard alternative security-quality-guard setup for React Biome configuration for Next.js security-quality-guard best practices Security-Quality-Guard React/Next.js 代码审计 Biome linting pnpm biome check --apply 代码安全 AI 에ージェント 代码监査 Uses Biome as the sole linting and formatting tool Configures Biome via biome.json Runs commands like `pnpm biome check --apply` for automated fixes Replaces ESLint and Prettier for streamlined code quality management Enforces consistent code formatting through Biome''s rules security-quality-guard is a code auditing and security enforcement skill for React/Next.js applications, leveraging Biome for linting and formatting');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Bebang-Enterprise-Inc/hrms/local-frappe', 'community', 'Bebang-Enterprise-Inc', 'hrms', 'Bebang-Enterprise-Inc/hrms', 'local-frappe', 0, 0, 57, '2026-03-08T01:57:15.343Z', '2026-03-08T02:03:30.612Z', '58a00f899ff6ad92ab14ace5408e6e805e310ed3eeb3157483a12a26177aefc0', '{"id":"Bebang-Enterprise-Inc/hrms/local-frappe","name":"local-frappe","description":{"en":"The local-frappe skill enables developers to set up and manage local Frappe development environments, ensuring iterative development without disrupting production. It benefits developers working with Frappe and Python.","zh":"local-frappe 是一个本地 Frappe 开发工具，用于快速测试和部署 Frappe/Python 代码","ja":"local-frappe は、Frappe/Python コードの迅速なテストとデプロイを実現するローカル開発ツールです","ko":"local-frappe 는 로컬에서 Frappe/Python 코드를 빠르게 테스트하고 배포하는 데 사용되는 도구입니다","es":"Local-frappe es una herramienta para desarrolladores que permite probar y depurar cambios en Frappe y Python de manera local y rápida","fr":"Local-frappe est un outil pour développeurs qui permet de tester et de déboguer les modifications de Frappe et Python de manière locale et rapide","de":"Local-frappe ist ein Tool für Entwickler, das das Testen und Debuggen von Änderungen in Frappe und Python auf lokale und schnelle Weise ermöglicht","pt":"O local-frappe é uma ferramenta essencial para desenvolvedores, permitindo testes locais rápidos e seguros antes de deploy em produção.","ru":"Локальный local-frappe - это важнейший инструмент для разработчиков, позволяющий проводить быстрые и безопасные локальные тесты перед deploy в производство.","ar":"أداة local-frappe المحلية هي أداة أساسية للمطورين، تمكنهم من إجراء اختبارات سريعة وأمنة قبل النشر في الإنتاج."},"seo":{"title":{"en":"local-frappe: Local Frappe Development Setup Guide | AI A...","zh":"local-frappe 本地开发设置指南","ja":"local-frappe ローカル開発セットアップガイド","ko":"local-frappe 로컬 개발 설정 가이드","es":"Guía de configuración local-frappe para desarrollo rápido","fr":"Guide de configuration local-frappe pour développement ra...","de":"Einrichtungsleitfaden für local-frappe zum schnellen Entw...","pt":"Guia de Configuração local-frappe para Desenvolvimento Rá...","ru":"ИИ Агенты: локальная настройка local-frappe для быстрой р...","ar":"إعداد أداة local-frappe المحلية لتعزيز الإنتاجية"},"description":{"en":"Streamline your Frappe development workflow by testing locally first. Learn how to set up local-frappe and avoid lengthy production build cycles.","zh":"了解 local-frappe 的本地开发设置和管理，实现快速的 Frappe/Python 代码测试和部署","ja":"local-frappe を使用したローカル開発の設定と管理方法を学び、Frappe/Python コードのテストとデプロイを迅速化する","ko":"local-frappe 로컬 개발 설정과 관리를 통해 Frappe/Python 코드 테스트와 배포를 빠르게 수행하는 방법","es":"Aprende a configurar local-frappe para agilizar tu desarrollo con Python y Frappe. Descubre los beneficios de probar localmente antes de implementar en produ...","fr":"Découvrez comment configurer local-frappe pour accélérer votre développement avec Python et Frappe. Comprenez l''importance de tester en local avant de déploy...","de":"Erfahren Sie, wie Sie local-frappe einrichten, um Ihr Entwicklungstempo mit Python und Frappe zu steigern. Erfahren Sie die Vorteile von lokalen Tests vor de...","pt":"Aprenda a configurar o local-frappe para desenvolvimento rápido e seguro, com dicas e práticas recomendadas para evitar erros de deploy","ru":"Узнайте, как настроить локальный local-frappe для быстрой и безопасной разработки, с советами и лучшими практиками для избежания ошибок deploy","ar":"تعرف على كيفية إعداد أداة local-frappe المحلية لتعزيز الإنتاجية والسرعة، مع نصائح وأفضل الممارسات لتجنب أخطاء Deploy"},"definition":{"en":"local-frappe is a development tool that allows developers to test and manage Frappe applications locally, reducing production deployment time from 15-20 minutes to mere seconds.","zh":"local-frappe 是一个用于本地开发的 Frappe 框架，用于测试和部署 Python 代码","ja":"local-frappe は、ローカル開発用の Frappe フレームワークで、Python コードのテストとデプロイに使用されます","ko":"local-frappe 는 로컬 개발을 위한 Frappe 프레임워크로 Python 코드 테스트와 배포에 사용됩니다","es":"Local-frappe es una herramienta de desarrollo que permite la configuración y gestión de entornos de desarrollo locales para Frappe y Python","fr":"Local-frappe est un outil de développement qui permet la configuration et la gestion d''environnements de développement locaux pour Frappe et Python","de":"Local-frappe ist ein Entwicklungstool, das die Konfiguration und Verwaltung von lokalen Entwicklungsumgebungen für Frappe und Python ermöglicht","pt":"O local-frappe é uma ferramenta de desenvolvimento local que permite testar e depurar aplicativos Frappe/Python de forma rápida e segura.","ru":"Локальный local-frappe - это инструмент локальной разработки, позволяющий тестировать и отлаживать приложения Frappe/Python быстро и безопасно.","ar":"أداة local-frappe المحلية هي أداة تطوير محلية تمكن من اختبار وتحسين تطبيقات Frappe/Python بسرعة وأمان."},"features":{"en":["Sets up local Frappe development environments","Manages local Frappe applications for iterative development","Reduces production deployment time from 15-20 minutes to seconds","Enforces critical rule of testing locally before production deployment","Supports rapid testing and development of Frappe and Python changes"],"zh":["本地测试和部署 Frappe/Python 代码","快速的测试和部署周期","避免直接将 Frappe/Python 改动部署到生产环境","支持秒级的本地测试","减少 15-20 分钟的生产构建和部署周期"],"ja":["Frappe/Python コードのローカルテストとデプロイ","迅速なテストとデプロイサイクル","Frappe/Python の変更を直接生产環境にデプロイしない","秒レベルのローカルテストをサポート","15-20 分の生产構築とデプロイサイクルを短縮"],"ko":["로컬에서 Frappe/Python 코드 테스트와 배포"," 빠른 테스트와 배포 주기","Frappe/Python 변경을 직접 생산 환경에 배포하지 않음","초 단위의 로컬 테스트 지원","15-20 분의 생산 빌드와 배포 주기 단축"],"es":["Configuración rápida de entornos de desarrollo locales","Pruebas y depuración de cambios en Frappe y Python","Implementación de cambios en producción de manera segura","Reducción del tiempo de construcción y despliegue en producción","Compatibilidad con Python y Frappe"],"fr":["Configuration rapide d''environnements de développement locaux","Tests et débogage des modifications de Frappe et Python","Déploiement des modifications en production de manière sécurisée","Réduction du temps de construction et de déploiement en production","Compatibilité avec Python et Frappe"],"de":["Schnelle Konfiguration von lokalen Entwicklungsumgebungen","Testen und Debuggen von Änderungen in Frappe und Python","Sichere Implementierung von Änderungen in die Produktion","Reduzierung der Build- und Deployment-Zeit in der Produktion","Kompatibilität mit Python und Frappe"],"pt":["Testes locais rápidos e seguros","Evita erros de deploy em produção","Permite desenvolvimento iterativo rápido","Suporta aplicativos Frappe/Python","Reduz o tempo de deploy em produção"],"ru":["Быстрые и безопасные локальные тесты","Избегает ошибок deploy в производство","Позволяет проводить быструю итеративную разработку","Поддерживает приложения Frappe/Python","Уменьшает время deploy в производство"],"ar":["اختبارات سريعة وأمنة على المستوى المحلي","تجنب أخطاء النشر في الإنتاج","تمكن من التطوير المتكرر السريع","تدعم تطبيقات Frappe/Python","تقلل من وقت النشر في الإنتاج"]},"keywords":{"en":["how to use local-frappe","local-frappe setup guide","local-frappe alternative","local-frappe vs Frappe","local-frappe install","what is local-frappe","local-frappe development","frappe local development","python local development"],"zh":["local-frappe","Frappe 本地开发","Python 代码测试","快速部署","本地测试","生产环境部署"],"ja":["local-frappe","Frappe ローカル開発","Python コードテスト","迅速なデプロイ","ローカルテスト","生产環境デプロイ"],"ko":["local-frappe","Frappe 로컬 개발","Python 코드 테스트","빠른 배포","로컬 테스트","생산 환경 배포"],"es":["local-frappe","desarrollo rápido","Frappe","Python","pruebas locales","depuración","implementación en producción","herramientas de desarrollo"],"fr":["local-frappe","développement rapide","Frappe","Python","tests locaux","débogage","déploiement en production","outils de développement"],"de":["local-frappe","schnelles Entwickeln","Frappe","Python","lokale Tests","Debuggen","Implementierung in die Produktion","Entwicklungstools"],"pt":["local-frappe","desenvolvimento local","testes locais","deploy em produção","Frappe/Python","desenvolvimento rápido","erros de deploy"," ferramentas de desenvolvimento"],"ru":["локальный local-frappe","локальная разработка","локальные тесты","deploy в производство","Frappe/Python","быстрая разработка","ошибки deploy","инструменты разработки"],"ar":["أداة local-frappe المحلية","التطوير المحلي","الاختبارات المحلية","نشر في الإنتاج","Frappe/Python","التطوير السريع","أخطاء النشر","أدوات التطوير"]}},"owner":"Bebang-Enterprise-Inc","repo":"hrms","repoPath":"Bebang-Enterprise-Inc/hrms","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.343Z","topics":[],"category":"community","skillMd":{"name":"local-frappe","description":"Local Frappe development environment for testing APIs before production deployment. Use when developing or testing Python/API changes locally.","bodyPreview":"# /local-frappe - Local Frappe Development\n\n## CRITICAL: TEST LOCALLY FIRST - NO EXCEPTIONS\n\n**NEVER deploy Frappe/Python changes directly to production.**\n\n| Action | Time | When to Use |\n|--------|------|-------------|\n| Local test | **Seconds** | ALWAYS - every code change |\n| Production deploy | 15-20 min | ONLY after local testing passes |\n\n**The 15-20 minute production build/deploy cycle is UNACCEPTABLE for iterative development.**\n\n## What This Command Does\n\nSets up and manages a local Fr","body":"# /local-frappe - Local Frappe Development\n\n## CRITICAL: TEST LOCALLY FIRST - NO EXCEPTIONS\n\n**NEVER deploy Frappe/Python changes directly to production.**\n\n| Action | Time | When to Use |\n|--------|------|-------------|\n| Local test | **Seconds** | ALWAYS - every code change |\n| Production deploy | 15-20 min | ONLY after local testing passes |\n\n**The 15-20 minute production build/deploy cycle is UNACCEPTABLE for iterative development.**\n\n## What This Command Does\n\nSets up and manages a local Frappe development environment for testing BEI custom APIs before deploying to production.\n\n**MANDATORY:** Always test changes locally BEFORE pushing to production. The local environment matches production (Frappe v15, ERPNext v15, HRMS v15).\n\n## Quick Start\n\n```bash\ncd docker-dev\ndev.bat start     # Windows (first run takes 10-15 minutes)\n./dev.sh start    # Linux/Mac\n```\n\n## Access\n\n| URL | Purpose |\n|-----|---------|\n| http://localhost:8000 | Frappe web UI |\n| http://localhost:8000/api/method/frappe.ping | API test endpoint |\n| http://localhost:8000/api/method/hrms.api.hello.hello | BEI test API |\n| localhost:3307 | MariaDB (user: root, pass: admin) |\n\n**Login:** Administrator / admin\n\n## Development Workflow\n\n### Standard Workflow (Edit → Sync → Test)\n\n```bash\n# 1. Edit your API file locally\n#    Example: hrms/api/employee_clearance.py\n\n# 2. Sync to container and clear cache\ndev.bat sync\n\n# 3. Test your API\ncurl http://localhost:8000/api/method/hrms.api.employee_clearance.get_status\n\n# 4. When ready, commit and push to production\ngit add .\ngit commit -m \"feat: Add employee clearance API\"\ngit push origin production\n```\n\n### Helper Commands\n\n| Command | Description |\n|---------|-------------|\n| `dev.bat start` | Start all containers (first run: 10-15 min) |\n| `dev.bat stop` | Stop all containers |\n| `dev.bat restart` | Restart Frappe to pick up code changes |\n| `dev.bat sync` | Copy API files and clear cache (quick reload) |\n| `dev.bat shell` | Open bash shell in container |\n| `dev.bat bench` | Run bench command (e.g., `dev.bat bench migrate`) |\n| `dev.bat logs` | Follow Frappe logs |\n| `dev.bat test` | Test hello API endpoint |\n| `dev.bat migrate` | Run database migrations |\n| `dev.bat status` | Show container status |\n| `dev.bat reset` | Delete everything and start fresh (DESTRUCTIVE) |\n\n## File Structure\n\n```\ndocker-dev/\n├── docker-compose.yml    # Container orchestration\n├── dev.bat               # Windows helper script\n└── dev.sh                # Linux/Mac helper script\n\nhrms/api/                 # BEI custom API files (synced to container)\n├── __init__.py           # API exports (CRITICAL - update when adding new APIs)\n├── hello.py              # Test endpoint\n├── employee_clearance.py # Clearance APIs\n├── enrichment.py         # Data enrichment APIs\n├── google_chat.py        # Google Chat integration\n├── google_drive.py       # Google Drive integration\n├── google_login.py       # Google OAuth\n├── oauth_tokens.py       # OAuth token management\n├── onboarding.py         # Employee onboarding\n└── roster.py             # Shift roster APIs\n```\n\n## Adding a New API\n\n### 1. Create your API file\n\n```python\n# hrms/api/my_new_api.py\nimport frappe\n\n@frappe.whitelist(allow_guest=True)\ndef hello():\n    \"\"\"Test endpoint.\"\"\"\n    return {\"message\": \"Hello from my new API!\"}\n\n@frappe.whitelist()\ndef get_data():\n    \"\"\"Requires authentication.\"\"\"\n    return {\"user\": frappe.session.user}\n```\n\n### 2. Update __init__.py\n\n```python\n# hrms/api/__init__.py\nfrom hrms.api.my_new_api import (\n    hello,\n    get_data,\n)\n```\n\n### 3. Sync and test\n\n```bash\ndev.bat sync\ncurl http://localhost:8000/api/method/hrms.api.my_new_api.hello\n```\n\n## Container Configuration\n\n| Component | Value |\n|-----------|-------|\n| Frappe Image | `frappe/bench:v5.25.11` |\n| Bench Location | `/workspace/frappe-bench` |\n| API Mount | `/bei-api` (read-only from `hrms/api/`) |\n| Site Name | `dev.localhost` |\n| MariaDB Port | 3307 (external), 3306 (internal) |\n| Web Port | 8000 |\n| Socket.IO Port | 9000 |\n\n## Volumes\n\n| Volume | Purpose |\n|--------|---------|\n| `docker-dev_frappe-bench` | Frappe bench directory (apps, sites, etc.) |\n| `docker-dev_mariadb-data` | Database data |\n\n**Note:** Volumes persist data across container restarts. To completely reset, use `docker compose down -v`.\n\n## Troubleshooting\n\n### Container won''t start\n\n```bash\n# Check logs\ndev.bat logs\n\n# Or directly\ndocker logs frappe-dev\n```\n\n### API changes not visible\n\n```bash\n# Force sync and clear cache\ndev.bat sync\n\n# If still not working, restart Frappe\ndev.bat restart\n```\n\n### Database connection errors\n\n```bash\n# Check MariaDB is healthy\ndocker ps\n\n# Should show mariadb-dev as (healthy)\n```\n\n### Need fresh start\n\n```bash\n# WARNING: This deletes all data\ndev.bat reset\n# Or manually:\ndocker compose -f docker-dev/docker-compose.yml down -v\ndev.bat start\n```\n\n### First run taking too long\n\nFirst run downloads and installs:\n- Frappe Framework (~3 min)\n- ERPNext (~5 min)\n- HRMS (~3 min)\n- Site creation (~2 min)\n\nTotal: 10-15 minutes. Subsequent starts are fast (~30 seconds).\n\n## Testing APIs\n\n### Without authentication\n\n```bash\n# APIs with @frappe.whitelist(allow_guest=True)\ncurl http://localhost:8000/api/method/hrms.api.hello.hello\n```\n\n### With authentication\n\n```bash\n# Get session cookie first\ncurl -c cookies.txt -X POST http://localhost:8000/api/method/login \\\n  -d \"usr=Administrator\" -d \"pwd=admin\"\n\n# Then use the cookie\ncurl -b cookies.txt http://localhost:8000/api/method/hrms.api.roster.get_roster\n```\n\n### Using bench execute\n\n```bash\n# Run Python code directly\ndev.bat bench execute hrms.api.hello.hello\n\n# With arguments\ndev.bat bench execute \"hrms.api.employee_clearance.get_status\" --args ''[\"HR-EMP-0001\"]''\n```\n\n## When to Deploy to Production\n\nAfter testing locally:\n\n1. **Commit changes:**\n   ```bash\n   git add hrms/api/\n   git commit -m \"feat: Add employee clearance API\"\n   ```\n\n2. **Push to production branch:**\n   ```bash\n   git push origin production\n   ```\n\n3. **Monitor GitHub Actions:** https://github.com/Bebang-Enterprise-Inc/hrms/actions\n\n4. **Verify production:**\n   ```bash\n   curl https://hq.bebang.ph/api/method/hrms.api.hello.hello\n   ```\n\nSee `/deploy-frappe` skill for full production deployment options.\n\n## DO NOT DO\n\n1. **NEVER edit files directly in the container** - Changes are lost on restart\n2. **NEVER use `docker commit`** - Corrupts the Python environment\n3. **NEVER push untested code to production** - Always test locally first\n4. **NEVER skip updating `__init__.py`** - API won''t be whitelisted\n5. **NEVER assume production deploy will pick up code changes** - Use `no_cache=true` (see below)\n\n---\n\n## CRITICAL: Local vs Production Asset Handling\n\n### Why Local Works But Production Breaks\n\n**Local development** allows `bench build` because:\n- Single container environment\n- No persistent asset volumes (fresh start each time)\n- Development mode reloads assets on change\n\n**Production** prohibits `bench build` because:\n- Multi-container architecture (frontend + backend)\n- Persistent volumes don''t auto-update\n- Assets baked into Docker image at build time\n\n### What This Means For You\n\n| Action | Local | Production |\n|--------|-------|------------|\n| `bench build` | ✅ OK | ❌ NEVER |\n| `bench migrate` | ✅ OK | ⚠️ Only via isolated container |\n| Edit Python files | ✅ Sync + restart | ❌ Rebuild image |\n| Edit CSS/JS | ✅ Sync + restart | ❌ Rebuild image |\n\n### The Production Rule\n\n**All code and asset changes MUST go through Docker image rebuild.**\n\nWhen you push to production:\n1. GitHub Actions rebuilds the entire Docker image\n2. New CSS/JS hashes are baked into image\n3. Assets volume should be deleted before deploy\n4. Fresh containers get consistent assets\n\n**Never \"hot-fix\" production by running bench commands.**\n\nSee `/deploy-frappe` for the full CSS 404 root cause analysis and fix.\n\n## Testing Custom WWW Pages Locally\n\n### Creating Custom Pages (like login)\n\n1. Create your page file:\n   ```\n   hrms/www/bei-login.html  # The HTML template\n   hrms/www/bei-login.py    # Optional Python context handler\n   ```\n\n2. If redirecting from an existing route, add to `hrms/hooks.py`:\n   ```python\n   website_redirects = [\n       {\"source\": \"/login\", \"target\": \"/bei-login\", \"redirect_http_status\": 302},\n   ]\n   ```\n\n3. Sync to container:\n   ```bash\n   dev.bat sync\n   ```\n\n4. Test locally:\n   ```bash\n   # Check redirect\n   curl -sI http://localhost:8000/login | grep -i location\n\n   # Check page renders\n   curl -s http://localhost:8000/bei-login | grep -o \"<title>.*</title>\"\n   ```\n\n### Important: Production Deployment Uses Docker Cache\n\n**After testing locally, you MUST use `no_cache=true` when deploying:**\n```bash\ngh workflow run \"Build and Deploy Frappe HRMS\" --repo Bebang-Enterprise-Inc/hrms -f no_cache=true -f run_migrate=true\n```\n\n**Why:** Docker cache doesn''t detect when git repo contents change. Without `no_cache=true`, the build serves cached layers from previous builds.\n\n**How to verify fresh build:** Check GitHub Actions build time:\n- ~2 min = CACHED (old code)\n- ~5-10 min = FRESH (new code)\n\n## Running bei-tasks Frontend Locally (Added 2026-01-24)\n\nFor full-stack local development, run both Frappe AND bei-tasks locally:\n\n### 1. Start Local Frappe\n\n```bash\ncd F:\\Dropbox\\Projects\\BEI-ERP\\docker-dev\npowershell -Command \"docker compose up -d\"\n# Wait for Frappe to start (~30 seconds if already initialized)\n```\n\n### 2. Generate API Keys (First Time Only)\n\n```bash\n# Login to get session cookie\ncurl -c cookies.txt -X POST \"http://localhost:8000/api/method/login\" \\\n  -d \"usr=Administrator&pwd=admin\"\n\n# Generate API keys\ncurl -b cookies.txt -X POST \\\n  \"http://localhost:8000/api/method/frappe.core.doctype.user.user.generate_keys?user=Administrator\"\n# Returns: {\"message\":{\"api_key\":\"xxx\",\"api_secret\":\"yyy\"}}\n```\n\n### 3. Configure bei-tasks for Local Frappe\n\nCreate/update `F:\\Dropbox\\Projects\\bei-tasks\\.env.development.local`:\n\n```env\n# Local Development Environment\nNEXT_PUBLIC_FRAPPE_URL=http://localhost:8000\n\n# Local Frappe API credentials (from step 2)\nFRAPPE_API_KEY=your-api-key\nFRAPPE_API_SECRET=your-api-secret\n\n# App Configuration\nNEXT_PUBLIC_APP_NAME=BEI Tasks (LOCAL)\n```\n\n### 4. Start Local bei-tasks\n\n```bash\ncd F:\\Dropbox\\Projects\\bei-tasks\nnpm run dev\n# Frontend runs at http://localhost:3000\n```\n\n### 5. Test the Connection\n\n```bash\n# Test Frappe API directly\ncurl -H \"Authorization: token api-key:api-secret\" \\\n  \"http://localhost:8000/api/method/hrms.api.onboarding.get_session?token=test\"\n\n# Expected: {\"message\":{\"success\":false,\"error\":\"Session not found\",...}}\n```\n\n### Local Development Stack\n\n| Component | URL | Purpose |\n|-----------|-----|---------|\n| Frappe Backend | http://localhost:8000 | API + Admin UI |\n| bei-tasks Frontend | http://localhost:3000 | React/Next.js app |\n| MariaDB | localhost:3307 | Database |\n| Socket.IO | localhost:9000 | Realtime |\n\n### Syncing Code Changes\n\n```bash\n# After editing hrms/api/*.py files:\ncd F:\\Dropbox\\Projects\\BEI-ERP\\docker-dev\n\n# Sync files and clear cache\npowershell -Command \"docker exec frappe-dev bash -c ''cp -f /bei-api/*.py /workspace/frappe-bench/apps/hrms/hrms/api/ && cd /workspace/frappe-bench && bench --site dev.localhost clear-cache''\"\n\n# If whitelist decorators changed, restart Frappe\npowershell -Command \"docker restart frappe-dev\"\n```\n\n### Important Notes\n\n1. **Authentication Required:** Local APIs need authentication (no `allow_guest=True`)\n2. **Session Cookie OR Token Auth:** Use either method for local testing\n3. **Different Site:** Local uses `dev.localhost`, production uses `hq.bebang.ph`\n4. **No Test Data:** Local DB is empty - create test data as needed\n\n## Related Skills\n\n- `/deploy-frappe` - Production deployment (ONLY after local testing)\n- `/frappe-sql-bulk` - Bulk data operations\n- `/frappe-doctype` - DocType development\n\n---\n\n## Production Testing Infrastructure (Added 2026-01-23)\n\n### CRITICAL: Database Architecture Discovery\n\n**The Frappe system at `hq.bebang.ph` uses a LOCAL Docker database via Docker Swarm (migrated 2026-01-29).**\n\n| Component | Service Name | Purpose |\n|-----------|--------------|---------|\n| Backend | `frappe_backend` | Frappe/ERPNext/HRMS (Gunicorn) |\n| Database | `frappe_db` | MariaDB (LOCAL) |\n| Frontend | `frappe_frontend` | Nginx proxy |\n| WebSocket | `frappe_websocket` | Socket.IO |\n| Queue | `frappe_queue-short`, `frappe_queue-long` | Background workers |\n| Scheduler | `frappe_scheduler` | Cron jobs |\n\n**Note:** Production now uses Docker Swarm (9 services). Container names changed from `frappe_docker-backend-1` to dynamic names under `frappe_backend.1.xxxx`.\n\n**Common Mistake:** AWS SSM commands often connect to the RDS database (`frappe-hrms-db.ctmwomgscn66.ap-southeast-1.rds.amazonaws.com`), but the live Frappe instance uses the local Docker database. This causes \"no employees found\" issues when testing.\n\n### Production Test Accounts\n\n| Employee ID | Email | Password | Role |\n|-------------|-------|----------|------|\n| TEST-STAFF-001 | test.staff@bebang.ph | BeiTest2026! | Store Staff |\n| TEST-SUPERVISOR-001 | test.supervisor@bebang.ph | BeiTest2026! | Store Supervisor |\n| TEST-AREA-001 | test.area@bebang.ph | BeiTest2026! | Area Supervisor |\n| TEST-HR-001 | test.hr@bebang.ph | BeiTest2026! | HR User |\n\n### Inserting Test Data into Production\n\n```bash\n# 1. Get AWS credentials\nexport AWS_ACCESS_KEY_ID=$(doppler secrets get AWS_ACCESS_KEY_ID --project bei-erp --config dev --plain)\nexport AWS_SECRET_ACCESS_KEY=$(doppler secrets get AWS_SECRET_ACCESS_KEY --project bei-erp --config dev --plain)\nexport AWS_DEFAULT_REGION=ap-southeast-1\n\n# 2. Run SQL on the CORRECT database (via Swarm backend container)\naws ssm send-command \\\n  --instance-ids \"i-026b7477d27bd46d6\" \\\n  --document-name \"AWS-RunShellScript\" \\\n  --parameters ''commands=[\n    \"docker exec $(docker ps -qf name=frappe_backend) bench --site hq.bebang.ph mariadb --execute \\\"INSERT INTO tabEmployee (name, employee_name, first_name, status, gender, date_of_birth, date_of_joining, company, user_id, creation, modified, owner, modified_by) VALUES (''TEST-STAFF-001'', ''Test Staff'', ''Test'', ''Active'', ''Male'', ''1990-01-01'', ''2024-01-01'', ''Bebang Enterprise Inc.'', ''test.staff@bebang.ph'', NOW(), NOW(), ''Administrator'', ''Administrator'');\\\"\"\n  ]''\n\n# 3. Verify\naws ssm send-command \\\n  --instance-ids \"i-026b7477d27bd46d6\" \\\n  --document-name \"AWS-RunShellScript\" \\\n  --parameters ''commands=[\n    \"docker exec $(docker ps -qf name=frappe_backend) bench --site hq.bebang.ph mariadb --execute \\\"SELECT name, employee_name, user_id FROM tabEmployee WHERE name LIKE ''TEST-%'';\\\"\"\n  ]''\n```\n\n### API Credentials for bei-tasks\n\n| Environment | Key | Secret | Source |\n|-------------|-----|--------|--------|\n| Production (Vercel) | `4a17c23aca83560` | `38ecc0e1054b1d2` | Doppler bei-erp |\n| Local (.env.local) | Same | Same | Doppler bei-erp |\n\n**IMPORTANT:** HR API routes use token auth (not session cookies) for Employee lookups because regular Frappe users don''t have Employee read permission.\n\n### Verifying API Connection\n\n```bash\n# Test from production\ncurl -X POST https://hq.bebang.ph/api/resource/Employee \\\n  -H \"Authorization: token 4a17c23aca83560:38ecc0e1054b1d2\" \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"filters\": [[\"user_id\", \"=\", \"test.staff@bebang.ph\"]]}''\n\n# Expected: Returns employee record\n```\n\n### Troubleshooting Production Tests\n\n1. **\"No employee found\" but employee exists:**\n   - Check you''re querying the Docker database, not RDS\n   - Use `bench --site hq.bebang.ph mariadb` not direct RDS connection\n\n2. **API returns 401:**\n   - Verify Vercel env vars match Doppler\n   - Redeploy after env var changes\n\n3. **Container not found:**\n   - Production now uses Docker Swarm (migrated 2026-01-29)\n   - Service names: `frappe_backend`, `frappe_frontend`, etc.\n   - Container names are dynamic: `frappe_backend.1.xxxxx`\n   - Use `docker service ls` to verify services\n   - Use `docker ps -qf name=frappe_backend` to get container ID\n\n4. **HR pages show \"Failed to get employee data\":**\n   - HR APIs need token auth, not session auth\n   - Check `app/api/hr/*/route.ts` uses `Authorization: token` header\n\n5. **Code deployed but changes not visible:**\n   - Docker build caching issue - use `no_cache=true` when deploying\n   - See `/deploy-frappe` for details on when to use no_cache\n   - Verify with: `curl https://hq.bebang.ph/api/method/hrms.api.hello.hello`\n   - Response should include `build_version` field showing deployment timestamp\n\n### Deployment Verification Endpoint\n\nThe hello API includes deployment info for verification:\n\n```bash\ncurl -s https://hq.bebang.ph/api/method/hrms.api.hello.hello | python -m json.tool\n```\n\nExpected response:\n```json\n{\n    \"message\": {\n        \"message\": \"Hello from Frappe HRMS!\",\n        \"timestamp\": \"2026-01-29 10:04:11.569399\",\n        \"build_version\": \"2026-01-29T12:16:00+08:00\",\n        \"deployment\": \"docker-swarm\"\n    }\n}\n```\n\nIf `build_version` doesn''t update after deployment, rebuild with `no_cache=true`.\n"},"lastSynced":"2026-03-08T02:03:30.612Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Development Agents needing efficient Frappe environment management.","zh":"适用于需要高效Frappe环境管理的Python开发代理。","ja":"Python開発エージェントが効率的なFrappe環境管理を必要とする場合に適しています。","ko":"효율적인 Frappe 환경 관리가 필요한 Python 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de Python que necesitan una gestión eficiente del entorno de Frappe.","fr":"Parfait pour les agents de développement Python nécessitant une gestion efficace de l''environnement Frappe.","de":"Perfekt für Python-Entwicklungsagenten, die eine effiziente Verwaltung der Frappe-Umgebung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Python que necessitam de gerenciamento eficiente de ambiente Frappe.","ru":"Идеально подходит для агентов разработки Python, которым требуется эффективное управление средой Frappe.","ar":"مثالي لعميل تطوير بايثون الذي يحتاج إلى إدارة بيئة فراب hiệu quả."},"recommendation":{"en":"Empowers agents to manage local Frappe development environments, ensuring iterative development without disrupting production, using Python and leveraging the Frappe framework for rapid testing and deployment cycles.","zh":"赋予代理管理本地Frappe开发环境的能力，确保在不破坏生产环境的情况下进行迭代开发，使用Python并利用Frappe框架实现快速测试和部署循环。","ja":"エージェントがローカルのFrappe開発環境を管理できるようにし、Pythonを使用して、Frappeフレームワークを利用して迅速なテストとデプロイサイクルを実現し、生産環境を混乱させずにイテレーティブ開発を実現します。","ko":"에이전트가 로컬 Frappe 개발 환경을 관리할 수 있도록 해주어, Python을 사용하여 Frappe 프레임워크를 활용하여 빠른 테스트 및 배포 주기를 구현하고, 생산 환경을混乱시키지 않고 반복 개발을 가능하게 합니다.","es":"Habilita a los agentes a gestionar entornos de desarrollo locales de Frappe, asegurando un desarrollo iterativo sin interrumpir la producción, utilizando Python y aprovechando el framework de Frappe para ciclos de prueba y despliegue rápidos.","fr":"Permet aux agents de gérer des environnements de développement locaux Frappe, assurant un développement itératif sans perturber la production, en utilisant Python et en exploitant le framework Frappe pour des cycles de test et de déploiement rapides.","de":"Ermächtigt Agenten, lokale Frappe-Entwicklungsumgebungen zu verwalten, iterative Entwicklung ohne Produktionsunterbrechung sicherzustellen, indem Python verwendet und das Frappe-Framework für schnelle Test- und Bereitstellungszyklen genutzt wird.","pt":"Habilita os agentes a gerenciar ambientes de desenvolvimento locais Frappe, garantindo desenvolvimento iterativo sem interromper a produção, usando Python e aproveitando o framework Frappe para ciclos de teste e implantação rápidos.","ru":"Наделяет агентов возможностью управлять локальными средами разработки Frappe, обеспечивая итеративную разработку без нарушения производства, используя Python и используя framework Frappe для быстрых циклов тестирования и развертывания.","ar":"يمنح الوكيل khảية إدارة بيئات التطوير المحلية Frappe، مما يضمن التطوير المتكرر دون تعطيل الإنتاج، باستخدام بايثون و الاستفادة من إطار عمل Frappe لأجلة اختبار وتحديث سريعة."},"useCases":{"en":["Setting up local Frappe development environments","Testing Frappe/Python changes before production deployment","Managing iterative development cycles"],"zh":["设置本地Frappe开发环境","在生产环境部署前测试Frappe/Python更改","管理迭代开发周期"],"ja":["ローカルのFrappe開発環境を設定する","生産環境にデプロイする前にFrappe/Pythonの変更をテストする","イテレーティブ開発サイクルを管理する"],"ko":["로컬 Frappe 개발 환경 설정","생산 환경에 배포하기 전에 Frappe/Python 변경 사항 테스트","반복 개발 주기 관리"],"es":["Configuración de entornos de desarrollo locales de Frappe","Prueba de cambios de Frappe/Python antes de la implementación en producción","Gestión de ciclos de desarrollo iterativos"],"fr":["Configuration d''environnements de développement locaux Frappe","Test des modifications Frappe/Python avant le déploiement en production","Gestion de cycles de développement itératifs"],"de":["Einrichtung lokaler Frappe-Entwicklungsumgebungen","Testen von Frappe/Python-Änderungen vor der Produktionseinrichtung","Verwaltung iterativer Entwicklungszyklen"],"pt":["Configuração de ambientes de desenvolvimento locais Frappe","Teste de alterações Frappe/Python antes do deploy de produção","Gerenciamento de ciclos de desenvolvimento iterativos"],"ru":["Настройка локальных сред разработки Frappe","Тестирование изменений Frappe/Python перед развертыванием в производство","Управление итеративными циклами разработки"],"ar":["تكوين بيئات التطوير المحلية Frappe","اختبار التغييرات Frappe/Python قبل نشر الإنتاج","إدارة دورات التطوير المتكرر"]},"limitations":{"en":["Requires local testing before production deployment","Frappe and Python expertise necessary","15-20 minute production build/deploy cycle applies"],"zh":["需要在生产环境部署前进行本地测试","需要Frappe和Python的专业知识","15-20分钟的生产构建/部署周期适用"],"ja":["生産環境にデプロイする前にローカルテストが必要","FrappeとPythonの専門知識が必要","15-20分の生産ビルド/デプロイサイクルが適用される"],"ko":["생산 환경에 배포하기 전에 로컬 테스트가 필요","Frappe 및 Python 전문 지식 필요","15-20분의 생산 빌드/배포 주기가 적용됨"],"es":["Requiere pruebas locales antes de la implementación en producción","Se requiere experiencia en Frappe y Python","Se aplica un ciclo de compilación/despliegue de producción de 15-20 minutos"],"fr":["Nécessite des tests locaux avant le déploiement en production","L''expertise en Frappe et Python est nécessaire","Un cycle de construction/déploiement de production de 15-20 minutes s''applique"],"de":["Erfordert lokale Tests vor der Produktionseinrichtung","Frappe- und Python-Expertise sind erforderlich","Ein Produktionsbuild-/Bereitstellungszyklus von 15-20 Minuten gilt"],"pt":["Requer testes locais antes do deploy de produção","É necessário conhecimento em Frappe e Python","Ciclo de compilação/implantação de produção de 15-20 minutos se aplica"],"ru":["Требуется локальное тестирование перед развертыванием в производство","Необходимо знание Frappe и Python","Применяется цикл сборки/развертывания производства 15-20 минут"],"ar":["يتطلب اختبارًا محليًا قبل نشر الإنتاج","يجب معرفة فراب و بايثون","يتطبق دورة بناء/نشر الإنتاج لمدة 15-20 دقيقة"]},"version":4},"contentHash":"58a00f899ff6ad92ab14ace5408e6e805e310ed3eeb3157483a12a26177aefc0","qualityScore":57}');
