INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Bebang-Enterprise-Inc/hrms/local-frappe', 'local-frappe', 'Bebang-Enterprise-Inc', 'hrms', 'community', 'local-frappe Bebang-Enterprise-Inc hrms community The local-frappe skill enables developers to set up and manage local Frappe development environments, ensuring iterative development without disrupting production. It benefits developers working with Frappe and Python. local-frappe 是一个本地 Frappe 开发工具，用于快速测试和部署 Frappe/Python 代码 local-frappe は、Frappe/Python コードの迅速なテストとデプロイを実現するローカル開発ツールです local-frappe 는 로컬에서 Frappe/Python 코드를 빠르게 테스트하고 배포하는 데 사용되는 도구입니다 Local-frappe es una herramienta para desarrolladores que permite probar y depurar cambios en Frappe y Python de manera local y rápida Local-frappe est un outil pour développeurs qui permet de tester et de déboguer les modifications de Frappe et Python de manière locale et rapide Local-frappe ist ein Tool für Entwickler, das das Testen und Debuggen von Änderungen in Frappe und Python auf lokale und schnelle Weise ermöglicht O local-frappe é uma ferramenta essencial para desenvolvedores, permitindo testes locais rápidos e seguros antes de deploy em produção. Локальный local-frappe - это важнейший инструмент для разработчиков, позволяющий проводить быстрые и безопасные локальные тесты перед deploy в производство. أداة local-frappe المحلية هي أداة أساسية للمطورين، تمكنهم من إجراء اختبارات سريعة وأمنة قبل النشر في الإنتاج. how to use local-frappe local-frappe setup guide local-frappe alternative local-frappe vs Frappe local-frappe install what is local-frappe local-frappe development frappe local development python local development local-frappe Frappe 本地开发 Python 代码测试 快速部署 本地测试 生产环境部署 Sets up local Frappe development environments Manages local Frappe applications for iterative development Reduces production deployment time from 15-20 minutes to seconds Enforces critical rule of testing locally before production deployment Supports rapid testing and development of Frappe and Python changes local-frappe is a development tool that allows developers to test and manage Frappe applications locally, reducing production deployment time from 15-20 minutes to mere seconds.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('omerakben/omer-akben/bundle-optimization', 'community', 'omerakben', 'omer-akben', 'omerakben/omer-akben', 'bundle-optimization', 0, 0, 57, '2026-03-08T01:57:15.344Z', '2026-03-08T02:03:32.678Z', '3ea44328f683624bae781e56e079d027b66a0eeb18bd305d8f48c2a959b1149d', '{"id":"omerakben/omer-akben/bundle-optimization","name":"bundle-optimization","description":{"en":"The bundle-optimization skill helps developers reduce bundle size through strategic optimizations, resulting in improved performance. It documents proven patterns for maintaining optimal bundle size.","zh":"本文介绍了 Bundle 优化技术，通过战略性的优化实现了 90% 的包大小减少","ja":"バンドル最適化技術を使用して、戦略的な最適化により 90% のパッケージサイズ削減を実現します","ko":"번들 최적화 기술을 사용하여 전략적인 최적화를 통해 90%의 패키지 크기 감소를 달성합니다","es":"La optimización de paquetes reduce el tamaño del bundle en un 90% mediante la implementación de patrones de optimización comprobados. Esta habilidad documenta soluciones efectivas para mantener un tamaño de paquete óptimo.","fr":"L''optimisation de bundle réduit la taille du bundle de 90% en mettant en œuvre des modèles d''optimisation éprouvés. Cette compétence documente des solutions efficaces pour maintenir une taille de bundle optimale.","de":"Die Bundle-Optimierung reduziert die Bundle-Größe um 90% durch die Implementierung bewährter Optimierungsmuster. Diese Fähigkeit dokumentiert effektive Lösungen, um eine optimale Bundle-Größe beizubehalten.","pt":"Otimização de pacotes para reduzir o tamanho da bundle e melhorar a performance da aplicação","ru":"Оптимизация пакетов для уменьшения размера пакета и улучшения производительности приложения","ar":"تحسين حزمة لتقليل حجم الحزمة و تحسين أداء التطبيق"},"seo":{"title":{"en":"bundle-optimization: 90% Bundle Reduction Setup Guide | A...","zh":"Bundle 优化设置指南 - 减少 90% 的包大小","ja":"バンドル最適化のためのベストプラクティス - AIエージェント","ko":"번들 최적화 설정 가이드 - 90% 패키지 크기 감소","es":"Guía de configuración de optimización de paquetes para de...","fr":"Guide de mise en place de l''optimisation de bundle pour l...","de":"Setup-Leitfaden für Bundle-Optimierung für Entwickler","pt":"Otimização de Pacotes: Guia de Configuração para Desenvol...","ru":"Оптимизация пакетов: лучшие практики для ИИ Агентов","ar":"تحسين حزمة: دليل الإعداد لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to achieve a 90% bundle reduction with the bundle-optimization skill. Learn how to optimize your bundles and improve performance - get started now!","zh":"了解如何使用 Bundle 优化技术减少包大小，提高 Web 应用的性能","ja":"バンドル最適化を使用してパッケージサイズを 90% 削減し、Web アプリケーションのパフォーマンスを向上させる方法を学びます - AIエージェント","ko":"번들 최적화를 사용하여 패키지 크기를 90% 줄이고 웹 애플리케이션의 성능을 개선하는 방법을 알아보세요","es":"Descubre cómo reducir el tamaño del paquete en un 90% con patrones de optimización comprobados y herramientas de AI como los Agentes de Inteligencia Artificial","fr":"Découvrez comment réduire la taille du bundle de 90% avec des modèles d''optimisation éprouvés et des outils d''IA tels que les Outils d''Intelligence Artificielle","de":"Erfahren Sie, wie Sie die Bundle-Größe um 90% reduzieren können, mit bewährten Optimierungsmustern und AI-Tools wie KI-Agenten","pt":"Aprenda a reduzir o tamanho da bundle em 90% com otimizações estratégicas e melhore a performance da sua aplicação","ru":"Узнайте, как уменьшить размер пакета на 90% с помощью стратегических оптимизаций и улучшить производительность вашего приложения с помощью ИИ Агентов","ar":"تعلم كيفية تقليل حجم الحزمة بنسبة 90% من خلال تحسينات استراتيجية و تحسين أداء تطبيقك مع أدوات الذكاء الاصطناعي"},"definition":{"en":"bundle-optimization is a technique for reducing the size of software bundles through strategic optimizations, resulting in improved performance and faster load times.","zh":"Bundle 优化是指通过最小化不必要的代码和资源来减少 Web 应用的包大小","ja":"バンドル最適化とは、不要なコードやリソースを最小限に抑えることで Web アプリケーションのパッケージサイズを削減すること","ko":"번들 최적화는 불필요한 코드와 리소스를 최소화하여 웹 애플리케이션의 패키지 크기를 줄이는 것을 의미합니다","es":"La optimización de paquetes es una técnica que reduce el tamaño del paquete mediante la implementación de patrones de optimización comprobados","fr":"L''optimisation de bundle est une technique qui réduit la taille du bundle en mettant en œuvre des modèles d''optimisation éprouvés","de":"Die Bundle-Optimierung ist eine Technik, die die Bundle-Größe durch die Implementierung bewährter Optimierungsmuster reduziert","pt":"Otimização de pacotes é uma técnica para reduzir o tamanho da bundle de uma aplicação","ru":"Оптимизация пакетов - это техника для уменьшения размера пакета приложения","ar":"تحسين حزمة هو تقنية لتقليل حجم الحزمة من تطبيق"},"features":{"en":["Achieves 90% bundle reduction through strategic optimizations","Utilizes icon manifest with build-time generation for optimal icon loading","Resolves wildcard import issues causing massive bundle bloat","Supports TypeScript for efficient and scalable coding","Generates optimized bundles with reduced sizes (e.g., 2.33MB → 236KB)","Implements proven patterns for maintaining optimal bundle size"],"zh":["通过 Icon Manifest 实现图标优化","使用构建时生成减少包大小","减少 90% 的包大小","支持 TypeScript 语言","最小化不必要的代码和资源"],"ja":["アイコンマニフェストを使用したアイコン最適化","ビルド時生成を使用してパッケージサイズを削減","90% のパッケージサイズ削減","TypeScript 言語のサポート","不要なコードやリソースの最小化"],"ko":["아이콘 매니페스트를 사용한 아이콘 최적화","빌드 시 생성을 사용하여 패키지 크기 감소","90%의 패키지 크기 감소","TypeScript 언어 지원","불필요한 코드와 리소스의 최소화"],"es":["Reducción del tamaño del paquete en un 90% mediante la implementación de patrones de optimización comprobados","Optimización de iconos con generación en tiempo de compilación","Uso de manifest de iconos para reducir la carga de paquetes","Implementación de patrones de optimización para mantener un tamaño de paquete óptimo","Integración con herramientas de desarrollo como TypeScript y CLI"],"fr":["Réduction de la taille du bundle de 90% en mettant en œuvre des modèles d''optimisation éprouvés","Optimisation des icônes avec génération en temps de compilation","Utilisation d''un manifest d''icônes pour réduire la charge de paquets","Mise en œuvre de modèles d''optimisation pour maintenir une taille de bundle optimale","Intégration avec des outils de développement tels que TypeScript et CLI"],"de":["Reduzierung der Bundle-Größe um 90% durch die Implementierung bewährter Optimierungsmuster","Optimierung von Icons mit Generierung in Compile-Zeit","Verwendung eines Icon-Manifests, um die Bundle-Last zu reduzieren","Implementierung von Optimierungsmustern, um eine optimale Bundle-Größe beizubehalten","Integration mit Entwicklungstools wie TypeScript und CLI"],"pt":["Redução de 90% no tamanho da bundle","Otimização de ícones com geração em tempo de build","Uso de manifesto de ícones para evitar imports desnecessários","Melhoria na performance da aplicação","Compatibilidade com bibliotecas como simple-icons"],"ru":["Уменьшение размера пакета на 90%","Оптимизация иконок с генерацией в время сборки","Использование манифеста иконок для избежания ненужных импортов","Улучшение производительности приложения","Совместимость с библиотеками seperti simple-icons"],"ar":["تقليل حجم الحزمة بنسبة 90%","تحسين الأيقونات مع توليد في وقت البناء","استخدام مаниفست الأيقونات لتجنب الاستيراد غير الضروري","تحسين أداء التطبيق","التوافق مع المكتبات مثل simple-icons"]},"keywords":{"en":["how to use bundle-optimization","what is bundle-optimization","bundle-optimization alternative","bundle-optimization vs webpack","bundle-optimization install","bundle-optimization setup guide","typescript bundle optimization","icon optimization techniques","reducing bundle size with bundle-optimization"],"zh":["Bundle 优化","包大小减少","Web 应用性能优化","Icon 优化","TypeScript","构建时生成","AI 工具","前端开发"],"ja":["バンドル最適化","パッケージサイズ削減","Web アプリケーションのパフォーマンス最適化","アイコン最適化","TypeScript","ビルド時生成","AIエージェント","フロントエンド開発"],"ko":["번들 최적화","패키지 크기 감소","웹 애플리케이션 성능 최적화","아이콘 최적화","TypeScript","빌드 시 생성","AI 도구","프론트엔드 개발"],"es":["optimización de paquetes","reducción de tamaño de paquete","patrones de optimización","herramientas de AI","Agentes de Inteligencia Artificial","TypeScript","CLI","desarrollo de software","optimización de bundle"],"fr":["optimisation de bundle","réduction de taille de bundle","modèles d''optimisation","outils d''IA","Outils d''Intelligence Artificielle","TypeScript","CLI","développement de logiciels","optimisation de bundle"],"de":["Bundle-Optimierung","Reduzierung der Bundle-Größe","Optimierungsmuster","KI-Tools","KI-Agenten","TypeScript","CLI","Software-Entwicklung","Bundle-Optimierung"],"pt":["otimização de pacotes","redução de bundle","melhoria de performance","ícones otimizados","manifesto de ícones","simple-icons","desenvolvimento de aplicativos","otimização de aplicativos"],"ru":["оптимизация пакетов","уменьшение размера пакета","улучшение производительности","оптимизированные иконки","манифест иконок","simple-icons","разработка приложений","оптимизация приложений"],"ar":["تحسين حزمة","تقليل حجم الحزمة","تحسين الأداء","أيقونات محسنة","مаниفست الأيقونات","simple-icons","تطوير التطبيقات","تحسين التطبيقات"]}},"owner":"omerakben","repo":"omer-akben","repoPath":"omerakben/omer-akben","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.344Z","topics":[],"category":"community","skillMd":{"name":"bundle-optimization","description":"Bundle size reduction strategies, icon optimization, tree-shaking, and performance analysis. Use when reducing bundle size or optimizing imports.","bodyPreview":"# Bundle Optimization Skill\n\n## Overview\n\nThis project achieved a **90% bundle reduction** (2.33MB → 236KB) through strategic optimizations. This skill documents proven patterns for maintaining optimal bundle size.\n\n## Key Achievement: Icon Optimization\n\n**Problem:** Wildcard imports caused massive bundle bloat\n**Solution:** Icon manifest with build-time generation\n**Result:** 90% reduction in bundle size\n\n### The Problem\n\n```typescript\n// ❌ WRONG - Imports entire simple-icons library (2.33MB)\ni","body":"# Bundle Optimization Skill\n\n## Overview\n\nThis project achieved a **90% bundle reduction** (2.33MB → 236KB) through strategic optimizations. This skill documents proven patterns for maintaining optimal bundle size.\n\n## Key Achievement: Icon Optimization\n\n**Problem:** Wildcard imports caused massive bundle bloat\n**Solution:** Icon manifest with build-time generation\n**Result:** 90% reduction in bundle size\n\n### The Problem\n\n```typescript\n// ❌ WRONG - Imports entire simple-icons library (2.33MB)\nimport * as Icons from ''simple-icons'';\n\n// This single line imports 2,000+ icons even if you only use 5\nconst reactIcon = Icons.siReact;\n```typescript\n\n### The Solution: Icon Manifest\n\n**Location:** `src/lib/icon-manifest.ts`\n\n### How it works\n\n1. Curate list of needed icons (42 in this project)\n2. Build script generates manifest with only those icons\n3. Runtime imports from manifest instead of full library\n\n```typescript\n// ✅ CORRECT - Only includes curated icons\nimport { getIcon } from ''@/lib/icon-manifest'';\n\nconst reactIcon = getIcon(''react'');\n// Bundle only includes 42 icons instead of 2,000+\n```typescript\n\n### Implementation\n\n**1. Icon Manifest Generator Script**\n\n**Location:** `scripts/generate-icons.js`\n\n```javascript\n// Runs during build process\n// Reads curated icon list\n// Generates optimized manifest\n// Only includes icons actually used in project\n```typescript\n\n**2. Icon Manifest**\n\n**Location:** `src/lib/icon-manifest.ts`\n\n```typescript\n// Auto-generated during build\nimport {\n  siReact,\n  siTypescript,\n  siNextdotjs,\n  // ... only 42 icons\n} from ''simple-icons'';\n\nconst iconManifest = {\n  react: siReact,\n  typescript: siTypescript,\n  nextdotjs: siNextdotjs,\n  // ...\n};\n\nexport const getIcon = (name: string) => iconManifest[name];\n```typescript\n\n**3. Package.json Build Hook**\n\n```json\n{\n  \"scripts\": {\n    \"prebuild\": \"node scripts/generate-icons.js\",\n    \"build\": \"next build\"\n  }\n}\n```typescript\n\n### Usage Pattern\n\n```typescript\n// Import the manifest function\nimport { getIcon } from ''@/lib/icon-manifest'';\n\nfunction SkillIcon({ name }: { name: string }) {\n  const icon = getIcon(name);\n\n  if (!icon) return null;\n\n  return (\n    <div dangerouslySetInnerHTML={{ __html: icon.svg }} />\n  );\n}\n```typescript\n\n### Adding New Icons\n\n1. Add icon name to curated list in `scripts/generate-icons.js`\n2. Run build or `node scripts/generate-icons.js`\n3. Manifest automatically regenerates\n4. Use with `getIcon(''newIconName'')`\n\n## Tree-Shaking Strategies\n\n### 1. Named Imports Only\n\n```typescript\n// ✅ CORRECT - Tree-shakeable\nimport { Button } from ''@/components/ui/button'';\nimport { Camera, Settings } from ''lucide-react'';\n\n// ❌ WRONG - Imports everything\nimport * as Components from ''@/components'';\nimport * as Icons from ''lucide-react'';\n```typescript\n\n### 2. Lucide Icons Configuration\n\n**Location:** `next.config.ts`\n\n```typescript\nmodularizeImports: {\n  ''lucide-react'': {\n    transform: ''lucide-react/dist/esm/icons/{{kebabCase member}}'',\n    skipDefaultConversion: true,\n  },\n}\n```typescript\n\n**Effect:** Each Lucide icon imports only its file, not entire library\n\n### 3. Dynamic Imports for Large Dependencies\n\n```typescript\n// ✅ CORRECT - Load only when needed\nconst HeavyChart = dynamic(() => import(''@/components/heavy-chart''), {\n  loading: () => <Skeleton />,\n  ssr: false, // Skip SSR if not needed\n});\n\n// Use in component\n<HeavyChart data={data} />\n```typescript\n\n### 4. Code Splitting by Route\n\nNext.js automatically code-splits by route, but you can optimize:\n\n```typescript\n// app/heavy-feature/page.tsx\nimport dynamic from ''next/dynamic'';\n\n// Split heavy components\nconst HeavyFeature = dynamic(() => import(''@/components/heavy-feature''));\n\nexport default function Page() {\n  return <HeavyFeature />;\n}\n```typescript\n\n## Bundle Analysis Workflow\n\n### Step 1: Enable Bundle Analyzer\n\n```bash\n# Install analyzer\nnpm install --save-dev @next/bundle-analyzer\n\n# Run analysis\nANALYZE=true npm run build\n```typescript\n\n### Step 2: Review Results\n\nAnalyzer opens in browser showing:\n\n- Chunk sizes\n- Import paths\n- Duplicate dependencies\n- Optimization opportunities\n\n### Step 3: Identify Issues\n\n### Look for\n\n- Large chunks (>500KB)\n- Duplicate libraries (same lib in multiple chunks)\n- Unused imports\n- Large dependencies that could be lazy-loaded\n\n### Step 4: Optimize\n\n### Common fixes\n\n1. Convert wildcard imports to named imports\n2. Add dynamic imports for heavy components\n3. Remove unused dependencies from package.json\n4. Use smaller alternatives (e.g., date-fns instead of moment)\n\n## Size Limit Configuration\n\n**Location:** `package.json`\n\n```json\n{\n  \"size-limit\": [\n    {\n      \"path\": \".next/static/chunks/app/page.js\",\n      \"limit\": \"40 KB\",\n      \"name\": \"Homepage\"\n    },\n    {\n      \"path\": \".next/static/chunks/app/skills/page.js\",\n      \"limit\": \"40 KB\",\n      \"name\": \"Skills Page\"\n    }\n  ]\n}\n```typescript\n\n### Running Size Checks\n\n```bash\n# Check all size limits\nnpm run size\n\n# Output shows:\n# ✓ Homepage: 7.73 KB / 40 KB (within limit)\n# ✓ Skills: 6.31 KB / 40 KB (within limit)\n```typescript\n\n### CI/CD Integration\n\nSize limits run in GitHub Actions quality gates:\n\n```yaml\n- name: Check bundle size\n  run: npm run size\n```typescript\n\n**Failure:** Blocks PR if any bundle exceeds limit\n\n## Performance Optimization Patterns\n\n### 1. Image Optimization\n\n```typescript\n// ✅ CORRECT - Next.js Image component\nimport Image from ''next/image'';\n\n<Image\n  src=\"/assets/photo.jpg\"\n  alt=\"Description\"\n  width={800}\n  height={600}\n  priority={false} // Lazy load by default\n  quality={85}\n/>\n```typescript\n\n### Benefits\n\n- Automatic WebP/AVIF conversion\n- Lazy loading by default\n- Responsive images\n- Optimized serving\n\n### 2. Font Optimization\n\n```typescript\n// app/layout.tsx\nimport { Inter } from ''next/font/google'';\n\nconst inter = Inter({\n  subsets: [''latin''],\n  display: ''swap'',\n  preload: true,\n});\n\nexport default function RootLayout({ children }) {\n  return (\n    <html className={inter.className}>\n      <body>{children}</body>\n    </html>\n  );\n}\n```typescript\n\n### Benefits\n\n- Self-hosted fonts (no external requests)\n- Automatic font optimization\n- Zero layout shift\n\n### 3. Script Loading Strategies\n\n```typescript\nimport Script from ''next/script'';\n\n// Load after page is interactive\n<Script\n  src=\"https://analytics.example.com/script.js\"\n  strategy=\"lazyOnload\"\n/>\n\n// Load before page is interactive\n<Script\n  src=\"https://critical.example.com/script.js\"\n  strategy=\"beforeInteractive\"\n/>\n```typescript\n\n### 4. CSS Optimization\n\n### Tailwind Configuration\n\n```javascript\n// tailwind.config.js\nmodule.exports = {\n  content: [\n    ''./src/**/*.{js,ts,jsx,tsx,mdx}'',\n  ],\n  // Purges unused CSS in production\n};\n```typescript\n\n**Result:** Only CSS actually used is included in bundle\n\n## Monitoring Bundle Size\n\n### Current Metrics (Production)\n\n```typescript\nHomepage:     7.73 KB / 40 KB (19% of limit) ✅\nSkills Page:  6.31 KB / 40 KB (16% of limit) ✅\nShared:       102 KB (routes share this)\n```typescript\n\n### Bundle Size History\n\n### Before Optimization (October 2024)\n\n- Homepage: 2.33 MB (with wildcard icon import)\n- Skills Page: 2.35 MB\n\n### After Icon Manifest (October 2024)\n\n- Homepage: 236 KB (90% reduction)\n- Skills Page: 193 KB\n\n### After Additional Optimizations (November 2024)\n\n- Homepage: 7.73 KB\n- Skills Page: 6.31 KB\n\n### Tracking Over Time\n\n```bash\n# Run before making changes\nnpm run size > before.txt\n\n# Make optimizations\n\n# Run after changes\nnpm run size > after.txt\n\n# Compare\ndiff before.txt after.txt\n```typescript\n\n## Common Optimization Mistakes\n\n### Mistake 1: Over-Splitting\n\n```typescript\n// ❌ WRONG - Too aggressive splitting\nconst Button = dynamic(() => import(''./button''));\nconst Text = dynamic(() => import(''./text''));\nconst Icon = dynamic(() => import(''./icon''));\n\n// Network overhead > bundle savings\n```typescript\n\n**Fix:** Only split genuinely large components (>50KB)\n\n### Mistake 2: Importing Dev Dependencies in Production\n\n```typescript\n// ❌ WRONG - Imports dev tool in production\nimport { faker } from ''@faker-js/faker'';\n\nconst mockData = faker.name.firstName();\n```typescript\n\n**Fix:** Use conditional imports or environment checks\n\n```typescript\n// ✅ CORRECT\nconst mockData = process.env.NODE_ENV === ''development''\n  ? await import(''@faker-js/faker'').then(m => m.faker.name.firstName())\n  : ''John'';\n```typescript\n\n### Mistake 3: Duplicate Dependencies\n\n```bash\n# Check for duplicates\nnpm ls <package-name>\n\n# Example: Multiple versions of same package\nnpm ls react\n# ├── react@19.0.0\n# └── some-lib\n#     └── react@18.0.0  # ❌ Duplicate!\n```typescript\n\n**Fix:** Update dependencies to use same version\n\n## Performance Budget\n\n### Current Limits\n\n- **Homepage:** 40 KB (first-party JavaScript)\n- **Other Routes:** 40 KB each\n- **Shared Chunks:** 150 KB total\n- **Images:** Lazy-loaded, optimized format\n\n### Adding New Features\n\n### Before adding dependency\n\n1. Check package size on Bundlephobia\n2. Consider alternatives\n3. Run size check after installation\n4. Verify no significant increase\n\n```bash\n# Check package size before installing\nnpx bundlephobia <package-name>\n\n# Install\nnpm install <package-name>\n\n# Verify size impact\nnpm run size\n```typescript\n\n## Optimization Checklist\n\nWhen adding new features:\n\n- [ ] Use named imports only (no wildcards)\n- [ ] Check if dependency can be dynamic import\n- [ ] Verify icon added to manifest (if using icons)\n- [ ] Run bundle analyzer to check impact\n- [ ] Ensure size limits still pass\n- [ ] Test production build size\n- [ ] Consider server-side alternative\n- [ ] Check for lighter alternatives\n\n## Quick Reference Commands\n\n```bash\n# Bundle analysis\nANALYZE=true npm run build\n\n# Size limit check\nnpm run size\n\n# Check package size before install\nnpx bundlephobia <package>\n\n# Find duplicate dependencies\nnpm ls <package>\n\n# Production build test\nnpm run build && npm run start\n\n# Generate icon manifest\nnode scripts/generate-icons.js\n```typescript\n\n## Related Files\n\n- `scripts/generate-icons.js` - Icon manifest generator\n- `src/lib/icon-manifest.ts` - Generated icon manifest\n- `next.config.ts` - Lucide tree-shaking configuration\n- `package.json` - Size limit configuration\n- `.github/workflows/quality-gates.yml` - CI/CD size checks\n\n## Resources\n\n- [Bundlephobia](https://bundlephobia.com/) - Check package sizes\n- [Next.js Bundle Analyzer](https://www.npmjs.com/package/@next/bundle-analyzer)\n- [size-limit](https://github.com/ai/size-limit) - Size limit enforcement\n"},"lastSynced":"2026-03-08T02:03:32.678Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing strategic bundle size reductions through optimized imports and icon management.","zh":"非常适合需要通过优化导入和图标管理来减少策略性捆绑包大小的前端代理。","ja":"フロントエンドエージェントが戦略的なバンドルサイズの削減を必要とする場合に最適です。最適化されたインポートとアイコン管理を通じてバンドルサイズの削減を実現します。","ko":"전면 에이전트가 최적화된 가져오기 및 아이콘 관리를 통해 전략적인 번들 크기 감소를 필요로 하는 경우에 완벽합니다.","es":"Perfecto para agentes Frontend que necesitan reducciones estratégicas del tamaño del paquete a través de importaciones optimizadas y gestión de iconos.","fr":"Parfait pour les agents Frontend ayant besoin de réductions stratégiques de la taille du paquet grâce à des importations optimisées et une gestion d''icônes.","de":"Perfekt für Frontend-Agents, die strategische Reduzierungen der Bundle-Größe durch optimierte Importe und Icon-Verwaltung benötigen.","pt":"Perfeito para Agentes Frontend que precisam de reduções estratégicas no tamanho do pacote por meio de imports otimizados e gerenciamento de ícones.","ru":"Идеально подходит для агентов Frontend, которым необходимы стратегические сокращения размера пакета за счет оптимизированных импортов и управления иконками.","ar":"مثالي لعمليات الوكلاء الأمامية التي تحتاج إلى تخفيضات استراتيجية في حجم الحزمة من خلال الاستيرادات المُحسنة وإدارة الرموز"},"recommendation":{"en":"Empowers agents to minimize bundle bloat by leveraging icon manifests with build-time generation, resulting in significant reductions in bundle size, such as achieving a 90% bundle reduction through wildcard import optimization and strategic use of libraries.","zh":"赋予代理人通过利用构建时生成的图标清单来最小化捆绑膨胀的能力，从而实现捆绑包大小的显著减少，例如通过通配符导入优化和战略性库使用实现90%的捆绑包大小减少。","ja":"ビルド時生成のアイコンマニフェストを利用することでバンドル膨張を最小限に抑えることができるため、バンドルサイズの削減が実現します。たとえば、ワイルドカードインポートの最適化や戦略的なライブラリの使用により、90%のバンドルサイズ削減が可能になります。","ko":"빌드 시간 생성의 아이콘 매니페스트를 활용하여 번들 부풀림을 최소화 할 수 있으므로 번들 크기 감소가 가능합니다. 예를 들어, 와일드 카드 가져오기 최적화 및 전략적 라이브러리 사용을 통해 90%의 번들 크기 감소가 가능합니다.","es":"Habilita a los agentes a minimizar el tamaño del paquete excesivo aprovechando los manifiestos de iconos con generación en tiempo de compilación, lo que resulta en reducciones significativas del tamaño del paquete, como lograr una reducción del 90% del tamaño del paquete a través de la optimización de importaciones de comodines y el uso estratégico de bibliotecas.","fr":"Permet aux agents de minimiser le gonflement du paquet en exploitant les manifests d''icônes avec la génération à temps de construction, ce qui aboutit à des réductions significatives de la taille du paquet, telles que réaliser une réduction de 90% de la taille du paquet grâce à l''optimisation des imports de caractères génériques et à l''utilisation stratégique des bibliothèques.","de":"Ermächtigt die Agenten, den Bundle-Überlauf zu minimieren, indem sie die Icon-Manifeste mit Buildzeit-Generierung nutzen, was zu signifikanten Reduzierungen der Bundle-Größe führt, wie z.B. eine Reduzierung der Bundle-Größe um 90% durch Optimierung von Wildcard-Importen und strategische Nutzung von Bibliotheken.","pt":"Habilita os agentes a minimizar o inchaço do pacote aproveitando manifestos de ícones com geração em tempo de compilação, resultando em reduções significativas no tamanho do pacote, como alcançar uma redução de 90% no tamanho do pacote por meio da otimização de importações genéricas e uso estratégico de bibliotecas.","ru":"Наделяет агентов возможностью минимизировать раздутость пакета, используя манифесты иконок с генерацией во время сборки, что приводит к существенным сокращениям размера пакета, например, к достижению сокращения размера пакета на 90% за счет оптимизации импортов по шаблону и стратегического использования библиотек.","ar":"تمكّن الوكلاء من تقليل انتفاخ الحزمة من خلال استخدام صور رموز مع توليد زمن البناء، مما يؤدي إلى تخفيضات كبيرة في حجم الحزمة، مثل تحقيق تخفيض بنسبة 90% في حجم الحزمة من خلال تحسين الاستيرادات العامة والاستخدام الاستراتيجي للمكتبات"},"useCases":{"en":["Optimizing bundle size through strategic import management","Implementing icon optimization techniques to reduce bundle bloat","Debugging wildcard imports causing massive bundle size increases"],"zh":["通过战略性导入管理优化捆绑包大小","实现图标优化技术以减少捆绑包膨胀","调试导致巨大捆绑包大小增加的通配符导入"],"ja":["戦略的なインポート管理を通じてバンドルサイズの最適化","アイコン最適化技術の実装によるバンドル膨張の削減","ワイルドカードインポートによって引き起こされる巨大なバンドルサイズ増加のデバッグ"],"ko":["전략적 가져오기 관리를 통해 번들 크기 최적화","아이콘 최적화 기술을 구현하여 번들 부풀림 감소","와일드카드 가져오기가引き起こす巨大한 번들 크기 증가의 디버깅"],"es":["Optimización del tamaño del paquete a través de la gestión estratégica de importaciones","Implementación de técnicas de optimización de iconos para reducir el tamaño del paquete excesivo","Depuración de imports de comodines que causan aumentos masivos del tamaño del paquete"],"fr":["Optimisation de la taille du paquet grâce à la gestion stratégique des imports","Mise en œuvre de techniques d''optimisation d''icônes pour réduire le gonflement du paquet","Débogage des imports de caractères génériques provoquant des augmentations massives de la taille du paquet"],"de":["Optimierung der Bundle-Größe durch strategische Importverwaltung","Implementierung von Icon-Optimierungstechniken, um den Bundle-Überlauf zu reduzieren","Fehlerbehebung bei Wildcard-Importen, die massive Erhöhungen der Bundle-Größe verursachen"],"pt":["Otimizando o tamanho do pacote por meio de gerenciamento de imports estratégico","Implementando técnicas de otimização de ícones para reduzir o inchaço do pacote","Depurando imports genéricos que causam aumentos maciços no tamanho do pacote"],"ru":["Оптимизация размера пакета за счет стратегического управления импортом","Реализация методов оптимизации иконок для уменьшения раздутости пакета","Отладка импортов по шаблону, вызывающих巨альные увеличения размера пакета"],"ar":["تحسين حجم الحزمة من خلال إدارة الاستيرادات الاستراتيجية","تطبيق تقنيات تحسين الرموز لتقليل انتفاخ الحزمة","تصحيح الأخطاء في الاستيرادات العامة التي تسبب زيادات كبيرة في حجم الحزمة"]},"limitations":{"en":["Requires understanding of import management and build-time generation","May require adjustments to existing codebase for optimal results"],"zh":["需要了解导入管理和构建时生成","可能需要对现有代码库进行调整以获得最佳结果"],"ja":["インポート管理とビルド時生成の理解が必要","最適な結果を得るために既存のコードベースの調整が必要になる場合がある"],"ko":["가져오기 관리 및 빌드 시간 생성에 대한 이해가 필요함","최적의 결과를 얻으려면 기존 코드베이스에 대한 조정이 필요할 수 있음"],"es":["Requiere comprensión de la gestión de importaciones y la generación en tiempo de compilación","Puede requerir ajustes en la base de código existente para obtener resultados óptimos"],"fr":["Nécessite une compréhension de la gestion des imports et de la génération à temps de construction","Peut nécessiter des ajustements dans la base de code existante pour obtenir des résultats optimaux"],"de":["Erfordert Verständnis für die Importverwaltung und die Buildzeit-Generierung","Kann Anpassungen an der bestehenden Codebasis erfordern, um optimale Ergebnisse zu erzielen"],"pt":["Exige compreensão de gerenciamento de imports e geração em tempo de compilação","Pode exigir ajustes na base de código existente para obter resultados ótimos"],"ru":["Требует понимания управления импортом и генерации во время сборки","Может потребовать корректировки существующей базы кода для достижения оптимальных результатов"],"ar":["يتطلب فهمًا لإدارة الاستيرادات وتوليد زمن البناء","قد يتطلب تعديلات على قاعدة الشفرة الحالية لتحقيق نتائج مثالية"]},"version":4},"contentHash":"3ea44328f683624bae781e56e079d027b66a0eeb18bd305d8f48c2a959b1149d","qualityScore":57}');
