INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('omerakben/omer-akben/bundle-optimization', 'bundle-optimization', 'omerakben', 'omer-akben', 'community', 'bundle-optimization omerakben omer-akben community The bundle-optimization skill helps developers reduce bundle size through strategic optimizations, resulting in improved performance. It documents proven patterns for maintaining optimal bundle size. 本文介绍了 Bundle 优化技术，通过战略性的优化实现了 90% 的包大小减少 バンドル最適化技術を使用して、戦略的な最適化により 90% のパッケージサイズ削減を実現します 번들 최적화 기술을 사용하여 전략적인 최적화를 통해 90%의 패키지 크기 감소를 달성합니다 La optimización de paquetes reduce el tamaño del bundle en un 90% mediante la implementación de patrones de optimización comprobados. Esta habilidad documenta soluciones efectivas para mantener un tamaño de paquete óptimo. L''optimisation de bundle réduit la taille du bundle de 90% en mettant en œuvre des modèles d''optimisation éprouvés. Cette compétence documente des solutions efficaces pour maintenir une taille de bundle optimale. Die Bundle-Optimierung reduziert die Bundle-Größe um 90% durch die Implementierung bewährter Optimierungsmuster. Diese Fähigkeit dokumentiert effektive Lösungen, um eine optimale Bundle-Größe beizubehalten. Otimização de pacotes para reduzir o tamanho da bundle e melhorar a performance da aplicação Оптимизация пакетов для уменьшения размера пакета и улучшения производительности приложения تحسين حزمة لتقليل حجم الحزمة و تحسين أداء التطبيق how to use bundle-optimization what is bundle-optimization bundle-optimization alternative bundle-optimization vs webpack bundle-optimization install bundle-optimization setup guide typescript bundle optimization icon optimization techniques reducing bundle size with bundle-optimization Bundle 优化 包大小减少 Web 应用性能优化 Icon 优化 TypeScript 构建时生成 AI 工具 前端开发 Achieves 90% bundle reduction through strategic optimizations Utilizes icon manifest with build-time generation for optimal icon loading Resolves wildcard import issues causing massive bundle bloat Supports TypeScript for efficient and scalable coding Generates optimized bundles with reduced sizes (e.g., 2.33MB → 236KB) Implements proven patterns for maintaining optimal bundle size bundle-optimization is a technique for reducing the size of software bundles through strategic optimizations, resulting in improved performance and faster load times.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('atondwal/config/taiga-api', 'community', 'atondwal', 'config', 'atondwal/config', 'taiga-api', 0, 0, 57, '2026-03-08T01:57:15.344Z', '2026-03-08T02:03:33.079Z', 'a19b7ec492405415ef7b65794cd74a9209c6a0b08f1c6a4a1285279b6d51a0d7', '{"id":"atondwal/config/taiga-api","name":"taiga-api","description":{"en":"The Taiga-API skill allows developers to query the hosted Taiga evaluation platform API for job results, transcripts, and problem runs using Python. It provides a helper function to load cookies, ensuring seamless API requests.","zh":"Taiga API 是一个用于查询 Taiga 评估平台的 API，支持使用 Python 加载 cookie 和查询 job 结果","ja":"Taiga API は、Taiga 評価プラットフォームを照会するための API であり、Python を使用して Cookie をロードし、ジョブ結果を照会できます","ko":"Taiga API는 Taiga 평가 플랫폼을 쿼리하는 데 사용되는 API로 Python을 사용하여 쿠키를 로드하고 작업 결과를 쿼리할 수 있습니다","es":"La API de Taiga permite a los desarrolladores acceder a resultados de trabajos, transcripciones y ejecuciones de problemas utilizando Python","fr":"L''API Taiga permet aux développeurs d''accéder aux résultats de tâches, transcriptions et exécutions de problèmes en utilisant Python","de":"Die Taiga-API ermöglicht es Entwicklern, auf Auftrags Ergebnisse, Transkriptionen und Problem-Runs mit Python zuzugreifen","pt":"O Taiga API permite consultar resultados de trabalho, transcrições e execuções de problemas com Python. Saiba mais sobre como usá-lo de forma eficaz","ru":"Taiga API позволяет запросить результаты работы, транскрипции и выполнения задач с помощью Python. Узнайте больше о его использовании","ar":"يسمح Taiga API باستعلام نتائج الوظائف والمحاكاة وتنفيذ المشكلات باستخدام Python. تعرف على كيفية استخدامها بفعالية"},"seo":{"title":{"en":"Taiga-API: Python-Based Query Setup Guide | AI Agent Skill","zh":"Taiga API 集成指南：使用 Python 实现自动化","ja":"Taiga API 導入ガイド：Python を使用した自動化","ko":"Taiga API 설정 가이드: Python을 사용한 자동화","es":"Guía d