INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('atondwal/config/taiga-api', 'taiga-api', 'atondwal', 'config', 'community', 'taiga-api atondwal config community The Taiga-API skill allows developers to query the hosted Taiga evaluation platform API for job results, transcripts, and problem runs using Python. It provides a helper function to load cookies, ensuring seamless API requests. Taiga API 是一个用于查询 Taiga 评估平台的 API，支持使用 Python 加载 cookie 和查询 job 结果 Taiga API は、Taiga 評価プラットフォームを照会するための API であり、Python を使用して Cookie をロードし、ジョブ結果を照会できます Taiga API는 Taiga 평가 플랫폼을 쿼리하는 데 사용되는 API로 Python을 사용하여 쿠키를 로드하고 작업 결과를 쿼리할 수 있습니다 La API de Taiga permite a los desarrolladores acceder a resultados de trabajos, transcripciones y ejecuciones de problemas utilizando Python L''API Taiga permet aux développeurs d''accéder aux résultats de tâches, transcriptions et exécutions de problèmes en utilisant Python Die Taiga-API ermöglicht es Entwicklern, auf Auftrags Ergebnisse, Transkriptionen und Problem-Runs mit Python zuzugreifen O Taiga API permite consultar resultados de trabalho, transcrições e execuções de problemas com Python. Saiba mais sobre como usá-lo de forma eficaz Taiga API позволяет запросить результаты работы, транскрипции и выполнения задач с помощью Python. Узнайте больше о его использовании يسمح Taiga API باستعلام نتائج الوظائف والمحاكاة وتنفيذ المشكلات باستخدام Python. تعرف على كيفية استخدامها بفعالية how to use taiga-api taiga-api python setup taiga-api alternative taiga-api vs other APIs taiga-api install guide taiga-api setup tutorial what is taiga-api taiga-api documentation taiga-api query examples Taiga API Python 自动化 Cookie Taiga 评估平台 API 集成 开发效率 工作流程自动化 Queries the hosted Taiga evaluation platform API using Python Loads cookies from a .env file using a Python helper function Retrieves job results, transcripts, and problem runs from the Taiga API Avoids shell env var and pipe bugs that strip cookie values Utilizes a Python-based approach for reliable API requests Taiga-api is a Python-based interface for querying the Taiga evaluation platform API, enabling developers to retrieve job results, transcripts, and problem runs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xiaolai/vmark/tiptap-editor', 'community', 'xiaolai', 'vmark', 'xiaolai/vmark', 'tiptap-editor', 0, 0, 57, '2026-03-08T01:57:15.347Z', '2026-03-08T02:03:39.108Z', '4b9e90a774a5eebc21aa21d971dd7ea61dbcb0c11bd25f91b0817ee20e338aea', '{"id":"xiaolai/vmark/tiptap-editor","name":"tiptap-editor","description":{"en":"The tiptap-editor skill provides a comprehensive guide to using Tiptap''s high-level API for markdown editing, benefiting AI agent developers. It helps distinguish when to use Tiptap''s API vs direct ProseMirror access.","zh":"Tiptap 编辑器是 AI 友好的 Markdown 编辑器，提供高级 API 和 ProseMirror 访问模式","ja":"Tiptap エディターは AI フレンドリーな Markdown エディターで、高級 API と ProseMirror アクセス パターンを提供","ko":"Tiptap 에디터는 AI 친화적인 Markdown 편집기로 고급 API와 ProseMirror 액세스 패턴을 제공","es":"Tiptap Editor es un editor de markdown amigo de la IA que ofrece funcionalidades de formato y edición avanzadas","fr":"Tiptap Editor est un éditeur de markdown compatible IA qui propose des fonctionnalités de formatage et d''édition avancées","de":"Tiptap Editor ist ein AI-freundlicher Markdown-Editor, der erweiterte Formatierungs- und Bearbeitungsfunktionen bietet","pt":"O Tiptap Editor é um editor de markdown amigável à IA, que fornece uma API de alto nível para formatar comandos e operações de bloco","ru":"Tiptap Editor — это редактор markdown, дружественный к ИИ, который предоставляет высокоуровневый API для форматирования команд и операций с блоками","ar":"محرر Tiptap هو محرر markdown صديق للتعلم الاصطناعي، يوفر واجهة برمجة تطبيقات من المستوى العلوي للتنسيق والأوامر"},"seo":{"title":{"en":"tiptap-editor: Mastering Markdown Editing for AI Agents |...","zh":"Tiptap 编辑器集成指南 - AI 编辑工具","ja":"Tiptap エディターのベストプラクティス - AIエージェント","ko":"Tiptap 에디터 설정 가이드 - AI 에이전트","es":"Guía de configuración de Tiptap Editor para desarrollador...","fr":"Meilleures pratiques de Tip