INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xiaolai/vmark/tiptap-editor', 'tiptap-editor', 'xiaolai', 'vmark', 'community', 'tiptap-editor xiaolai vmark community The tiptap-editor skill provides a comprehensive guide to using Tiptap''s high-level API for markdown editing, benefiting AI agent developers. It helps distinguish when to use Tiptap''s API vs direct ProseMirror access. Tiptap 编辑器是 AI 友好的 Markdown 编辑器，提供高级 API 和 ProseMirror 访问模式 Tiptap エディターは AI フレンドリーな Markdown エディターで、高級 API と ProseMirror アクセス パターンを提供 Tiptap 에디터는 AI 친화적인 Markdown 편집기로 고급 API와 ProseMirror 액세스 패턴을 제공 Tiptap Editor es un editor de markdown amigo de la IA que ofrece funcionalidades de formato y edición avanzadas Tiptap Editor est un éditeur de markdown compatible IA qui propose des fonctionnalités de formatage et d''édition avancées Tiptap Editor ist ein AI-freundlicher Markdown-Editor, der erweiterte Formatierungs- und Bearbeitungsfunktionen bietet O Tiptap Editor é um editor de markdown amigável à IA, que fornece uma API de alto nível para formatar comandos e operações de bloco Tiptap Editor — это редактор markdown, дружественный к ИИ, который предоставляет высокоуровневый API для форматирования команд и операций с блоками محرر Tiptap هو محرر markdown صديق للتعلم الاصطناعي، يوفر واجهة برمجة تطبيقات من المستوى العلوي للتنسيق والأوامر how to use tiptap-editor tiptap-editor alternative tiptap-editor setup guide what is tiptap-editor tiptap-editor vs ProseMirror tiptap-editor install tiptap-editor API documentation markdown editing with tiptap-editor tiptap-editor for AI agents Tiptap 编辑器 AI 编辑工具 Markdown 编辑器 高级 API ProseMirror 格式命令 块类型更改 列表操作 表格操作 Utilizes Tiptap''s high-level API for format commands (bold, italic, underline, etc.) Supports block type changes (heading, paragraph, code block) via Tiptap API Enables list operations (bullet, ordered, toggle, indent/outdent) through Tiptap API Provides table operations via Tiptap table extension Allows content insertion and manipulation using Tiptap API tiptap-editor is an AI-friendly markdown editor that utilizes Tiptap''s API for format commands, block type changes, and other operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AutumnsGrove/GroveEngine/grove-spec-writing', 'community', 'AutumnsGrove', 'GroveEngine', 'AutumnsGrove/GroveEngine', 'grove-spec-writing', 0, 0, 57, '2026-03-08T01:57:15.349Z', '2026-03-08T02:03:44.439Z', '5bbb13eb32ebf94593fce9ee588edb50e66ba39347041a7a06947e3d94d48ad4', '{"id":"AutumnsGrove/GroveEngine/grove-spec-writing","name":"grove-spec-writing","description":{"en":"The grove-spec-writing skill helps developers create and standardize technical specifications in the Grove ecosystem. It assists in writing new specs and reviewing existing ones for completeness.","zh":"Grove Spec Writing 是一个用于创建和标准化技术规范的综合指南，用于验证和标准化现有的规范","ja":"Grove Spec Writing は、テクニカルスペックの作成と標準化を支援するための包括的なガイドです","ko":"Grove Spec Writing은 기술 사양을 생성하고 표준화하기 위한 포괄적인 가이드입니다","es":"Grove Spec Writing es una guía para escribir especificaciones técnicas en el ecosistema de Grove. Ayuda a crear nuevos specs y a validar los existentes.","fr":"Grove Spec Writing est un guide pour écrire des spécifications techniques dans l''écosystème Grove. Il aide à créer de nouveaux specs et à valider les existants.","de":"Grove Spec Writing ist ein Leitfaden für das Schreiben technischer Spezifikationen im Grove-Ökosystem. Es hilft bei der Erstellung neuer Specs und der Validierung bestehender Specs.","pt":"O Grove Spec Writing é uma ferramenta de AI para criar e validar especificações técnicas em plataformas de blog multi-tenant, permitindo a standardização e a adição de elementos visuais","ru":"Grove Spec Writing - это инструмент ИИ для создания и проверки технических спецификаций на платформах блогов с несколькими арендаторами, обеспечивающий стандартизацию и добавление визуальных элементов","ar":"Grove Spec Writing هو أداة ذكاء اصطناعي لإنشاء وتحقق من المواصفات الفنية على منصات المدونات المتعددة، مما يسمح بالتوحيد والاضافات البصرية"},"seo":{"title":{