INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AutumnsGrove/GroveEngine/grove-spec-writing', 'grove-spec-writing', 'AutumnsGrove', 'GroveEngine', 'community', 'grove-spec-writing AutumnsGrove GroveEngine community The grove-spec-writing skill helps developers create and standardize technical specifications in the Grove ecosystem. It assists in writing new specs and reviewing existing ones for completeness. Grove Spec Writing 是一个用于创建和标准化技术规范的综合指南，用于验证和标准化现有的规范 Grove Spec Writing は、テクニカルスペックの作成と標準化を支援するための包括的なガイドです Grove Spec Writing은 기술 사양을 생성하고 표준화하기 위한 포괄적인 가이드입니다 Grove Spec Writing es una guía para escribir especificaciones técnicas en el ecosistema de Grove. Ayuda a crear nuevos specs y a validar los existentes. Grove Spec Writing est un guide pour écrire des spécifications techniques dans l''écosystème Grove. Il aide à créer de nouveaux specs et à valider les existants. Grove Spec Writing ist ein Leitfaden für das Schreiben technischer Spezifikationen im Grove-Ökosystem. Es hilft bei der Erstellung neuer Specs und der Validierung bestehender Specs. O Grove Spec Writing é uma ferramenta de AI para criar e validar especificações técnicas em plataformas de blog multi-tenant, permitindo a standardização e a adição de elementos visuais Grove Spec Writing - это инструмент ИИ для создания и проверки технических спецификаций на платформах блогов с несколькими арендаторами, обеспечивающий стандартизацию и добавление визуальных элементов Grove Spec Writing هو أداة ذكاء اصطناعي لإنشاء وتحقق من المواصفات الفنية على منصات المدونات المتعددة، مما يسمح بالتوحيد والاضافات البصرية how to use grove-spec-writing grove-spec-writing setup guide grove-spec-writing alternative grove-spec-writing vs storybook what is grove-spec-writing grove-spec-writing install technical specification writing tools grove ecosystem specs spec writing best practices Grove Spec Writing 技术规范编写 AI 工具 ASCII 艺术标题 图表和视觉元素 标准化 frontmatter Creates new specs with storybook-like entries Validates and standardizes existing specs for completeness Adds ASCII art headers to specs missing them Supports adding diagrams, mockups, or visual elements to text-heavy specs Standardizes frontmatter across spec files Validates specs to ensure consistency grove-spec-writing is a multi-tenant blog platform skill for creating, validating, and standardizing technical specifications with features like ASCII art headers and diagram additions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NammDev/Goads-Krea/assets-organizing', 'community', 'NammDev', 'Goads-Krea', 'NammDev/Goads-Krea', 'assets-organizing', 0, 0, 57, '2026-03-08T01:57:15.350Z', '2026-03-08T02:03:47.747Z', '10cb6439c93d87bd88639c5d3aa2f46244be2bed6009b438368f744b8b9316d8', '{"id":"NammDev/Goads-Krea/assets-organizing","name":"assets-organizing","description":{"en":"The assets-organizing skill standardizes asset output locations, naming conventions, and directory structures for marketing outputs, benefiting developers and content creators. It simplifies content organization and generation.","zh":"AI资产组织工具用于标准化资产输出的路径、命名约定和目录结构，适用于创建内容、生成AI资产和组织现有资产","ja":"AIエージェントによるアセット整理は、アセットの出力パス、命名規則、ディレクトリ構造を標準化するために使用され、コンテンツの作成、AIアセットの生成、既存アセットの整理に適しています","ko":"AI 에이전트를 활용한 자산 구성은 자산의 출력 경로, 이름 지정 규칙 및 디렉토리 구조를 표준화하는 데 사용되며, 콘텐츠 생성, AI 자산 생성 및 기존 자산 구성에 적합합니다","es":"El skill de organización de activos permite standardizar la salida de activos de marketing. Establece rutas de salida, convenciones de nomenclatura y estructuras de directorios para artículos, videos, diseños y más.","fr":"Le skill d''organisation d''actifs permet de standardiser la sortie d''actifs de marketing. Il établit des chemins de sortie, des conventions de nommage et des structures de répertoires pour les articles, les vidéos, les conceptions et plus encore.","de":"Das Skill zur Organisation von Assets ermöglicht die Standardisierung der Ausgabe von Marketing-Assets. Es legt Ausgabepfade, Namenskonventionen und Verzeichnisstrukturen für Artikel, Videos, Designs und mehr fest.","pt":"Organize ativos de marketing com padrões de saída e nomeação para Ferramentas de IA. Padronize a estrutura de diretório para conteúdo de marketing.","ru":"Организуйте маркетинговые активы с помощью стандартов вывода и именования для ИИ Агентов. Стандартизируйте структуру директорий для 